INSERT INTO temp_seed_reviews_2000 VALUES
('54500700-0000-4000-9000-000000000501', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3510320', '주식회사라온문화창작소', '평일 연차 쓰고 혼자 주식회사라온문화창작소 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.646830, 128.848880, '2026-10-16T06:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000502', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2746352', '청와대 세트장', '조용히 사색하고 싶어서 찾은 청와대 세트장. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.548450, 128.072862, '2026-10-16T03:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000503', '54500700-0000-4000-8000-000000000072', 'p-tourapi-1615878', '철종외가', '주말에 친구들이랑 철종외가 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "방문팁"]'::jsonb, 37.704924, 126.477278, '2026-10-16T09:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000504', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2604344', '락희원', '조용히 사색하고 싶어서 찾은 락희원. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 35.837371, 129.212015, '2026-10-16T07:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000505', '54500700-0000-4000-8000-000000000195', 'p-tourapi-795829', '청송 후송당 고택', '오랜만에 여유 찾으러 청송 후송당 고택 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "산책로", "힐링", "온마루"]'::jsonb, 36.289739, 129.009676, '2026-10-16T13:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000506', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2575836', '북촌 게스트하우스', '조용히 사색하고 싶어서 찾은 북촌 게스트하우스. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.578628, 126.985681, '2026-10-16T02:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000507', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3102111', '옥천풍경', '예전부터 가보고 싶었던 옥천풍경 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 34.952831, 127.481799, '2026-10-16T04:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000508', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2604833', '해로당', '평일 연차 쓰고 혼자 해로당 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 34.739740, 126.717855, '2026-10-16T08:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000509', '54500700-0000-4000-8000-000000000147', 'p-tourapi-127896', '양주 도자기나라', '비 오는 날 운치 찾아 양주 도자기나라 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "방문팁", "가족여행"]'::jsonb, 37.713434, 126.953952, '2026-10-16T08:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000510', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2638521', '영천 목재문화체험장', '근처 여행 코스로 영천 목재문화체험장 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 36.142432, 128.978252, '2026-10-16T10:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000511', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1883087', '연우하우스', 'SNS에서 사진 보고 찾아간 연우하우스, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "가족여행", "주말나들이"]'::jsonb, 37.582281, 126.985312, '2026-10-16T12:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000512', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3072219', '북촌빈관 by 락고재', '평일 연차 쓰고 혼자 북촌빈관 by 락고재 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 37.582347, 126.984220, '2026-10-16T13:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000513', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '매죽헌2(매죽헌한옥민박) 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.069064, 127.401634, '2026-10-16T04:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000514', '54500700-0000-4000-8000-000000000176', 'p-tourapi-798830', '영동 김참판댁', '근처 여행 코스로 영동 김참판댁 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "혼자여행", "고즈넉", "온마루"]'::jsonb, 36.153087, 127.754835, '2026-10-16T05:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000515', '54500700-0000-4000-8000-000000000058', 'p-tourapi-1997639', '찰방공종택', '비 오는 날 운치 찾아 찰방공종택 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 36.437150, 129.026228, '2026-10-16T04:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000516', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2514834', '죽정분교(구,죽정초등학교)', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 38.470473, 128.419768, '2026-10-16T13:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000517', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2602750', '쥬라기랜드', 'SNS에서 사진 보고 찾아간 쥬라기랜드, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.435562, 127.023837, '2026-10-16T05:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000518', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2569824', '흥해배씨 임연재종택', '해 질 무렵에 흥해배씨 임연재종택 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "고즈넉"]'::jsonb, 36.550011, 128.791685, '2026-10-16T07:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000519', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '조용히 사색하고 싶어서 찾은 2025 서울 카페&베이커리페어. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "고즈넉", "힐링"]'::jsonb, 37.496089, 127.070767, '2026-10-16T10:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000520', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3533129', '감성보다 양평서종점', '해 질 무렵에 감성보다 양평서종점 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.616090, 127.443055, '2026-10-16T08:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000521', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2787267', '오봉정사', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 35.184232, 127.524356, '2026-10-16T13:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000522', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2990185', '금곡영화마을', '예전부터 가보고 싶었던 금곡영화마을 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.395210, 126.734176, '2026-10-16T10:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000523', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2531497', '추우재', '추우재 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 35.668719, 128.227467, '2026-10-16T05:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000524', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2821554', '꽃이 머무는 자리', '비 오는 날 운치 찾아 꽃이 머무는 자리 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 36.393985, 126.857156, '2026-10-16T02:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000525', '54500700-0000-4000-8000-000000000143', 'p-tourapi-1964622', '스카이로드', '평일 연차 쓰고 혼자 스카이로드 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.329147, 127.427818, '2026-10-16T05:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000526', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', '부모님 모시고 꽃동네제빵소(꽃구움) 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.890582, 127.566334, '2026-10-16T12:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000527', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3533007', '종로 성혜헌', '근처 여행 코스로 종로 성혜헌 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "가족여행"]'::jsonb, 37.573010, 127.017373, '2026-10-16T04:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000528', '54500700-0000-4000-8000-000000000165', 'p-tourapi-802358', '아산 대통령마을(농촌전통테마)', '비 오는 날 운치 찾아 아산 대통령마을(농촌전통테마) 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "고즈넉"]'::jsonb, 36.834409, 127.022921, '2026-10-16T09:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000529', '54500700-0000-4000-8000-000000000178', 'p-tourapi-1590793', '노동환가옥', '비 오는 날 운치 찾아 노동환가옥 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "힐링", "고즈넉"]'::jsonb, 35.484368, 127.266354, '2026-10-16T13:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000530', '54500700-0000-4000-8000-000000000203', 'p-tourapi-736751', '화성 정시영 고택', '부모님 모시고 화성 정시영 고택 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.133126, 126.700850, '2026-10-16T12:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000531', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2717600', '이플아토', '해 질 무렵에 이플아토 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "혼자여행"]'::jsonb, 36.452038, 126.803592, '2026-10-16T06:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000532', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2604573', '산들바다애(산들바다애 한옥민박)', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 34.438653, 126.632908, '2026-10-16T02:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000533', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2891349', '미술관아래협동조합', '비 오는 날 운치 찾아 미술관아래협동조합 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "사진맛집", "온마루"]'::jsonb, 34.775012, 126.646788, '2026-10-16T03:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000534', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2531496', '하동댁', '근처 여행 코스로 하동댁 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 35.667412, 128.227754, '2026-10-16T07:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000535', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3438496', '소우주', '오랜만에 여유 찾으러 소우주 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.640970, 126.938620, '2026-10-16T10:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000536', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2615342', '비비정예술열차', '날씨가 너무 맑아서 비비정예술열차 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.898992, 127.067778, '2026-10-16T07:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000537', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2939639', '유현문화관광지', '유현문화관광지 다녀왔어요! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 37.530718, 127.819940, '2026-10-16T05:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000538', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '평일 연차 쓰고 혼자 사단법인 푸른차문화연구원 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "풍경맛집", "힐링"]'::jsonb, 35.835036, 128.677134, '2026-10-16T10:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000539', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2046299', '한옥이야기', '한옥이야기 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 35.812317, 127.153572, '2026-10-16T11:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000540', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2930839', '경리단길', '해 질 무렵에 경리단길 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "혼자여행"]'::jsonb, 37.538452, 126.987515, '2026-10-16T03:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000541', '54500700-0000-4000-8000-000000000063', 'p-tourapi-1627236', '신경섭 전통가옥', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.420803, 126.668294, '2026-10-16T06:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000542', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2707438', '하은재', '하은재 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "혼자여행", "사색", "온마루"]'::jsonb, 37.581938, 126.971282, '2026-10-16T10:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000543', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2600265', '섬계고택', '드라이브 겸 나들이로 섬계고택 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "인생샷", "온마루"]'::jsonb, 36.734625, 128.618878, '2026-10-16T09:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000544', '54500700-0000-4000-8000-000000000123', 'p-tourapi-264466', '김하인 아트홀 국화꽃향기', '비 오는 날 운치 찾아 김하인 아트홀 국화꽃향기 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 38.307369, 128.541457, '2026-10-16T02:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000545', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '농업회사법인주식회사꿀벌인 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.014031, 128.421877, '2026-10-16T04:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000546', '54500700-0000-4000-8000-000000000126', 'p-tourapi-802420', '천안 두아람마을 [농촌전통테마]', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 36.691585, 127.075875, '2026-10-16T05:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000547', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2820733', '생생마을여행사', '주말에 친구들이랑 생생마을여행사 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.027128, 127.630291, '2026-10-16T06:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000548', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3510987', '주식회사감천아울', '주식회사감천아울 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.093432, 129.008795, '2026-10-16T09:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000549', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2599272', '모지고택', '해 질 무렵에 모지고택 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 36.540737, 128.518264, '2026-10-16T06:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000550', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2939639', '유현문화관광지', '조용히 사색하고 싶어서 찾은 유현문화관광지. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.530718, 127.819940, '2026-10-16T09:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000551', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3532970', '한옥스테이 유유자적', '기대 이상으로 너무 좋았던 한옥스테이 유유자적! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 35.826750, 129.206949, '2026-10-14T17:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000552', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3009051', '도깨비 양조장', '드라이브 겸 나들이로 도깨비 양조장 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.026390, 128.384743, '2026-10-15T21:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000553', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3421909', '그런고로', '부모님 모시고 그런고로 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "사진맛집", "데이트", "온마루"]'::jsonb, 35.157559, 129.064247, '2026-10-13T17:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000554', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1614564', '달성 삼가헌 고택', '예전부터 가보고 싶었던 달성 삼가헌 고택 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트", "사진맛집", "온마루"]'::jsonb, 35.906695, 128.412664, '2026-10-15T06:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000555', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2599504', '수졸당', '예전부터 가보고 싶었던 수졸당 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 36.733893, 128.859173, '2026-10-15T04:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000556', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3533007', '종로 성혜헌', '해 질 무렵에 종로 성혜헌 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "주말나들이", "데이트"]'::jsonb, 37.573010, 127.017373, '2026-10-15T13:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000557', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2615320', '봄의 왈츠 드라마 촬영지', '비 오는 날 운치 찾아 봄의 왈츠 드라마 촬영지 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 34.170111, 126.862381, '2026-10-13T13:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000558', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '주말에 친구들이랑 한옥카페 갤러리 도솔 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.641997, 126.506472, '2026-10-15T19:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000559', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3442142', '서울숲 곤충식물원', '비 오는 날 운치 찾아 서울숲 곤충식물원 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 37.543125, 127.041813, '2026-10-14T06:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000560', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2047715', '소강고택', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.893692, 128.712359, '2026-10-14T01:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000561', '54500700-0000-4000-8000-000000000200', 'p-tourapi-1594746', '장현식고택', '기대 이상으로 너무 좋았던 장현식고택! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 35.812156, 127.156492, '2026-10-14T20:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000562', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2695730', '효자스테이', '기대 이상으로 너무 좋았던 효자스테이! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 37.578800, 126.973488, '2026-10-16T00:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000563', '54500700-0000-4000-8000-000000000181', 'p-tourapi-1882371', '학인당', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "고즈넉"]'::jsonb, 35.811812, 127.152057, '2026-10-15T12:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000564', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3533114', '스테이여유담', '기대 이상으로 너무 좋았던 스테이여유담! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "힐링", "사색", "온마루"]'::jsonb, 35.051415, 126.864112, '2026-10-14T08:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000565', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3427162', '타임빌라스 수원', '해 질 무렵에 타임빌라스 수원 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "사진맛집", "방문팁", "온마루"]'::jsonb, 37.264229, 126.997308, '2026-10-15T17:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000566', '54500700-0000-4000-8000-000000000172', 'p-tourapi-252602', '영천 만취당 고택', '천천히 골목 걷다가 마주친 영천 만취당 고택. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.906474, 128.890866, '2026-10-15T23:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000567', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2707440', '누와', '해 질 무렵에 누와 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 37.579630, 126.967797, '2026-10-15T03:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000568', '54500700-0000-4000-8000-000000000135', 'p-tourapi-3582693', '한복남 북촌점', 'SNS에서 사진 보고 찾아간 한복남 북촌점, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.579845, 126.984742, '2026-10-15T20:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000569', '54500700-0000-4000-8000-000000000176', 'p-tourapi-1566740', '양평 맑은숲캠프', '날씨가 너무 맑아서 양평 맑은숲캠프 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 37.562041, 127.734400, '2026-10-14T20:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000570', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2767753', '후암거실', '천천히 골목 걷다가 마주친 후암거실. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.548492, 126.976250, '2026-10-15T05:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000571', '54500700-0000-4000-8000-000000000138', 'p-tourapi-4104618', '함계정사', '예전부터 가보고 싶었던 함계정사 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["가족여행", "데이트"]'::jsonb, 36.047544, 128.977956, '2026-10-15T12:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000572', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3438420', '성북 은은한가', '날씨가 너무 맑아서 성북 은은한가 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "힐링"]'::jsonb, 37.590744, 127.009037, '2026-10-14T11:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000573', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2679990', '신라불교초전지', '신라불교초전지 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.291071, 128.363252, '2026-10-14T18:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000574', '54500700-0000-4000-8000-000000000142', 'p-tourapi-130903', '북촌문화센터', '주말에 친구들이랑 북촌문화센터 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 37.579053, 126.986706, '2026-10-14T13:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000575', '54500700-0000-4000-8000-000000000144', 'p-tourapi-3438572', '스테이 노아', '천천히 골목 걷다가 마주친 스테이 노아. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 36.099279, 127.450069, '2026-10-14T20:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000576', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.646687, 126.696228, '2026-10-15T15:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000577', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2850614', '스탈릿성수', 'SNS에서 사진 보고 찾아간 스탈릿성수, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 37.544494, 127.055473, '2026-10-13T23:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000578', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2603884', '연당', '드라이브 겸 나들이로 연당 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "인생샷", "가족여행", "온마루"]'::jsonb, 37.582603, 126.987073, '2026-10-14T07:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000579', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2380834', '마복산 목재문화체험장', '부모님 모시고 마복산 목재문화체험장 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "사진맛집", "온마루"]'::jsonb, 34.550477, 127.375721, '2026-10-14T17:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000580', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2713396', '함정균가옥', '주말에 친구들이랑 함정균가옥 들렀는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집", "사색", "온마루"]'::jsonb, 38.341137, 128.498580, '2026-10-15T10:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000581', '54500700-0000-4000-8000-000000000074', 'p-tourapi-4070357', '한옥온온', '날씨가 너무 맑아서 한옥온온 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "산책로"]'::jsonb, 36.735279, 127.404911, '2026-10-13T16:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000582', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2572817', '옥산정사 독락당', '주말에 친구들이랑 옥산정사 독락당 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 36.016958, 129.159976, '2026-10-14T15:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000583', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2638479', '장생포 모노레일', '비 오는 날 운치 찾아 장생포 모노레일 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.502970, 129.381340, '2026-10-14T13:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000584', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2595847', '달의 정원', 'SNS에서 사진 보고 찾아간 달의 정원, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.790073, 128.087332, '2026-10-14T16:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000585', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2611472', '보리수 자수 숙박', '천천히 골목 걷다가 마주친 보리수 자수 숙박. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 35.811676, 127.153395, '2026-10-15T04:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000586', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2870141', '한옥마을 박씨네추어탕', '날씨가 너무 맑아서 한옥마을 박씨네추어탕 한 바퀴 돌고 왔네요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 37.648006, 126.701833, '2026-10-16T00:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000587', '54500700-0000-4000-8000-000000000064', 'p-tourapi-1971917', '청공한옥', '청공한옥 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 35.781946, 129.303306, '2026-10-13T20:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000588', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2708329', '학림재', '근처 여행 코스로 학림재 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "인생샷", "온마루"]'::jsonb, 36.551056, 127.189936, '2026-10-13T21:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000589', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2701396', '서남산한옥', '조용히 사색하고 싶어서 찾은 서남산한옥. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.780864, 129.204559, '2026-10-15T13:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000590', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2592885', '엘크레', '오랜만에 여유 찾으러 엘크레 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.520935, 127.023218, '2026-10-13T20:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000591', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2850614', '스탈릿성수', '비 오는 날 운치 찾아 스탈릿성수 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색", "풍경맛집", "온마루"]'::jsonb, 37.544494, 127.055473, '2026-10-14T12:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000592', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3102033', '풍경의 아침', '비 오는 날 운치 찾아 풍경의 아침 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "방문팁", "사진맛집", "온마루"]'::jsonb, 35.387905, 126.884933, '2026-10-15T06:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000593', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3114431', '모주체험 여', '근처 여행 코스로 모주체험 여 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.815809, 127.152069, '2026-10-14T23:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000594', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3438588', '유유가', '근처 여행 코스로 유유가 넣길 정말 잘했어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "주말나들이", "인생샷"]'::jsonb, 34.955870, 127.483135, '2026-10-14T01:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000595', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2606207', '목포 해상케이블카', '평일 연차 쓰고 혼자 목포 해상케이블카 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 34.799416, 126.370053, '2026-10-15T02:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000596', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3438241', '한가로움', '한가로움 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "인생샷", "데이트", "온마루"]'::jsonb, 37.586955, 126.981359, '2026-10-13T20:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000597', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2610062', '태양의 후예 촬영지', 'SNS에서 사진 보고 찾아간 태양의 후예 촬영지, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 37.160565, 129.043152, '2026-10-13T17:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000598', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2569581', '춘하원(죽헌고택)', '춘하원(죽헌고택) 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉", "사색", "온마루"]'::jsonb, 36.647336, 128.663423, '2026-10-14T14:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000599', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '해 질 무렵에 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "주말나들이"]'::jsonb, 37.912546, 128.817052, '2026-10-14T16:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000600', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2593271', '가은채', '주말에 친구들이랑 가은채 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.817064, 127.153292, '2026-10-14T06:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000601', '54500700-0000-4000-8000-000000000148', 'p-tourapi-127060', '이장우가옥', '부모님 모시고 이장우가옥 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.140617, 126.914133, '2026-10-15T18:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000602', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3040204', '함파우소리체험관', '다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.398096, 127.384307, '2026-10-14T15:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000603', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2725010', '휴식 레스토랑', '조용히 사색하고 싶어서 찾은 휴식 레스토랑. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "풍경맛집", "힐링"]'::jsonb, 36.451188, 126.813247, '2026-10-14T16:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000604', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3072197', '오롯이, 한옥', '해 질 무렵에 오롯이, 한옥 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 37.580005, 126.968005, '2026-10-14T06:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000605', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2629570', '새마을 시대촌', '조용히 사색하고 싶어서 찾은 새마을 시대촌. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.599962, 128.761203, '2026-10-14T21:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000606', '54500700-0000-4000-8000-000000000140', 'p-tourapi-1626699', '아산 외암마을 참판댁', '천천히 골목 걷다가 마주친 아산 외암마을 참판댁. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.730305, 127.018491, '2026-10-15T12:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000607', '54500700-0000-4000-8000-000000000091', 'p-tourapi-1624846', '창원정씨종가', '근처 여행 코스로 창원정씨종가 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.565400, 127.395266, '2026-10-14T02:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000608', '54500700-0000-4000-8000-000000000103', 'p-tourapi-129433', '영주 괴헌고택', '드라이브 겸 나들이로 영주 괴헌고택 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 36.734100, 128.681200, '2026-10-13T13:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000609', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2458168', '일락당사랑채', '근처 여행 코스로 일락당사랑채 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.816130, 127.152858, '2026-10-14T10:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000610', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3438189', '한옥 북클럽 하우스', '비 오는 날 운치 찾아 한옥 북클럽 하우스 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "주말나들이", "데이트"]'::jsonb, 37.591369, 127.005287, '2026-10-15T01:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000611', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2583187', '전통문화체험장', '마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "데이트", "온마루"]'::jsonb, 35.989227, 127.260964, '2026-10-14T06:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000612', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2570339', '달빛한옥민박 별유풍경', '예전부터 가보고 싶었던 달빛한옥민박 별유풍경 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "혼자여행"]'::jsonb, 34.740223, 126.718999, '2026-10-14T21:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000613', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3438433', '호우재 한옥', '조용히 사색하고 싶어서 찾은 호우재 한옥. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.595407, 126.999649, '2026-10-13T20:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000614', '54500700-0000-4000-8000-000000000066', 'p-tourapi-1395270', '최순우 옛집', '조용히 사색하고 싶어서 찾은 최순우 옛집. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "고즈넉", "힐링", "온마루"]'::jsonb, 37.593065, 127.000360, '2026-10-14T23:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000615', '54500700-0000-4000-8000-000000000133', 'p-tourapi-1623828', '안동권씨유회당종가일원', '오랜만에 여유 찾으러 안동권씨유회당종가일원 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.277697, 127.404793, '2026-10-14T19:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000616', '54500700-0000-4000-8000-000000000171', 'p-tourapi-264353', '인사동', '부모님 모시고 인사동 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.575462, 126.983523, '2026-10-15T23:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000617', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3056595', '전주한옥마을역사관', '날씨가 너무 맑아서 전주한옥마을역사관 한 바퀴 돌고 왔네요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 35.816007, 127.152938, '2026-10-14T03:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000618', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', '조용히 사색하고 싶어서 찾은 달달구리(주식회사달달구리). 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링", "사색"]'::jsonb, 35.938670, 127.166846, '2026-10-14T06:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000619', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2804328', '만죽재고택', '예전부터 가보고 싶었던 만죽재고택 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 36.731417, 128.621407, '2026-10-13T23:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000620', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3102079', '한옥에서 하루를', '예전부터 가보고 싶었던 한옥에서 하루를 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 37.840382, 126.754273, '2026-10-14T14:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000621', '54500700-0000-4000-8000-000000000057', 'p-tourapi-971122', '강화 아르미애월드', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.702926, 126.434756, '2026-10-14T11:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000622', '54500700-0000-4000-8000-000000000118', 'p-tourapi-4006383', '고요별서', '해 질 무렵에 고요별서 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 34.821952, 128.043511, '2026-10-15T03:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000623', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3582643', '한복남 창덕궁점', '오랜만에 여유 찾으러 한복남 창덕궁점 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 37.576183, 126.990671, '2026-10-15T06:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000624', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3577428', '고창 전통예술체험마을', '예전부터 가보고 싶었던 고창 전통예술체험마을 드디어 방문! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "방문팁", "온마루"]'::jsonb, 35.430478, 126.701515, '2026-10-15T00:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000625', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2350029', '도래미하우스', '평일 연차 쓰고 혼자 도래미하우스 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 34.997557, 126.824853, '2026-10-14T04:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000626', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2793068', '밀양 퇴로리 이씨고가', '평일 연차 쓰고 혼자 밀양 퇴로리 이씨고가 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 35.551147, 128.700501, '2026-10-14T09:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000627', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3102087', '한옥더원', '달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.471089, 127.505831, '2026-10-16T00:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000628', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3101961', '자미재', '부모님 모시고 자미재 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "사색", "온마루"]'::jsonb, 34.911789, 126.648057, '2026-10-13T21:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000629', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2531357', '경주한옥1번가', '날씨가 너무 맑아서 경주한옥1번가 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.825723, 129.213132, '2026-10-15T04:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000630', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2708657', '초정행궁', '드라이브 겸 나들이로 초정행궁 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "주말나들이"]'::jsonb, 36.721236, 127.601291, '2026-10-14T07:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000631', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3072271', '청담', '천천히 골목 걷다가 마주친 청담. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 36.455874, 127.120608, '2026-10-14T05:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000632', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2992823', 'K-컬처 스크린(대한민국역사박물관)', 'K-컬처 스크린(대한민국역사박물관) 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "인생샷", "가족여행"]'::jsonb, 37.574134, 126.977574, '2026-10-15T03:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000633', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3532605', '조각집', '조용히 사색하고 싶어서 찾은 조각집. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "고즈넉", "온마루"]'::jsonb, 35.846904, 129.210645, '2026-10-15T19:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000634', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2932921', '한울', '천천히 골목 걷다가 마주친 한울. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.237134, 127.265493, '2026-10-13T23:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000635', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2638488', '거제 관광모노레일', '거제 관광모노레일 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "주말나들이", "가족여행"]'::jsonb, 34.876418, 128.625395, '2026-10-15T15:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000636', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3438621', '희게', '근처 여행 코스로 희게 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.554282, 128.923586, '2026-10-14T05:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000637', '54500700-0000-4000-8000-000000000078', 'p-tourapi-264402', '화성어차', '천천히 골목 걷다가 마주친 화성어차. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 37.287915, 127.023703, '2026-10-15T11:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000638', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2607706', '곡전재', '오랜만에 여유 찾으러 곡전재 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "사색", "온마루"]'::jsonb, 35.203570, 127.513904, '2026-10-15T07:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000639', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2717594', '바늘꽃피우다', '부모님 모시고 바늘꽃피우다 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 36.781875, 126.452474, '2026-10-15T15:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000640', '54500700-0000-4000-8000-000000000135', 'p-tourapi-1600719', '정종수 고택', '드라이브 겸 나들이로 정종수 고택 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 35.773895, 126.858535, '2026-10-14T21:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000641', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3428354', '스타필드 시티 부천', '천천히 골목 걷다가 마주친 스타필드 시티 부천. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 37.461527, 126.813928, '2026-10-13T13:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000642', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2663054', '경주 춘추관', '근처 여행 코스로 경주 춘추관 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "데이트", "주말나들이", "온마루"]'::jsonb, 35.822778, 129.185834, '2026-10-15T10:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000643', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2820706', '폴링 인 진주', '조용히 사색하고 싶어서 찾은 폴링 인 진주. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.183188, 128.085518, '2026-10-15T17:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000644', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3510944', '주식회사영리캐롤', '예전부터 가보고 싶었던 주식회사영리캐롤 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.008325, 128.359602, '2026-10-14T03:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000645', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2576540', '풍정(풍정게스트하우스)', '평일 연차 쓰고 혼자 풍정(풍정게스트하우스) 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 35.840785, 129.230785, '2026-10-14T13:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000646', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2775017', '주식회사 하늘', '평일 연차 쓰고 혼자 주식회사 하늘 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "사색"]'::jsonb, 35.304934, 126.546587, '2026-10-15T09:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000647', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2717337', '소백산꽃차이야기', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "인생샷", "온마루"]'::jsonb, 36.883221, 128.563895, '2026-10-15T00:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000648', '54500700-0000-4000-8000-000000000083', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '조용히 사색하고 싶어서 찾은 아산 맹씨 행단(맹사성 고택). 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "산책로"]'::jsonb, 36.747083, 127.041871, '2026-10-14T08:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000649', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2792804', '금시당', '근처 여행 코스로 금시당 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.487230, 128.784021, '2026-10-14T05:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000650', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3511656', '하얀민들레마을(주식회사미진)', '오랜만에 여유 찾으러 하얀민들레마을(주식회사미진) 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 36.493609, 127.611311, '2026-10-14T09:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000651', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3453929', '경상북도교육청 발명체험교육관', '근처 여행 코스로 경상북도교육청 발명체험교육관 넣길 정말 잘했어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 35.833375, 129.212993, '2026-10-10T10:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000652', '54500700-0000-4000-8000-000000000128', 'p-tourapi-231909', '안동 예안이씨 충효당', '안동 예안이씨 충효당 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "혼자여행"]'::jsonb, 36.574451, 128.580208, '2026-10-08T20:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000653', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '근처 여행 코스로 제이한옥(JAY Hanok) 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "가족여행", "방문팁", "온마루"]'::jsonb, 37.582308, 126.987336, '2026-10-11T18:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000654', '54500700-0000-4000-8000-000000000092', 'p-tourapi-128653', '거창 동계종택', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "주말나들이", "방문팁"]'::jsonb, 35.755466, 127.828767, '2026-10-08T21:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000655', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3353909', '소잉(에이핸즈협동조합)', '조용히 사색하고 싶어서 찾은 소잉(에이핸즈협동조합). 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.207714, 126.865083, '2026-10-10T15:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000656', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3447048', '사우당 종택', '기대 이상으로 너무 좋았던 사우당 종택! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "가족여행", "사진맛집"]'::jsonb, 35.828256, 128.214952, '2026-10-12T09:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000657', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3102212', '한옥마을숙박 가인당', '해 질 무렵에 한옥마을숙박 가인당 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.812323, 127.151861, '2026-10-11T16:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000658', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3511603', '수달궁(문화살롱주식회사)', '오랜만에 여유 찾으러 수달궁(문화살롱주식회사) 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.864580, 127.123890, '2026-10-08T19:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000659', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2611575', '양천생활안전체험교육관', '기대 이상으로 너무 좋았던 양천생활안전체험교육관! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "가족여행", "온마루"]'::jsonb, 37.516780, 126.863744, '2026-10-08T19:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000660', '54500700-0000-4000-8000-000000000202', 'p-tourapi-231932', '탁청정종가', '오랜만에 여유 찾으러 탁청정종가 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 36.673285, 128.801397, '2026-10-10T05:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000661', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2792804', '금시당', '해 질 무렵에 금시당 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.487230, 128.784021, '2026-10-10T08:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000662', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2996825', '애플트리 힐링팜', '예전부터 가보고 싶었던 애플트리 힐링팜 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.557187, 127.099039, '2026-10-10T22:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000663', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2623585', '별궁', '비 오는 날 운치 찾아 별궁 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 36.940750, 126.301319, '2026-10-10T12:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000664', '54500700-0000-4000-8000-000000000123', 'p-tourapi-1626349', '팔공산 케이블카', '주말에 친구들이랑 팔공산 케이블카 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.990847, 128.694870, '2026-10-10T21:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000665', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3532948', '하녹명당', '하녹명당 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "풍경맛집"]'::jsonb, 35.836630, 129.211832, '2026-10-10T00:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000666', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2706484', '3917마중', '해 질 무렵에 3917마중 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 35.033297, 126.710840, '2026-10-11T03:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000667', '54500700-0000-4000-8000-000000000058', 'p-tourapi-129030', '전주유씨 무실종택', '전주유씨 무실종택 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.553440, 128.923692, '2026-10-10T06:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000668', '54500700-0000-4000-8000-000000000128', 'p-tourapi-2777043', '김택준가옥', '해 질 무렵에 김택준가옥 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.971882, 128.759283, '2026-10-10T18:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000669', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2715382', '여송정', '부모님 모시고 여송정 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 37.477472, 128.724527, '2026-10-08T16:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000670', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3438567', '스테이 자하', '천천히 골목 걷다가 마주친 스테이 자하. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "산책로", "온마루"]'::jsonb, 37.891841, 127.724494, '2026-10-12T05:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000671', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2819607', '드로잉라이프', '조용히 사색하고 싶어서 찾은 드로잉라이프. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 34.951259, 127.483463, '2026-10-10T18:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000672', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3533130', '대전별서', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "산책로", "고즈넉"]'::jsonb, 36.286024, 127.448086, '2026-10-10T11:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000673', '54500700-0000-4000-8000-000000000074', 'p-tourapi-3353949', '㈜ 희품씨', '해 질 무렵에 ㈜ 희품씨 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 35.567161, 129.112429, '2026-10-10T09:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000674', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3438295', '함한옥스테이', '조용히 사색하고 싶어서 찾은 함한옥스테이. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "풍경맛집", "산책로"]'::jsonb, 37.582494, 126.987131, '2026-10-11T20:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000675', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2819644', '적정온도(순향가)', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.872833, 127.528064, '2026-10-12T02:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000676', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2587355', '소이한옥', '천천히 골목 걷다가 마주친 소이한옥. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 35.834849, 129.211676, '2026-10-08T16:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000677', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2594862', '향우당', '조용히 사색하고 싶어서 찾은 향우당. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.602705, 128.907270, '2026-10-11T12:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000678', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2783558', '필운동 홍건익 가옥', '비 오는 날 운치 찾아 필운동 홍건익 가옥 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 37.577918, 126.968880, '2026-10-12T12:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000679', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2570188', '청풍헌(시랑골한옥스테이)', '드라이브 겸 나들이로 청풍헌(시랑골한옥스테이) 선택했는데 대만족! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.979639, 127.233292, '2026-10-10T14:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000680', '54500700-0000-4000-8000-000000000115', 'p-tourapi-129046', '서벽고택', '평일 연차 쓰고 혼자 서벽고택 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 36.458625, 129.022353, '2026-10-11T13:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000681', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3072197', '오롯이, 한옥', '부모님 모시고 오롯이, 한옥 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 37.580005, 126.968005, '2026-10-11T11:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000682', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3056873', '영암 집영재', '드라이브 겸 나들이로 영암 집영재 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 34.762693, 126.533766, '2026-10-11T12:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000683', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2647026', '석가헌', '평일 연차 쓰고 혼자 석가헌 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "풍경맛집"]'::jsonb, 37.719017, 128.904867, '2026-10-12T09:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000684', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2598597', '덕여재', '덕여재 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.540676, 128.516537, '2026-10-10T00:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000685', '54500700-0000-4000-8000-000000000177', 'p-tourapi-635593', '갈중이(천연염색체험)', '근처 여행 코스로 갈중이(천연염색체험) 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "방문팁", "사진맛집"]'::jsonb, 33.235113, 126.313647, '2026-10-08T19:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000686', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2699326', '월출산 청풍명월', '기대 이상으로 너무 좋았던 월출산 청풍명월! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 34.769877, 126.654557, '2026-10-10T23:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000687', '54500700-0000-4000-8000-000000000109', 'p-tourapi-319577', '경주 독락당', '해 질 무렵에 경주 독락당 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 36.016516, 129.160076, '2026-10-10T16:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000688', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3452786', '시흥시청소년수련관', 'SNS에서 사진 보고 찾아간 시흥시청소년수련관, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 37.446487, 126.797388, '2026-10-11T08:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000689', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2606219', '영천전투메모리얼파크', '부모님 모시고 영천전투메모리얼파크 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "인생샷", "가족여행", "온마루"]'::jsonb, 35.973412, 128.926969, '2026-10-12T03:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000690', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3102073', '오원 스테이', '비 오는 날 운치 찾아 오원 스테이 다녀왔어요. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.836305, 129.208901, '2026-10-12T00:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000691', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2621282', '사슴이랑배랑농원', '천천히 골목 걷다가 마주친 사슴이랑배랑농원. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 35.187698, 126.591355, '2026-10-11T03:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000692', '54500700-0000-4000-8000-000000000064', 'p-tourapi-130854', '해미 청소년 문화의집', '주말에 친구들이랑 해미 청소년 문화의집 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행", "방문팁"]'::jsonb, 36.710040, 126.542590, '2026-10-10T17:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000693', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2000725', '안동 수애당', '비 오는 날 운치 찾아 안동 수애당 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "데이트"]'::jsonb, 36.553329, 128.923380, '2026-10-10T13:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000694', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2702581', '강릉 오금집', '비 오는 날 운치 찾아 강릉 오금집 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.756371, 128.894042, '2026-10-12T01:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000695', '54500700-0000-4000-8000-000000000066', 'p-tourapi-126419', '다산초당', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집"]'::jsonb, 34.580650, 126.745073, '2026-10-11T20:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000696', '54500700-0000-4000-8000-000000000059', 'p-tourapi-129030', '전주유씨 무실종택', '기대 이상으로 너무 좋았던 전주유씨 무실종택! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 36.553440, 128.923692, '2026-10-10T15:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000697', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2768086', '한양 한옥마을점', '한양 한옥마을점 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.390854, 126.638901, '2026-10-09T17:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000698', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2594216', '전주한옥마당', '평일 연차 쓰고 혼자 전주한옥마당 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "혼자여행"]'::jsonb, 35.811342, 127.152134, '2026-10-10T17:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000699', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2624013', '별동산달빛아래', '주말에 친구들이랑 별동산달빛아래 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 36.439086, 129.027058, '2026-10-12T02:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000700', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2595021', '동락원', '평일 연차 쓰고 혼자 동락원 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "산책로", "고즈넉"]'::jsonb, 35.816866, 127.152651, '2026-10-10T14:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000701', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3531662', '최선평 가옥', '드라이브 겸 나들이로 최선평 가옥 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "방문팁", "가족여행", "온마루"]'::jsonb, 37.878304, 128.795960, '2026-10-08T21:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000702', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1621161', '제주 성읍마을 고창환 고택', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 33.387294, 126.800135, '2026-10-09T08:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000703', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3577428', '고창 전통예술체험마을', '부모님 모시고 고창 전통예술체험마을 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.430478, 126.701515, '2026-10-12T04:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000704', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2821565', '룰루낭만협동조합', '근처 여행 코스로 룰루낭만협동조합 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.235588, 128.881352, '2026-10-10T21:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000705', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3547622', '허균 허난설헌 기념공원 초희전통차체험관', '기대 이상으로 너무 좋았던 허균 허난설헌 기념공원 초희전통차체험관! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "가족여행", "인생샷"]'::jsonb, 37.790989, 128.910156, '2026-10-10T08:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000706', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3533008', '청택고택', '비 오는 날 운치 찾아 청택고택 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.591880, 127.015628, '2026-10-10T18:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000707', '54500700-0000-4000-8000-000000000097', 'p-tourapi-1992038', '귀애고택', '오랜만에 여유 찾으러 귀애고택 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 36.057015, 128.874144, '2026-10-09T19:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000708', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2458168', '일락당사랑채', '해 질 무렵에 일락당사랑채 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.816130, 127.152858, '2026-10-11T02:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000709', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '오랜만에 여유 찾으러 버들국수 (농업법인 주식회사 유화 ㈜) 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "사색", "온마루"]'::jsonb, 35.576300, 128.439048, '2026-10-09T17:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000710', '54500700-0000-4000-8000-000000000131', 'p-tourapi-3438629', '아늑', '오랜만에 여유 찾으러 아늑 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 36.554223, 128.757179, '2026-10-11T14:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000711', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2699354', '은혜당', '근처 여행 코스로 은혜당 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.507605, 129.400748, '2026-10-09T03:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000712', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3532956', '경주황리단길숙소 한옥스테이 목화', '주말에 친구들이랑 경주황리단길숙소 한옥스테이 목화 들렀는데 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.836671, 129.211196, '2026-10-08T16:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000713', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2795007', '화성 정수영 고택', '조용히 사색하고 싶어서 찾은 화성 정수영 고택. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.132502, 126.700661, '2026-10-09T02:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000714', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2715383', '수고당', '수고당 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "데이트"]'::jsonb, 37.484790, 128.848379, '2026-10-08T23:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000715', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2699328', '혜간헌', '기대 이상으로 너무 좋았던 혜간헌! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.462281, 127.116217, '2026-10-10T11:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000716', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2593235', '거목장민박', '거목장민박 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 34.508412, 126.606738, '2026-10-11T07:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000717', '54500700-0000-4000-8000-000000000153', 'p-tourapi-129514', '정읍 전봉준 유적', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "인생샷", "온마루"]'::jsonb, 35.670914, 126.814519, '2026-10-12T09:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000718', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2638441', '제주탐나라공화국', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 33.334512, 126.325686, '2026-10-11T13:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000719', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2804370', '화담재', '평일 연차 쓰고 혼자 화담재 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 34.739037, 126.716758, '2026-10-08T15:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000720', '54500700-0000-4000-8000-000000000086', 'p-tourapi-128594', '창녕 석리 성씨고가', '창녕 석리 성씨고가 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색"]'::jsonb, 35.556828, 128.459572, '2026-10-11T02:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000721', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2358186', '쌍산재', 'SNS에서 사진 보고 찾아간 쌍산재, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.215716, 127.498082, '2026-10-11T10:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000722', '54500700-0000-4000-8000-000000000098', 'p-tourapi-1081744', '한국전통음식문화체험관(정강원)', '드라이브 겸 나들이로 한국전통음식문화체험관(정강원) 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 37.570880, 128.408077, '2026-10-12T09:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000723', '54500700-0000-4000-8000-000000000128', 'p-tourapi-1871270', '맥산댁', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.667289, 128.228714, '2026-10-12T00:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000724', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3006699', '어린이농장학농원', '근처 여행 코스로 어린이농장학농원 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 37.104514, 127.110738, '2026-10-10T08:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000725', '54500700-0000-4000-8000-000000000133', 'p-tourapi-130938', '광나루안전체험관', '광나루안전체험관 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 37.551311, 127.077162, '2026-10-10T09:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000726', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2717604', '어슬티굿밤', '기대 이상으로 너무 좋았던 어슬티굿밤! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.487826, 126.822648, '2026-10-12T12:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000727', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3453166', '원주교육문화관 독도체험관', '주말에 친구들이랑 원주교육문화관 독도체험관 들렀는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.351708, 127.934949, '2026-10-10T19:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000728', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3483083', '간송옛집', 'SNS에서 사진 보고 찾아간 간송옛집, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "가족여행", "방문팁", "온마루"]'::jsonb, 37.664893, 127.028187, '2026-10-10T21:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000729', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2676000', '응정헌', '응정헌 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.640298, 126.939686, '2026-10-12T07:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000730', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438287', '사적인', '디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.574931, 126.982307, '2026-10-09T07:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000731', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2600498', '주실고택', '기대 이상으로 너무 좋았던 주실고택! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "가족여행"]'::jsonb, 36.735575, 128.619444, '2026-10-12T11:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000732', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2621282', '사슴이랑배랑농원', '조용히 사색하고 싶어서 찾은 사슴이랑배랑농원. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 35.187698, 126.591355, '2026-10-10T00:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000733', '54500700-0000-4000-8000-000000000073', 'p-tourapi-3533116', '덕만재', 'SNS에서 사진 보고 찾아간 덕만재, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "사진맛집", "온마루"]'::jsonb, 35.821940, 129.243965, '2026-10-09T01:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000734', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1596067', '김정회고가', '예전부터 가보고 싶었던 김정회고가 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "인생샷", "데이트"]'::jsonb, 35.439912, 126.659929, '2026-10-09T15:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000735', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3442142', '서울숲 곤충식물원', '해 질 무렵에 서울숲 곤충식물원 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이", "가족여행", "온마루"]'::jsonb, 37.543125, 127.041813, '2026-10-09T10:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000736', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3532773', '덕용재4.9', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 36.691817, 128.409670, '2026-10-11T01:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000737', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2638488', '거제 관광모노레일', '오랜만에 여유 찾으러 거제 관광모노레일 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 34.876418, 128.625395, '2026-10-09T07:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000738', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2633954', '산속등대 복합문화공간', '해 질 무렵에 산속등대 복합문화공간 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.869349, 127.252007, '2026-10-10T01:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000739', '54500700-0000-4000-8000-000000000173', 'p-tourapi-1579747', '거창 동호리 이씨고가', '주말에 친구들이랑 거창 동호리 이씨고가 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 35.798952, 127.927362, '2026-10-08T22:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000740', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2996749', '송금체험마을영농조합법인', '다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 35.713551, 128.720592, '2026-10-09T05:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000741', '54500700-0000-4000-8000-000000000152', 'p-tourapi-1884057', '태백산 한옥펜션', 'SNS에서 사진 보고 찾아간 태백산 한옥펜션, 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 37.134231, 128.951869, '2026-10-11T17:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000742', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2674014', '비체올린', '기대 이상으로 너무 좋았던 비체올린! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링", "산책로", "온마루"]'::jsonb, 33.349456, 126.218239, '2026-10-09T20:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000743', '54500700-0000-4000-8000-000000000072', 'p-tourapi-1579747', '거창 동호리 이씨고가', '부모님 모시고 거창 동호리 이씨고가 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "데이트", "주말나들이", "온마루"]'::jsonb, 35.798952, 127.927362, '2026-10-08T20:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000744', '54500700-0000-4000-8000-000000000137', 'p-tourapi-3072242', '이화당', '조용히 사색하고 싶어서 찾은 이화당. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 35.040146, 126.773917, '2026-10-11T03:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000745', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2598297', '목재고택', '드라이브 겸 나들이로 목재고택 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 36.742903, 128.863861, '2026-10-11T04:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000746', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2774723', '니지모리 스튜디오', '조용히 사색하고 싶어서 찾은 니지모리 스튜디오. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 37.879620, 127.092404, '2026-10-10T06:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000747', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2725025', '소찬 협동조합', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.513209, 126.814884, '2026-10-10T00:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000748', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1621410', '김용학가옥', '드라이브 겸 나들이로 김용학가옥 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "인생샷"]'::jsonb, 35.190386, 126.888220, '2026-10-10T19:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000749', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3425093', '서울 인디스페이스', '천천히 골목 걷다가 마주친 서울 인디스페이스. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["주말나들이", "사진맛집", "인생샷", "온마루"]'::jsonb, 37.557285, 126.925012, '2026-10-11T06:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000750', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2651450', '한옥혜윰', '기대 이상으로 너무 좋았던 한옥혜윰! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.811471, 127.152078, '2026-10-11T05:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000751', '54500700-0000-4000-8000-000000000116', 'p-tourapi-1883996', '취옹예술관', '비 오는 날 운치 찾아 취옹예술관 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 37.752549, 127.359939, '2026-10-12T07:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000752', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2604371', '노을한옥', '노을한옥 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 34.851191, 127.523245, '2026-10-09T14:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000753', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2650230', '문래예술공장', '오랜만에 여유 찾으러 문래예술공장 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 37.513281, 126.900160, '2026-10-11T06:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000754', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3448778', '양평 생활문화센터', '부모님 모시고 양평 생활문화센터 산책 겸 다녀왔습니다. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 37.499629, 127.476933, '2026-10-10T03:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000755', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2820838', '평창캠프닉', '조용히 사색하고 싶어서 찾은 평창캠프닉. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.578828, 128.331753, '2026-10-09T23:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000756', '54500700-0000-4000-8000-000000000121', 'p-tourapi-1619375', '조병수 가옥', '주말에 친구들이랑 조병수 가옥 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "데이트", "방문팁"]'::jsonb, 37.451170, 126.404425, '2026-10-10T09:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000757', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2595672', '하회 양진당', 'SNS에서 사진 보고 찾아간 하회 양진당, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 36.539006, 128.516673, '2026-10-11T05:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000758', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2994636', '다담한옥', 'SNS에서 사진 보고 찾아간 다담한옥, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 35.588333, 129.059829, '2026-10-09T05:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000759', '54500700-0000-4000-8000-000000000079', 'p-tourapi-1997202', '여수 해상케이블카', '오랜만에 여유 찾으러 여수 해상케이블카 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "혼자여행"]'::jsonb, 34.730797, 127.739326, '2026-10-10T11:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000760', '54500700-0000-4000-8000-000000000181', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.380351, 127.121194, '2026-10-10T00:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000761', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '드라이브 겸 나들이로 매죽헌2(매죽헌한옥민박) 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.069064, 127.401634, '2026-10-11T13:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000762', '54500700-0000-4000-8000-000000000107', 'p-tourapi-1972014', '삼락헌', '오랜만에 여유 찾으러 삼락헌 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.815648, 127.152720, '2026-10-10T18:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000763', '54500700-0000-4000-8000-000000000161', 'p-tourapi-1882853', '풍남헌', '천천히 골목 걷다가 마주친 풍남헌. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷", "사진맛집"]'::jsonb, 35.816784, 127.152314, '2026-10-11T01:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000764', '54500700-0000-4000-8000-000000000152', 'p-tourapi-1621155', '제주 성읍마을 고평오 고택', '비 오는 날 운치 찾아 제주 성읍마을 고평오 고택 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 33.385992, 126.801815, '2026-10-11T12:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000765', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2790490', '비손농장(포항체험잇다)', '해 질 무렵에 비손농장(포항체험잇다) 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 36.197610, 129.317423, '2026-10-08T16:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000766', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3021290', '자작자작협동조합', '날씨가 너무 맑아서 자작자작협동조합 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트", "방문팁"]'::jsonb, 36.969041, 127.932752, '2026-10-09T14:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000767', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2738663', '김환기고택', '기대 이상으로 너무 좋았던 김환기고택! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "주말나들이", "데이트"]'::jsonb, 34.752859, 126.121621, '2026-10-09T19:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000768', '54500700-0000-4000-8000-000000000173', 'p-tourapi-264284', '전북 전주 한옥마을 [슬로시티]', '평일 연차 쓰고 혼자 전북 전주 한옥마을 [슬로시티] 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 35.818273, 127.153613, '2026-10-08T14:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000769', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2662467', '만천하 알파인코스터', '부모님 모시고 만천하 알파인코스터 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.977675, 128.337071, '2026-10-09T04:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000770', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3511613', '전라감영양조장(전라감영주식회사)', '주말에 친구들이랑 전라감영양조장(전라감영주식회사) 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "인생샷", "사진맛집", "온마루"]'::jsonb, 35.817342, 127.145881, '2026-10-09T09:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000771', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2000648', '하회 북촌댁', '주말에 친구들이랑 하회 북촌댁 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "가족여행", "데이트", "온마루"]'::jsonb, 36.539740, 128.517876, '2026-10-09T18:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000772', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2615320', '봄의 왈츠 드라마 촬영지', '드라이브 겸 나들이로 봄의 왈츠 드라마 촬영지 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "주말나들이", "데이트", "온마루"]'::jsonb, 34.170111, 126.862381, '2026-10-11T12:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000773', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2612909', '해남 공재고택', '주말에 친구들이랑 해남 공재고택 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 34.440656, 126.518349, '2026-10-08T23:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000774', '54500700-0000-4000-8000-000000000084', 'p-tourapi-3536364', '속리산 테마파크', '근처 여행 코스로 속리산 테마파크 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "주말나들이"]'::jsonb, 36.498037, 127.792255, '2026-10-10T20:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000775', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3438379', '더 모먼트', '예전부터 가보고 싶었던 더 모먼트 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 37.577489, 126.970624, '2026-10-12T01:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000776', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2814147', '순천만숲', '근처 여행 코스로 순천만숲 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "사진맛집", "온마루"]'::jsonb, 34.897269, 127.506515, '2026-10-11T17:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000777', '54500700-0000-4000-8000-000000000171', 'p-tourapi-879633', '물드리네', '근처 여행 코스로 물드리네 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 33.322742, 126.226945, '2026-10-09T11:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000778', '54500700-0000-4000-8000-000000000121', 'p-tourapi-1623646', '권희문가옥', '예전부터 가보고 싶었던 권희문가옥 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.587661, 127.386260, '2026-10-09T17:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000779', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2613459', '공주 중학동 구 선교사 가옥', '부모님 모시고 공주 중학동 구 선교사 가옥 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "주말나들이", "인생샷", "온마루"]'::jsonb, 36.449491, 127.126458, '2026-10-12T02:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000780', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2605443', '사나래한옥', '천천히 골목 걷다가 마주친 사나래한옥. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트", "가족여행"]'::jsonb, 34.837123, 126.902747, '2026-10-08T17:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000781', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3426935', '구리문화재단', '드라이브 겸 나들이로 구리문화재단 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 37.595604, 127.129868, '2026-10-12T04:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000782', '54500700-0000-4000-8000-000000000167', 'p-tourapi-4012448', '검무한옥 호운당', '평일 연차 쓰고 혼자 검무한옥 호운당 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "사색"]'::jsonb, 36.575391, 128.511453, '2026-10-09T04:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000783', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2781621', '숫골', '평일 연차 쓰고 혼자 숫골 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집"]'::jsonb, 36.829947, 128.625224, '2026-10-10T02:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000784', '54500700-0000-4000-8000-000000000205', 'p-tourapi-1685586', '청풍 황석리 고가', '청풍 황석리 고가 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 37.005405, 128.170535, '2026-10-10T03:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000785', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2700309', '경주읍성한옥', '천천히 골목 걷다가 마주친 경주읍성한옥. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.849567, 129.211526, '2026-10-09T16:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000786', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2996133', '(주)손으로만드는수공예', '(주)손으로만드는수공예 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "주말나들이", "온마루"]'::jsonb, 36.099130, 127.492874, '2026-10-09T15:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000787', '54500700-0000-4000-8000-000000000157', 'p-tourapi-803988', '순천 용오름마을 [농촌전통테마마을]', '오랜만에 여유 찾으러 순천 용오름마을 [농촌전통테마마을] 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.092132, 127.202231, '2026-10-11T13:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000788', '54500700-0000-4000-8000-000000000179', 'p-tourapi-635593', '갈중이(천연염색체험)', '근처 여행 코스로 갈중이(천연염색체험) 넣길 정말 잘했어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 33.235113, 126.313647, '2026-10-10T22:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000789', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1433369', '괴산 김항묵 고택', '부모님 모시고 괴산 김항묵 고택 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 36.781516, 127.859430, '2026-10-11T04:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000790', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3438329', '안유재', '드라이브 겸 나들이로 안유재 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "가족여행", "온마루"]'::jsonb, 37.583322, 126.987706, '2026-10-08T22:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000791', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2939588', '행주커뮤니티센터', '비 오는 날 운치 찾아 행주커뮤니티센터 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 37.602622, 126.822865, '2026-10-08T22:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000792', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2357469', '훈몽재 유지', 'SNS에서 사진 보고 찾아간 훈몽재 유지, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행"]'::jsonb, 35.472605, 126.968424, '2026-10-10T19:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000793', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2725025', '소찬 협동조합', '천천히 골목 걷다가 마주친 소찬 협동조합. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "가족여행", "데이트"]'::jsonb, 36.513209, 126.814884, '2026-10-10T18:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000794', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3006699', '어린이농장학농원', '평일 연차 쓰고 혼자 어린이농장학농원 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.104514, 127.110738, '2026-10-08T22:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000795', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2600221', '박정우가옥', '날씨가 너무 맑아서 박정우가옥 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 36.734650, 128.619780, '2026-10-12T11:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000796', '54500700-0000-4000-8000-000000000166', 'p-tourapi-4072014', '스테이 화녹', '부모님 모시고 스테이 화녹 산책 겸 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 35.801123, 129.196940, '2026-10-10T09:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000797', '54500700-0000-4000-8000-000000000187', 'p-tourapi-319577', '경주 독락당', '부모님 모시고 경주 독락당 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 36.016516, 129.160076, '2026-10-11T21:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000798', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2996115', '야미야미팜(야미야미팜농업회사법인(주))', '부모님 모시고 야미야미팜(야미야미팜농업회사법인(주)) 산책 겸 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 34.704847, 126.614109, '2026-10-12T09:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000799', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2701356', '달빛한옥 수류화개', '근처 여행 코스로 달빛한옥 수류화개 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["인생샷", "데이트", "온마루"]'::jsonb, 34.739148, 126.717016, '2026-10-11T11:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000800', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2603889', '문행당', '기대 이상으로 너무 좋았던 문행당! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 36.913254, 128.741100, '2026-10-08T23:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000801', '54500700-0000-4000-8000-000000000188', 'p-tourapi-1872077', '석정댁', 'SNS에서 사진 보고 찾아간 석정댁, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.667053, 128.229073, '2026-10-02T08:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000802', '54500700-0000-4000-8000-000000000071', 'p-tourapi-4079535', '우구정가옥', '조용히 사색하고 싶어서 찾은 우구정가옥. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.205377, 128.377850, '2026-10-05T01:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000803', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1883367', '축구꿈나무집', '드라이브 겸 나들이로 축구꿈나무집 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.667336, 128.228967, '2026-10-06T20:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000804', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2721915', '밀양 월연정', 'SNS에서 사진 보고 찾아간 밀양 월연정, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.498663, 128.779954, '2026-10-06T01:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000805', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2595871', '나들한옥', '오랜만에 여유 찾으러 나들한옥 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 35.836116, 129.218364, '2026-10-01T20:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000806', '54500700-0000-4000-8000-000000000122', 'p-tourapi-127664', '최참판댁', '오랜만에 여유 찾으러 최참판댁 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.155594, 127.688090, '2026-10-06T11:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000807', '54500700-0000-4000-8000-000000000087', 'p-tourapi-1870849', '덕동댁', '오랜만에 여유 찾으러 덕동댁 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.666836, 128.227948, '2026-10-05T16:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000808', '54500700-0000-4000-8000-000000000202', 'p-tourapi-1583137', '이배원 가옥', '근처 여행 코스로 이배원 가옥 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집", "힐링"]'::jsonb, 36.060379, 126.910343, '2026-10-05T23:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000809', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3532999', '한옥,만월 프리미엄스테이', '기대 이상으로 너무 좋았던 한옥,만월 프리미엄스테이! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.862415, 128.598079, '2026-10-05T16:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000810', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3536364', '속리산 테마파크', '조용히 사색하고 싶어서 찾은 속리산 테마파크. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "풍경맛집", "산책로"]'::jsonb, 36.498037, 127.792255, '2026-10-06T21:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000811', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2855009', '한옥 생고기', '천천히 골목 걷다가 마주친 한옥 생고기. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "인생샷"]'::jsonb, 37.948869, 127.189507, '2026-10-07T14:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000812', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3454381', '디즈니스토어 현대프리미엄아울렛 대전점', '부모님 모시고 디즈니스토어 현대프리미엄아울렛 대전점 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "주말나들이", "인생샷", "온마루"]'::jsonb, 36.423483, 127.398534, '2026-10-06T02:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000813', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1865597', '가람초연재', '가람초연재 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "산책로", "온마루"]'::jsonb, 36.538990, 128.516242, '2026-10-01T14:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000814', '54500700-0000-4000-8000-000000000056', 'p-tourapi-4065036', '스테이로이', '부모님 모시고 스테이로이 산책 겸 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 36.102776, 127.486586, '2026-10-02T01:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000815', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2657838', '마차리폐광촌', '천천히 골목 걷다가 마주친 마차리폐광촌. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "산책로", "혼자여행", "온마루"]'::jsonb, 37.255195, 128.456002, '2026-10-05T03:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000816', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3511602', '주식회사조아지구', '천천히 골목 걷다가 마주친 주식회사조아지구. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 35.944178, 127.164482, '2026-10-07T17:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000817', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', '주말에 친구들이랑 꽃동네제빵소(꽃구움) 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "풍경맛집"]'::jsonb, 36.890582, 127.566334, '2026-10-04T09:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000818', '54500700-0000-4000-8000-000000000126', 'p-tourapi-4012463', '검무한옥 휴복당', '날씨가 너무 맑아서 검무한옥 휴복당 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 36.575421, 128.511679, '2026-10-07T22:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000819', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2668524', '이천백사 산수유영농조합법인(이천산수유마을)', '드라이브 겸 나들이로 이천백사 산수유영농조합법인(이천산수유마을) 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["데이트", "가족여행", "사진맛집", "온마루"]'::jsonb, 37.340828, 127.462314, '2026-10-07T20:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000820', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2707439', '스테이 데이 오프', '근처 여행 코스로 스테이 데이 오프 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "사진맛집"]'::jsonb, 37.577273, 126.971179, '2026-10-06T09:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000821', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2623585', '별궁', '조용히 사색하고 싶어서 찾은 별궁. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "고즈넉", "온마루"]'::jsonb, 36.940750, 126.301319, '2026-10-06T18:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000822', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3007507', '호수양조장', '조용히 사색하고 싶어서 찾은 호수양조장. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "산책로", "풍경맛집", "온마루"]'::jsonb, 37.872331, 127.731141, '2026-10-08T00:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000823', '54500700-0000-4000-8000-000000000115', 'p-tourapi-1390248', '장흥 오헌고택', '장흥 오헌고택 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 34.548911, 126.939716, '2026-10-07T04:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000824', '54500700-0000-4000-8000-000000000160', 'p-tourapi-1937772', '계룡 사계고택', '천천히 골목 걷다가 마주친 계룡 사계고택. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 36.265582, 127.271408, '2026-10-02T06:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000825', '54500700-0000-4000-8000-000000000164', 'p-tourapi-129514', '정읍 전봉준 유적', '천천히 골목 걷다가 마주친 정읍 전봉준 유적. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.670914, 126.814519, '2026-10-05T05:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000826', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3447048', '사우당 종택', '조용히 사색하고 싶어서 찾은 사우당 종택. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "풍경맛집", "온마루"]'::jsonb, 35.828256, 128.214952, '2026-10-04T15:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000827', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3438599', '이사빛1968 한옥스테이', '해 질 무렵에 이사빛1968 한옥스테이 방문했는데 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 36.564774, 128.737264, '2026-10-02T23:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000828', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3065503', '전주 대사습청', '드라이브 겸 나들이로 전주 대사습청 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 35.817686, 127.153545, '2026-10-08T13:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000829', '54500700-0000-4000-8000-000000000100', 'p-tourapi-1436162', '괴산 이창훈 고가', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 36.840840, 127.859224, '2026-10-01T16:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000830', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2606387', '예천군체육회활체험센터', 'SNS에서 사진 보고 찾아간 예천군체육회활체험센터, 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 36.634678, 128.468413, '2026-10-07T00:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000831', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2600265', '섬계고택', '섬계고택 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 36.734625, 128.618878, '2026-10-06T12:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000832', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3080477', '수원전통문화관', '날씨가 너무 맑아서 수원전통문화관 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로"]'::jsonb, 37.287470, 127.014633, '2026-10-06T20:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000833', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3469883', '서동선화한옥', '예전부터 가보고 싶었던 서동선화한옥 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷", "가족여행", "온마루"]'::jsonb, 36.291875, 126.927691, '2026-10-03T13:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000834', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3438412', '중림재', '해 질 무렵에 중림재 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "데이트"]'::jsonb, 37.558236, 126.967703, '2026-10-05T05:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000835', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2705419', '피크닉댕댕', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 37.866991, 127.108520, '2026-10-03T23:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000836', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2715385', '난포정(蘭浦亭)', '날씨가 너무 맑아서 난포정(蘭浦亭) 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 37.482477, 128.849626, '2026-10-05T11:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000837', '54500700-0000-4000-8000-000000000119', 'p-tourapi-1992038', '귀애고택', '날씨가 너무 맑아서 귀애고택 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 36.057015, 128.874144, '2026-10-07T19:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000838', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3351567', '충남안전체험관', '해 질 무렵에 충남안전체험관 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 36.821766, 127.191892, '2026-10-07T18:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000839', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2576865', '한옥산에산에', '천천히 골목 걷다가 마주친 한옥산에산에. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.198225, 128.558323, '2026-10-03T11:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000840', '54500700-0000-4000-8000-000000000088', 'p-tourapi-893974', '개평한옥마을', '주말에 친구들이랑 개평한옥마을 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 35.565814, 127.767372, '2026-10-06T01:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000841', '54500700-0000-4000-8000-000000000080', 'p-tourapi-126537', '북촌한옥마을', '기대 이상으로 너무 좋았던 북촌한옥마을! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.579053, 126.986706, '2026-10-04T18:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000842', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2620413', '병암고택', '드라이브 겸 나들이로 병암고택 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 36.558046, 129.128132, '2026-10-03T11:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000843', '54500700-0000-4000-8000-000000000105', 'p-tourapi-4039810', '스테이꼬리', '근처 여행 코스로 스테이꼬리 넣길 정말 잘했어요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 35.813146, 129.212540, '2026-10-08T09:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000844', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2717549', '순솝', 'SNS에서 사진 보고 찾아간 순솝, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 34.947674, 127.504205, '2026-10-06T04:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000845', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2544638', '바운스 트램폴린파크 동대구신세계백화점센터', '근처 여행 코스로 바운스 트램폴린파크 동대구신세계백화점센터 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 35.879720, 128.633215, '2026-10-06T17:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000846', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2604344', '락희원', '드라이브 겸 나들이로 락희원 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "가족여행", "방문팁"]'::jsonb, 35.837371, 129.212015, '2026-10-05T03:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000847', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '주말에 친구들이랑 아동청소년친화공간 꿈이랑 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 38.199574, 128.580209, '2026-10-07T06:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000848', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2613456', '금강아트센터', '조용히 사색하고 싶어서 찾은 금강아트센터. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.428931, 127.202146, '2026-10-07T20:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000849', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2610526', '안정궁 관광 한옥 펜션', '오랜만에 여유 찾으러 안정궁 관광 한옥 펜션 다녀왔습니다. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 34.945473, 128.398155, '2026-10-07T06:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000850', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2747760', '그라운드플래닛', '예전부터 가보고 싶었던 그라운드플래닛 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 37.433912, 127.011166, '2026-10-07T16:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000851', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2804370', '화담재', '부모님 모시고 화담재 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "인생샷", "데이트"]'::jsonb, 34.739037, 126.716758, '2026-10-08T10:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000852', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3438182', '여느날', '날씨가 너무 맑아서 여느날 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 37.576570, 126.969605, '2026-10-01T20:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000853', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3442142', '서울숲 곤충식물원', '비 오는 날 운치 찾아 서울숲 곤충식물원 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "사진맛집", "데이트"]'::jsonb, 37.543125, 127.041813, '2026-10-04T11:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000854', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2668091', '구림전통한옥민박', 'SNS에서 사진 보고 찾아간 구림전통한옥민박, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "데이트", "방문팁"]'::jsonb, 34.763510, 126.621510, '2026-10-04T01:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000855', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3452786', '시흥시청소년수련관', '주말에 친구들이랑 시흥시청소년수련관 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["인생샷", "가족여행", "데이트"]'::jsonb, 37.446487, 126.797388, '2026-10-04T08:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000856', '54500700-0000-4000-8000-000000000151', 'p-tourapi-129448', '두륜산케이블카', '평일 연차 쓰고 혼자 두륜산케이블카 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "사색", "힐링"]'::jsonb, 34.496818, 126.625341, '2026-10-04T21:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000857', '54500700-0000-4000-8000-000000000142', 'p-tourapi-1872077', '석정댁', '천천히 골목 걷다가 마주친 석정댁. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["가족여행", "데이트", "사진맛집", "온마루"]'::jsonb, 35.667053, 128.229073, '2026-10-07T05:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000858', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2663054', '경주 춘추관', '평일 연차 쓰고 혼자 경주 춘추관 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.822778, 129.185834, '2026-10-08T03:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000859', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3469883', '서동선화한옥', '드라이브 겸 나들이로 서동선화한옥 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "주말나들이", "방문팁"]'::jsonb, 36.291875, 126.927691, '2026-10-01T15:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000860', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3421909', '그런고로', '그런고로 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 35.157559, 129.064247, '2026-10-04T09:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000861', '54500700-0000-4000-8000-000000000157', 'p-tourapi-1971844', '필봉문화촌 취락원', '비 오는 날 운치 찾아 필봉문화촌 취락원 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.537413, 127.154646, '2026-10-01T23:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000862', '54500700-0000-4000-8000-000000000174', 'p-tourapi-1624505', '해남 민정기 가옥', '드라이브 겸 나들이로 해남 민정기 가옥 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 34.542754, 126.568428, '2026-10-08T02:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000863', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3533116', '덕만재', '오랜만에 여유 찾으러 덕만재 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 35.821940, 129.243965, '2026-10-02T01:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000864', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3013272', '무계원', '드라이브 겸 나들이로 무계원 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 37.591792, 126.963611, '2026-10-05T19:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000865', '54500700-0000-4000-8000-000000000202', 'p-tourapi-801918', '무안 감풀마을 [농촌전통테마]', '조용히 사색하고 싶어서 찾은 무안 감풀마을 [농촌전통테마]. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.061300, 126.406043, '2026-10-08T03:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000866', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2996647', '정촌유기농원', '오랜만에 여유 찾으러 정촌유기농원 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.425472, 126.672099, '2026-10-07T08:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000867', '54500700-0000-4000-8000-000000000154', 'p-tourapi-3072218', '오히', '날씨가 너무 맑아서 오히 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 35.824170, 129.212582, '2026-10-06T00:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000868', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1372956', '이상화 고택', '부모님 모시고 이상화 고택 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.867231, 128.587976, '2026-10-01T15:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000869', '54500700-0000-4000-8000-000000000177', 'p-tourapi-126537', '북촌한옥마을', '예전부터 가보고 싶었던 북촌한옥마을 드디어 방문! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.579053, 126.986706, '2026-10-08T09:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000870', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2724392', '은평한옥마을', '조용히 사색하고 싶어서 찾은 은평한옥마을. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 37.641395, 126.939225, '2026-10-07T15:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000871', '54500700-0000-4000-8000-000000000129', 'p-tourapi-128645', '춘천최재근가옥', '천천히 골목 걷다가 마주친 춘천최재근가옥. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 37.843130, 127.727499, '2026-10-03T14:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000872', '54500700-0000-4000-8000-000000000173', 'p-tourapi-894145', '명품옻골 1616 협동조합', '예전부터 가보고 싶었던 명품옻골 1616 협동조합 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 35.907762, 128.686842, '2026-10-02T20:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000873', '54500700-0000-4000-8000-000000000073', 'p-tourapi-3511018', '주식회사어반힐링', '날씨가 너무 맑아서 주식회사어반힐링 한 바퀴 돌고 왔네요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.111832, 128.965198, '2026-10-04T03:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000874', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2603913', '후연지한옥펜션', '예전부터 가보고 싶었던 후연지한옥펜션 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 35.780468, 129.204095, '2026-10-03T01:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000875', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3101971', '나모:온', '주말에 친구들이랑 나모:온 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "데이트", "주말나들이"]'::jsonb, 34.951409, 127.481427, '2026-10-07T20:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000876', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2718257', '서울웨이브아트센터', '천천히 골목 걷다가 마주친 서울웨이브아트센터. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 37.518441, 127.007298, '2026-10-07T20:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000877', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2744514', '합천목재문화체험장', '예전부터 가보고 싶었던 합천목재문화체험장 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "사색", "온마루"]'::jsonb, 35.548494, 128.073079, '2026-10-03T12:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000878', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2722936', '아모레 성수', '천천히 골목 걷다가 마주친 아모레 성수. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "산책로", "온마루"]'::jsonb, 37.544603, 127.059070, '2026-10-05T07:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000879', '54500700-0000-4000-8000-000000000119', 'p-tourapi-127337', '당진 필경사', 'SNS에서 사진 보고 찾아간 당진 필경사, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 36.952004, 126.771723, '2026-10-06T07:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000880', '54500700-0000-4000-8000-000000000072', 'p-tourapi-128542', '안성 정무공 오정방 고택', '비 오는 날 운치 찾아 안성 정무공 오정방 고택 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.045771, 127.185867, '2026-10-04T10:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000881', '54500700-0000-4000-8000-000000000139', 'p-tourapi-1867806', '공주한옥마을', '드라이브 겸 나들이로 공주한옥마을 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 36.464500, 127.108700, '2026-10-08T06:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000882', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3510971', '컬러브릿지협동조합', '드라이브 겸 나들이로 컬러브릿지협동조합 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "힐링"]'::jsonb, 35.141137, 126.916908, '2026-10-07T16:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000883', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2604833', '해로당', 'SNS에서 사진 보고 찾아간 해로당, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 34.739740, 126.717855, '2026-10-01T19:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000884', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2696528', '토박이숙박', '드라이브 겸 나들이로 토박이숙박 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "힐링"]'::jsonb, 35.813664, 127.152175, '2026-10-03T03:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000885', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3540259', '한옥스테이 파인앤프렌즈', '평일 연차 쓰고 혼자 한옥스테이 파인앤프렌즈 다녀옴. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 37.776189, 128.933054, '2026-10-03T13:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000886', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2586166', '황토한옥고마', '부모님 모시고 황토한옥고마 산책 겸 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 36.461445, 127.122366, '2026-10-05T22:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000887', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3438041', '유선재', '조용히 사색하고 싶어서 찾은 유선재. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 37.490512, 127.709293, '2026-10-03T12:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000888', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '오랜만에 여유 찾으러 경주 황리단길 한옥 독채 풀빌라 무와 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "힐링", "산책로"]'::jsonb, 35.835985, 129.207990, '2026-10-03T06:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000889', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2569980', '온고을', '조용히 사색하고 싶어서 찾은 온고을. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.812253, 127.152459, '2026-10-07T12:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000890', '54500700-0000-4000-8000-000000000092', 'p-tourapi-4074857', '미옥스테이', '날씨가 너무 맑아서 미옥스테이 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 35.866838, 128.612096, '2026-10-02T23:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000891', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2717492', '비녀랑 한복이랑', '날씨가 너무 맑아서 비녀랑 한복이랑 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.629768, 127.287278, '2026-10-03T07:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000892', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3452166', '커넥트현대', 'SNS에서 사진 보고 찾아간 커넥트현대, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "데이트", "사진맛집"]'::jsonb, 35.141341, 129.058601, '2026-10-05T11:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000893', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2717600', '이플아토', '근처 여행 코스로 이플아토 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "가족여행", "방문팁"]'::jsonb, 36.452038, 126.803592, '2026-10-05T11:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000894', '54500700-0000-4000-8000-000000000090', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '전주 풍패지관 (전주객사) 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "풍경맛집", "사색", "온마루"]'::jsonb, 35.818500, 127.145400, '2026-10-05T17:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000895', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1991992', '고택 한옥에서', '기대 이상으로 너무 좋았던 고택 한옥에서! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.237659, 127.020591, '2026-10-01T14:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000896', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3438082', '안길사가', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.577486, 126.984503, '2026-10-03T06:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000897', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2822187', '꽃동네제빵소(꽃구움)', 'SNS에서 사진 보고 찾아간 꽃동네제빵소(꽃구움), 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 36.890582, 127.566334, '2026-10-03T09:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000898', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3438545', '예맥당 한옥스테이', '예전부터 가보고 싶었던 예맥당 한옥스테이 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 37.640767, 126.938895, '2026-10-07T00:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000899', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2993194', '위라이드 서울전차', '오랜만에 여유 찾으러 위라이드 서울전차 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "혼자여행"]'::jsonb, 37.570898, 126.979937, '2026-10-03T11:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000900', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2650230', '문래예술공장', '근처 여행 코스로 문래예술공장 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 37.513281, 126.900160, '2026-10-01T23:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000901', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3438735', '소월담', '기대 이상으로 너무 좋았던 소월담! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 37.578825, 126.985898, '2026-10-06T22:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000902', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2514834', '죽정분교(구,죽정초등학교)', '천천히 골목 걷다가 마주친 죽정분교(구,죽정초등학교). 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 38.470473, 128.419768, '2026-10-07T05:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000903', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3072242', '이화당', '천천히 골목 걷다가 마주친 이화당. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 35.040146, 126.773917, '2026-10-08T06:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000904', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3532759', '스테이 희와', '스테이 희와 다녀왔어요! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 37.589255, 126.998038, '2026-10-07T16:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000905', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2576343', '뜰안채', '날씨가 너무 맑아서 뜰안채 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 35.817136, 127.149337, '2026-10-06T02:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000906', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2587355', '소이한옥', '비 오는 날 운치 찾아 소이한옥 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "사색"]'::jsonb, 35.834849, 129.211676, '2026-10-02T11:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000907', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2820629', '부여북포한옥마을', '조용히 사색하고 싶어서 찾은 부여북포한옥마을. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "사색"]'::jsonb, 36.292906, 126.924516, '2026-10-02T06:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000908', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3425093', '서울 인디스페이스', '달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 37.557285, 126.925012, '2026-10-03T03:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000909', '54500700-0000-4000-8000-000000000169', 'p-tourapi-3337799', '레이홉', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 35.542409, 129.307407, '2026-10-06T15:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000910', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2795956', '양평 창대리 고가', '주말에 친구들이랑 양평 창대리 고가 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "데이트", "사진맛집"]'::jsonb, 37.471103, 127.505915, '2026-10-04T06:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000911', '54500700-0000-4000-8000-000000000110', 'p-tourapi-4079535', '우구정가옥', '예전부터 가보고 싶었던 우구정가옥 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "고즈넉", "힐링"]'::jsonb, 37.205377, 128.377850, '2026-10-06T01:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000912', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3532989', '예선재', '해 질 무렵에 예선재 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 36.962072, 127.938133, '2026-10-03T03:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000913', '54500700-0000-4000-8000-000000000113', 'p-tourapi-1606009', '삼청동오위장김춘영가옥', '평일 연차 쓰고 혼자 삼청동오위장김춘영가옥 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 37.558800, 126.994800, '2026-10-07T05:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000914', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3532883', '소풍한옥풀빌라', '부모님 모시고 소풍한옥풀빌라 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 35.855854, 129.267029, '2026-10-07T03:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000915', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2789827', '제천 김세균 고가', '제천 김세균 고가 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "주말나들이"]'::jsonb, 36.881984, 128.080349, '2026-10-02T09:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000916', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '조용히 사색하고 싶어서 찾은 락고재 컬쳐 라운지 애가헌. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "힐링"]'::jsonb, 37.582243, 126.983944, '2026-10-05T09:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000917', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3438379', '더 모먼트', '주말에 친구들이랑 더 모먼트 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 37.577489, 126.970624, '2026-10-02T07:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000918', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '조용히 사색하고 싶어서 찾은 (사)영남선비문화수련원(구암서원). 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.901625, 128.596853, '2026-10-08T08:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000919', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3543415', '주문진문화교육센터', '조용히 사색하고 싶어서 찾은 주문진문화교육센터. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.881902, 128.822300, '2026-10-04T16:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000920', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3438485', '다락재', '조용히 사색하고 싶어서 찾은 다락재. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링", "혼자여행", "온마루"]'::jsonb, 37.641231, 126.939842, '2026-10-05T19:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000921', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2996115', '야미야미팜(야미야미팜농업회사법인(주))', '오랜만에 여유 찾으러 야미야미팜(야미야미팜농업회사법인(주)) 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 34.704847, 126.614109, '2026-10-07T07:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000922', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3337799', '레이홉', '레이홉 다녀왔어요! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.542409, 129.307407, '2026-10-07T12:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000923', '54500700-0000-4000-8000-000000000147', 'p-tourapi-1626780', '예산 오추리 고택(정동호 가옥)', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["주말나들이", "데이트", "인생샷"]'::jsonb, 36.763845, 126.719911, '2026-10-05T07:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000924', '54500700-0000-4000-8000-000000000086', 'p-tourapi-4074856', '연림스테이', '비 오는 날 운치 찾아 연림스테이 다녀왔어요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.972113, 128.698835, '2026-10-01T16:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000925', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2602196', '의양리 권진사댁', '조용히 사색하고 싶어서 찾은 의양리 권진사댁. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "풍경맛집", "산책로", "온마루"]'::jsonb, 36.944795, 128.912231, '2026-10-04T17:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000926', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3459013', '월영광장', '월영광장 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 35.180228, 128.557804, '2026-10-02T15:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000927', '54500700-0000-4000-8000-000000000132', 'p-tourapi-1883070', '정재종택', '근처 여행 코스로 정재종택 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "사진맛집", "온마루"]'::jsonb, 36.559323, 128.915579, '2026-10-01T20:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000928', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2764323', '은평역사한옥박물관', '부모님 모시고 은평역사한옥박물관 산책 겸 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.640334, 126.938008, '2026-10-07T20:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000929', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2732271', '수작코리아', '주말에 친구들이랑 수작코리아 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.717640, 126.877254, '2026-10-02T13:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000930', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3080013', '에덴파크 단양', '오랜만에 여유 찾으러 에덴파크 단양 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "고즈넉", "힐링", "온마루"]'::jsonb, 36.929836, 128.334011, '2026-10-04T04:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000931', '54500700-0000-4000-8000-000000000192', 'p-tourapi-1992543', '송정고택', '천천히 골목 걷다가 마주친 송정고택. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "인생샷"]'::jsonb, 36.435930, 129.026245, '2026-10-03T12:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000932', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3438653', '호호재', '근처 여행 코스로 호호재 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 36.560299, 128.710802, '2026-10-02T18:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000933', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2613254', '도봉서당', '해 질 무렵에 도봉서당 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.827489, 129.184732, '2026-10-05T16:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000934', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2706047', '한옥 게스트하우스 동촌재', '날씨가 너무 맑아서 한옥 게스트하우스 동촌재 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 37.580111, 126.969855, '2026-10-02T21:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000935', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2932871', '한복입고 유유자적 (주식회사고영)', '근처 여행 코스로 한복입고 유유자적 (주식회사고영) 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 34.760007, 126.623276, '2026-10-07T20:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000936', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1606014', '순정효황후윤씨친가', '평일 연차 쓰고 혼자 순정효황후윤씨친가 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "힐링", "산책로", "온마루"]'::jsonb, 37.558678, 126.993992, '2026-10-08T01:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000937', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3421909', '그런고로', '부모님 모시고 그런고로 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 35.157559, 129.064247, '2026-10-02T19:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000938', '54500700-0000-4000-8000-000000000128', 'p-tourapi-252606', '영암 삼성당 고택', '해 질 무렵에 영암 삼성당 고택 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 34.829680, 126.733079, '2026-10-07T06:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000939', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3438735', '소월담', '근처 여행 코스로 소월담 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 37.578825, 126.985898, '2026-10-04T15:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000940', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2747760', '그라운드플래닛', 'SNS에서 사진 보고 찾아간 그라운드플래닛, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "인생샷", "가족여행"]'::jsonb, 37.433912, 127.011166, '2026-10-08T04:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000941', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2561208', '디키디키', '평일 연차 쓰고 혼자 디키디키 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 37.568196, 127.010313, '2026-10-05T20:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000942', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2574064', '백미응서재', '기대 이상으로 너무 좋았던 백미응서재! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.141612, 126.690753, '2026-10-01T15:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000943', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3101956', '죽록정사', 'SNS에서 사진 보고 찾아간 죽록정사, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.226528, 127.485989, '2026-10-02T21:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000944', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2574250', '라온한옥꿀잠', '평일 연차 쓰고 혼자 라온한옥꿀잠 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "혼자여행", "산책로", "온마루"]'::jsonb, 35.815836, 127.154314, '2026-10-06T10:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000945', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2576546', '홍시(전주한옥마을 숙박 홍시)', '부모님 모시고 홍시(전주한옥마을 숙박 홍시) 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 35.815306, 127.153014, '2026-10-05T17:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000946', '54500700-0000-4000-8000-000000000065', 'p-tourapi-128644', '춘천김정은가옥', '천천히 골목 걷다가 마주친 춘천김정은가옥. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "산책로", "혼자여행", "온마루"]'::jsonb, 37.844972, 127.729000, '2026-10-06T11:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000947', '54500700-0000-4000-8000-000000000145', 'p-tourapi-1373030', '서상돈 고택', '예전부터 가보고 싶었던 서상돈 고택 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.867165, 128.587812, '2026-10-07T00:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000948', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3532883', '소풍한옥풀빌라', '근처 여행 코스로 소풍한옥풀빌라 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "방문팁", "데이트"]'::jsonb, 35.855854, 129.267029, '2026-10-04T05:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000949', '54500700-0000-4000-8000-000000000168', 'p-tourapi-1018702', '국제시장 먹자골목', '천천히 골목 걷다가 마주친 국제시장 먹자골목. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "인생샷", "사진맛집", "온마루"]'::jsonb, 35.101131, 129.028079, '2026-10-08T09:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000950', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1245865', '심산기념문화센터', '드라이브 겸 나들이로 심산기념문화센터 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.498535, 126.990730, '2026-10-04T20:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000951', '54500700-0000-4000-8000-000000000088', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', '드라이브 겸 나들이로 춘천 강언덕마을 [농촌전통테마] 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 37.678664, 127.613691, '2026-10-07T09:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000952', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2613318', '이가한옥', '비 오는 날 운치 찾아 이가한옥 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.816647, 127.155597, '2026-10-05T11:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000953', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3421909', '그런고로', '근처 여행 코스로 그런고로 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.157559, 129.064247, '2026-10-05T07:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000954', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2699607', '모꼬지', '예전부터 가보고 싶었던 모꼬지 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 35.811895, 127.156228, '2026-10-08T05:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000955', '54500700-0000-4000-8000-000000000093', 'p-tourapi-1883593', '월인당', '기대 이상으로 너무 좋았던 월인당! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "주말나들이", "가족여행"]'::jsonb, 34.777745, 126.612364, '2026-10-07T06:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000956', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3469953', '하녹집', '주말에 친구들이랑 하녹집 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁", "주말나들이"]'::jsonb, 36.564721, 128.736503, '2026-10-07T03:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000957', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2996855', '버금상점', '주말에 친구들이랑 버금상점 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 34.972636, 128.323866, '2026-10-05T22:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000958', '54500700-0000-4000-8000-000000000141', 'p-tourapi-129030', '전주유씨 무실종택', '오랜만에 여유 찾으러 전주유씨 무실종택 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.553440, 128.923692, '2026-10-05T14:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000959', '54500700-0000-4000-8000-000000000191', 'p-tourapi-1872077', '석정댁', 'SNS에서 사진 보고 찾아간 석정댁, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 35.667053, 128.229073, '2026-10-04T11:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000960', '54500700-0000-4000-8000-000000000104', 'p-tourapi-1872145', '설아다원', '날씨가 너무 맑아서 설아다원 한 바퀴 돌고 왔네요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "데이트", "인생샷"]'::jsonb, 34.468122, 126.660100, '2026-10-07T12:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000961', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3101960', '한옥스테이 연', '기대 이상으로 너무 좋았던 한옥스테이 연! 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 36.734623, 127.405067, '2026-10-07T22:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000962', '54500700-0000-4000-8000-000000000190', 'p-tourapi-250372', '의성김씨 학봉종택', '의성김씨 학봉종택 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "주말나들이", "방문팁"]'::jsonb, 36.609676, 128.669221, '2026-10-03T07:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000963', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2572817', '옥산정사 독락당', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 36.016958, 129.159976, '2026-10-06T07:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000964', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2620236', '예다움', '날씨가 너무 맑아서 예다움 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "풍경맛집", "사색", "온마루"]'::jsonb, 35.273709, 127.936778, '2026-10-07T04:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000965', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3532767', '도동유교문화관', '부모님 모시고 도동유교문화관 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.701990, 128.371548, '2026-10-06T09:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000966', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2663065', '휴휴당', '비 오는 날 운치 찾아 휴휴당 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.835513, 129.212276, '2026-10-06T04:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000967', '54500700-0000-4000-8000-000000000196', 'p-tourapi-4012448', '검무한옥 호운당', '해 질 무렵에 검무한옥 호운당 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 36.575391, 128.511453, '2026-10-06T14:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000968', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2569824', '흥해배씨 임연재종택', '해 질 무렵에 흥해배씨 임연재종택 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 36.550011, 128.791685, '2026-10-07T03:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000969', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2662883', '경주 오릉 한옥', '조용히 사색하고 싶어서 찾은 경주 오릉 한옥. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "힐링", "혼자여행", "온마루"]'::jsonb, 35.825584, 129.207502, '2026-10-06T23:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000970', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3511230', '김씨네마카롱공장(주식회사필링)', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 35.490603, 129.435739, '2026-10-02T01:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000971', '54500700-0000-4000-8000-000000000104', 'p-tourapi-129514', '정읍 전봉준 유적', '근처 여행 코스로 정읍 전봉준 유적 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "주말나들이", "인생샷"]'::jsonb, 35.670914, 126.814519, '2026-10-02T13:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000972', '54500700-0000-4000-8000-000000000081', 'p-tourapi-129035', '안동 묵계서원 및 보백당 종택', '조용히 사색하고 싶어서 찾은 안동 묵계서원 및 보백당 종택. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.417486, 128.915394, '2026-10-02T11:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000973', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2638441', '제주탐나라공화국', '제주탐나라공화국 다녀왔어요! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "사색"]'::jsonb, 33.334512, 126.325686, '2026-10-08T07:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000974', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2611575', '양천생활안전체험교육관', '천천히 골목 걷다가 마주친 양천생활안전체험교육관. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 37.516780, 126.863744, '2026-10-02T20:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000975', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3532757', '곰곰하우스', '부모님 모시고 곰곰하우스 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.581397, 126.986473, '2026-10-05T01:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000976', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3081677', '운림공원', '오랜만에 여유 찾으러 운림공원 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 34.465100, 126.292600, '2026-10-07T10:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000977', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2850614', '스탈릿성수', '드라이브 겸 나들이로 스탈릿성수 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 37.544494, 127.055473, '2026-10-04T03:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000978', '54500700-0000-4000-8000-000000000102', 'p-tourapi-126375', '진도 운림산방', '기대 이상으로 너무 좋았던 진도 운림산방! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "풍경맛집"]'::jsonb, 34.466413, 126.308364, '2026-10-05T22:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000979', '54500700-0000-4000-8000-000000000150', 'p-tourapi-1972381', '서로', '평일 연차 쓰고 혼자 서로 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 35.815775, 127.153606, '2026-10-02T22:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000980', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2600248', '수춘제(김태길) 고택', '부모님 모시고 수춘제(김태길) 고택 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 36.734841, 128.618767, '2026-10-05T00:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000981', '54500700-0000-4000-8000-000000000161', 'p-tourapi-4071289', '함평 이재혁 가옥', '드라이브 겸 나들이로 함평 이재혁 가옥 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.066416, 126.512216, '2026-10-03T20:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000982', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3056595', '전주한옥마을역사관', '비 오는 날 운치 찾아 전주한옥마을역사관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 35.816007, 127.152938, '2026-10-08T07:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000983', '54500700-0000-4000-8000-000000000060', 'p-tourapi-3532595', '오브헤리티지', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "가족여행", "데이트", "온마루"]'::jsonb, 34.546627, 127.137142, '2026-10-01T20:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000984', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2715382', '여송정', '날씨가 너무 맑아서 여송정 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.477472, 128.724527, '2026-10-05T03:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000985', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3089931', '모영재', '평일 연차 쓰고 혼자 모영재 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 35.934271, 128.719016, '2026-10-08T07:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000986', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2595489', '동해한옥 동안재', '기대 이상으로 너무 좋았던 동해한옥 동안재! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 37.528246, 129.108618, '2026-10-02T16:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000987', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3067572', '점핑고', '근처 여행 코스로 점핑고 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 36.787725, 127.121480, '2026-10-02T00:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000988', '54500700-0000-4000-8000-000000000172', 'p-tourapi-1991992', '고택 한옥에서', '해 질 무렵에 고택 한옥에서 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 35.237659, 127.020591, '2026-10-06T14:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000989', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3438588', '유유가', '주말에 친구들이랑 유유가 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 34.955870, 127.483135, '2026-10-02T17:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000990', '54500700-0000-4000-8000-000000000153', 'p-tourapi-3541047', '주문진 관광안내센터', '예전부터 가보고 싶었던 주문진 관광안내센터 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "고즈넉", "온마루"]'::jsonb, 37.889982, 128.828574, '2026-10-05T18:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000991', '54500700-0000-4000-8000-000000000141', 'p-tourapi-4093690', '삼호정', '비 오는 날 운치 찾아 삼호정 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.464644, 126.624894, '2026-10-03T12:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000992', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2572908', '별바라기집', '주말에 친구들이랑 별바라기집 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉"]'::jsonb, 34.740867, 126.717738, '2026-10-08T02:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000993', '54500700-0000-4000-8000-000000000128', 'p-tourapi-250436', '아산 용궁댁', '날씨가 너무 맑아서 아산 용궁댁 한 바퀴 돌고 왔네요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 36.740537, 126.892613, '2026-10-02T21:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000994', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2509920', '울산중구생활문화센터', '근처 여행 코스로 울산중구생활문화센터 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.556530, 129.322163, '2026-10-05T11:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000995', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3065503', '전주 대사습청', '비 오는 날 운치 찾아 전주 대사습청 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.817686, 127.153545, '2026-10-03T17:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000996', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2769810', '오창 미래지 한옥마을', '천천히 골목 걷다가 마주친 오창 미래지 한옥마을. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 36.735102, 127.404736, '2026-10-03T19:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000997', '54500700-0000-4000-8000-000000000095', 'p-tourapi-127289', '괴산 홍범식 고가(벽초 홍명희 생가)', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "사진맛집", "데이트", "온마루"]'::jsonb, 36.813843, 127.794842, '2026-10-06T08:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000998', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2679044', '청향재', '평일 연차 쓰고 혼자 청향재 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.641706, 126.940197, '2026-10-05T05:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000000999', '54500700-0000-4000-8000-000000000121', 'p-tourapi-1081744', '한국전통음식문화체험관(정강원)', '천천히 골목 걷다가 마주친 한국전통음식문화체험관(정강원). 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["사진맛집", "가족여행", "주말나들이"]'::jsonb, 37.570880, 128.408077, '2026-10-01T18:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001000', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2622784', '소양고택 한옥스테이', '천천히 골목 걷다가 마주친 소양고택 한옥스테이. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트", "가족여행"]'::jsonb, 35.903680, 127.243089, '2026-10-03T12:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001001', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2992061', '씨파크', '비 오는 날 운치 찾아 씨파크 다녀왔어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 35.544428, 128.053794, '2026-09-19T11:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001002', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2792819', '박시춘옛집', '평일 연차 쓰고 혼자 박시춘옛집 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 35.492034, 128.755694, '2026-09-19T00:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001003', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3438160', '통인 1939', '평일 연차 쓰고 혼자 통인 1939 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.579028, 126.970980, '2026-09-17T12:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001004', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2997257', '청담1942', '근처 여행 코스로 청담1942 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.899777, 128.230155, '2026-09-20T00:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001005', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2775304', '아올', '날씨가 너무 맑아서 아올 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 35.276153, 126.509438, '2026-09-19T11:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001006', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2576343', '뜰안채', '날씨가 너무 맑아서 뜰안채 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행"]'::jsonb, 35.817136, 127.149337, '2026-09-22T08:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001007', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3438586', '휴휴가', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.955134, 127.480782, '2026-09-19T13:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001008', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1626349', '팔공산 케이블카', '근처 여행 코스로 팔공산 케이블카 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트", "가족여행", "온마루"]'::jsonb, 35.990847, 128.694870, '2026-09-18T05:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001009', '54500700-0000-4000-8000-000000000056', 'p-tourapi-3072227', '아담한옥', '근처 여행 코스로 아담한옥 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.580389, 126.969677, '2026-09-25T00:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001010', '54500700-0000-4000-8000-000000000195', 'p-tourapi-2050197', '어련당', '예전부터 가보고 싶었던 어련당 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.574050, 129.350277, '2026-09-20T03:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001011', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2620380', '풍송재', '부모님 모시고 풍송재 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "주말나들이", "데이트"]'::jsonb, 36.574374, 128.514189, '2026-09-21T10:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001012', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2706568', '왕의지밀', '기대 이상으로 너무 좋았던 왕의지밀! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.799797, 127.178462, '2026-09-17T17:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001013', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3392012', '한강시원지체험관', '평일 연차 쓰고 혼자 한강시원지체험관 다녀옴. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.720010, 128.602322, '2026-09-27T17:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001014', '54500700-0000-4000-8000-000000000184', 'p-tourapi-1870849', '덕동댁', '주말에 친구들이랑 덕동댁 들렀는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 35.666836, 128.227948, '2026-09-16T10:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001015', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2744514', '합천목재문화체험장', '기대 이상으로 너무 좋았던 합천목재문화체험장! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["주말나들이", "가족여행", "온마루"]'::jsonb, 35.548494, 128.073079, '2026-09-23T04:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001016', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2613097', '월암재', '비 오는 날 운치 찾아 월암재 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.815671, 129.216207, '2026-09-21T03:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001017', '54500700-0000-4000-8000-000000000202', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', '기대 이상으로 너무 좋았던 춘천 강언덕마을 [농촌전통테마]! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "주말나들이", "데이트", "온마루"]'::jsonb, 37.678664, 127.613691, '2026-09-18T14:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001018', '54500700-0000-4000-8000-000000000159', 'p-tourapi-736754', '홍승인고가', '예전부터 가보고 싶었던 홍승인고가 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 37.152244, 126.959379, '2026-09-22T20:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001019', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3532883', '소풍한옥풀빌라', '평일 연차 쓰고 혼자 소풍한옥풀빌라 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.855854, 129.267029, '2026-09-28T19:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001020', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2990185', '금곡영화마을', '근처 여행 코스로 금곡영화마을 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.395210, 126.734176, '2026-09-23T14:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001021', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2544734', '한채당 한옥체험관', '해 질 무렵에 한채당 한옥체험관 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 36.830048, 126.161265, '2026-09-27T23:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001022', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2733074', '오산 드라마세트장', '근처 여행 코스로 오산 드라마세트장 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "데이트", "사진맛집"]'::jsonb, 37.180159, 127.062869, '2026-10-01T01:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001023', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2789002', '조규승가옥', '평일 연차 쓰고 혼자 조규승가옥 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "힐링", "온마루"]'::jsonb, 37.944143, 128.765314, '2026-10-01T08:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001024', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3427223', '충무로영상센터 오재미동', '주말에 친구들이랑 충무로영상센터 오재미동 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 37.561341, 126.994223, '2026-09-28T07:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001025', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2390314', '한복남 경복궁점', '한복남 경복궁점 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "사진맛집", "온마루"]'::jsonb, 37.576289, 126.973321, '2026-09-24T11:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001026', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3013816', '궁집', '해 질 무렵에 궁집 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 37.644001, 127.230377, '2026-09-19T07:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001027', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2621282', '사슴이랑배랑농원', '해 질 무렵에 사슴이랑배랑농원 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 35.187698, 126.591355, '2026-09-17T00:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001028', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3444479', '성주 예산리 배리댁', '부모님 모시고 성주 예산리 배리댁 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집", "데이트", "온마루"]'::jsonb, 35.923369, 128.285109, '2026-09-29T21:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001029', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2769769', 'SK하이닉스 문화센터', '오랜만에 여유 찾으러 SK하이닉스 문화센터 다녀왔습니다. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 36.649243, 127.424542, '2026-09-18T08:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001030', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2777931', '생산소', '날씨가 너무 맑아서 생산소 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.243697, 126.887802, '2026-09-21T07:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001031', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3511181', '주식회사도시나무', '비 오는 날 운치 찾아 주식회사도시나무 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 35.489395, 129.418907, '2026-09-28T19:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001032', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2717486', '엘오알오', '기대 이상으로 너무 좋았던 엘오알오! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.733429, 128.108470, '2026-09-23T00:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001033', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2674014', '비체올린', '예전부터 가보고 싶었던 비체올린 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 33.349456, 126.218239, '2026-09-30T23:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001034', '54500700-0000-4000-8000-000000000089', 'p-tourapi-231940', '안동 소호헌', '주말에 친구들이랑 안동 소호헌 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 36.463695, 128.663462, '2026-09-17T14:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001035', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2706484', '3917마중', 'SNS에서 사진 보고 찾아간 3917마중, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로", "고즈넉", "온마루"]'::jsonb, 35.033297, 126.710840, '2026-09-16T22:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001036', '54500700-0000-4000-8000-000000000087', 'p-tourapi-129210', '무안 유교리 고택', 'SNS에서 사진 보고 찾아간 무안 유교리 고택, 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 34.847445, 126.438282, '2026-09-20T15:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001037', '54500700-0000-4000-8000-000000000167', 'p-tourapi-4074857', '미옥스테이', '비 오는 날 운치 찾아 미옥스테이 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.866838, 128.612096, '2026-09-30T11:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001038', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3438582', '여가', '해 질 무렵에 여가 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.815564, 127.153403, '2026-09-21T09:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001039', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3102211', '자하연', '천천히 골목 걷다가 마주친 자하연. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "데이트", "가족여행", "온마루"]'::jsonb, 35.812215, 127.155011, '2026-09-16T07:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001040', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3438584', '건축의 선율', '평일 연차 쓰고 혼자 건축의 선율 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.816228, 127.153461, '2026-09-16T12:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001041', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2717423', '힐데루시 자연치유 협동조합', '날씨가 너무 맑아서 힐데루시 자연치유 협동조합 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 37.958534, 127.157852, '2026-09-21T15:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001042', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2568571', '1928 쉼마루', '부모님 모시고 1928 쉼마루 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 35.811859, 127.152536, '2026-09-25T11:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001043', '54500700-0000-4000-8000-000000000164', 'p-tourapi-1884345', '행복드림한옥', '오랜만에 여유 찾으러 행복드림한옥 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.905472, 127.209637, '2026-09-17T08:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001044', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2647026', '석가헌', '천천히 골목 걷다가 마주친 석가헌. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 37.719017, 128.904867, '2026-09-18T21:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001045', '54500700-0000-4000-8000-000000000186', 'p-tourapi-128644', '춘천김정은가옥', '드라이브 겸 나들이로 춘천김정은가옥 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트", "인생샷", "온마루"]'::jsonb, 37.844972, 127.729000, '2026-09-19T08:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001046', '54500700-0000-4000-8000-000000000126', 'p-tourapi-126391', '고창신재효고택', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.432158, 126.703050, '2026-09-24T11:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001047', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '해 질 무렵에 농업회사법인주식회사꿀벌인 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.014031, 128.421877, '2026-09-22T22:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001048', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2820838', '평창캠프닉', 'SNS에서 사진 보고 찾아간 평창캠프닉, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.578828, 128.331753, '2026-09-21T15:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001049', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2770587', '연암서당골', '드라이브 겸 나들이로 연암서당골 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "사진맛집", "데이트"]'::jsonb, 35.900539, 128.596578, '2026-10-01T08:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001050', '54500700-0000-4000-8000-000000000075', 'p-tourapi-1201060', '이천보고가', '이천보고가 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.798653, 127.348090, '2026-09-30T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001051', '54500700-0000-4000-8000-000000000130', 'p-tourapi-705411', '군위 남천고택', '비 오는 날 운치 찾아 군위 남천고택 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.058639, 128.653986, '2026-09-20T23:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001052', '54500700-0000-4000-8000-000000000145', 'p-tourapi-128542', '안성 정무공 오정방 고택', '해 질 무렵에 안성 정무공 오정방 고택 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁", "데이트", "온마루"]'::jsonb, 37.045771, 127.185867, '2026-10-01T09:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001053', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2592885', '엘크레', '근처 여행 코스로 엘크레 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷", "사진맛집", "온마루"]'::jsonb, 37.520935, 127.023218, '2026-09-18T17:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001054', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2633954', '산속등대 복합문화공간', '천천히 골목 걷다가 마주친 산속등대 복합문화공간. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트", "주말나들이"]'::jsonb, 35.869349, 127.252007, '2026-09-23T04:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001055', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2500771', '타오르는 강 문학관', '드라이브 겸 나들이로 타오르는 강 문학관 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "풍경맛집", "온마루"]'::jsonb, 34.999466, 126.713123, '2026-09-30T22:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001056', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2657848', '한국트로트가요센터', '천천히 골목 걷다가 마주친 한국트로트가요센터. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 34.791589, 126.685354, '2026-09-22T13:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001057', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3438261', '이도한옥', '오랜만에 여유 찾으러 이도한옥 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉", "혼자여행", "온마루"]'::jsonb, 37.580561, 126.986978, '2026-10-01T12:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001058', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2795229', '한지생각이닥', '오랜만에 여유 찾으러 한지생각이닥 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.470628, 126.626196, '2026-09-25T00:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001059', '54500700-0000-4000-8000-000000000076', 'p-tourapi-4041219', '지후헌', '비 오는 날 운치 찾아 지후헌 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "방문팁", "사진맛집"]'::jsonb, 37.589451, 127.003238, '2026-09-21T18:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001060', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2531222', '강릉오죽한옥마을', '기대 이상으로 너무 좋았던 강릉오죽한옥마을! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.777333, 128.877966, '2026-09-17T20:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001061', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3337188', '세종전통문화체험관', '오랜만에 여유 찾으러 세종전통문화체험관 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 36.506871, 127.291859, '2026-09-18T10:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001062', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2819644', '적정온도(순향가)', '드라이브 겸 나들이로 적정온도(순향가) 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 34.872833, 127.528064, '2026-09-17T13:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001063', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2697287', '하서원(외암민속마을)', '하서원(외암민속마을) 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이", "가족여행", "온마루"]'::jsonb, 36.731535, 127.014419, '2026-09-22T12:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001064', '54500700-0000-4000-8000-000000000156', 'p-tourapi-231909', '안동 예안이씨 충효당', '근처 여행 코스로 안동 예안이씨 충효당 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "방문팁", "주말나들이", "온마루"]'::jsonb, 36.574451, 128.580208, '2026-09-28T03:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001065', '54500700-0000-4000-8000-000000000080', 'p-tourapi-129518', '경주 양동마을 송첨종택', '오랜만에 여유 찾으러 경주 양동마을 송첨종택 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.003814, 129.253626, '2026-09-29T15:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001066', '54500700-0000-4000-8000-000000000188', 'p-tourapi-127430', '신석정 고택', '근처 여행 코스로 신석정 고택 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 35.739888, 126.734270, '2026-09-21T14:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001067', '54500700-0000-4000-8000-000000000057', 'p-tourapi-252546', '영덕 무안박씨 무의공파 종택', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.509929, 129.409209, '2026-09-27T21:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001068', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3038851', '치헌', '부모님 모시고 치헌 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.534748, 128.860953, '2026-09-26T06:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001069', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3354209', '오로시예술공방(주식회사오로시프로젝트)', '해 질 무렵에 오로시예술공방(주식회사오로시프로젝트) 방문했는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "인생샷"]'::jsonb, 34.982555, 126.959936, '2026-09-26T09:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001070', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3056873', '영암 집영재', '날씨가 너무 맑아서 영암 집영재 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "방문팁", "데이트", "온마루"]'::jsonb, 34.762693, 126.533766, '2026-09-27T23:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001071', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3428354', '스타필드 시티 부천', '스타필드 시티 부천 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "사색", "온마루"]'::jsonb, 37.461527, 126.813928, '2026-09-17T12:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001072', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3582643', '한복남 창덕궁점', '천천히 골목 걷다가 마주친 한복남 창덕궁점. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.576183, 126.990671, '2026-09-25T02:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001073', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2037306', '완도 청해포구촬영장', '평일 연차 쓰고 혼자 완도 청해포구촬영장 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "힐링", "사색"]'::jsonb, 34.323313, 126.670402, '2026-09-22T02:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001074', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3411229', '천지인 전통사상체험관', '조용히 사색하고 싶어서 찾은 천지인 전통사상체험관. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.730825, 128.614743, '2026-09-23T09:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001075', '54500700-0000-4000-8000-000000000138', 'p-tourapi-894145', '명품옻골 1616 협동조합', 'SNS에서 사진 보고 찾아간 명품옻골 1616 협동조합, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.907762, 128.686842, '2026-09-15T16:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001076', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2638479', '장생포 모노레일', '비 오는 날 운치 찾아 장생포 모노레일 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "방문팁", "가족여행", "온마루"]'::jsonb, 35.502970, 129.381340, '2026-09-28T23:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001077', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3422587', '더맑음', '더맑음 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "힐링", "산책로", "온마루"]'::jsonb, 35.540524, 129.338596, '2026-09-15T23:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001078', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2020734', '영동국악체험촌', '비 오는 날 운치 찾아 영동국악체험촌 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 36.211277, 127.702276, '2026-09-28T08:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001079', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2602750', '쥬라기랜드', 'SNS에서 사진 보고 찾아간 쥬라기랜드, 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.435562, 127.023837, '2026-09-24T19:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001080', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2775017', '주식회사 하늘', 'SNS에서 사진 보고 찾아간 주식회사 하늘, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.304934, 126.546587, '2026-09-28T20:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001081', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438674', '나들방', '오랜만에 여유 찾으러 나들방 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.816039, 127.151436, '2026-09-24T04:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001082', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3426935', '구리문화재단', 'SNS에서 사진 보고 찾아간 구리문화재단, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 37.595604, 127.129868, '2026-09-18T19:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001083', '54500700-0000-4000-8000-000000000195', 'p-tourapi-129051', '청송 송소 고택', '부모님 모시고 청송 송소 고택 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.436136, 129.026491, '2026-09-25T03:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001084', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3444479', '성주 예산리 배리댁', '날씨가 너무 맑아서 성주 예산리 배리댁 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.923369, 128.285109, '2026-09-30T03:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001085', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2570532', '한옥미담(전주한옥마을 한옥미담)', '평일 연차 쓰고 혼자 한옥미담(전주한옥마을 한옥미담) 다녀옴. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 35.819325, 127.150592, '2026-09-23T17:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001086', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2465890', '시은재', '오랜만에 여유 찾으러 시은재 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.573704, 126.987248, '2026-09-18T16:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001087', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2932871', '한복입고 유유자적 (주식회사고영)', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷", "사진맛집"]'::jsonb, 34.760007, 126.623276, '2026-09-20T02:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001088', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2668524', '이천백사 산수유영농조합법인(이천산수유마을)', '기대 이상으로 너무 좋았던 이천백사 산수유영농조합법인(이천산수유마을)! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 37.340828, 127.462314, '2026-09-30T13:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001089', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3438586', '휴휴가', '평일 연차 쓰고 혼자 휴휴가 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "사색", "산책로"]'::jsonb, 34.955134, 127.480782, '2026-09-24T04:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001090', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3510971', '컬러브릿지협동조합', '부모님 모시고 컬러브릿지협동조합 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "가족여행"]'::jsonb, 35.141137, 126.916908, '2026-09-23T23:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001091', '54500700-0000-4000-8000-000000000133', 'p-tourapi-1621481', '화기리인동장씨종택', 'SNS에서 사진 보고 찾아간 화기리인동장씨종택, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.769256, 128.575177, '2026-09-17T15:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001092', '54500700-0000-4000-8000-000000000180', 'p-tourapi-3438590', '중정별채', '평일 연차 쓰고 혼자 중정별채 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 35.076940, 126.685755, '2026-09-19T14:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001093', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2612877', '장욱진 고택', '주말에 친구들이랑 장욱진 고택 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행"]'::jsonb, 37.301193, 127.120568, '2026-09-23T05:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001094', '54500700-0000-4000-8000-000000000154', 'p-tourapi-231907', '정읍 김명관 고택', '오랜만에 여유 찾으러 정읍 김명관 고택 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.616162, 127.019992, '2026-09-19T01:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001095', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2000964', '향단', '날씨가 너무 맑아서 향단 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 35.999890, 129.252940, '2026-09-21T05:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001096', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2668037', '월암종택(김호장군고택)', '월암종택(김호장군고택) 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 35.819635, 129.218670, '2026-09-21T20:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001097', '54500700-0000-4000-8000-000000000164', 'p-tourapi-128145', '나주 목사내아', '해 질 무렵에 나주 목사내아 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집", "온마루"]'::jsonb, 35.031915, 126.715352, '2026-09-23T11:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001098', '54500700-0000-4000-8000-000000000194', 'p-tourapi-128759', '강릉 수리골 고택', '오랜만에 여유 찾으러 강릉 수리골 고택 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "풍경맛집", "산책로"]'::jsonb, 37.786154, 128.891107, '2026-10-01T10:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001099', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2570576', '금농헌', '드라이브 겸 나들이로 금농헌 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "데이트", "방문팁"]'::jsonb, 35.820339, 127.157447, '2026-09-15T17:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001100', '54500700-0000-4000-8000-000000000198', 'p-tourapi-3532694', '어보이', '기대 이상으로 너무 좋았던 어보이! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 35.811670, 127.153239, '2026-09-23T05:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001101', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3438575', '일상이상', '비 오는 날 운치 찾아 일상이상 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.824608, 127.154286, '2026-09-25T16:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001102', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2598628', '별아래한옥', '드라이브 겸 나들이로 별아래한옥 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "사진맛집", "방문팁"]'::jsonb, 36.537190, 128.821374, '2026-09-29T18:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001103', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2686588', '오성한옥마을', '부모님 모시고 오성한옥마을 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.903070, 127.243284, '2026-09-18T11:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001104', '54500700-0000-4000-8000-000000000165', 'p-tourapi-1395270', '최순우 옛집', '근처 여행 코스로 최순우 옛집 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "혼자여행", "풍경맛집"]'::jsonb, 37.593065, 127.000360, '2026-09-21T19:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001105', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2603889', '문행당', 'SNS에서 사진 보고 찾아간 문행당, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 36.913254, 128.741100, '2026-09-20T21:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001106', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2696256', '낙안재', 'SNS에서 사진 보고 찾아간 낙안재, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.835991, 129.208413, '2026-09-23T19:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001107', '54500700-0000-4000-8000-000000000203', 'p-tourapi-792208', '괴산 한지체험박물관', '기대 이상으로 너무 좋았던 괴산 한지체험박물관! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["주말나들이", "데이트"]'::jsonb, 36.785439, 128.014900, '2026-09-17T03:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001108', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2606192', '선샤인랜드', '오랜만에 여유 찾으러 선샤인랜드 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "혼자여행", "사색"]'::jsonb, 36.101997, 127.106014, '2026-09-27T15:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001109', '54500700-0000-4000-8000-000000000169', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '기대 이상으로 너무 좋았던 전주한옥마을 독채덕수궁! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "데이트", "인생샷"]'::jsonb, 35.816792, 127.151648, '2026-09-18T06:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001110', '54500700-0000-4000-8000-000000000088', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '비 오는 날 운치 찾아 거창 갈계리 임씨고가 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.780200, 127.818700, '2026-09-21T03:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001111', '54500700-0000-4000-8000-000000000076', 'p-tourapi-3438653', '호호재', '기대 이상으로 너무 좋았던 호호재! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 36.560299, 128.710802, '2026-10-01T08:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001112', '54500700-0000-4000-8000-000000000163', 'p-tourapi-129046', '서벽고택', '해 질 무렵에 서벽고택 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.458625, 129.022353, '2026-09-30T15:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001113', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2594864', '남호구택', '조용히 사색하고 싶어서 찾은 남호구택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "산책로", "힐링"]'::jsonb, 36.893831, 128.712401, '2026-09-28T03:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001114', '54500700-0000-4000-8000-000000000142', 'p-tourapi-3455504', '용인특례시 가상현실스포츠체험센터', '부모님 모시고 용인특례시 가상현실스포츠체험센터 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "방문팁", "주말나들이"]'::jsonb, 37.238601, 127.180554, '2026-09-18T04:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001115', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2737307', '경기광주 한옥마을', '근처 여행 코스로 경기광주 한옥마을 넣길 정말 잘했어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 37.438504, 127.230030, '2026-09-19T16:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001116', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2609894', '경기전 연가', '드라이브 겸 나들이로 경기전 연가 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.817436, 127.150187, '2026-09-29T19:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001117', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2593272', '가은채2', '기대 이상으로 너무 좋았던 가은채2! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 35.815526, 127.153504, '2026-09-22T19:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001118', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3547622', '허균 허난설헌 기념공원 초희전통차체험관', '부모님 모시고 허균 허난설헌 기념공원 초희전통차체험관 산책 겸 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "인생샷", "주말나들이", "온마루"]'::jsonb, 37.790989, 128.910156, '2026-09-22T18:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001119', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2606296', '청풍호반케이블카', '해 질 무렵에 청풍호반케이블카 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 37.001314, 128.166802, '2026-09-25T13:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001120', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3427223', '충무로영상센터 오재미동', 'SNS에서 사진 보고 찾아간 충무로영상센터 오재미동, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 37.561341, 126.994223, '2026-09-27T15:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001121', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '천천히 골목 걷다가 마주친 2025 서울 카페&베이커리페어. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 37.496089, 127.070767, '2026-09-28T14:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001122', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2717590', '김성래 가옥', '평일 연차 쓰고 혼자 김성래 가옥 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 37.987361, 128.739890, '2026-09-21T12:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001123', '54500700-0000-4000-8000-000000000081', 'p-tourapi-1433369', '괴산 김항묵 고택', '드라이브 겸 나들이로 괴산 김항묵 고택 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.781516, 127.859430, '2026-09-19T06:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001124', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3438630', '서우재', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 36.559685, 128.708380, '2026-09-25T13:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001125', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2701396', '서남산한옥', '날씨가 너무 맑아서 서남산한옥 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 35.780864, 129.204559, '2026-09-15T21:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001126', '54500700-0000-4000-8000-000000000102', 'p-tourapi-3442142', '서울숲 곤충식물원', '비 오는 날 운치 찾아 서울숲 곤충식물원 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "가족여행", "데이트", "온마루"]'::jsonb, 37.543125, 127.041813, '2026-09-24T10:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001127', '54500700-0000-4000-8000-000000000129', 'p-tourapi-895327', '남도한옥민박마을', '기대 이상으로 너무 좋았던 남도한옥민박마을! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 34.509319, 126.605754, '2026-09-28T02:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001128', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2707444', '가영당', '근처 여행 코스로 가영당 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "혼자여행", "힐링", "온마루"]'::jsonb, 36.735122, 127.405542, '2026-09-22T21:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001129', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '주말에 친구들이랑 경북전통음식체험관 모심정 들렀는데 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "방문팁", "주말나들이", "온마루"]'::jsonb, 36.661949, 128.119119, '2026-09-30T05:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001130', '54500700-0000-4000-8000-000000000112', 'p-tourapi-3533156', '라라몽몽', '주말에 친구들이랑 라라몽몽 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.821666, 127.138654, '2026-09-27T18:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001131', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2663065', '휴휴당', '근처 여행 코스로 휴휴당 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행", "주말나들이"]'::jsonb, 35.835513, 129.212276, '2026-09-28T18:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001132', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2657716', '치유의숲 무장애길', 'SNS에서 사진 보고 찾아간 치유의숲 무장애길, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.736664, 128.040921, '2026-09-21T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001133', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1883135', '안동고택 이상루', '비 오는 날 운치 찾아 안동고택 이상루 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 36.634748, 128.678495, '2026-09-30T08:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001134', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2647939', '고스락', '비 오는 날 운치 찾아 고스락 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 36.045904, 126.960681, '2026-09-26T14:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001135', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3101965', '스테이서문', '평일 연차 쓰고 혼자 스테이서문 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.033584, 126.712506, '2026-09-19T07:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001136', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2708322', '이화고택', '드라이브 겸 나들이로 이화고택 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 35.816284, 127.153995, '2026-09-16T01:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001137', '54500700-0000-4000-8000-000000000165', 'p-tourapi-1621481', '화기리인동장씨종택', '평일 연차 쓰고 혼자 화기리인동장씨종택 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 36.769256, 128.575177, '2026-09-15T14:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001138', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2717486', '엘오알오', '부모님 모시고 엘오알오 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "가족여행"]'::jsonb, 36.733429, 128.108470, '2026-09-27T17:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001139', '54500700-0000-4000-8000-000000000141', 'p-tourapi-1594746', '장현식고택', '근처 여행 코스로 장현식고택 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.812156, 127.156492, '2026-09-29T09:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001140', '54500700-0000-4000-8000-000000000177', 'p-tourapi-1883070', '정재종택', '비 오는 날 운치 찾아 정재종택 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 36.559323, 128.915579, '2026-09-18T13:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001141', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.912546, 128.817052, '2026-09-29T10:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001142', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2608154', '조약도 한옥체험', '조용히 사색하고 싶어서 찾은 조약도 한옥체험. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 34.373225, 126.888001, '2026-09-28T12:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001143', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2657848', '한국트로트가요센터', '근처 여행 코스로 한국트로트가요센터 넣길 정말 잘했어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "풍경맛집"]'::jsonb, 34.791589, 126.685354, '2026-09-21T14:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001144', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3056624', '한복남 전주한옥마을점', '드라이브 겸 나들이로 한복남 전주한옥마을점 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색"]'::jsonb, 35.814532, 127.152366, '2026-09-24T18:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001145', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2855009', '한옥 생고기', '해 질 무렵에 한옥 생고기 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 37.948869, 127.189507, '2026-09-16T13:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001146', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3438587', '빌라오', '근처 여행 코스로 빌라오 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 34.953237, 127.479852, '2026-09-21T11:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001147', '54500700-0000-4000-8000-000000000175', 'p-tourapi-3438684', '물길스테이', '예전부터 가보고 싶었던 물길스테이 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "사진맛집", "인생샷", "온마루"]'::jsonb, 36.505586, 128.852705, '2026-09-17T19:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001148', '54500700-0000-4000-8000-000000000134', 'p-tourapi-127329', '목포시사', '조용히 사색하고 싶어서 찾은 목포시사. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 34.790017, 126.377297, '2026-09-25T05:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001149', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2680781', '소리터', '부모님 모시고 소리터 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 34.762180, 126.622615, '2026-09-16T07:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001150', '54500700-0000-4000-8000-000000000056', 'p-tourapi-125800', '강릉 선교장', '날씨가 너무 맑아서 강릉 선교장 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 37.786503, 128.885049, '2026-09-30T09:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001151', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2782688', '와글아이', '부모님 모시고 와글아이 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "사색", "온마루"]'::jsonb, 37.654185, 126.775751, '2026-09-20T22:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001152', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3469883', '서동선화한옥', '해 질 무렵에 서동선화한옥 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 36.291875, 126.927691, '2026-09-26T13:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001153', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2624231', '장충영각', 'SNS에서 사진 보고 찾아간 장충영각, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 36.572538, 126.612051, '2026-10-01T07:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001154', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3532694', '어보이', '날씨가 너무 맑아서 어보이 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "사진맛집"]'::jsonb, 35.811670, 127.153239, '2026-09-29T17:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001155', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3353800', '뜻모아센터', '조용히 사색하고 싶어서 찾은 뜻모아센터. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 35.189206, 126.907641, '2026-09-15T18:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001156', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3337761', '마마스홈퀴진', '예전부터 가보고 싶었던 마마스홈퀴진 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 35.561501, 129.116689, '2026-09-26T15:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001157', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2613254', '도봉서당', '근처 여행 코스로 도봉서당 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 35.827489, 129.184732, '2026-09-23T07:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001158', '54500700-0000-4000-8000-000000000060', 'p-tourapi-1433369', '괴산 김항묵 고택', '드라이브 겸 나들이로 괴산 김항묵 고택 선택했는데 대만족! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 36.781516, 127.859430, '2026-09-19T00:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001159', '54500700-0000-4000-8000-000000000071', 'p-tourapi-1566740', '양평 맑은숲캠프', '날씨가 너무 맑아서 양평 맑은숲캠프 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 37.562041, 127.734400, '2026-09-24T15:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001160', '54500700-0000-4000-8000-000000000160', 'p-tourapi-3533116', '덕만재', '덕만재 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.821940, 129.243965, '2026-09-29T08:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001161', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2665817', '부여안방마님', '드라이브 겸 나들이로 부여안방마님 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.265577, 126.848410, '2026-09-17T11:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001162', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3438379', '더 모먼트', '날씨가 너무 맑아서 더 모먼트 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행", "인생샷", "온마루"]'::jsonb, 37.577489, 126.970624, '2026-09-21T00:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001163', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2707233', '한옥人(한옥인)', '날씨가 너무 맑아서 한옥人(한옥인) 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트", "가족여행"]'::jsonb, 35.834869, 129.211446, '2026-09-19T17:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001164', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3019714', '같이삽시도', '예전부터 가보고 싶었던 같이삽시도 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 36.346087, 126.353294, '2026-09-18T02:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001165', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2663054', '경주 춘추관', '드라이브 겸 나들이로 경주 춘추관 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.822778, 129.185834, '2026-09-30T10:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001166', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3448778', '양평 생활문화센터', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "주말나들이", "사진맛집", "온마루"]'::jsonb, 37.499629, 127.476933, '2026-09-27T17:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001167', '54500700-0000-4000-8000-000000000058', 'p-tourapi-3438581', '교동94', '기대 이상으로 너무 좋았던 교동94! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.812687, 127.152503, '2026-09-16T20:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001168', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2820629', '부여북포한옥마을', '천천히 골목 걷다가 마주친 부여북포한옥마을. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "산책로"]'::jsonb, 36.292906, 126.924516, '2026-09-22T14:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001169', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2751455', '시흥 ABC행복학습타운', '조용히 사색하고 싶어서 찾은 시흥 ABC행복학습타운. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.448903, 126.785386, '2026-09-18T20:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001170', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2817792', '밀알영농조합', '예전부터 가보고 싶었던 밀알영농조합 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "인생샷", "온마루"]'::jsonb, 35.081710, 128.185789, '2026-09-21T13:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001171', '54500700-0000-4000-8000-000000000135', 'p-tourapi-3427800', '더헤븐 리조트', 'SNS에서 사진 보고 찾아간 더헤븐 리조트, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 37.229905, 126.562665, '2026-09-29T08:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001172', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3511181', '주식회사도시나무', '평일 연차 쓰고 혼자 주식회사도시나무 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "힐링", "온마루"]'::jsonb, 35.489395, 129.418907, '2026-09-15T20:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001173', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2768086', '한양 한옥마을점', '날씨가 너무 맑아서 한양 한옥마을점 한 바퀴 돌고 왔네요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.390854, 126.638901, '2026-09-27T01:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001174', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2570611', '잊음', '기대 이상으로 너무 좋았던 잊음! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이", "온마루"]'::jsonb, 34.846535, 128.418809, '2026-09-24T02:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001175', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2594218', '정가한옥', '정가한옥 다녀왔어요! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 35.816289, 127.155113, '2026-09-25T12:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001176', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2544095', '전통리조트 구름에', '평일 연차 쓰고 혼자 전통리조트 구름에 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 36.573201, 128.768308, '2026-09-16T12:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001177', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2610549', '예원당(한옥체험 예원당)', '예전부터 가보고 싶었던 예원당(한옥체험 예원당) 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 35.817395, 127.152742, '2026-09-19T13:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001178', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2572886', '삼연재', '조용히 사색하고 싶어서 찾은 삼연재. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 36.675777, 128.490968, '2026-09-27T18:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001179', '54500700-0000-4000-8000-000000000171', 'p-tourapi-1627167', '추사 김정희 선생 고택', 'SNS에서 사진 보고 찾아간 추사 김정희 선생 고택, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "인생샷", "데이트"]'::jsonb, 36.746800, 126.798900, '2026-09-18T17:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001180', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2820707', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주)', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주) 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.235898, 128.030338, '2026-09-27T22:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001181', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2629010', '영남알프스 얼음골케이블카', 'SNS에서 사진 보고 찾아간 영남알프스 얼음골케이블카, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로", "사색", "온마루"]'::jsonb, 35.582782, 128.986997, '2026-09-20T01:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001182', '54500700-0000-4000-8000-000000000170', 'p-tourapi-1937772', '계룡 사계고택', '드라이브 겸 나들이로 계룡 사계고택 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 36.265582, 127.271408, '2026-09-19T06:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001183', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2574225', '도원', '부모님 모시고 도원 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "산책로"]'::jsonb, 35.807848, 127.150092, '2026-09-23T14:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001184', '54500700-0000-4000-8000-000000000190', 'p-tourapi-1883087', '연우하우스', '천천히 골목 걷다가 마주친 연우하우스. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 37.582281, 126.985312, '2026-09-29T03:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001185', '54500700-0000-4000-8000-000000000133', 'p-tourapi-250460', '남원몽심재', '조용히 사색하고 싶어서 찾은 남원몽심재. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 35.337994, 127.374746, '2026-09-23T04:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001186', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2602750', '쥬라기랜드', '비 오는 날 운치 찾아 쥬라기랜드 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "가족여행"]'::jsonb, 37.435562, 127.023837, '2026-09-26T05:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001187', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2932894', '주월재', '조용히 사색하고 싶어서 찾은 주월재. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 34.779345, 127.167378, '2026-09-17T16:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001188', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2717286', '마린데크(커피마린협동조합)', '천천히 골목 걷다가 마주친 마린데크(커피마린협동조합). 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.456778, 129.186075, '2026-09-21T14:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001189', '54500700-0000-4000-8000-000000000173', 'p-tourapi-1623646', '권희문가옥', '기대 이상으로 너무 좋았던 권희문가옥! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 35.587661, 127.386260, '2026-09-17T09:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001190', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3038830', '백하구려', '예전부터 가보고 싶었던 백하구려 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.534575, 128.859861, '2026-09-15T20:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001191', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2609894', '경기전 연가', 'SNS에서 사진 보고 찾아간 경기전 연가, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.817436, 127.150187, '2026-09-19T19:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001192', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3438189', '한옥 북클럽 하우스', '오랜만에 여유 찾으러 한옥 북클럽 하우스 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 37.591369, 127.005287, '2026-09-28T10:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001193', '54500700-0000-4000-8000-000000000111', 'p-tourapi-798830', '영동 김참판댁', '부모님 모시고 영동 김참판댁 산책 겸 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "가족여행"]'::jsonb, 36.153087, 127.754835, '2026-09-17T18:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001194', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2531417', '전주 한옥숙박체험관', 'SNS에서 사진 보고 찾아간 전주 한옥숙박체험관, 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 35.814970, 127.152169, '2026-09-21T23:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001195', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2029564', '오미요리연구소', '오랜만에 여유 찾으러 오미요리연구소 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "고즈넉", "온마루"]'::jsonb, 37.583206, 127.040943, '2026-09-18T00:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001196', '54500700-0000-4000-8000-000000000104', 'p-tourapi-128645', '춘천최재근가옥', '춘천최재근가옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 37.843130, 127.727499, '2026-10-01T03:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001197', '54500700-0000-4000-8000-000000000119', 'p-tourapi-803988', '순천 용오름마을 [농촌전통테마마을]', '예전부터 가보고 싶었던 순천 용오름마을 [농촌전통테마마을] 드디어 방문! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.092132, 127.202231, '2026-09-18T20:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001198', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2787267', '오봉정사', '예전부터 가보고 싶었던 오봉정사 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "사색", "온마루"]'::jsonb, 35.184232, 127.524356, '2026-09-29T13:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001199', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2409490', '만회고택', '천천히 골목 걷다가 마주친 만회고택. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.897302, 128.715223, '2026-09-21T08:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001200', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2050197', '어련당', '평일 연차 쓰고 혼자 어련당 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.574050, 129.350277, '2026-09-18T05:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001201', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2575836', '북촌 게스트하우스', '북촌 게스트하우스 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["가족여행", "데이트"]'::jsonb, 37.578628, 126.985681, '2026-09-17T00:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001202', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2609838', '다래헌', '근처 여행 코스로 다래헌 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "혼자여행"]'::jsonb, 35.815623, 127.152920, '2026-09-27T06:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001203', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2621263', '자연스토리', '해 질 무렵에 자연스토리 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행", "주말나들이", "온마루"]'::jsonb, 34.509125, 126.605515, '2026-09-17T03:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001204', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2604100', '예직한옥체험마을(용인예직한옥체험 마을)', '해 질 무렵에 예직한옥체험마을(용인예직한옥체험 마을) 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 37.191822, 127.255584, '2026-09-19T19:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001205', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '오랜만에 여유 찾으러 선성현문화단지 한옥체험관 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "사색", "온마루"]'::jsonb, 36.698302, 128.814675, '2026-09-27T09:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001206', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2435103', '중앙탑의상실', '해 질 무렵에 중앙탑의상실 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 37.018227, 127.866085, '2026-09-18T22:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001207', '54500700-0000-4000-8000-000000000099', 'p-tourapi-1105980', '양천구어린이교통안전교육장', '근처 여행 코스로 양천구어린이교통안전교육장 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "인생샷", "방문팁", "온마루"]'::jsonb, 37.509867, 126.870035, '2026-09-19T13:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001208', '54500700-0000-4000-8000-000000000072', 'p-tourapi-1590793', '노동환가옥', '드라이브 겸 나들이로 노동환가옥 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 35.484368, 127.266354, '2026-09-16T19:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001209', '54500700-0000-4000-8000-000000000059', 'p-tourapi-753850', '키즈오토파크', '비 오는 날 운치 찾아 키즈오토파크 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.549361, 127.076293, '2026-09-29T05:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001210', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2409490', '만회고택', '평일 연차 쓰고 혼자 만회고택 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "사색"]'::jsonb, 36.897302, 128.715223, '2026-09-25T15:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001211', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2767851', '송도 한옥마을', '비 오는 날 운치 찾아 송도 한옥마을 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "가족여행", "사진맛집"]'::jsonb, 37.390252, 126.638790, '2026-09-29T09:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001212', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2939639', '유현문화관광지', '날씨가 너무 맑아서 유현문화관광지 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "산책로", "온마루"]'::jsonb, 37.530718, 127.819940, '2026-09-29T07:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001213', '54500700-0000-4000-8000-000000000085', 'p-tourapi-1972012', '산에는 꽃이피네', '평일 연차 쓰고 혼자 산에는 꽃이피네 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 34.998671, 126.823311, '2026-09-30T19:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001214', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2531222', '강릉오죽한옥마을', '천천히 골목 걷다가 마주친 강릉오죽한옥마을. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "혼자여행"]'::jsonb, 37.777333, 128.877966, '2026-09-15T17:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001215', '54500700-0000-4000-8000-000000000140', 'p-tourapi-2598978', '온계종택(삼백당)', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["가족여행", "방문팁"]'::jsonb, 36.752627, 128.827817, '2026-09-21T17:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001216', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2717337', '소백산꽃차이야기', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 36.883221, 128.563895, '2026-09-17T03:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001217', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3038851', '치헌', '날씨가 너무 맑아서 치헌 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "사색", "풍경맛집"]'::jsonb, 36.534748, 128.860953, '2026-09-16T10:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001218', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2037306', '완도 청해포구촬영장', '날씨가 너무 맑아서 완도 청해포구촬영장 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "방문팁", "주말나들이", "온마루"]'::jsonb, 34.323313, 126.670402, '2026-09-15T17:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001219', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '해 질 무렵에 미담 한옥 게스트 하우스 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "인생샷", "방문팁", "온마루"]'::jsonb, 37.580664, 126.986353, '2026-09-19T14:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001220', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2777931', '생산소', '기대 이상으로 너무 좋았던 생산소! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트", "가족여행"]'::jsonb, 36.243697, 126.887802, '2026-09-26T23:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001221', '54500700-0000-4000-8000-000000000126', 'p-tourapi-3451224', '은계2어울림센터', '은계2어울림센터 다녀왔어요! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "방문팁", "사진맛집", "온마루"]'::jsonb, 37.435836, 126.797916, '2026-09-19T03:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001222', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2583699', '소소하우스', '날씨가 너무 맑아서 소소하우스 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "방문팁", "인생샷", "온마루"]'::jsonb, 37.580333, 126.968163, '2026-09-15T14:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001223', '54500700-0000-4000-8000-000000000176', 'p-tourapi-3438722', '전주 한옥마을 중심 독채', '주말에 친구들이랑 전주 한옥마을 중심 독채 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "가족여행", "데이트", "온마루"]'::jsonb, 35.815253, 127.151759, '2026-09-29T17:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001224', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2707041', '경극고택', 'SNS에서 사진 보고 찾아간 경극고택, 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.907476, 128.686676, '2026-09-26T19:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001225', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3438052', '중정독채', '평일 연차 쓰고 혼자 중정독채 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.034687, 126.715051, '2026-09-27T11:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001226', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3469889', '석주재', '천천히 골목 걷다가 마주친 석주재. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 35.510612, 128.837726, '2026-09-23T05:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001227', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1627280', '단양 조덕수 고택', '근처 여행 코스로 단양 조덕수 고택 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "산책로"]'::jsonb, 37.003392, 128.383774, '2026-09-20T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001228', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2867659', '곤지암반디숲', '드라이브 겸 나들이로 곤지암반디숲 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "고즈넉", "산책로"]'::jsonb, 37.363523, 127.330953, '2026-09-27T20:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001229', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2574064', '백미응서재', '천천히 골목 걷다가 마주친 백미응서재. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.141612, 126.690753, '2026-09-16T23:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001230', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2633895', '예천목재문화체험장', '드라이브 겸 나들이로 예천목재문화체험장 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 36.799471, 128.376139, '2026-09-18T19:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001231', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2638521', '영천 목재문화체험장', '조용히 사색하고 싶어서 찾은 영천 목재문화체험장. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "사색", "풍경맛집"]'::jsonb, 36.142432, 128.978252, '2026-09-20T20:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001232', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3105334', '133파티룸 한옥스테이점', 'SNS에서 사진 보고 찾아간 133파티룸 한옥스테이점, 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 37.279463, 127.016073, '2026-09-28T13:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001233', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3438585', '스테이 구도', '근처 여행 코스로 스테이 구도 넣길 정말 잘했어요. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "인생샷", "온마루"]'::jsonb, 34.791917, 126.380222, '2026-09-26T00:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001234', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3533116', '덕만재', 'SNS에서 사진 보고 찾아간 덕만재, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 35.821940, 129.243965, '2026-09-16T23:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001235', '54500700-0000-4000-8000-000000000106', 'p-tourapi-228892', '담양 명옥헌 원림', '조용히 사색하고 싶어서 찾은 담양 명옥헌 원림. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.219331, 126.996376, '2026-09-28T08:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001236', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '부모님 모시고 한옥카페 갤러리 도솔 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 37.641997, 126.506472, '2026-09-19T22:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001237', '54500700-0000-4000-8000-000000000186', 'p-tourapi-4074856', '연림스테이', '부모님 모시고 연림스테이 산책 겸 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "사진맛집", "가족여행", "온마루"]'::jsonb, 35.972113, 128.698835, '2026-09-22T11:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001238', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '평일 연차 쓰고 혼자 나무키움(전의양묘영농조합법인) 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "산책로", "온마루"]'::jsonb, 36.676447, 127.197876, '2026-09-24T08:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001239', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2650825', '일몰이아름다운한옥', '근처 여행 코스로 일몰이아름다운한옥 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 34.847563, 127.527931, '2026-09-22T02:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001240', '54500700-0000-4000-8000-000000000162', 'p-tourapi-801918', '무안 감풀마을 [농촌전통테마]', '예전부터 가보고 싶었던 무안 감풀마을 [농촌전통테마] 드디어 방문! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 35.061300, 126.406043, '2026-09-28T09:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001241', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2820794', '별내리마을', '날씨가 너무 맑아서 별내리마을 한 바퀴 돌고 왔네요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 35.455167, 126.843373, '2026-09-21T13:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001242', '54500700-0000-4000-8000-000000000176', 'p-tourapi-3072072', '한옥에세이 서촌', '근처 여행 코스로 한옥에세이 서촌 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집", "온마루"]'::jsonb, 37.578669, 126.968397, '2026-09-24T11:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001243', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2995168', '유한회사복합문화공간 서리울', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.015152, 127.145485, '2026-09-16T05:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001244', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2574250', '라온한옥꿀잠', 'SNS에서 사진 보고 찾아간 라온한옥꿀잠, 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 35.815836, 127.154314, '2026-09-27T06:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001245', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2603889', '문행당', '부모님 모시고 문행당 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 36.913254, 128.741100, '2026-09-22T03:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001246', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3577428', '고창 전통예술체험마을', '해 질 무렵에 고창 전통예술체험마을 방문했는데 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.430478, 126.701515, '2026-09-18T18:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001247', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3438735', '소월담', '소월담 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 37.578825, 126.985898, '2026-09-15T22:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001248', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2568571', '1928 쉼마루', '날씨가 너무 맑아서 1928 쉼마루 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "데이트", "온마루"]'::jsonb, 35.811859, 127.152536, '2026-09-22T17:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001249', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2574250', '라온한옥꿀잠', '드라이브 겸 나들이로 라온한옥꿀잠 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "데이트", "사진맛집"]'::jsonb, 35.815836, 127.154314, '2026-09-20T21:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001250', '54500700-0000-4000-8000-000000000072', 'p-tourapi-3068424', '가리왕산케이블카', '기대 이상으로 너무 좋았던 가리왕산케이블카! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "방문팁", "가족여행", "온마루"]'::jsonb, 37.474254, 128.609754, '2026-09-20T04:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001251', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3102073', '오원 스테이', '평일 연차 쓰고 혼자 오원 스테이 다녀옴. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 35.836305, 129.208901, '2026-09-24T13:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001252', '54500700-0000-4000-8000-000000000146', 'p-tourapi-1883086', '연경당', '근처 여행 코스로 연경당 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "풍경맛집", "온마루"]'::jsonb, 35.015690, 127.585952, '2026-09-27T16:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001253', '54500700-0000-4000-8000-000000000113', 'p-tourapi-3011053', '더 히로 플레이 그라운드', '근처 여행 코스로 더 히로 플레이 그라운드 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 37.866611, 127.277146, '2026-09-19T04:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001254', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2795007', '화성 정수영 고택', '기대 이상으로 너무 좋았던 화성 정수영 고택! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.132502, 126.700661, '2026-09-22T15:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001255', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2602750', '쥬라기랜드', '평일 연차 쓰고 혼자 쥬라기랜드 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.435562, 127.023837, '2026-09-24T01:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001256', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2426995', '전주한옥레일바이크', '기대 이상으로 너무 좋았던 전주한옥레일바이크! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "가족여행", "온마루"]'::jsonb, 35.829677, 127.175971, '2026-09-19T10:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001257', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2708327', '사단법인 한국천연염색 숨', '근처 여행 코스로 사단법인 한국천연염색 숨 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 34.905069, 127.120407, '2026-09-27T17:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001258', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2592489', '복합한옥공간 곳', '천천히 골목 걷다가 마주친 복합한옥공간 곳. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 37.579753, 126.987367, '2026-09-30T01:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001259', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3469883', '서동선화한옥', '천천히 골목 걷다가 마주친 서동선화한옥. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "힐링", "고즈넉", "온마루"]'::jsonb, 36.291875, 126.927691, '2026-09-20T06:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001260', '54500700-0000-4000-8000-000000000182', 'p-tourapi-128560', '안동 임청각', '기대 이상으로 너무 좋았던 안동 임청각! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 36.565132, 128.745004, '2026-09-23T03:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001261', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3447048', '사우당 종택', '부모님 모시고 사우당 종택 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "산책로", "혼자여행"]'::jsonb, 35.828256, 128.214952, '2026-09-27T15:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001262', '54500700-0000-4000-8000-000000000199', 'p-tourapi-1584115', '익산 김병순 고택', '조용히 사색하고 싶어서 찾은 익산 김병순 고택. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.060814, 126.909606, '2026-09-28T06:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001263', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3438582', '여가', '기대 이상으로 너무 좋았던 여가! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 35.815564, 127.153403, '2026-09-17T16:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001264', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3422587', '더맑음', '예전부터 가보고 싶었던 더맑음 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "데이트", "가족여행", "온마루"]'::jsonb, 35.540524, 129.338596, '2026-09-20T02:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001265', '54500700-0000-4000-8000-000000000126', 'p-tourapi-1171915', '조선왕가', '주말에 친구들이랑 조선왕가 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "사색"]'::jsonb, 38.063643, 127.101473, '2026-09-20T08:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001266', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2725123', '운기석9020(운기석9020협동조합)', '드라이브 겸 나들이로 운기석9020(운기석9020협동조합) 선택했는데 대만족! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.380565, 128.662682, '2026-09-15T17:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001267', '54500700-0000-4000-8000-000000000153', 'p-tourapi-3544074', '대한노인회 강릉시지회', '해 질 무렵에 대한노인회 강릉시지회 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "사색", "힐링"]'::jsonb, 37.747772, 128.884015, '2026-09-21T13:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001268', '54500700-0000-4000-8000-000000000104', 'p-tourapi-1883758', '창실고택', '오랜만에 여유 찾으러 창실고택 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.438275, 129.027039, '2026-09-25T12:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001269', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1971844', '필봉문화촌 취락원', '근처 여행 코스로 필봉문화촌 취락원 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "방문팁", "온마루"]'::jsonb, 35.537413, 127.154646, '2026-09-23T23:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001270', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3353949', '㈜ 희품씨', '근처 여행 코스로 ㈜ 희품씨 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 35.567161, 129.112429, '2026-09-25T10:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001271', '54500700-0000-4000-8000-000000000131', 'p-tourapi-2652952', '김해한옥체험관', '비 오는 날 운치 찾아 김해한옥체험관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "방문팁", "인생샷"]'::jsonb, 35.234037, 128.877208, '2026-09-18T17:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001272', '54500700-0000-4000-8000-000000000155', 'p-tourapi-1883590', '옥연정사', '해 질 무렵에 옥연정사 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "사색", "산책로"]'::jsonb, 36.543375, 128.518006, '2026-09-24T03:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001273', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2531496', '하동댁', '근처 여행 코스로 하동댁 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.667412, 128.227754, '2026-09-21T10:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001274', '54500700-0000-4000-8000-000000000114', 'p-tourapi-4065036', '스테이로이', 'SNS에서 사진 보고 찾아간 스테이로이, 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "가족여행"]'::jsonb, 36.102776, 127.486586, '2026-09-29T23:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001275', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2820707', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주)', '프로스트맥주협동조합 (망경동 에일맥주. 진주유등축제 흑맥주. 촉석루라거맥주. 진주석류에일맥주) 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 35.235898, 128.030338, '2026-09-28T14:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001276', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3353949', '㈜ 희품씨', '㈜ 희품씨 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.567161, 129.112429, '2026-09-21T20:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001277', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3468318', '청재한옥', '비 오는 날 운치 찾아 청재한옥 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.784405, 129.311281, '2026-09-30T19:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001278', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2610850', '강원숲체험장', '부모님 모시고 강원숲체험장 산책 겸 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 37.963056, 127.639721, '2026-09-25T06:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001279', '54500700-0000-4000-8000-000000000101', 'p-tourapi-2743393', '강선대', '강선대 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.135210, 127.695732, '2026-09-18T19:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001280', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2743740', '육영재단 어린이회관', '조용히 사색하고 싶어서 찾은 육영재단 어린이회관. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "고즈넉", "사색", "온마루"]'::jsonb, 37.547053, 127.078190, '2026-09-18T05:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001281', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2775344', '지구마을산책', '예전부터 가보고 싶었던 지구마을산책 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.875767, 128.892347, '2026-09-23T13:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001282', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3582693', '한복남 북촌점', '주말에 친구들이랑 한복남 북촌점 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.579845, 126.984742, '2026-09-30T19:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001283', '54500700-0000-4000-8000-000000000151', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', '평일 연차 쓰고 혼자 청송 평산신씨 판사공파 종택과 분가 고택 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "풍경맛집"]'::jsonb, 36.458491, 129.022801, '2026-09-27T16:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001284', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2782485', '종학당', 'SNS에서 사진 보고 찾아간 종학당, 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.291118, 127.097766, '2026-09-17T13:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001285', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2597551', '고성이씨 탑동종택', '부모님 모시고 고성이씨 탑동종택 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "힐링"]'::jsonb, 36.569299, 128.744280, '2026-09-26T10:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001286', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2854436', '옥천전통문화체험관', '근처 여행 코스로 옥천전통문화체험관 넣길 정말 잘했어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["데이트", "사진맛집", "주말나들이", "온마루"]'::jsonb, 36.316731, 127.585462, '2026-09-20T09:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001287', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2600248', '수춘제(김태길) 고택', '날씨가 너무 맑아서 수춘제(김태길) 고택 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "주말나들이", "사진맛집"]'::jsonb, 36.734841, 128.618767, '2026-09-28T16:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001288', '54500700-0000-4000-8000-000000000138', 'p-tourapi-1682936', '제천 중전리 고가', '조용히 사색하고 싶어서 찾은 제천 중전리 고가. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.062446, 128.190876, '2026-09-18T01:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001289', '54500700-0000-4000-8000-000000000152', 'p-tourapi-843726', '한옥집김치찜', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "데이트", "방문팁"]'::jsonb, 35.869289, 128.594129, '2026-09-29T21:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001290', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3081792', '화순 고인돌선사체험장', '날씨가 너무 맑아서 화순 고인돌선사체험장 한 바퀴 돌고 왔네요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 34.987100, 126.916400, '2026-10-01T12:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001291', '54500700-0000-4000-8000-000000000154', 'p-tourapi-3113740', '고결', 'SNS에서 사진 보고 찾아간 고결, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "주말나들이", "인생샷"]'::jsonb, 36.642765, 128.064640, '2026-09-30T07:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001292', '54500700-0000-4000-8000-000000000173', 'p-tourapi-129518', '경주 양동마을 송첨종택', '예전부터 가보고 싶었던 경주 양동마을 송첨종택 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.003814, 129.253626, '2026-09-19T07:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001293', '54500700-0000-4000-8000-000000000085', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '오랜만에 여유 찾으러 아산 맹씨 행단(맹사성 고택) 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.747083, 127.041871, '2026-09-19T12:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001294', '54500700-0000-4000-8000-000000000092', 'p-tourapi-2725101', '주티스트', '비 오는 날 운치 찾아 주티스트 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로", "사색", "온마루"]'::jsonb, 36.842867, 128.550983, '2026-09-23T00:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001295', '54500700-0000-4000-8000-000000000058', 'p-tourapi-127588', '애은당고택·사우정고택·용계정', '기대 이상으로 너무 좋았던 애은당고택·사우정고택·용계정! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "가족여행"]'::jsonb, 36.166884, 129.186030, '2026-09-19T12:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001296', '54500700-0000-4000-8000-000000000170', 'p-tourapi-3438589', '윤은재', '비 오는 날 운치 찾아 윤은재 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "인생샷", "가족여행", "온마루"]'::jsonb, 35.033470, 126.712265, '2026-09-22T16:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001297', '54500700-0000-4000-8000-000000000157', 'p-tourapi-1089992', '대전교통문화연수원', '오랜만에 여유 찾으러 대전교통문화연수원 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 36.377207, 127.386364, '2026-09-25T11:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001298', '54500700-0000-4000-8000-000000000183', 'p-tourapi-264570', '강남', '근처 여행 코스로 강남 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 37.526896, 127.027073, '2026-09-26T11:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001299', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2592489', '복합한옥공간 곳', '기대 이상으로 너무 좋았던 복합한옥공간 곳! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 37.579753, 126.987367, '2026-09-25T07:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001300', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2698680', '4.16희망목공소(4.16희망목공협동조합)', '4.16희망목공소(4.16희망목공협동조합) 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "데이트", "온마루"]'::jsonb, 37.343691, 126.834985, '2026-09-30T01:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001301', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3102081', '동파랑', '평일 연차 쓰고 혼자 동파랑 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 35.843940, 129.224478, '2026-09-11T06:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001302', '54500700-0000-4000-8000-000000000191', 'p-tourapi-1201060', '이천보고가', '예전부터 가보고 싶었던 이천보고가 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 37.798653, 127.348090, '2026-08-06T14:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001303', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2695742', '대성 정담한옥', '주말에 친구들이랑 대성 정담한옥 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.796724, 127.178317, '2026-09-12T01:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001304', '54500700-0000-4000-8000-000000000201', 'p-tourapi-128788', '설악산 케이블카', '비 오는 날 운치 찾아 설악산 케이블카 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 38.173154, 128.489166, '2026-08-05T01:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001305', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2717493', '삼버들협동조합', '비 오는 날 운치 찾아 삼버들협동조합 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷", "방문팁"]'::jsonb, 36.527709, 127.370087, '2026-08-23T06:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001306', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3532595', '오브헤리티지', '예전부터 가보고 싶었던 오브헤리티지 드디어 방문! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "사진맛집", "데이트"]'::jsonb, 34.546627, 127.137142, '2026-09-06T12:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001307', '54500700-0000-4000-8000-000000000161', 'p-tourapi-231940', '안동 소호헌', '비 오는 날 운치 찾아 안동 소호헌 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 36.463695, 128.663462, '2026-08-16T14:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001308', '54500700-0000-4000-8000-000000000169', 'p-tourapi-231933', '경주 양동 무첨당', '조용히 사색하고 싶어서 찾은 경주 양동 무첨당. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 36.002020, 129.252657, '2026-08-01T07:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001309', '54500700-0000-4000-8000-000000000105', 'p-tourapi-1972397', '주식회사 황남관', 'SNS에서 사진 보고 찾아간 주식회사 황남관, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁", "인생샷", "온마루"]'::jsonb, 35.833708, 129.209618, '2026-08-16T10:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001310', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2621825', '어울림', '기대 이상으로 너무 좋았던 어울림! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.813381, 127.153295, '2026-08-19T08:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001311', '54500700-0000-4000-8000-000000000062', 'p-tourapi-129051', '청송 송소 고택', '날씨가 너무 맑아서 청송 송소 고택 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "데이트"]'::jsonb, 36.436136, 129.026491, '2026-07-26T07:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001312', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3533165', '청량안채', '천천히 골목 걷다가 마주친 청량안채. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "주말나들이", "사진맛집"]'::jsonb, 37.574949, 127.048426, '2026-07-27T12:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001313', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2531675', '진도한옥펜션', '진도한옥펜션 다녀왔어요! 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 34.398482, 126.277327, '2026-09-06T07:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001314', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2570229', '결성향교', 'SNS에서 사진 보고 찾아간 결성향교, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 36.528794, 126.543250, '2026-09-08T20:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001315', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2996818', '반줄', '기대 이상으로 너무 좋았던 반줄! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.945451, 127.101776, '2026-08-02T05:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001316', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2721915', '밀양 월연정', '근처 여행 코스로 밀양 월연정 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.498663, 128.779954, '2026-08-16T08:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001317', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3102210', '선음재', 'SNS에서 사진 보고 찾아간 선음재, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.585097, 126.985631, '2026-08-03T19:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001318', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2821865', '향온', 'SNS에서 사진 보고 찾아간 향온, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "힐링", "온마루"]'::jsonb, 36.404006, 126.846248, '2026-07-17T16:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001319', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2603550', '무척산관광예술원', '평일 연차 쓰고 혼자 무척산관광예술원 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 35.383738, 128.839466, '2026-08-28T21:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001320', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3438368', '해아원', '드라이브 겸 나들이로 해아원 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.582897, 126.983320, '2026-08-19T04:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001321', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3438621', '희게', '천천히 골목 걷다가 마주친 희게. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 36.554282, 128.923586, '2026-08-10T13:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001322', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2715385', '난포정(蘭浦亭)', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "방문팁", "데이트"]'::jsonb, 37.482477, 128.849626, '2026-08-25T09:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001323', '54500700-0000-4000-8000-000000000122', 'p-tourapi-3438579', '스테이 한울', '날씨가 너무 맑아서 스테이 한울 한 바퀴 돌고 왔네요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 35.812648, 127.152359, '2026-07-20T11:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001324', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2990185', '금곡영화마을', '부모님 모시고 금곡영화마을 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 35.395210, 126.734176, '2026-09-14T14:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001325', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2604100', '예직한옥체험마을(용인예직한옥체험 마을)', '평일 연차 쓰고 혼자 예직한옥체험마을(용인예직한옥체험 마을) 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 37.191822, 127.255584, '2026-09-11T15:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001326', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2606296', '청풍호반케이블카', '평일 연차 쓰고 혼자 청풍호반케이블카 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 37.001314, 128.166802, '2026-08-01T11:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001327', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2782667', '김대기가옥', '날씨가 너무 맑아서 김대기가옥 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 36.692685, 128.410225, '2026-08-02T19:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001328', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2717549', '순솝', '예전부터 가보고 싶었던 순솝 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "주말나들이", "방문팁"]'::jsonb, 34.947674, 127.504205, '2026-08-02T11:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001329', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '비 오는 날 운치 찾아 제이한옥(JAY Hanok) 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "가족여행", "인생샷"]'::jsonb, 37.582308, 126.987336, '2026-07-25T02:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001330', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3453929', '경상북도교육청 발명체험교육관', '경상북도교육청 발명체험교육관 다녀왔어요! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 35.833375, 129.212993, '2026-07-19T15:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001331', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2481866', '백인제가옥', '평일 연차 쓰고 혼자 백인제가옥 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "산책로"]'::jsonb, 37.580469, 126.984142, '2026-07-19T02:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001332', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2770621', '향사례 대구시민단', '해 질 무렵에 향사례 대구시민단 방문했는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행", "사색"]'::jsonb, 35.898095, 128.601267, '2026-07-28T22:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001333', '54500700-0000-4000-8000-000000000195', 'p-tourapi-129182', '오색약수골전통장', '날씨가 너무 맑아서 오색약수골전통장 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 38.079749, 128.506280, '2026-07-23T01:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001334', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3582744', '한복남 한국민속촌점', '근처 여행 코스로 한복남 한국민속촌점 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.256757, 127.113931, '2026-07-21T17:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001335', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2932828', '우리술과힐링(주식회사우리술과힐링)', '우리술과힐링(주식회사우리술과힐링) 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 34.800738, 126.698180, '2026-09-02T11:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001336', '54500700-0000-4000-8000-000000000156', 'p-tourapi-129514', '정읍 전봉준 유적', '근처 여행 코스로 정읍 전봉준 유적 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 35.670914, 126.814519, '2026-09-02T22:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001337', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2606387', '예천군체육회활체험센터', '기대 이상으로 너무 좋았던 예천군체육회활체험센터! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "사진맛집", "온마루"]'::jsonb, 36.634678, 128.468413, '2026-08-25T15:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001338', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2409490', '만회고택', '근처 여행 코스로 만회고택 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.897302, 128.715223, '2026-08-26T17:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001339', '54500700-0000-4000-8000-000000000142', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '오랜만에 여유 찾으러 전주 풍패지관 (전주객사) 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.818500, 127.145400, '2026-08-24T14:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001340', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438569', '아담', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.450638, 127.122067, '2026-07-20T03:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001341', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2714563', '서편제 촬영지', '드라이브 겸 나들이로 서편제 촬영지 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 34.172272, 126.862103, '2026-08-31T15:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001342', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3102164', '황남별곡', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.837357, 129.210321, '2026-09-09T21:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001343', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3438684', '물길스테이', '해 질 무렵에 물길스테이 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 36.505586, 128.852705, '2026-07-28T12:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001344', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2775344', '지구마을산책', '비 오는 날 운치 찾아 지구마을산책 다녀왔어요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["주말나들이", "인생샷", "가족여행"]'::jsonb, 35.875767, 128.892347, '2026-08-15T03:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001345', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3438422', '한옥 스테이 미경', '날씨가 너무 맑아서 한옥 스테이 미경 한 바퀴 돌고 왔네요. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "사진맛집"]'::jsonb, 37.586652, 127.007921, '2026-09-02T21:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001346', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2725025', '소찬 협동조합', '비 오는 날 운치 찾아 소찬 협동조합 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["가족여행", "방문팁", "온마루"]'::jsonb, 36.513209, 126.814884, '2026-08-28T14:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001347', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2574307', '목양산방', 'SNS에서 사진 보고 찾아간 목양산방, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 34.889717, 127.507484, '2026-09-09T05:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001348', '54500700-0000-4000-8000-000000000126', 'p-tourapi-1005548', '충주 최응성 고가', '천천히 골목 걷다가 마주친 충주 최응성 고가. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 36.895772, 127.980199, '2026-08-10T22:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001349', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3438591', '구례 문 한옥 게스트 하우스', '조용히 사색하고 싶어서 찾은 구례 문 한옥 게스트 하우스. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링", "사색"]'::jsonb, 35.244037, 127.453633, '2026-07-29T12:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001350', '54500700-0000-4000-8000-000000000128', 'p-tourapi-2717286', '마린데크(커피마린협동조합)', '주말에 친구들이랑 마린데크(커피마린협동조합) 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.456778, 129.186075, '2026-09-07T09:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001351', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2708657', '초정행궁', '비 오는 날 운치 찾아 초정행궁 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 36.721236, 127.601291, '2026-09-11T21:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001352', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2820820', '위인더랜드', '근처 여행 코스로 위인더랜드 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.301738, 126.780513, '2026-09-11T17:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001353', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2775344', '지구마을산책', '지구마을산책 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 35.875767, 128.892347, '2026-07-22T09:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001354', '54500700-0000-4000-8000-000000000137', 'p-tourapi-128046', '여주 황포돛배', '조용히 사색하고 싶어서 찾은 여주 황포돛배. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.293112, 127.666922, '2026-08-03T15:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001355', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3102031', '소산당', '평일 연차 쓰고 혼자 소산당 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.206651, 127.511859, '2026-08-23T16:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001356', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2606296', '청풍호반케이블카', '예전부터 가보고 싶었던 청풍호반케이블카 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 37.001314, 128.166802, '2026-09-05T07:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001357', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2820659', '부여 선샤인', '날씨가 너무 맑아서 부여 선샤인 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.274232, 126.887320, '2026-08-17T18:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001358', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3354017', '술작가 양조장', '날씨가 너무 맑아서 술작가 양조장 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.473367, 126.641335, '2026-08-09T14:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001359', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2932973', '다올재', '날씨가 너무 맑아서 다올재 한 바퀴 돌고 왔네요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 34.955084, 127.480693, '2026-09-14T05:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001360', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2819158', '매원마을', '예전부터 가보고 싶었던 매원마을 드디어 방문! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["방문팁", "가족여행", "데이트"]'::jsonb, 35.994099, 128.430999, '2026-08-08T08:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001361', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3438674', '나들방', '오랜만에 여유 찾으러 나들방 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.816039, 127.151436, '2026-09-15T13:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001362', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2706568', '왕의지밀', '해 질 무렵에 왕의지밀 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "온마루"]'::jsonb, 35.799797, 127.178462, '2026-08-05T07:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001363', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2775365', '바다공룡 워케이션', '해 질 무렵에 바다공룡 워케이션 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 35.016750, 128.297998, '2026-07-18T07:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001364', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2743393', '강선대', '예전부터 가보고 싶었던 강선대 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집", "데이트", "온마루"]'::jsonb, 36.135210, 127.695732, '2026-08-02T09:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001365', '54500700-0000-4000-8000-000000000072', 'p-tourapi-1997639', '찰방공종택', '조용히 사색하고 싶어서 찾은 찰방공종택. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 36.437150, 129.026228, '2026-09-14T19:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001366', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2782981', '존재고택', '평일 연차 쓰고 혼자 존재고택 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "혼자여행", "힐링"]'::jsonb, 34.549500, 126.950118, '2026-09-13T16:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001367', '54500700-0000-4000-8000-000000000104', 'p-tourapi-1600719', '정종수 고택', '비 오는 날 운치 찾아 정종수 고택 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.773895, 126.858535, '2026-08-01T22:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001368', '54500700-0000-4000-8000-000000000115', 'p-tourapi-264311', '명동', '주말에 친구들이랑 명동 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "힐링", "온마루"]'::jsonb, 37.562152, 126.984915, '2026-07-20T02:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001369', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3438470', '한옥 카키', '근처 여행 코스로 한옥 카키 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.642397, 126.939164, '2026-08-24T04:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001370', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2669992', '산청 이사재', '기대 이상으로 너무 좋았던 산청 이사재! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.276606, 127.935071, '2026-08-17T20:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001371', '54500700-0000-4000-8000-000000000098', 'p-tourapi-736754', '홍승인고가', '드라이브 겸 나들이로 홍승인고가 선택했는데 대만족! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "풍경맛집"]'::jsonb, 37.152244, 126.959379, '2026-07-27T07:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001372', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2695757', '한옥게스트하우스 ''安(Ahn)''', '기대 이상으로 너무 좋았던 한옥게스트하우스 ''安(Ahn)''! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.872898, 128.610889, '2026-09-04T14:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001373', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2509933', '울산 큰애기집', '부모님 모시고 울산 큰애기집 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 35.556627, 129.321719, '2026-08-02T10:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001374', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3056624', '한복남 전주한옥마을점', '근처 여행 코스로 한복남 전주한옥마을점 넣길 정말 잘했어요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.814532, 127.152366, '2026-08-02T04:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001375', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2707445', '일독일박', '날씨가 너무 맑아서 일독일박 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.578486, 126.968545, '2026-09-03T17:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001376', '54500700-0000-4000-8000-000000000073', 'p-tourapi-3533128', '달에게 빌려온 하루', '해 질 무렵에 달에게 빌려온 하루 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 37.680970, 126.412531, '2026-08-27T03:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001377', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2604806', '목임당', '날씨가 너무 맑아서 목임당 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 34.951854, 127.201749, '2026-08-15T03:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001378', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3511602', '주식회사조아지구', '부모님 모시고 주식회사조아지구 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 35.944178, 127.164482, '2026-08-15T11:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001379', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3337761', '마마스홈퀴진', '평일 연차 쓰고 혼자 마마스홈퀴진 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.561501, 129.116689, '2026-08-30T18:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001380', '54500700-0000-4000-8000-000000000064', 'p-tourapi-1627167', '추사 김정희 선생 고택', '드라이브 겸 나들이로 추사 김정희 선생 고택 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "풍경맛집", "힐링"]'::jsonb, 36.746800, 126.798900, '2026-08-03T13:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001381', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438573', '자단', '평일 연차 쓰고 혼자 자단 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "고즈넉", "사색"]'::jsonb, 35.823741, 127.153289, '2026-08-01T21:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001382', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2996127', '기범이네국수', '오랜만에 여유 찾으러 기범이네국수 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 36.104796, 127.488265, '2026-09-11T07:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001383', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2701396', '서남산한옥', '서남산한옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 35.780864, 129.204559, '2026-07-21T16:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001384', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3511602', '주식회사조아지구', '천천히 골목 걷다가 마주친 주식회사조아지구. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.944178, 127.164482, '2026-08-07T20:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001385', '54500700-0000-4000-8000-000000000168', 'p-tourapi-780778', '이상한나라의 앨리스', 'SNS에서 사진 보고 찾아간 이상한나라의 앨리스, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "주말나들이", "사진맛집"]'::jsonb, 33.288973, 126.321826, '2026-09-13T05:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001386', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '기대 이상으로 너무 좋았던 나무키움(전의양묘영농조합법인)! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "방문팁", "인생샷"]'::jsonb, 36.676447, 127.197876, '2026-07-21T09:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001387', '54500700-0000-4000-8000-000000000062', 'p-tourapi-231899', '용흥궁', '평일 연차 쓰고 혼자 용흥궁 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 37.747894, 126.485987, '2026-07-26T16:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001388', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '부모님 모시고 버들국수 (농업법인 주식회사 유화 ㈜) 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 35.576300, 128.439048, '2026-09-11T21:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001389', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2569165', '수곡고택', '부모님 모시고 수곡고택 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 36.574103, 128.526316, '2026-08-30T22:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001390', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3080477', '수원전통문화관', '예전부터 가보고 싶었던 수원전통문화관 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.287470, 127.014633, '2026-09-10T22:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001391', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1626791', '영동 성장환 고택', '예전부터 가보고 싶었던 영동 성장환 고택 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 36.121398, 127.710465, '2026-08-19T12:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001392', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2613382', '수곡당', '조용히 사색하고 싶어서 찾은 수곡당. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 35.405340, 127.381974, '2026-09-06T22:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001393', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2593571', '부경당', '기대 이상으로 너무 좋았던 부경당! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 35.815989, 127.154236, '2026-08-20T11:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001394', '54500700-0000-4000-8000-000000000077', 'p-tourapi-250436', '아산 용궁댁', '근처 여행 코스로 아산 용궁댁 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "가족여행", "주말나들이"]'::jsonb, 36.740537, 126.892613, '2026-08-08T03:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001395', '54500700-0000-4000-8000-000000000134', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.558364, 126.994403, '2026-08-15T03:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001396', '54500700-0000-4000-8000-000000000188', 'p-tourapi-3451976', '길음역롯데캐슬트윈골드상가', '평일 연차 쓰고 혼자 길음역롯데캐슬트윈골드상가 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "산책로", "힐링", "온마루"]'::jsonb, 37.603853, 127.023488, '2026-07-20T03:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001397', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2605489', '군위 상매댁(군위남천고택)', '날씨가 너무 맑아서 군위 상매댁(군위남천고택) 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "방문팁", "데이트"]'::jsonb, 36.058677, 128.654013, '2026-09-02T18:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001398', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2569581', '춘하원(죽헌고택)', '오랜만에 여유 찾으러 춘하원(죽헌고택) 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.647336, 128.663423, '2026-07-31T04:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001399', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2795007', '화성 정수영 고택', '날씨가 너무 맑아서 화성 정수영 고택 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["가족여행", "인생샷", "데이트"]'::jsonb, 37.132502, 126.700661, '2026-08-28T19:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001400', '54500700-0000-4000-8000-000000000193', 'p-tourapi-1871262', '락고재 하회한옥호텔 초가별관', '드라이브 겸 나들이로 락고재 하회한옥호텔 초가별관 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 36.540511, 128.517525, '2026-07-26T05:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001401', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2696271', '공주공산성게스트 하우스', '해 질 무렵에 공주공산성게스트 하우스 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트", "사진맛집"]'::jsonb, 36.465170, 127.122763, '2026-08-22T03:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001402', '54500700-0000-4000-8000-000000000091', 'p-tourapi-1883758', '창실고택', '예전부터 가보고 싶었던 창실고택 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["사진맛집", "주말나들이", "가족여행", "온마루"]'::jsonb, 36.438275, 129.027039, '2026-09-08T14:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001403', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2605489', '군위 상매댁(군위남천고택)', '날씨가 너무 맑아서 군위 상매댁(군위남천고택) 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 36.058677, 128.654013, '2026-08-06T14:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001404', '54500700-0000-4000-8000-000000000128', 'p-tourapi-791531', '의성 소계당', '기대 이상으로 너무 좋았던 의성 소계당! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 36.400826, 128.774047, '2026-08-10T19:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001405', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2594216', '전주한옥마당', '예전부터 가보고 싶었던 전주한옥마당 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.811342, 127.152134, '2026-08-07T05:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001406', '54500700-0000-4000-8000-000000000180', 'p-tourapi-127588', '애은당고택·사우정고택·용계정', '부모님 모시고 애은당고택·사우정고택·용계정 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.166884, 129.186030, '2026-09-15T06:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001407', '54500700-0000-4000-8000-000000000134', 'p-tourapi-129584', '강릉 해운정', '조용히 사색하고 싶어서 찾은 강릉 해운정. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 37.786154, 128.891107, '2026-07-30T01:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001408', '54500700-0000-4000-8000-000000000153', 'p-tourapi-1584115', '익산 김병순 고택', '익산 김병순 고택 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "주말나들이", "가족여행", "온마루"]'::jsonb, 36.060814, 126.909606, '2026-08-14T21:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001409', '54500700-0000-4000-8000-000000000155', 'p-tourapi-1998565', '학봉종택', '천천히 골목 걷다가 마주친 학봉종택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트", "방문팁", "온마루"]'::jsonb, 36.609729, 128.669580, '2026-08-24T01:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001410', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2612804', '스카이큐브', '오랜만에 여유 찾으러 스카이큐브 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로", "힐링"]'::jsonb, 34.926790, 127.501834, '2026-09-10T23:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001411', '54500700-0000-4000-8000-000000000061', 'p-tourapi-4074857', '미옥스테이', '조용히 사색하고 싶어서 찾은 미옥스테이. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.866838, 128.612096, '2026-07-19T01:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001412', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2743393', '강선대', 'SNS에서 사진 보고 찾아간 강선대, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "산책로", "온마루"]'::jsonb, 36.135210, 127.695732, '2026-08-08T17:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001413', '54500700-0000-4000-8000-000000000191', 'p-tourapi-126795', '고성 어명기 고택', '날씨가 너무 맑아서 고성 어명기 고택 한 바퀴 돌고 왔네요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 38.314719, 128.517729, '2026-08-01T21:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001414', '54500700-0000-4000-8000-000000000120', 'p-tourapi-893974', '개평한옥마을', '평일 연차 쓰고 혼자 개평한옥마을 다녀옴. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "힐링"]'::jsonb, 35.565814, 127.767372, '2026-08-29T08:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001415', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', '예전부터 가보고 싶었던 주문진읍 BTS 앨범사진 촬영지 (버스정류장) 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 37.912546, 128.817052, '2026-08-16T00:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001416', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3428354', '스타필드 시티 부천', '스타필드 시티 부천 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.461527, 126.813928, '2026-07-27T08:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001417', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2000964', '향단', 'SNS에서 사진 보고 찾아간 향단, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "가족여행"]'::jsonb, 35.999890, 129.252940, '2026-07-28T05:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001418', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3353949', '㈜ 희품씨', '주말에 친구들이랑 ㈜ 희품씨 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.567161, 129.112429, '2026-08-10T05:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001419', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2850614', '스탈릿성수', '예전부터 가보고 싶었던 스탈릿성수 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.544494, 127.055473, '2026-08-27T23:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001420', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3105217', '오늘스테이 동대문점', '조용히 사색하고 싶어서 찾은 오늘스테이 동대문점. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "산책로", "사색"]'::jsonb, 37.577112, 127.037268, '2026-08-09T15:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001421', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3102032', '무아기와', '기대 이상으로 너무 좋았던 무아기와! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "주말나들이"]'::jsonb, 37.574949, 127.048426, '2026-07-24T04:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001422', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2575836', '북촌 게스트하우스', '조용히 사색하고 싶어서 찾은 북촌 게스트하우스. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "고즈넉", "풍경맛집"]'::jsonb, 37.578628, 126.985681, '2026-08-06T09:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001423', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2604533', '고집불통송가네', '오랜만에 여유 찾으러 고집불통송가네 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 34.441563, 126.631442, '2026-08-16T15:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001424', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2993587', '대구 신천물놀이장', '천천히 골목 걷다가 마주친 대구 신천물놀이장. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "방문팁", "온마루"]'::jsonb, 35.854272, 128.607554, '2026-08-17T01:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001425', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2621370', '태양아래월출산', '오랜만에 여유 찾으러 태양아래월출산 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "사색", "산책로", "온마루"]'::jsonb, 34.739842, 126.718469, '2026-07-17T21:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001426', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2502595', '술샘', '근처 여행 코스로 술샘 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 37.233510, 127.298585, '2026-08-18T01:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001427', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2996133', '(주)손으로만드는수공예', '드라이브 겸 나들이로 (주)손으로만드는수공예 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 36.099130, 127.492874, '2026-08-14T12:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001428', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2769810', '오창 미래지 한옥마을', '평일 연차 쓰고 혼자 오창 미래지 한옥마을 다녀옴. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 36.735102, 127.404736, '2026-07-29T08:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001429', '54500700-0000-4000-8000-000000000154', 'p-tourapi-1882371', '학인당', '해 질 무렵에 학인당 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.811812, 127.152057, '2026-08-20T09:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001430', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1594500', '전주목판서화체험관', '해 질 무렵에 전주목판서화체험관 방문했는데 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["사진맛집", "가족여행"]'::jsonb, 35.811515, 127.155650, '2026-07-27T11:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001431', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2613176', '현부자네 집', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "가족여행", "데이트"]'::jsonb, 34.849863, 127.353049, '2026-08-29T19:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001432', '54500700-0000-4000-8000-000000000196', 'p-tourapi-2746709', '파주팜랜드', '드라이브 겸 나들이로 파주팜랜드 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.810093, 126.692393, '2026-08-28T18:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001433', '54500700-0000-4000-8000-000000000118', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '비 오는 날 운치 찾아 노송정종택(퇴계생가) 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁", "사진맛집"]'::jsonb, 36.749721, 128.828350, '2026-08-27T05:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001434', '54500700-0000-4000-8000-000000000093', 'p-tourapi-1684863', '제천 지곡리 고가', '비 오는 날 운치 찾아 제천 지곡리 고가 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.004633, 128.171035, '2026-08-01T20:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001435', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2594862', '향우당', '기대 이상으로 너무 좋았던 향우당! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 35.602705, 128.907270, '2026-08-15T17:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001436', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2706613', '송계헌', '기대 이상으로 너무 좋았던 송계헌! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 36.543015, 128.556686, '2026-08-30T22:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001437', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3438684', '물길스테이', '조용히 사색하고 싶어서 찾은 물길스테이. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링"]'::jsonb, 36.505586, 128.852705, '2026-09-05T03:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001438', '54500700-0000-4000-8000-000000000139', 'p-tourapi-802358', '아산 대통령마을(농촌전통테마)', '조용히 사색하고 싶어서 찾은 아산 대통령마을(농촌전통테마). 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.834409, 127.022921, '2026-08-18T22:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001439', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2569165', '수곡고택', '근처 여행 코스로 수곡고택 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 36.574103, 128.526316, '2026-07-18T15:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001440', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2795007', '화성 정수영 고택', '평일 연차 쓰고 혼자 화성 정수영 고택 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 37.132502, 126.700661, '2026-09-12T19:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001441', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2700309', '경주읍성한옥', '조용히 사색하고 싶어서 찾은 경주읍성한옥. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 35.849567, 129.211526, '2026-08-28T10:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001442', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '해 질 무렵에 경북전통음식체험관 모심정 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 36.661949, 128.119119, '2026-07-23T03:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001443', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3529694', '서울아리', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 37.576723, 126.991345, '2026-08-31T04:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001444', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3511613', '전라감영양조장(전라감영주식회사)', '비 오는 날 운치 찾아 전라감영양조장(전라감영주식회사) 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.817342, 127.145881, '2026-09-07T09:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001445', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2046122', '정강원 관광농원', '드라이브 겸 나들이로 정강원 관광농원 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "가족여행"]'::jsonb, 37.570208, 128.408072, '2026-09-01T22:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001446', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2047895', '대승한지마을 한옥전통문화체험관', 'SNS에서 사진 보고 찾아간 대승한지마을 한옥전통문화체험관, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 35.854007, 127.294149, '2026-08-14T23:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001447', '54500700-0000-4000-8000-000000000157', 'p-tourapi-3102084', '산온 리트릿', '드라이브 겸 나들이로 산온 리트릿 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 36.573926, 128.578439, '2026-07-27T08:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001448', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2620182', '송담 고택', '평일 연차 쓰고 혼자 송담 고택 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 37.106547, 127.191898, '2026-08-15T05:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001449', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2605927', '초원사진관', '예전부터 가보고 싶었던 초원사진관 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "산책로", "온마루"]'::jsonb, 35.987737, 126.708383, '2026-09-08T22:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001450', '54500700-0000-4000-8000-000000000184', 'p-tourapi-1620863', '양금석가옥', '날씨가 너무 맑아서 양금석가옥 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 33.291311, 126.628597, '2026-07-31T12:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001451', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1621161', '제주 성읍마을 고창환 고택', '오랜만에 여유 찾으러 제주 성읍마을 고창환 고택 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 33.387294, 126.800135, '2026-07-27T11:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001452', '54500700-0000-4000-8000-000000000162', 'p-tourapi-264402', '화성어차', '비 오는 날 운치 찾아 화성어차 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "사진맛집", "인생샷"]'::jsonb, 37.287915, 127.023703, '2026-08-09T05:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001453', '54500700-0000-4000-8000-000000000123', 'p-tourapi-1939620', '보은 하얀민들레한옥마을', '보은 하얀민들레한옥마을 다녀왔어요! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "데이트", "사진맛집"]'::jsonb, 36.492056, 127.609666, '2026-09-11T05:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001454', '54500700-0000-4000-8000-000000000195', 'p-tourapi-792208', '괴산 한지체험박물관', '기대 이상으로 너무 좋았던 괴산 한지체험박물관! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 36.785439, 128.014900, '2026-09-01T20:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001455', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3438166', '뉠스테이', '오랜만에 여유 찾으러 뉠스테이 다녀왔습니다. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "사색", "힐링"]'::jsonb, 37.579350, 126.967738, '2026-09-03T13:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001456', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2696256', '낙안재', '드라이브 겸 나들이로 낙안재 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.835991, 129.208413, '2026-08-27T16:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001457', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2570638', '강령전', '기대 이상으로 너무 좋았던 강령전! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "주말나들이", "사진맛집", "온마루"]'::jsonb, 35.815053, 127.151934, '2026-09-06T10:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001458', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2702475', '고진하 가옥', '비 오는 날 운치 찾아 고진하 가옥 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 37.174095, 128.386897, '2026-08-15T16:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001459', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2603884', '연당', '평일 연차 쓰고 혼자 연당 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.582603, 126.987073, '2026-08-29T15:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001460', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3105334', '133파티룸 한옥스테이점', '평일 연차 쓰고 혼자 133파티룸 한옥스테이점 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.279463, 127.016073, '2026-07-23T01:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001461', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2651358', '홍휘관', '조용히 사색하고 싶어서 찾은 홍휘관. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉", "힐링"]'::jsonb, 36.465967, 127.122968, '2026-07-17T22:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001462', '54500700-0000-4000-8000-000000000173', 'p-tourapi-1626780', '예산 오추리 고택(정동호 가옥)', '조용히 사색하고 싶어서 찾은 예산 오추리 고택(정동호 가옥). 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 36.763845, 126.719911, '2026-08-10T03:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001463', '54500700-0000-4000-8000-000000000151', 'p-tourapi-742022', '한터농원(한터조랑말농장)', '드라이브 겸 나들이로 한터농원(한터조랑말농장) 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "사진맛집"]'::jsonb, 37.271263, 127.265303, '2026-08-11T10:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001464', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3066467', '우리 놀이터 마루달', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 35.816545, 127.152350, '2026-08-12T00:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001465', '54500700-0000-4000-8000-000000000065', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '부모님 모시고 선성현문화단지 한옥체험관 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.698302, 128.814675, '2026-09-06T05:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001466', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3072240', '온유헌 바이 버틀러리', 'SNS에서 사진 보고 찾아간 온유헌 바이 버틀러리, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.581611, 126.987489, '2026-08-01T11:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001467', '54500700-0000-4000-8000-000000000091', 'p-tourapi-971122', '강화 아르미애월드', '부모님 모시고 강화 아르미애월드 산책 겸 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷", "주말나들이"]'::jsonb, 37.702926, 126.434756, '2026-09-10T07:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001468', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2595871', '나들한옥', '평일 연차 쓰고 혼자 나들한옥 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 35.836116, 129.218364, '2026-07-29T12:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001469', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1627280', '단양 조덕수 고택', '평일 연차 쓰고 혼자 단양 조덕수 고택 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 37.003392, 128.383774, '2026-08-09T13:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001470', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3531662', '최선평 가옥', '주말에 친구들이랑 최선평 가옥 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링"]'::jsonb, 37.878304, 128.795960, '2026-08-11T07:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001471', '54500700-0000-4000-8000-000000000141', 'p-tourapi-987720', '신사동 가로수길', '예전부터 가보고 싶었던 신사동 가로수길 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.519705, 127.022757, '2026-09-07T08:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001472', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', '기대 이상으로 너무 좋았던 달달구리(주식회사달달구리)! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 35.938670, 127.166846, '2026-09-12T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001473', '54500700-0000-4000-8000-000000000155', 'p-tourapi-1972487', '시원 한옥체험관', '날씨가 너무 맑아서 시원 한옥체험관 한 바퀴 돌고 왔네요. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "가족여행", "방문팁", "온마루"]'::jsonb, 35.812616, 127.153801, '2026-07-23T10:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001474', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2725051', '다올재 협동조합', '날씨가 너무 맑아서 다올재 협동조합 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 34.955270, 127.480499, '2026-09-13T06:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001475', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3438588', '유유가', '평일 연차 쓰고 혼자 유유가 다녀옴. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "산책로", "풍경맛집"]'::jsonb, 34.955870, 127.483135, '2026-08-01T10:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001476', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2996749', '송금체험마을영농조합법인', '기대 이상으로 너무 좋았던 송금체험마을영농조합법인! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.713551, 128.720592, '2026-08-21T16:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001477', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2568571', '1928 쉼마루', '천천히 골목 걷다가 마주친 1928 쉼마루. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.811859, 127.152536, '2026-08-29T01:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001478', '54500700-0000-4000-8000-000000000120', 'p-tourapi-3533167', '황남채', '기대 이상으로 너무 좋았던 황남채! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.837052, 129.210321, '2026-09-02T00:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001479', '54500700-0000-4000-8000-000000000129', 'p-tourapi-127329', '목포시사', '오랜만에 여유 찾으러 목포시사 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 34.790017, 126.377297, '2026-08-17T02:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001480', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2009156', '고택문화체험관', '천천히 골목 걷다가 마주친 고택문화체험관. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷", "데이트", "온마루"]'::jsonb, 35.616604, 127.020195, '2026-07-20T10:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001481', '54500700-0000-4000-8000-000000000116', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', '해 질 무렵에 청송 평산신씨 판사공파 종택과 분가 고택 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "데이트", "사진맛집", "온마루"]'::jsonb, 36.458491, 129.022801, '2026-07-21T10:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001482', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3337188', '세종전통문화체험관', '해 질 무렵에 세종전통문화체험관 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 36.506871, 127.291859, '2026-09-15T10:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001483', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3449335', '고양드론앵커센터', '기대 이상으로 너무 좋았던 고양드론앵커센터! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 37.604415, 126.867258, '2026-08-19T05:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001484', '54500700-0000-4000-8000-000000000125', 'p-tourapi-129043', '청송 사남고택', '날씨가 너무 맑아서 청송 사남고택 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 36.458300, 129.021642, '2026-08-25T02:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001485', '54500700-0000-4000-8000-000000000117', 'p-tourapi-893974', '개평한옥마을', '드라이브 겸 나들이로 개평한옥마을 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.565814, 127.767372, '2026-09-01T00:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001486', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2683997', '카포레', '천천히 골목 걷다가 마주친 카포레. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 37.505770, 127.435390, '2026-09-02T02:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001487', '54500700-0000-4000-8000-000000000065', 'p-tourapi-1685627', '청풍 후산리 고가', '청풍 후산리 고가 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "사진맛집", "가족여행"]'::jsonb, 37.003994, 128.172490, '2026-08-07T11:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001488', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2575760', '연우당', '비 오는 날 운치 찾아 연우당 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.815586, 127.153136, '2026-07-21T03:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001489', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2900858', '제천비행장', '비 오는 날 운치 찾아 제천비행장 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 37.162851, 128.213624, '2026-08-10T15:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001490', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2777043', '김택준가옥', '부모님 모시고 김택준가옥 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.971882, 128.759283, '2026-09-12T14:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001491', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1623646', '권희문가옥', '날씨가 너무 맑아서 권희문가옥 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이", "방문팁", "온마루"]'::jsonb, 35.587661, 127.386260, '2026-07-30T14:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001492', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2604602', '경주 교동한옥집', '오랜만에 여유 찾으러 경주 교동한옥집 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.828919, 129.211782, '2026-09-05T03:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001493', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3438450', '평안채', '기대 이상으로 너무 좋았던 평안채! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "인생샷"]'::jsonb, 37.640873, 126.938714, '2026-09-05T05:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001494', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1578365', '거창 무릉리 정씨고가', '드라이브 겸 나들이로 거창 무릉리 정씨고가 선택했는데 대만족! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 35.664194, 127.945816, '2026-07-23T23:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001495', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2725123', '운기석9020(운기석9020협동조합)', '날씨가 너무 맑아서 운기석9020(운기석9020협동조합) 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "데이트", "사진맛집"]'::jsonb, 37.380565, 128.662682, '2026-09-07T15:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001496', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2706514', '여수한옥체험관', '비 오는 날 운치 찾아 여수한옥체험관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 34.748513, 127.630066, '2026-09-03T20:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001497', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '비 오는 날 운치 찾아 경주 황리단길 한옥 독채 풀빌라 무와 다녀왔어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.835985, 129.207990, '2026-08-30T05:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001498', '54500700-0000-4000-8000-000000000196', 'p-tourapi-1395466', '만해 한용운 심우장', '예전부터 가보고 싶었던 만해 한용운 심우장 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "사진맛집"]'::jsonb, 37.593599, 126.991816, '2026-08-07T00:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001499', '54500700-0000-4000-8000-000000000164', 'p-tourapi-1615878', '철종외가', '평일 연차 쓰고 혼자 철종외가 다녀옴. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.704924, 126.477278, '2026-08-25T14:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001500', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2569105', '너와 나의 둥지', '너와 나의 둥지 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 34.741020, 126.718124, '2026-07-26T10:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001501', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2623228', '권정생동화나라', 'SNS에서 사진 보고 찾아간 권정생동화나라, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "인생샷"]'::jsonb, 36.460707, 128.664809, '2026-08-26T01:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001502', '54500700-0000-4000-8000-000000000085', 'p-tourapi-128145', '나주 목사내아', '오랜만에 여유 찾으러 나주 목사내아 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.031915, 126.715352, '2026-08-09T20:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001503', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2609850', '마당예쁜집(전주한옥마을 마당예쁜집)', '예전부터 가보고 싶었던 마당예쁜집(전주한옥마을 마당예쁜집) 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "데이트"]'::jsonb, 35.812284, 127.153878, '2026-08-14T00:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001504', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2695757', '한옥게스트하우스 ''安(Ahn)''', '주말에 친구들이랑 한옥게스트하우스 ''安(Ahn)'' 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.872898, 128.610889, '2026-09-10T02:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001505', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2820027', '바른스포츠월드', '근처 여행 코스로 바른스포츠월드 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 36.599193, 127.423099, '2026-08-26T02:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001506', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2784682', '진해루', 'SNS에서 사진 보고 찾아간 진해루, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "산책로"]'::jsonb, 35.147185, 128.685143, '2026-09-12T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001507', '54500700-0000-4000-8000-000000000117', 'p-tourapi-1951619', '비암사 도깨비도로', '천천히 골목 걷다가 마주친 비암사 도깨비도로. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.610910, 127.191878, '2026-07-26T12:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001508', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3438724', '소월정', '해 질 무렵에 소월정 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.583277, 126.986492, '2026-08-05T08:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001509', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2699326', '월출산 청풍명월', '비 오는 날 운치 찾아 월출산 청풍명월 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 34.769877, 126.654557, '2026-08-03T11:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001510', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2608154', '조약도 한옥체험', '오랜만에 여유 찾으러 조약도 한옥체험 다녀왔습니다. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 34.373225, 126.888001, '2026-07-21T00:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001511', '54500700-0000-4000-8000-000000000089', 'p-tourapi-4070358', '호메오', '기대 이상으로 너무 좋았던 호메오! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집"]'::jsonb, 35.815258, 127.142134, '2026-08-27T17:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001512', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3116447', '웰컴미스테익스', 'SNS에서 사진 보고 찾아간 웰컴미스테익스, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.591722, 126.963228, '2026-08-03T08:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001513', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3438126', '스테이 어플로트', '스테이 어플로트 다녀왔어요! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "사색", "산책로"]'::jsonb, 37.578722, 126.972782, '2026-07-24T21:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001514', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1992717', '의성 소우당', '비 오는 날 운치 찾아 의성 소우당 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 36.245624, 128.701551, '2026-09-06T23:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001515', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3532720', '메모리스테이 효자', '드라이브 겸 나들이로 메모리스테이 효자 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 37.582736, 126.971016, '2026-09-02T07:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001516', '54500700-0000-4000-8000-000000000146', 'p-tourapi-4039810', '스테이꼬리', '날씨가 너무 맑아서 스테이꼬리 한 바퀴 돌고 왔네요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 35.813146, 129.212540, '2026-07-26T09:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001517', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2995169', '농업회사법인 주식회사 공동체공간 수작', '부모님 모시고 농업회사법인 주식회사 공동체공간 수작 산책 겸 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "고즈넉", "산책로"]'::jsonb, 35.942063, 127.263195, '2026-09-03T06:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001518', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2569824', '흥해배씨 임연재종택', '날씨가 너무 맑아서 흥해배씨 임연재종택 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉", "혼자여행"]'::jsonb, 36.550011, 128.791685, '2026-07-31T12:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001519', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2575841', '지우당', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.812862, 127.154059, '2026-07-27T20:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001520', '54500700-0000-4000-8000-000000000190', 'p-tourapi-705411', '군위 남천고택', '군위 남천고택 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 36.058639, 128.653986, '2026-08-20T10:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001521', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2586166', '황토한옥고마', '황토한옥고마 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 36.461445, 127.122366, '2026-07-19T00:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001522', '54500700-0000-4000-8000-000000000056', 'p-tourapi-971122', '강화 아르미애월드', '날씨가 너무 맑아서 강화 아르미애월드 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 37.702926, 126.434756, '2026-09-11T10:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001523', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2778518', '주포지구한옥전원마을', '오랜만에 여유 찾으러 주포지구한옥전원마을 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.091951, 126.461197, '2026-07-24T13:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001524', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2697287', '하서원(외암민속마을)', '기대 이상으로 너무 좋았던 하서원(외암민속마을)! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["사진맛집", "인생샷"]'::jsonb, 36.731535, 127.014419, '2026-08-25T03:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001525', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2679044', '청향재', '해 질 무렵에 청향재 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 37.641706, 126.940197, '2026-07-28T03:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001526', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3072315', '담담', '기대 이상으로 너무 좋았던 담담! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 36.453646, 127.121900, '2026-07-23T14:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001527', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3454074', '영화의전당 라이브러리 자료실', '주말에 친구들이랑 영화의전당 라이브러리 자료실 들렀는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 35.171003, 129.127069, '2026-07-29T13:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001528', '54500700-0000-4000-8000-000000000095', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '천천히 골목 걷다가 마주친 노송정종택(퇴계생가). 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 36.749721, 128.828350, '2026-08-24T12:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001529', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2819644', '적정온도(순향가)', '예전부터 가보고 싶었던 적정온도(순향가) 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "인생샷"]'::jsonb, 34.872833, 127.528064, '2026-08-13T05:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001530', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2707445', '일독일박', '비 오는 날 운치 찾아 일독일박 다녀왔어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 37.578486, 126.968545, '2026-07-21T16:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001531', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3541047', '주문진 관광안내센터', '근처 여행 코스로 주문진 관광안내센터 넣길 정말 잘했어요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 37.889982, 128.828574, '2026-08-17T15:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001532', '54500700-0000-4000-8000-000000000060', 'p-tourapi-3438182', '여느날', '주말에 친구들이랑 여느날 들렀는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.576570, 126.969605, '2026-07-18T13:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001533', '54500700-0000-4000-8000-000000000171', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '해 질 무렵에 수내동가옥(이택구가옥) 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 37.380351, 127.121194, '2026-08-04T04:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001534', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2350029', '도래미하우스', '천천히 골목 걷다가 마주친 도래미하우스. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "데이트", "인생샷", "온마루"]'::jsonb, 34.997557, 126.824853, '2026-08-10T10:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001535', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2683997', '카포레', '오랜만에 여유 찾으러 카포레 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.505770, 127.435390, '2026-07-26T06:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001536', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3102068', '경주 황리단길 한옥 독채 풀빌라 무와', '조용히 사색하고 싶어서 찾은 경주 황리단길 한옥 독채 풀빌라 무와. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.835985, 129.207990, '2026-08-06T10:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001537', '54500700-0000-4000-8000-000000000162', 'p-tourapi-127060', '이장우가옥', '이장우가옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 35.140617, 126.914133, '2026-08-03T16:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001538', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2663065', '휴휴당', '비 오는 날 운치 찾아 휴휴당 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.835513, 129.212276, '2026-08-19T16:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001539', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3072218', '오히', '기대 이상으로 너무 좋았던 오히! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.824170, 129.212582, '2026-08-11T16:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001540', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1883593', '월인당', '해 질 무렵에 월인당 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 34.777745, 126.612364, '2026-09-02T13:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001541', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2795956', '양평 창대리 고가', '부모님 모시고 양평 창대리 고가 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 37.471103, 127.505915, '2026-08-25T10:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001542', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2598628', '별아래한옥', '조용히 사색하고 싶어서 찾은 별아래한옥. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 36.537190, 128.821374, '2026-07-24T08:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001543', '54500700-0000-4000-8000-000000000113', 'p-tourapi-800812', '장성 자라뫼마을 [농촌전통테마]', '장성 자라뫼마을 [농촌전통테마] 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "산책로", "온마루"]'::jsonb, 35.419942, 126.821986, '2026-07-29T01:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001544', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2707444', '가영당', '평일 연차 쓰고 혼자 가영당 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "풍경맛집", "산책로", "온마루"]'::jsonb, 36.735122, 127.405542, '2026-09-11T18:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001545', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2786859', '읍청정(산청)', '오랜만에 여유 찾으러 읍청정(산청) 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "혼자여행", "산책로"]'::jsonb, 35.308869, 127.965517, '2026-07-21T17:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001546', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3012678', '사기막골 도예촌', '천천히 골목 걷다가 마주친 사기막골 도예촌. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.293633, 127.411828, '2026-07-19T22:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001547', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2696271', '공주공산성게스트 하우스', '오랜만에 여유 찾으러 공주공산성게스트 하우스 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "혼자여행", "산책로"]'::jsonb, 36.465170, 127.122763, '2026-08-08T09:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001548', '54500700-0000-4000-8000-000000000060', 'p-tourapi-1947036', '스미스가 좋아하는 한옥', '평일 연차 쓰고 혼자 스미스가 좋아하는 한옥 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 37.578031, 126.980048, '2026-07-17T19:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001549', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2599272', '모지고택', '모지고택 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "데이트", "온마루"]'::jsonb, 36.540737, 128.518264, '2026-07-18T09:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001550', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '예전부터 가보고 싶었던 농업회사법인주식회사꿀벌인 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 36.014031, 128.421877, '2026-07-20T08:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001551', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2742194', '울산시립어린이테마파크', '예전부터 가보고 싶었던 울산시립어린이테마파크 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 35.488518, 129.437747, '2026-08-14T20:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001552', '54500700-0000-4000-8000-000000000144', 'p-tourapi-2701356', '달빛한옥 수류화개', '부모님 모시고 달빛한옥 수류화개 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 34.739148, 126.717016, '2026-09-04T19:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001553', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2932873', '계와고택', '근처 여행 코스로 계와고택 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 36.506191, 128.852914, '2026-09-12T06:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001554', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2605277', '웰컴투동막골촬영지', '해 질 무렵에 웰컴투동막골촬영지 방문했는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 37.313992, 128.470760, '2026-09-05T09:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001555', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3116447', '웰컴미스테익스', '평일 연차 쓰고 혼자 웰컴미스테익스 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "산책로"]'::jsonb, 37.591722, 126.963228, '2026-08-20T08:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001556', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3438422', '한옥 스테이 미경', '드라이브 겸 나들이로 한옥 스테이 미경 선택했는데 대만족! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "풍경맛집"]'::jsonb, 37.586652, 127.007921, '2026-08-12T06:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001557', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2702475', '고진하 가옥', '예전부터 가보고 싶었던 고진하 가옥 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링"]'::jsonb, 37.174095, 128.386897, '2026-08-17T15:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001558', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3438586', '휴휴가', '기대 이상으로 너무 좋았던 휴휴가! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁", "온마루"]'::jsonb, 34.955134, 127.480782, '2026-08-20T21:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001559', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2996647', '정촌유기농원', 'SNS에서 사진 보고 찾아간 정촌유기농원, 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 36.425472, 126.672099, '2026-08-25T16:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001560', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', 'SNS에서 사진 보고 찾아간 아동청소년친화공간 꿈이랑, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 38.199574, 128.580209, '2026-09-05T15:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001561', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3438585', '스테이 구도', '예전부터 가보고 싶었던 스테이 구도 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "주말나들이", "사진맛집"]'::jsonb, 34.791917, 126.380222, '2026-08-11T16:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001562', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3072235', '유준당 바이 버틀러리', '기대 이상으로 너무 좋았던 유준당 바이 버틀러리! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 37.582111, 126.987314, '2026-09-13T03:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001563', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2707444', '가영당', '비 오는 날 운치 찾아 가영당 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "가족여행", "인생샷", "온마루"]'::jsonb, 36.735122, 127.405542, '2026-08-08T03:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001564', '54500700-0000-4000-8000-000000000187', 'p-tourapi-126419', '다산초당', '평일 연차 쓰고 혼자 다산초당 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 34.580650, 126.745073, '2026-07-29T12:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001565', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2569237', '운정루', '평일 연차 쓰고 혼자 운정루 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "풍경맛집", "산책로", "온마루"]'::jsonb, 35.791283, 129.245897, '2026-07-27T16:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001566', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3511656', '하얀민들레마을(주식회사미진)', '천천히 골목 걷다가 마주친 하얀민들레마을(주식회사미진). 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 36.493609, 127.611311, '2026-08-11T22:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001567', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2782543', '보성 이진래고택', '근처 여행 코스로 보성 이진래고택 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 34.762787, 127.186655, '2026-09-02T22:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001568', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2701896', '평창지동봉가옥', '드라이브 겸 나들이로 평창지동봉가옥 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.333462, 128.379317, '2026-08-02T05:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001569', '54500700-0000-4000-8000-000000000063', 'p-tourapi-2667868', '마음의 고향', 'SNS에서 사진 보고 찾아간 마음의 고향, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 35.032787, 126.391307, '2026-09-08T08:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001570', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2850183', '대한옥', '드라이브 겸 나들이로 대한옥 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이", "방문팁", "온마루"]'::jsonb, 37.519414, 126.910895, '2026-08-23T18:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001571', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2751703', '달팽이', '비 오는 날 운치 찾아 달팽이 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "산책로"]'::jsonb, 35.413979, 127.616603, '2026-07-19T19:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001572', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '조용히 사색하고 싶어서 찾은 미담 한옥 게스트 하우스. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "사색"]'::jsonb, 37.580664, 126.986353, '2026-07-17T22:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001573', '54500700-0000-4000-8000-000000000143', 'p-tourapi-250460', '남원몽심재', '예전부터 가보고 싶었던 남원몽심재 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 35.337994, 127.374746, '2026-08-07T16:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001574', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3102131', '여여재', '부모님 모시고 여여재 산책 겸 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "가족여행", "데이트"]'::jsonb, 37.283865, 127.008904, '2026-08-11T04:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001575', '54500700-0000-4000-8000-000000000138', 'p-tourapi-3544376', '강릉종합사회복지관', '오랜만에 여유 찾으러 강릉종합사회복지관 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 37.764743, 128.916148, '2026-08-02T21:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001576', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2702475', '고진하 가옥', '평일 연차 쓰고 혼자 고진하 가옥 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "힐링", "온마루"]'::jsonb, 37.174095, 128.386897, '2026-08-12T15:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001577', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2998479', '삼판서고택', '비 오는 날 운치 찾아 삼판서고택 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "가족여행", "온마루"]'::jsonb, 36.820564, 128.616192, '2026-08-27T23:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001578', '54500700-0000-4000-8000-000000000139', 'p-tourapi-1437668', '순창장류체험관', '드라이브 겸 나들이로 순창장류체험관 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.365887, 127.108041, '2026-08-13T10:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001579', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2717416', '올드타임', '드라이브 겸 나들이로 올드타임 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "사진맛집", "온마루"]'::jsonb, 37.000182, 127.200417, '2026-07-28T12:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001580', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2604371', '노을한옥', '천천히 골목 걷다가 마주친 노을한옥. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "고즈넉", "힐링"]'::jsonb, 34.851191, 127.523245, '2026-09-15T05:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001581', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2605277', '웰컴투동막골촬영지', 'SNS에서 사진 보고 찾아간 웰컴투동막골촬영지, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.313992, 128.470760, '2026-08-25T19:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001582', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3102084', '산온 리트릿', '천천히 골목 걷다가 마주친 산온 리트릿. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "가족여행", "방문팁"]'::jsonb, 36.573926, 128.578439, '2026-08-24T14:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001583', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2358186', '쌍산재', '드라이브 겸 나들이로 쌍산재 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.215716, 127.498082, '2026-09-09T15:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001584', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2789519', '황병산사냥민속놀이체험관', '황병산사냥민속놀이체험관 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.707181, 128.687251, '2026-08-22T17:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001585', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2817792', '밀알영농조합', '비 오는 날 운치 찾아 밀알영농조합 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 35.081710, 128.185789, '2026-08-24T23:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001586', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3510971', '컬러브릿지협동조합', '기대 이상으로 너무 좋았던 컬러브릿지협동조합! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.141137, 126.916908, '2026-08-12T21:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001587', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2717292', '카페 방림별곡', '조용히 사색하고 싶어서 찾은 카페 방림별곡. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "혼자여행"]'::jsonb, 37.426499, 128.394686, '2026-08-05T23:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001588', '54500700-0000-4000-8000-000000000130', 'p-tourapi-2633890', '통영어드벤처타워', '기대 이상으로 너무 좋았던 통영어드벤처타워! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 34.824779, 128.422401, '2026-09-10T21:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001589', '54500700-0000-4000-8000-000000000100', 'p-tourapi-1623646', '권희문가옥', '부모님 모시고 권희문가옥 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 35.587661, 127.386260, '2026-07-20T18:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001590', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2717494', '쌍류포도정원협동조합', '평일 연차 쓰고 혼자 쌍류포도정원협동조합 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "힐링"]'::jsonb, 36.603381, 127.216182, '2026-08-15T08:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001591', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1992090', '논산 명재고택', '천천히 골목 걷다가 마주친 논산 명재고택. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 36.281869, 127.131209, '2026-09-04T08:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001592', '54500700-0000-4000-8000-000000000145', 'p-tourapi-1605990', '관훈동 민씨 가옥 (구 부마도위박영효가옥)', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "인생샷", "방문팁", "온마루"]'::jsonb, 37.558508, 126.993575, '2026-08-10T12:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001593', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3438431', '사월 한옥', '평일 연차 쓰고 혼자 사월 한옥 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.593910, 127.000024, '2026-08-11T08:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001594', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3007507', '호수양조장', '비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 37.872331, 127.731141, '2026-07-31T07:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001595', '54500700-0000-4000-8000-000000000200', 'p-tourapi-1883536', '산청율수원', '예전부터 가보고 싶었던 산청율수원 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.380312, 128.010272, '2026-09-01T14:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001596', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2607706', '곡전재', '기대 이상으로 너무 좋았던 곡전재! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.203570, 127.513904, '2026-09-05T03:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001597', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2736325', '전주 한옥마을 덕수궁', '비 오는 날 운치 찾아 전주 한옥마을 덕수궁 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트", "사진맛집"]'::jsonb, 35.816664, 127.155750, '2026-08-04T23:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001598', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2676000', '응정헌', '예전부터 가보고 싶었던 응정헌 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["가족여행", "방문팁", "데이트"]'::jsonb, 37.640298, 126.939686, '2026-07-31T10:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001599', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2932894', '주월재', '천천히 골목 걷다가 마주친 주월재. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 34.779345, 127.167378, '2026-07-19T18:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001600', '54500700-0000-4000-8000-000000000190', 'p-tourapi-231938', '서울 경모궁지', '부모님 모시고 서울 경모궁지 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로", "풍경맛집", "온마루"]'::jsonb, 37.580402, 126.999009, '2026-09-13T16:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001601', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2695730', '효자스테이', '근처 여행 코스로 효자스테이 넣길 정말 잘했어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 37.578800, 126.973488, '2026-07-21T12:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001602', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1883996', '취옹예술관', '천천히 골목 걷다가 마주친 취옹예술관. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "인생샷", "가족여행"]'::jsonb, 37.752549, 127.359939, '2026-08-24T08:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001603', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2531372', '소설재', '주말에 친구들이랑 소설재 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트", "사진맛집"]'::jsonb, 35.834185, 129.214507, '2026-07-22T19:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001604', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2708325', '봉황재 한옥 게스트하우스', '평일 연차 쓰고 혼자 봉황재 한옥 게스트하우스 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 36.450819, 127.120031, '2026-09-04T14:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001605', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2770621', '향사례 대구시민단', '향사례 대구시민단 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.898095, 128.601267, '2026-07-19T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001606', '54500700-0000-4000-8000-000000000162', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', '평일 연차 쓰고 혼자 국가유산 방문 캠페인 인천공항 홍보관 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 37.447703, 126.452175, '2026-09-11T17:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001607', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3447048', '사우당 종택', '부모님 모시고 사우당 종택 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁", "인생샷", "온마루"]'::jsonb, 35.828256, 128.214952, '2026-08-07T14:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001608', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2594831', '양참사댁(양동호 가옥 / 한옥152)', '부모님 모시고 양참사댁(양동호 가옥 / 한옥152) 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 34.984345, 126.911408, '2026-09-12T23:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001609', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3438450', '평안채', '천천히 골목 걷다가 마주친 평안채. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 37.640873, 126.938714, '2026-08-19T01:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001610', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2569552', '셔블', '셔블 다녀왔어요! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉", "힐링"]'::jsonb, 35.836816, 129.211543, '2026-08-28T08:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001611', '54500700-0000-4000-8000-000000000079', 'p-tourapi-1971911', '채원당', '오랜만에 여유 찾으러 채원당 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "힐링"]'::jsonb, 35.275784, 127.307017, '2026-07-22T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001612', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2574250', '라온한옥꿀잠', '근처 여행 코스로 라온한옥꿀잠 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 35.815836, 127.154314, '2026-08-23T14:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001613', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2358186', '쌍산재', '쌍산재 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "주말나들이", "데이트"]'::jsonb, 35.215716, 127.498082, '2026-07-28T10:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001614', '54500700-0000-4000-8000-000000000172', 'p-tourapi-3102203', '함라한옥체험단지', '부모님 모시고 함라한옥체험단지 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "풍경맛집", "온마루"]'::jsonb, 36.062774, 126.909874, '2026-07-29T09:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001615', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2605443', '사나래한옥', '평일 연차 쓰고 혼자 사나래한옥 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 34.837123, 126.902747, '2026-08-22T18:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001616', '54500700-0000-4000-8000-000000000178', 'p-tourapi-3438583', '여유', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 35.812420, 127.158586, '2026-07-21T20:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001617', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2777057', '이두형가옥', '비 오는 날 운치 찾아 이두형가옥 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁", "온마루"]'::jsonb, 38.087832, 128.567839, '2026-07-22T08:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001618', '54500700-0000-4000-8000-000000000057', 'p-tourapi-3438622', '스테이 나스러움', '비 오는 날 운치 찾아 스테이 나스러움 다녀왔어요. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁"]'::jsonb, 36.563329, 128.713671, '2026-07-19T01:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001619', '54500700-0000-4000-8000-000000000200', 'p-tourapi-2939003', '영월애살으리랏다', '천천히 골목 걷다가 마주친 영월애살으리랏다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 37.243614, 128.355684, '2026-07-28T02:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001620', '54500700-0000-4000-8000-000000000128', 'p-tourapi-2782981', '존재고택', '기대 이상으로 너무 좋았던 존재고택! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "힐링", "사색"]'::jsonb, 34.549500, 126.950118, '2026-09-15T11:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001621', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2995167', '달달구리(주식회사달달구리)', '부모님 모시고 달달구리(주식회사달달구리) 산책 겸 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 35.938670, 127.166846, '2026-09-08T23:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001622', '54500700-0000-4000-8000-000000000126', 'p-tourapi-1882248', '인우하우스', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 37.582709, 126.986956, '2026-09-05T20:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001623', '54500700-0000-4000-8000-000000000083', 'p-tourapi-3532989', '예선재', '주말에 친구들이랑 예선재 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 36.962072, 127.938133, '2026-09-01T04:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001624', '54500700-0000-4000-8000-000000000068', 'p-tourapi-3351556', '서천문화예술창작공간', 'SNS에서 사진 보고 찾아간 서천문화예술창작공간, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집", "방문팁", "온마루"]'::jsonb, 36.008334, 126.695905, '2026-08-10T00:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001625', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3532595', '오브헤리티지', 'SNS에서 사진 보고 찾아간 오브헤리티지, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "힐링", "온마루"]'::jsonb, 34.546627, 127.137142, '2026-09-15T03:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001626', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2570109', '망와고택', '조용히 사색하고 싶어서 찾은 망와고택. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "풍경맛집", "산책로"]'::jsonb, 36.982774, 128.739107, '2026-09-10T02:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001627', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2668426', '학림재', '비 오는 날 운치 찾아 학림재 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "주말나들이", "온마루"]'::jsonb, 36.551056, 127.189936, '2026-08-24T17:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001628', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2633890', '통영어드벤처타워', '부모님 모시고 통영어드벤처타워 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 34.824779, 128.422401, '2026-08-05T05:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001629', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2409490', '만회고택', '평일 연차 쓰고 혼자 만회고택 다녀옴. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링"]'::jsonb, 36.897302, 128.715223, '2026-08-01T11:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001630', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3532618', '산성동그곳', '해 질 무렵에 산성동그곳 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "산책로", "혼자여행"]'::jsonb, 36.458874, 127.126462, '2026-08-20T18:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001631', '54500700-0000-4000-8000-000000000182', 'p-tourapi-128591', '창녕 진양하씨 고택', '비 오는 날 운치 찾아 창녕 진양하씨 고택 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행", "온마루"]'::jsonb, 35.540554, 128.496111, '2026-08-10T14:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001632', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1594374', '전주전통한지원', '조용히 사색하고 싶어서 찾은 전주전통한지원. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 35.815995, 127.153533, '2026-08-29T06:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001633', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2668091', '구림전통한옥민박', '기대 이상으로 너무 좋았던 구림전통한옥민박! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "방문팁", "사진맛집"]'::jsonb, 34.763510, 126.621510, '2026-08-18T14:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001634', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3533114', '스테이여유담', '예전부터 가보고 싶었던 스테이여유담 드디어 방문! 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.051415, 126.864112, '2026-08-13T23:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001635', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2699607', '모꼬지', '부모님 모시고 모꼬지 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 35.811895, 127.156228, '2026-07-17T20:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001636', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2588908', '모항갯벌체험장', '비 오는 날 운치 찾아 모항갯벌체험장 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 35.587229, 126.513866, '2026-09-13T14:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001637', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2932435', '3S', '오랜만에 여유 찾으러 3S 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 34.918992, 126.396379, '2026-08-26T20:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001638', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2572817', '옥산정사 독락당', '부모님 모시고 옥산정사 독락당 산책 겸 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 36.016958, 129.159976, '2026-08-22T23:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001639', '54500700-0000-4000-8000-000000000058', 'p-tourapi-1626784', '영동규당고택', '예전부터 가보고 싶었던 영동규당고택 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "가족여행", "방문팁"]'::jsonb, 36.180692, 127.776338, '2026-07-24T08:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001640', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '평일 연차 쓰고 혼자 한옥 201(Hanok 201) 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.580558, 126.985414, '2026-08-02T19:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001641', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2572817', '옥산정사 독락당', '기대 이상으로 너무 좋았던 옥산정사 독락당! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "데이트", "사진맛집", "온마루"]'::jsonb, 36.016958, 129.159976, '2026-08-09T02:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001642', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2820794', '별내리마을', '해 질 무렵에 별내리마을 방문했는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "혼자여행", "온마루"]'::jsonb, 35.455167, 126.843373, '2026-07-19T20:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001643', '54500700-0000-4000-8000-000000000119', 'p-tourapi-1799268', '회원식당', '예전부터 가보고 싶었던 회원식당 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "고즈넉", "혼자여행"]'::jsonb, 35.078071, 127.769291, '2026-07-22T16:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001644', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2570611', '잊음', '오랜만에 여유 찾으러 잊음 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 34.846535, 128.418809, '2026-07-31T05:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001645', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3101965', '스테이서문', '스테이서문 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷", "가족여행", "온마루"]'::jsonb, 35.033584, 126.712506, '2026-09-06T08:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001646', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2606387', '예천군체육회활체험센터', '비 오는 날 운치 찾아 예천군체육회활체험센터 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 36.634678, 128.468413, '2026-07-27T06:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001647', '54500700-0000-4000-8000-000000000192', 'p-tourapi-127371', '수내동가옥(이택구가옥)', '조용히 사색하고 싶어서 찾은 수내동가옥(이택구가옥). 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.380351, 127.121194, '2026-08-20T22:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001648', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2995168', '유한회사복합문화공간 서리울', '평일 연차 쓰고 혼자 유한회사복합문화공간 서리울 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 36.015152, 127.145485, '2026-07-24T10:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001649', '54500700-0000-4000-8000-000000000119', 'p-tourapi-250369', '퇴계종택', 'SNS에서 사진 보고 찾아간 퇴계종택, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["사진맛집", "인생샷", "주말나들이"]'::jsonb, 36.736862, 128.848777, '2026-08-20T13:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001650', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2623573', '한미장', '주말에 친구들이랑 한미장 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "사진맛집", "인생샷", "온마루"]'::jsonb, 37.671220, 127.007590, '2026-08-29T04:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001651', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3438470', '한옥 카키', '부모님 모시고 한옥 카키 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.642397, 126.939164, '2026-07-26T19:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001652', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3532717', '스테이 안김A', '평일 연차 쓰고 혼자 스테이 안김A 다녀옴. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.835527, 129.212995, '2026-08-07T20:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001653', '54500700-0000-4000-8000-000000000195', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '주말에 친구들이랑 전주한옥마을 독채덕수궁 들렀는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 35.816792, 127.151648, '2026-08-29T00:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001654', '54500700-0000-4000-8000-000000000082', 'p-tourapi-1677831', '괴산 수월정', '드라이브 겸 나들이로 괴산 수월정 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 36.747126, 127.840761, '2026-08-11T18:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001655', '54500700-0000-4000-8000-000000000119', 'p-tourapi-2717494', '쌍류포도정원협동조합', '조용히 사색하고 싶어서 찾은 쌍류포도정원협동조합. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 36.603381, 127.216182, '2026-07-22T11:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001656', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3101961', '자미재', '해 질 무렵에 자미재 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 34.911789, 126.648057, '2026-09-11T16:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001657', '54500700-0000-4000-8000-000000000178', 'p-tourapi-1437668', '순창장류체험관', 'SNS에서 사진 보고 찾아간 순창장류체험관, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.365887, 127.108041, '2026-09-10T00:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001658', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2696528', '토박이숙박', '조용히 사색하고 싶어서 찾은 토박이숙박. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "힐링", "고즈넉"]'::jsonb, 35.813664, 127.152175, '2026-08-30T03:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001659', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3438573', '자단', '마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 35.823741, 127.153289, '2026-08-28T01:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001660', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2509933', '울산 큰애기집', '기대 이상으로 너무 좋았던 울산 큰애기집! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "인생샷", "사진맛집"]'::jsonb, 35.556627, 129.321719, '2026-07-18T04:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001661', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2050339', '장보고한옥펜션', 'SNS에서 사진 보고 찾아간 장보고한옥펜션, 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 37.762661, 126.446945, '2026-08-27T03:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001662', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2869033', '광릉한옥점', '광릉한옥점 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "방문팁", "인생샷"]'::jsonb, 37.743115, 127.199321, '2026-09-04T00:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001663', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3438166', '뉠스테이', '주말에 친구들이랑 뉠스테이 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 37.579350, 126.967738, '2026-08-03T00:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001664', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2660381', '매월당', '부모님 모시고 매월당 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.348864, 127.272895, '2026-09-07T03:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001665', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2600301', '김진호가옥', '조용히 사색하고 싶어서 찾은 김진호가옥. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 36.733780, 128.620100, '2026-07-22T21:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001666', '54500700-0000-4000-8000-000000000120', 'p-tourapi-1971880', '좋은날', '조용히 사색하고 싶어서 찾은 좋은날. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 35.817283, 127.149292, '2026-08-20T22:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001667', '54500700-0000-4000-8000-000000000182', 'p-tourapi-1201060', '이천보고가', '근처 여행 코스로 이천보고가 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "사진맛집", "가족여행"]'::jsonb, 37.798653, 127.348090, '2026-08-01T00:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001668', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2717291', '바우파머스몰(대관령마켓)', '기대 이상으로 너무 좋았던 바우파머스몰(대관령마켓)! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "주말나들이", "온마루"]'::jsonb, 37.672630, 128.706636, '2026-07-29T22:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001669', '54500700-0000-4000-8000-000000000114', 'p-tourapi-3009051', '도깨비 양조장', 'SNS에서 사진 보고 찾아간 도깨비 양조장, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 37.026390, 128.384743, '2026-07-24T17:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001670', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2513410', '삼척해상케이블카', '예전부터 가보고 싶었던 삼척해상케이블카 드디어 방문! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.289144, 129.308522, '2026-08-23T06:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001671', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2814166', '강현재', '기대 이상으로 너무 좋았던 강현재! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "주말나들이"]'::jsonb, 34.949185, 127.204357, '2026-09-11T10:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001672', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3532717', '스테이 안김A', '근처 여행 코스로 스테이 안김A 넣길 정말 잘했어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "사진맛집"]'::jsonb, 35.835527, 129.212995, '2026-07-20T01:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001673', '54500700-0000-4000-8000-000000000108', 'p-tourapi-2708322', '이화고택', '비 오는 날 운치 찾아 이화고택 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 35.816284, 127.153995, '2026-09-05T11:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001674', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2996818', '반줄', '반줄 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.945451, 127.101776, '2026-07-25T12:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001675', '54500700-0000-4000-8000-000000000140', 'p-tourapi-4065913', '청원루', '날씨가 너무 맑아서 청원루 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로"]'::jsonb, 36.579469, 128.548711, '2026-09-06T05:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001676', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2995169', '농업회사법인 주식회사 공동체공간 수작', '비 오는 날 운치 찾아 농업회사법인 주식회사 공동체공간 수작 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["주말나들이", "사진맛집"]'::jsonb, 35.942063, 127.263195, '2026-08-20T23:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001677', '54500700-0000-4000-8000-000000000185', 'p-tourapi-2575839', '사랑나무 한옥펜션', '오랜만에 여유 찾으러 사랑나무 한옥펜션 다녀왔습니다. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "힐링", "풍경맛집", "온마루"]'::jsonb, 35.811437, 127.152670, '2026-07-18T16:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001678', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2621370', '태양아래월출산', '기대 이상으로 너무 좋았던 태양아래월출산! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["방문팁", "사진맛집", "데이트"]'::jsonb, 34.739842, 126.718469, '2026-09-01T23:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001679', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3426935', '구리문화재단', '구리문화재단 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 37.595604, 127.129868, '2026-08-13T21:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001680', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2821865', '향온', '조용히 사색하고 싶어서 찾은 향온. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "힐링"]'::jsonb, 36.404006, 126.846248, '2026-07-28T15:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001681', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2000946', '치암고택', '오랜만에 여유 찾으러 치암고택 다녀왔습니다. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 36.583250, 128.736044, '2026-08-17T16:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001682', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2610549', '예원당(한옥체험 예원당)', '조용히 사색하고 싶어서 찾은 예원당(한옥체험 예원당). 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 35.817395, 127.152742, '2026-07-20T07:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001683', '54500700-0000-4000-8000-000000000198', 'p-tourapi-3533161', '앙니드 공이안', '비 오는 날 운치 찾아 앙니드 공이안 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 37.581633, 126.981493, '2026-08-03T20:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001684', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3531662', '최선평 가옥', '조용히 사색하고 싶어서 찾은 최선평 가옥. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로"]'::jsonb, 37.878304, 128.795960, '2026-07-18T12:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001685', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2996004', '달창재(달창사랑 협동조합)', '날씨가 너무 맑아서 달창재(달창사랑 협동조합) 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 35.635289, 128.487081, '2026-09-15T14:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001686', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2855009', '한옥 생고기', '천천히 골목 걷다가 마주친 한옥 생고기. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "데이트", "사진맛집", "온마루"]'::jsonb, 37.948869, 127.189507, '2026-09-10T04:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001687', '54500700-0000-4000-8000-000000000151', 'p-tourapi-4072012', '호텔호자', '조용히 사색하고 싶어서 찾은 호텔호자. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "사색"]'::jsonb, 34.794970, 126.377709, '2026-08-05T06:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001688', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3438435', '사임당 귀한그대', '주말에 친구들이랑 사임당 귀한그대 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.641234, 126.940136, '2026-07-21T19:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001689', '54500700-0000-4000-8000-000000000081', 'p-tourapi-1372956', '이상화 고택', '주말에 친구들이랑 이상화 고택 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 35.867231, 128.587976, '2026-09-15T02:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001690', '54500700-0000-4000-8000-000000000127', 'p-tourapi-1055245', '서천 이하복 고택', '드라이브 겸 나들이로 서천 이하복 고택 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "방문팁", "데이트"]'::jsonb, 36.081024, 126.759328, '2026-07-19T16:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001691', '54500700-0000-4000-8000-000000000164', 'p-tourapi-128825', '독도전망대 케이블카', '평일 연차 쓰고 혼자 독도전망대 케이블카 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "산책로"]'::jsonb, 37.483068, 130.900258, '2026-07-20T06:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001692', '54500700-0000-4000-8000-000000000056', 'p-tourapi-1437090', '괴산 송병일 고택', '천천히 골목 걷다가 마주친 괴산 송병일 고택. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행", "고즈넉"]'::jsonb, 36.661567, 127.738214, '2026-09-15T02:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001693', '54500700-0000-4000-8000-000000000199', 'p-tourapi-1938123', '광천토굴새우젓단지', '기대 이상으로 너무 좋았던 광천토굴새우젓단지! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.485253, 126.615611, '2026-08-09T18:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001694', '54500700-0000-4000-8000-000000000096', 'p-tourapi-3438215', '무월관', '천천히 골목 걷다가 마주친 무월관. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 37.577295, 126.983620, '2026-08-03T17:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001695', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1972014', '삼락헌', '삼락헌 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 35.815648, 127.152720, '2026-08-09T23:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001696', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '전주한옥마을 독채덕수궁 다녀왔어요! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.816792, 127.151648, '2026-07-29T02:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001697', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2544573', '광화문한옥집', '예전부터 가보고 싶었던 광화문한옥집 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "사색"]'::jsonb, 37.572716, 126.973999, '2026-09-10T23:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001698', '54500700-0000-4000-8000-000000000141', 'p-tourapi-1812994', '조랑말체험공원', '드라이브 겸 나들이로 조랑말체험공원 선택했는데 대만족! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "인생샷"]'::jsonb, 33.383477, 126.735668, '2026-08-21T18:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001699', '54500700-0000-4000-8000-000000000075', 'p-tourapi-231892', '안동 의성김씨 종택', '부모님 모시고 안동 의성김씨 종택 산책 겸 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "데이트", "가족여행", "온마루"]'::jsonb, 36.535846, 128.856287, '2026-09-05T18:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001700', '54500700-0000-4000-8000-000000000141', 'p-tourapi-2706608', '경주오릉한옥', '평일 연차 쓰고 혼자 경주오릉한옥 다녀옴. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "힐링", "고즈넉"]'::jsonb, 35.825828, 129.207499, '2026-08-23T16:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001701', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2048324', '사랑가득', '주말에 친구들이랑 사랑가득 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.812465, 127.158014, '2026-07-16T15:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001702', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '주말에 친구들이랑 (사)영남선비문화수련원(구암서원) 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["데이트", "가족여행", "사진맛집"]'::jsonb, 35.901625, 128.596853, '2026-06-20T09:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001703', '54500700-0000-4000-8000-000000000176', 'p-tourapi-129210', '무안 유교리 고택', '예전부터 가보고 싶었던 무안 유교리 고택 드디어 방문! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 34.847445, 126.438282, '2026-04-24T21:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001704', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3354226', '농업회사법인주식회사 월출산꽃따리농장', '해 질 무렵에 농업회사법인주식회사 월출산꽃따리농장 방문했는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "데이트", "가족여행", "온마루"]'::jsonb, 34.720709, 126.576620, '2026-07-09T12:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001705', '54500700-0000-4000-8000-000000000145', 'p-tourapi-231938', '서울 경모궁지', '주말에 친구들이랑 서울 경모궁지 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "사진맛집"]'::jsonb, 37.580402, 126.999009, '2026-04-24T11:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001706', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3533114', '스테이여유담', '기대 이상으로 너무 좋았던 스테이여유담! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 35.051415, 126.864112, '2026-06-30T08:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001707', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2528155', '남원예촌', '평일 연차 쓰고 혼자 남원예촌 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 35.404443, 127.379394, '2026-04-18T18:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001708', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3422587', '더맑음', '오랜만에 여유 찾으러 더맑음 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "풍경맛집", "혼자여행"]'::jsonb, 35.540524, 129.338596, '2026-05-06T19:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001709', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2820370', '버들국수 (농업법인 주식회사 유화 ㈜)', '근처 여행 코스로 버들국수 (농업법인 주식회사 유화 ㈜) 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "사진맛집", "인생샷"]'::jsonb, 35.576300, 128.439048, '2026-06-22T04:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001710', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3432261', '인천업사이클에코센터', '평일 연차 쓰고 혼자 인천업사이클에코센터 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.443213, 126.655334, '2026-06-28T02:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001711', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2599272', '모지고택', '조용히 사색하고 싶어서 찾은 모지고택. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "힐링", "풍경맛집"]'::jsonb, 36.540737, 128.518264, '2026-05-11T06:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001712', '54500700-0000-4000-8000-000000000094', 'p-tourapi-1089992', '대전교통문화연수원', '주말에 친구들이랑 대전교통문화연수원 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 36.377207, 127.386364, '2026-06-15T04:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001713', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1882538', '인심좋은웅기댁', '날씨가 너무 맑아서 인심좋은웅기댁 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "가족여행", "데이트"]'::jsonb, 35.667497, 128.229317, '2026-05-09T12:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001714', '54500700-0000-4000-8000-000000000141', 'p-tourapi-126391', '고창신재효고택', '주말에 친구들이랑 고창신재효고택 들렀는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행", "온마루"]'::jsonb, 35.432158, 126.703050, '2026-04-29T03:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001715', '54500700-0000-4000-8000-000000000076', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '조용히 사색하고 싶어서 찾은 아동청소년친화공간 꿈이랑. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 38.199574, 128.580209, '2026-06-05T03:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001716', '54500700-0000-4000-8000-000000000066', 'p-tourapi-128994', '구례 운조루 고택', '구례 운조루 고택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.206079, 127.515423, '2026-05-18T21:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001717', '54500700-0000-4000-8000-000000000080', 'p-tourapi-129539', '동천석실', '동천석실 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "인생샷", "주말나들이"]'::jsonb, 34.153444, 126.541579, '2026-05-26T15:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001718', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2594865', '성암재', '드라이브 겸 나들이로 성암재 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["사진맛집", "방문팁"]'::jsonb, 36.940240, 128.913637, '2026-06-23T23:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001719', '54500700-0000-4000-8000-000000000136', 'p-tourapi-1908555', '지리산한옥마을', 'SNS에서 사진 보고 찾아간 지리산한옥마을, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "사진맛집", "주말나들이", "온마루"]'::jsonb, 35.418226, 127.625727, '2026-06-04T07:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001720', '54500700-0000-4000-8000-000000000102', 'p-tourapi-3532968', '황남별채', '해 질 무렵에 황남별채 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "방문팁"]'::jsonb, 35.835152, 129.208990, '2026-06-23T09:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001721', '54500700-0000-4000-8000-000000000196', 'p-tourapi-231931', '논산명재고택', '주말에 친구들이랑 논산명재고택 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.281980, 127.131490, '2026-05-28T04:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001722', '54500700-0000-4000-8000-000000000111', 'p-tourapi-2671267', '가락청', '가락청 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 35.817322, 127.153567, '2026-05-13T18:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001723', '54500700-0000-4000-8000-000000000128', 'p-tourapi-2507433', '삼해소주', '평일 연차 쓰고 혼자 삼해소주 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "풍경맛집", "힐링"]'::jsonb, 37.562965, 126.913596, '2026-06-02T02:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001724', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3510987', '주식회사감천아울', '드라이브 겸 나들이로 주식회사감천아울 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.093432, 129.008795, '2026-05-15T19:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001725', '54500700-0000-4000-8000-000000000059', 'p-tourapi-4074856', '연림스테이', '연림스테이 다녀왔어요! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로", "온마루"]'::jsonb, 35.972113, 128.698835, '2026-05-21T22:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001726', '54500700-0000-4000-8000-000000000067', 'p-tourapi-1972381', '서로', '비 오는 날 운치 찾아 서로 다녀왔어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.815775, 127.153606, '2026-05-06T04:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001727', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2714217', '만천하 슬라이드', 'SNS에서 사진 보고 찾아간 만천하 슬라이드, 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "가족여행", "온마루"]'::jsonb, 36.977525, 128.337104, '2026-06-20T08:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001728', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3030491', '선성현문화단지 한옥체험관', '선성현문화단지 한옥체험관 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "혼자여행", "온마루"]'::jsonb, 36.698302, 128.814675, '2026-07-03T23:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001729', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2647939', '고스락', '주말에 친구들이랑 고스락 들렀는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "사진맛집", "주말나들이", "온마루"]'::jsonb, 36.045904, 126.960681, '2026-07-12T20:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001730', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1395270', '최순우 옛집', '주말에 친구들이랑 최순우 옛집 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 37.593065, 127.000360, '2026-07-03T11:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001731', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3025473', '영광 매간당 고택', '천천히 골목 걷다가 마주친 영광 매간당 고택. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 35.240848, 126.474309, '2026-05-20T03:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001732', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3411229', '천지인 전통사상체험관', '천천히 골목 걷다가 마주친 천지인 전통사상체험관. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.730825, 128.614743, '2026-06-08T08:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001733', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2717604', '어슬티굿밤', '비 오는 날 운치 찾아 어슬티굿밤 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.487826, 126.822648, '2026-06-01T21:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001734', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2435103', '중앙탑의상실', '천천히 골목 걷다가 마주친 중앙탑의상실. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 37.018227, 127.866085, '2026-06-03T08:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001735', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3438599', '이사빛1968 한옥스테이', '이사빛1968 한옥스테이 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 36.564774, 128.737264, '2026-06-26T11:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001736', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3072197', '오롯이, 한옥', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.580005, 126.968005, '2026-05-14T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001737', '54500700-0000-4000-8000-000000000193', 'p-tourapi-127520', '서귀포 김정희 유배지', '드라이브 겸 나들이로 서귀포 김정희 유배지 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "데이트", "방문팁", "온마루"]'::jsonb, 33.249935, 126.278322, '2026-04-20T10:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001738', '54500700-0000-4000-8000-000000000198', 'p-tourapi-1610542', '달성 조길방 고택', '주말에 친구들이랑 달성 조길방 고택 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.755808, 128.581749, '2026-04-18T18:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001739', '54500700-0000-4000-8000-000000000111', 'p-tourapi-753850', '키즈오토파크', '조용히 사색하고 싶어서 찾은 키즈오토파크. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "사색", "온마루"]'::jsonb, 37.549361, 127.076293, '2026-06-08T12:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001740', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2725128', '오대산힐링빌리지', '근처 여행 코스로 오대산힐링빌리지 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.610086, 128.517541, '2026-04-30T04:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001741', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2621722', '꽃잠', '비 오는 날 운치 찾아 꽃잠 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "데이트", "방문팁"]'::jsonb, 35.818783, 127.152861, '2026-06-30T14:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001742', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2996127', '기범이네국수', '부모님 모시고 기범이네국수 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 36.104796, 127.488265, '2026-04-27T15:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001743', '54500700-0000-4000-8000-000000000088', 'p-tourapi-231940', '안동 소호헌', '날씨가 너무 맑아서 안동 소호헌 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "풍경맛집", "온마루"]'::jsonb, 36.463695, 128.663462, '2026-05-21T22:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001744', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2570282', '서문한옥게스트하우스', '부모님 모시고 서문한옥게스트하우스 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.866762, 128.579575, '2026-07-11T00:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001745', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2713848', '수상한마법학교', '수상한마법학교 다녀왔어요! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 37.730501, 128.879166, '2026-05-27T19:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001746', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3080477', '수원전통문화관', '근처 여행 코스로 수원전통문화관 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.287470, 127.014633, '2026-04-20T15:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001747', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2788137', '화사별서(조씨고가)', '조용히 사색하고 싶어서 찾은 화사별서(조씨고가). 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.171341, 127.700944, '2026-07-14T05:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001748', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3337761', '마마스홈퀴진', '평일 연차 쓰고 혼자 마마스홈퀴진 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.561501, 129.116689, '2026-06-22T10:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001749', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2605927', '초원사진관', '주말에 친구들이랑 초원사진관 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "방문팁", "온마루"]'::jsonb, 35.987737, 126.708383, '2026-05-28T10:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001750', '54500700-0000-4000-8000-000000000202', 'p-tourapi-1971917', '청공한옥', '조용히 사색하고 싶어서 찾은 청공한옥. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "풍경맛집", "고즈넉"]'::jsonb, 35.781946, 129.303306, '2026-05-23T01:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001751', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2603550', '무척산관광예술원', '날씨가 너무 맑아서 무척산관광예술원 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "사색", "혼자여행", "온마루"]'::jsonb, 35.383738, 128.839466, '2026-06-23T09:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001752', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2696383', '한옥 201(Hanok 201)', '근처 여행 코스로 한옥 201(Hanok 201) 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 37.580558, 126.985414, '2026-04-23T09:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001753', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2701896', '평창지동봉가옥', '드라이브 겸 나들이로 평창지동봉가옥 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 37.333462, 128.379317, '2026-05-01T16:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001754', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3072219', '북촌빈관 by 락고재', '기대 이상으로 너무 좋았던 북촌빈관 by 락고재! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 37.582347, 126.984220, '2026-05-30T05:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001755', '54500700-0000-4000-8000-000000000107', 'p-tourapi-1626699', '아산 외암마을 참판댁', '드라이브 겸 나들이로 아산 외암마을 참판댁 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "인생샷", "가족여행"]'::jsonb, 36.730305, 127.018491, '2026-05-31T20:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001756', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2717493', '삼버들협동조합', '해 질 무렵에 삼버들협동조합 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 36.527709, 127.370087, '2026-05-31T16:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001757', '54500700-0000-4000-8000-000000000183', 'p-tourapi-1871362', '문화공간 양사재', '문화공간 양사재 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "데이트", "가족여행"]'::jsonb, 35.813145, 127.154136, '2026-05-20T01:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001758', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2607481', '향운', '드라이브 겸 나들이로 향운 선택했는데 대만족! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "산책로", "혼자여행"]'::jsonb, 37.583027, 126.985925, '2026-06-13T01:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001759', '54500700-0000-4000-8000-000000000184', 'p-tourapi-843726', '한옥집김치찜', '평일 연차 쓰고 혼자 한옥집김치찜 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.869289, 128.594129, '2026-07-14T20:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001760', '54500700-0000-4000-8000-000000000058', 'p-tourapi-3532750', '해우당', '드라이브 겸 나들이로 해우당 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "데이트", "방문팁", "온마루"]'::jsonb, 37.355575, 127.064858, '2026-05-30T19:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001761', '54500700-0000-4000-8000-000000000157', 'p-tourapi-2783068', '하이원리조트 알파인코스터', '천천히 골목 걷다가 마주친 하이원리조트 알파인코스터. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 37.210430, 128.827173, '2026-05-03T10:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001762', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2575760', '연우당', '조용히 사색하고 싶어서 찾은 연우당. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "산책로", "힐링", "온마루"]'::jsonb, 35.815586, 127.153136, '2026-06-27T00:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001763', '54500700-0000-4000-8000-000000000085', 'p-tourapi-1114959', '음성잿말고택 (김주태가옥)', '오랜만에 여유 찾으러 음성잿말고택 (김주태가옥) 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 37.080814, 127.657818, '2026-04-23T23:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001764', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2717494', '쌍류포도정원협동조합', '쌍류포도정원협동조합 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 36.603381, 127.216182, '2026-06-26T09:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001765', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2660381', '매월당', '평일 연차 쓰고 혼자 매월당 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "힐링", "산책로", "온마루"]'::jsonb, 35.348864, 127.272895, '2026-04-24T05:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001766', '54500700-0000-4000-8000-000000000101', 'p-tourapi-3033516', '논산한옥마을', '기대 이상으로 너무 좋았던 논산한옥마을! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.211445, 127.181241, '2026-05-15T07:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001767', '54500700-0000-4000-8000-000000000097', 'p-tourapi-4071289', '함평 이재혁 가옥', '함평 이재혁 가옥 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 35.066416, 126.512216, '2026-05-18T23:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001768', '54500700-0000-4000-8000-000000000203', 'p-tourapi-126747', '남산골한옥마을', '기대 이상으로 너무 좋았던 남산골한옥마을! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 37.559778, 126.993287, '2026-06-12T12:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001769', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2615342', '비비정예술열차', 'SNS에서 사진 보고 찾아간 비비정예술열차, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 35.898992, 127.067778, '2026-05-11T17:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001770', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2820838', '평창캠프닉', '근처 여행 코스로 평창캠프닉 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 37.578828, 128.331753, '2026-06-23T10:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001771', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3452165', '경산청년지식놀이터', '오랜만에 여유 찾으러 경산청년지식놀이터 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.841329, 128.760013, '2026-04-27T16:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001772', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2681174', '고선재', '주말에 친구들이랑 고선재 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "힐링", "혼자여행", "온마루"]'::jsonb, 36.566131, 127.517847, '2026-07-13T18:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001773', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3438592', '한옥스테이 다가감', '침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "주말나들이", "온마루"]'::jsonb, 35.835069, 129.212923, '2026-06-27T17:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001774', '54500700-0000-4000-8000-000000000169', 'p-tourapi-126387', '전주 풍패지관 (전주객사)', '날씨가 너무 맑아서 전주 풍패지관 (전주객사) 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "인생샷", "가족여행", "온마루"]'::jsonb, 35.818500, 127.145400, '2026-06-18T00:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001775', '54500700-0000-4000-8000-000000000078', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', 'SNS에서 사진 보고 찾아간 춘천 강언덕마을 [농촌전통테마], 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.678664, 127.613691, '2026-07-11T21:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001776', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2531374', '교동살래', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "혼자여행", "온마루"]'::jsonb, 35.811295, 127.153370, '2026-07-15T22:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001777', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2595672', '하회 양진당', '조용히 사색하고 싶어서 찾은 하회 양진당. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 36.539006, 128.516673, '2026-06-23T16:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001778', '54500700-0000-4000-8000-000000000182', 'p-tourapi-1390215', '장흥 죽헌고택', '기대 이상으로 너무 좋았던 장흥 죽헌고택! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "인생샷", "가족여행"]'::jsonb, 34.548792, 126.949837, '2026-06-14T09:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001779', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3532712', '스테이화요일', '날씨가 너무 맑아서 스테이화요일 한 바퀴 돌고 왔네요. 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 36.847611, 126.904632, '2026-07-03T18:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001780', '54500700-0000-4000-8000-000000000120', 'p-tourapi-2623573', '한미장', 'SNS에서 사진 보고 찾아간 한미장, 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 37.671220, 127.007590, '2026-05-30T08:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001781', '54500700-0000-4000-8000-000000000142', 'p-tourapi-2932921', '한울', 'SNS에서 사진 보고 찾아간 한울, 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "사진맛집", "주말나들이"]'::jsonb, 37.237134, 127.265493, '2026-06-13T01:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001782', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2698680', '4.16희망목공소(4.16희망목공협동조합)', '부모님 모시고 4.16희망목공소(4.16희망목공협동조합) 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.343691, 126.834985, '2026-04-24T20:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001783', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3532478', '임당생활문화센터', '임당생활문화센터 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 37.754768, 128.895014, '2026-06-10T16:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001784', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2717486', '엘오알오', '은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "가족여행", "온마루"]'::jsonb, 36.733429, 128.108470, '2026-05-06T11:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001785', '54500700-0000-4000-8000-000000000100', 'p-tourapi-128560', '안동 임청각', '평일 연차 쓰고 혼자 안동 임청각 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "풍경맛집", "사색", "온마루"]'::jsonb, 36.565132, 128.745004, '2026-06-13T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001786', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2605809', '태화강동굴피아', '조용히 사색하고 싶어서 찾은 태화강동굴피아. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "풍경맛집", "온마루"]'::jsonb, 35.545284, 129.302468, '2026-06-24T12:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001787', '54500700-0000-4000-8000-000000000056', 'p-tourapi-3533157', '미미몽몽', '미미몽몽 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 35.819017, 127.158386, '2026-04-24T11:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001788', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3438578', '나루 한옥스테이 독채', '평일 연차 쓰고 혼자 나루 한옥스테이 독채 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행", "풍경맛집"]'::jsonb, 35.811404, 127.154417, '2026-04-25T23:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001789', '54500700-0000-4000-8000-000000000065', 'p-tourapi-128694', '안동한지', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 36.580776, 128.555101, '2026-06-24T09:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001790', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3426935', '구리문화재단', '구리문화재단 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "산책로", "혼자여행", "온마루"]'::jsonb, 37.595604, 127.129868, '2026-04-27T07:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001791', '54500700-0000-4000-8000-000000000202', 'p-tourapi-3101970', '불국사한옥동오당', '오랜만에 여유 찾으러 불국사한옥동오당 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.782830, 129.328318, '2026-05-12T16:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001792', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3572354', '포항전통문화체험관', '드라이브 겸 나들이로 포항전통문화체험관 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 36.165077, 129.185188, '2026-07-14T02:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001793', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2583187', '전통문화체험장', '해 질 무렵에 전통문화체험장 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 35.989227, 127.260964, '2026-07-17T09:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001794', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2572898', '고현당', '천천히 골목 걷다가 마주친 고현당. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 35.815292, 127.153725, '2026-05-02T23:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001795', '54500700-0000-4000-8000-000000000135', 'p-tourapi-1623828', '안동권씨유회당종가일원', '평일 연차 쓰고 혼자 안동권씨유회당종가일원 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "사색"]'::jsonb, 36.277697, 127.404793, '2026-07-13T13:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001796', '54500700-0000-4000-8000-000000000118', 'p-tourapi-1621155', '제주 성읍마을 고평오 고택', 'SNS에서 사진 보고 찾아간 제주 성읍마을 고평오 고택, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 33.385992, 126.801815, '2026-06-12T19:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001797', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2610985', '전주 한옥숙박 체험관', '천천히 골목 걷다가 마주친 전주 한옥숙박 체험관. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "산책로", "혼자여행", "온마루"]'::jsonb, 35.815023, 127.152192, '2026-06-21T12:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001798', '54500700-0000-4000-8000-000000000150', 'p-tourapi-1923400', '백두대간협곡열차(V-트레인)', '천천히 골목 걷다가 마주친 백두대간협곡열차(V-트레인). 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 37.113109, 129.036710, '2026-04-22T07:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001799', '54500700-0000-4000-8000-000000000132', 'p-tourapi-1623646', '권희문가옥', '비 오는 날 운치 찾아 권희문가옥 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 35.587661, 127.386260, '2026-06-03T04:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001800', '54500700-0000-4000-8000-000000000167', 'p-tourapi-1883104', '연풍고택(문충고가)', '비 오는 날 운치 찾아 연풍고택(문충고가) 다녀왔어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "풍경맛집"]'::jsonb, 35.668014, 128.228639, '2026-07-08T04:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001801', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2621722', '꽃잠', '비 오는 날 운치 찾아 꽃잠 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이", "데이트", "온마루"]'::jsonb, 35.818783, 127.152861, '2026-05-05T05:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001802', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2657501', '한옥카페 갤러리 도솔', '해 질 무렵에 한옥카페 갤러리 도솔 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 37.641997, 126.506472, '2026-06-04T21:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001803', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438182', '여느날', '달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "산책로", "온마루"]'::jsonb, 37.576570, 126.969605, '2026-07-15T19:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001804', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2638529', '포항 장기유배문화체험촌', '주말에 친구들이랑 포항 장기유배문화체험촌 들렀는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 35.903713, 129.486122, '2026-05-12T02:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001805', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3454381', '디즈니스토어 현대프리미엄아울렛 대전점', '기대 이상으로 너무 좋았던 디즈니스토어 현대프리미엄아울렛 대전점! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.423483, 127.398534, '2026-07-12T04:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001806', '54500700-0000-4000-8000-000000000201', 'p-tourapi-3438041', '유선재', '오랜만에 여유 찾으러 유선재 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.490512, 127.709293, '2026-06-28T14:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001807', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2821565', '룰루낭만협동조합', '부모님 모시고 룰루낭만협동조합 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트", "방문팁"]'::jsonb, 35.235588, 128.881352, '2026-05-02T01:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001808', '54500700-0000-4000-8000-000000000140', 'p-tourapi-1882210', '얼음골한옥펜션', '드라이브 겸 나들이로 얼음골한옥펜션 선택했는데 대만족! 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["사진맛집", "주말나들이", "인생샷"]'::jsonb, 35.598251, 128.953272, '2026-06-13T15:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001809', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2007983', '경북전통음식체험관 모심정', '오랜만에 여유 찾으러 경북전통음식체험관 모심정 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 36.661949, 128.119119, '2026-05-08T20:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001810', '54500700-0000-4000-8000-000000000068', 'p-tourapi-129688', '보은 우당고택', '날씨가 너무 맑아서 보은 우당고택 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["방문팁", "인생샷", "온마루"]'::jsonb, 36.468892, 127.790163, '2026-06-16T07:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001811', '54500700-0000-4000-8000-000000000173', 'p-tourapi-1883996', '취옹예술관', '예전부터 가보고 싶었던 취옹예술관 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.752549, 127.359939, '2026-05-20T15:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001812', '54500700-0000-4000-8000-000000000162', 'p-tourapi-2623572', '그 여자네 집', '조용히 사색하고 싶어서 찾은 그 여자네 집. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 35.812173, 127.155125, '2026-04-25T03:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001813', '54500700-0000-4000-8000-000000000092', 'p-tourapi-1055245', '서천 이하복 고택', '해 질 무렵에 서천 이하복 고택 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["방문팁", "데이트"]'::jsonb, 36.081024, 126.759328, '2026-06-11T11:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001814', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2574326', '개울한옥민박', '주말에 친구들이랑 개울한옥민박 들렀는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷", "주말나들이"]'::jsonb, 34.515972, 126.661646, '2026-04-30T05:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001815', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2717492', '비녀랑 한복이랑', '예전부터 가보고 싶었던 비녀랑 한복이랑 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.629768, 127.287278, '2026-06-27T18:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001816', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2705296', '물뫼힐링팜', '근처 여행 코스로 물뫼힐링팜 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 33.464266, 126.396568, '2026-06-18T13:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001817', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2698914', '한옥펜션 나비의 꿈', '해 질 무렵에 한옥펜션 나비의 꿈 방문했는데 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.608120, 126.585103, '2026-06-01T13:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001818', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3532478', '임당생활문화센터', '근처 여행 코스로 임당생활문화센터 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.754768, 128.895014, '2026-05-31T08:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001819', '54500700-0000-4000-8000-000000000076', 'p-tourapi-3572354', '포항전통문화체험관', '예전부터 가보고 싶었던 포항전통문화체험관 드디어 방문! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "방문팁", "사진맛집", "온마루"]'::jsonb, 36.165077, 129.185188, '2026-07-01T12:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001820', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '천천히 골목 걷다가 마주친 해풍부원군윤택영댁재실. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 37.558364, 126.994403, '2026-06-26T16:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001821', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3438358', '정연재', '주말에 친구들이랑 정연재 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["가족여행", "주말나들이", "데이트"]'::jsonb, 37.583480, 126.980701, '2026-07-03T22:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001822', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2753977', '울진과학체험관', '드라이브 겸 나들이로 울진과학체험관 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 36.996618, 129.408077, '2026-04-26T20:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001823', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3438233', '월운', '근처 여행 코스로 월운 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로"]'::jsonb, 37.574104, 126.991700, '2026-07-09T08:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001824', '54500700-0000-4000-8000-000000000137', 'p-tourapi-1622772', '합천 사의정', '주말에 친구들이랑 합천 사의정 들렀는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 35.544184, 128.000424, '2026-05-13T14:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001825', '54500700-0000-4000-8000-000000000093', 'p-tourapi-129057', '청송 평산신씨 판사공파 종택과 분가 고택', '비 오는 날 운치 찾아 청송 평산신씨 판사공파 종택과 분가 고택 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["힐링", "고즈넉", "온마루"]'::jsonb, 36.458491, 129.022801, '2026-07-06T12:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001826', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2531409', '더 한옥', '주말에 친구들이랑 더 한옥 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 35.813687, 127.152403, '2026-07-10T22:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001827', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2531497', '추우재', '비 오는 날 운치 찾아 추우재 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 35.668719, 128.227467, '2026-07-02T22:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001828', '54500700-0000-4000-8000-000000000100', 'p-tourapi-129688', '보은 우당고택', '예전부터 가보고 싶었던 보은 우당고택 드디어 방문! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.468892, 127.790163, '2026-07-15T02:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001829', '54500700-0000-4000-8000-000000000130', 'p-tourapi-1623828', '안동권씨유회당종가일원', '근처 여행 코스로 안동권씨유회당종가일원 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행", "데이트"]'::jsonb, 36.277697, 127.404793, '2026-06-23T07:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001830', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2049307', '녹운재', '날씨가 너무 맑아서 녹운재 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.902864, 127.242582, '2026-05-14T21:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001831', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3510444', '농업회사법인주식회사꿀벌인', '농업회사법인주식회사꿀벌인 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.014031, 128.421877, '2026-05-29T21:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001832', '54500700-0000-4000-8000-000000000145', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '드라이브 겸 나들이로 거창 갈계리 임씨고가 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "방문팁"]'::jsonb, 35.780200, 127.818700, '2026-06-21T08:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001833', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2792794', '밀양교동 손씨고가', '비 오는 날 운치 찾아 밀양교동 손씨고가 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "힐링", "온마루"]'::jsonb, 35.504944, 128.755187, '2026-06-01T19:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001834', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2891349', '미술관아래협동조합', '평일 연차 쓰고 혼자 미술관아래협동조합 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 34.775012, 126.646788, '2026-04-25T02:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001835', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1883086', '연경당', '근처 여행 코스로 연경당 넣길 정말 잘했어요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 35.015690, 127.585952, '2026-06-07T03:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001836', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2574307', '목양산방', '비 오는 날 운치 찾아 목양산방 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.889717, 127.507484, '2026-04-28T14:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001837', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2820184', '감성공작소', '기대 이상으로 너무 좋았던 감성공작소! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집", "고즈넉"]'::jsonb, 37.442379, 129.163108, '2026-05-08T03:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001838', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2718998', '전북특별자치도 119안전체험관', '날씨가 너무 맑아서 전북특별자치도 119안전체험관 한 바퀴 돌고 왔네요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.602099, 127.283772, '2026-06-18T15:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001839', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2717492', '비녀랑 한복이랑', '평일 연차 쓰고 혼자 비녀랑 한복이랑 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "사색"]'::jsonb, 36.629768, 127.287278, '2026-05-12T16:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001840', '54500700-0000-4000-8000-000000000084', 'p-tourapi-3469419', '미지한옥', 'SNS에서 사진 보고 찾아간 미지한옥, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "사진맛집", "온마루"]'::jsonb, 36.567913, 128.734769, '2026-05-04T10:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001841', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3438412', '중림재', '주말에 친구들이랑 중림재 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.558236, 126.967703, '2026-05-29T08:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001842', '54500700-0000-4000-8000-000000000184', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '천천히 골목 걷다가 마주친 사단법인 푸른차문화연구원. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["방문팁", "데이트", "주말나들이", "온마루"]'::jsonb, 35.835036, 128.677134, '2026-05-26T14:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001843', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2717605', '청양의 봄, 청춘', '기대 이상으로 너무 좋았던 청양의 봄, 청춘! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 36.450299, 126.800487, '2026-05-23T09:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001844', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3066467', '우리 놀이터 마루달', '날씨가 너무 맑아서 우리 놀이터 마루달 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 35.816545, 127.152350, '2026-07-03T04:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001845', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2574415', '별자리', '부모님 모시고 별자리 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁", "가족여행"]'::jsonb, 35.816547, 127.151270, '2026-05-11T10:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001846', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2595847', '달의 정원', '날씨가 너무 맑아서 달의 정원 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "방문팁", "사진맛집"]'::jsonb, 35.790073, 128.087332, '2026-06-25T16:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001847', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2594513', '단촌서원고택', '단촌서원고택 다녀왔어요! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 36.929514, 128.335222, '2026-05-28T07:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001848', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3438736', '전주한옥마을 독채덕수궁', '전주한옥마을 독채덕수궁 다녀왔어요! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["인생샷", "주말나들이", "방문팁"]'::jsonb, 35.816792, 127.151648, '2026-07-17T02:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001849', '54500700-0000-4000-8000-000000000097', 'p-tourapi-127289', '괴산 홍범식 고가(벽초 홍명희 생가)', '기대 이상으로 너무 좋았던 괴산 홍범식 고가(벽초 홍명희 생가)! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 36.813843, 127.794842, '2026-04-19T00:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001850', '54500700-0000-4000-8000-000000000173', 'p-tourapi-3510944', '주식회사영리캐롤', '비 오는 날 운치 찾아 주식회사영리캐롤 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.008325, 128.359602, '2026-04-22T07:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001851', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3438126', '스테이 어플로트', '기대 이상으로 너무 좋았던 스테이 어플로트! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "주말나들이"]'::jsonb, 37.578722, 126.972782, '2026-05-27T08:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001852', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2747760', '그라운드플래닛', '비 오는 날 운치 찾아 그라운드플래닛 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.433912, 127.011166, '2026-04-23T21:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001853', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1579747', '거창 동호리 이씨고가', '비 오는 날 운치 찾아 거창 동호리 이씨고가 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 35.798952, 127.927362, '2026-05-01T14:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001854', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2717494', '쌍류포도정원협동조합', '산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 36.603381, 127.216182, '2026-05-23T17:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001855', '54500700-0000-4000-8000-000000000150', 'p-tourapi-2714563', '서편제 촬영지', '예전부터 가보고 싶었던 서편제 촬영지 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "사진맛집", "방문팁"]'::jsonb, 34.172272, 126.862103, '2026-05-22T00:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001856', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2707233', '한옥人(한옥인)', '부모님 모시고 한옥人(한옥인) 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 35.834869, 129.211446, '2026-05-15T08:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001857', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2706568', '왕의지밀', '근처 여행 코스로 왕의지밀 넣길 정말 잘했어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트", "인생샷"]'::jsonb, 35.799797, 127.178462, '2026-06-01T19:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001858', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2662467', '만천하 알파인코스터', '드라이브 겸 나들이로 만천하 알파인코스터 선택했는데 대만족! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 36.977675, 128.337071, '2026-06-12T16:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001859', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2608508', '취락당', '천천히 골목 걷다가 마주친 취락당. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.818658, 127.152736, '2026-06-28T18:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001860', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2820395', '놀러와외갓집(우리동네협동조합)', '오랜만에 여유 찾으러 놀러와외갓집(우리동네협동조합) 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "산책로"]'::jsonb, 35.388033, 128.478478, '2026-05-01T23:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001861', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2600248', '수춘제(김태길) 고택', '해 질 무렵에 수춘제(김태길) 고택 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "힐링"]'::jsonb, 36.734841, 128.618767, '2026-05-14T04:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001862', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3019714', '같이삽시도', '비 오는 날 운치 찾아 같이삽시도 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["인생샷", "데이트", "사진맛집"]'::jsonb, 36.346087, 126.353294, '2026-06-09T19:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001863', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3438494', '상상헌', '오랜만에 여유 찾으러 상상헌 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 37.641609, 126.938603, '2026-07-13T08:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001864', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2707439', '스테이 데이 오프', '천천히 골목 걷다가 마주친 스테이 데이 오프. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 37.577273, 126.971179, '2026-05-10T05:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001865', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3038851', '치헌', '비 오는 날 운치 찾아 치헌 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.534748, 128.860953, '2026-06-07T16:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001866', '54500700-0000-4000-8000-000000000194', 'p-tourapi-4013381', '장흥한옥수영장', '비 오는 날 운치 찾아 장흥한옥수영장 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "가족여행"]'::jsonb, 37.739728, 126.958265, '2026-06-17T13:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001867', '54500700-0000-4000-8000-000000000170', 'p-tourapi-795829', '청송 후송당 고택', 'SNS에서 사진 보고 찾아간 청송 후송당 고택, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "데이트", "주말나들이", "온마루"]'::jsonb, 36.289739, 129.009676, '2026-05-02T02:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001868', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3438571', '거북이 한옥', 'SNS에서 사진 보고 찾아간 거북이 한옥, 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 36.329834, 126.543089, '2026-04-23T04:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001869', '54500700-0000-4000-8000-000000000170', 'p-tourapi-4079534', '한옥스테이 궁붙', '주말에 친구들이랑 한옥스테이 궁붙 들렀는데 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 36.000952, 129.014620, '2026-06-27T00:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001870', '54500700-0000-4000-8000-000000000064', 'p-tourapi-4072014', '스테이 화녹', '스테이 화녹 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 35.801123, 129.196940, '2026-06-10T04:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001871', '54500700-0000-4000-8000-000000000089', 'p-tourapi-1583188', '조해영가옥', '주말에 친구들이랑 조해영가옥 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "풍경맛집"]'::jsonb, 36.061040, 126.910882, '2026-05-31T08:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001872', '54500700-0000-4000-8000-000000000065', 'p-tourapi-843726', '한옥집김치찜', '근처 여행 코스로 한옥집김치찜 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "방문팁", "데이트"]'::jsonb, 35.869289, 128.594129, '2026-06-30T03:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001873', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3511602', '주식회사조아지구', '예전부터 가보고 싶었던 주식회사조아지구 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 35.944178, 127.164482, '2026-07-14T05:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001874', '54500700-0000-4000-8000-000000000134', 'p-tourapi-1951619', '비암사 도깨비도로', '조용히 사색하고 싶어서 찾은 비암사 도깨비도로. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "힐링"]'::jsonb, 36.610910, 127.191878, '2026-06-06T08:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001875', '54500700-0000-4000-8000-000000000115', 'p-tourapi-3532956', '경주황리단길숙소 한옥스테이 목화', '비 오는 날 운치 찾아 경주황리단길숙소 한옥스테이 목화 다녀왔어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.836671, 129.211196, '2026-06-20T10:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001876', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3102210', '선음재', '비 오는 날 운치 찾아 선음재 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "데이트", "온마루"]'::jsonb, 37.585097, 126.985631, '2026-04-27T09:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001877', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3532694', '어보이', '예전부터 가보고 싶었던 어보이 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 35.811670, 127.153239, '2026-04-22T03:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001878', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2820629', '부여북포한옥마을', '예전부터 가보고 싶었던 부여북포한옥마을 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 36.292906, 126.924516, '2026-05-14T03:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001879', '54500700-0000-4000-8000-000000000150', 'p-tourapi-1990092', '고성 최필간고택', '평일 연차 쓰고 혼자 고성 최필간고택 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 34.950583, 128.193670, '2026-05-02T11:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001880', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2699326', '월출산 청풍명월', '오랜만에 여유 찾으러 월출산 청풍명월 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "사색"]'::jsonb, 34.769877, 126.654557, '2026-06-08T23:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001881', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '오랜만에 여유 찾으러 김포아트빌리지 전통한옥숙박체험관 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 37.646687, 126.696228, '2026-06-09T18:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001882', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2700309', '경주읍성한옥', '비 오는 날 운치 찾아 경주읍성한옥 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.849567, 129.211526, '2026-07-08T15:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001883', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2587036', '백년한옥', '예전부터 가보고 싶었던 백년한옥 드디어 방문! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 35.815953, 127.155314, '2026-06-24T22:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001884', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2610985', '전주 한옥숙박 체험관', '날씨가 너무 맑아서 전주 한옥숙박 체험관 한 바퀴 돌고 왔네요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.815023, 127.152192, '2026-07-01T23:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001885', '54500700-0000-4000-8000-000000000134', 'p-tourapi-3102031', '소산당', '기대 이상으로 너무 좋았던 소산당! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "혼자여행"]'::jsonb, 35.206651, 127.511859, '2026-05-13T12:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001886', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2820893', '평창사랑', '부모님 모시고 평창사랑 산책 겸 다녀왔습니다. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "방문팁"]'::jsonb, 37.490534, 128.410696, '2026-05-30T08:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001887', '54500700-0000-4000-8000-000000000157', 'p-tourapi-1872349', '순천만 해룡성고택', '평일 연차 쓰고 혼자 순천만 해룡성고택 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "산책로", "사색"]'::jsonb, 34.919947, 127.502479, '2026-04-28T00:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001888', '54500700-0000-4000-8000-000000000143', 'p-tourapi-2657848', '한국트로트가요센터', '주말에 친구들이랑 한국트로트가요센터 들렀는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 34.791589, 126.685354, '2026-05-09T18:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001889', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3102087', '한옥더원', '비 오는 날 운치 찾아 한옥더원 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "사색", "온마루"]'::jsonb, 37.471089, 127.505831, '2026-07-06T20:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001890', '54500700-0000-4000-8000-000000000160', 'p-tourapi-128547', '이해룡고가', '오랜만에 여유 찾으러 이해룡고가 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "사색", "산책로"]'::jsonb, 36.911705, 127.287028, '2026-04-22T18:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001891', '54500700-0000-4000-8000-000000000173', 'p-tourapi-3438435', '사임당 귀한그대', 'SNS에서 사진 보고 찾아간 사임당 귀한그대, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 37.641234, 126.940136, '2026-06-30T21:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001892', '54500700-0000-4000-8000-000000000084', 'p-tourapi-2598985', '초전고택', '주말에 친구들이랑 초전고택 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["방문팁", "주말나들이", "사진맛집"]'::jsonb, 36.440949, 129.024403, '2026-06-08T21:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001893', '54500700-0000-4000-8000-000000000104', 'p-tourapi-3438496', '소우주', '천천히 골목 걷다가 마주친 소우주. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["가족여행", "방문팁", "사진맛집"]'::jsonb, 37.640970, 126.938620, '2026-06-21T00:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001894', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1882248', '인우하우스', '조용히 사색하고 싶어서 찾은 인우하우스. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 37.582709, 126.986956, '2026-06-20T21:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001895', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3532773', '덕용재4.9', '부모님 모시고 덕용재4.9 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 36.691817, 128.409670, '2026-06-03T20:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001896', '54500700-0000-4000-8000-000000000061', 'p-tourapi-126795', '고성 어명기 고택', '예전부터 가보고 싶었던 고성 어명기 고택 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 38.314719, 128.517729, '2026-05-24T00:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001897', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2811451', '스테이황룡', '비 오는 날 운치 찾아 스테이황룡 다녀왔어요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "주말나들이", "사진맛집"]'::jsonb, 35.294972, 126.770106, '2026-05-18T15:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001898', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2775304', '아올', '근처 여행 코스로 아올 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 35.276153, 126.509438, '2026-07-07T13:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001899', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3532711', '안스테이', '근처 여행 코스로 안스테이 넣길 정말 잘했어요. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "사진맛집", "인생샷"]'::jsonb, 37.765344, 127.392716, '2026-07-11T20:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001900', '54500700-0000-4000-8000-000000000191', 'p-tourapi-635593', '갈중이(천연염색체험)', '드라이브 겸 나들이로 갈중이(천연염색체험) 선택했는데 대만족! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 33.235113, 126.313647, '2026-06-30T04:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001901', '54500700-0000-4000-8000-000000000174', 'p-tourapi-2717590', '김성래 가옥', '날씨가 너무 맑아서 김성래 가옥 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "혼자여행", "산책로", "온마루"]'::jsonb, 37.987361, 128.739890, '2026-05-22T11:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001902', '54500700-0000-4000-8000-000000000145', 'p-tourapi-3438576', '테오리아', '조용히 사색하고 싶어서 찾은 테오리아. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.818531, 127.151050, '2026-04-28T03:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001903', '54500700-0000-4000-8000-000000000138', 'p-tourapi-2574307', '목양산방', '평일 연차 쓰고 혼자 목양산방 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 34.889717, 127.507484, '2026-05-30T06:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001904', '54500700-0000-4000-8000-000000000180', 'p-tourapi-250372', '의성김씨 학봉종택', '예전부터 가보고 싶었던 의성김씨 학봉종택 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 36.609676, 128.669221, '2026-04-30T12:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001905', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3438581', '교동94', '비 오는 날 운치 찾아 교동94 다녀왔어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.812687, 127.152503, '2026-04-25T01:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001906', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2760074', '지리산태고재 (정일품농원)', '비 오는 날 운치 찾아 지리산태고재 (정일품농원) 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "사진맛집", "데이트", "온마루"]'::jsonb, 35.565109, 127.767297, '2026-07-03T18:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001907', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3511230', '김씨네마카롱공장(주식회사필링)', '날씨가 너무 맑아서 김씨네마카롱공장(주식회사필링) 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 35.490603, 129.435739, '2026-07-02T12:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001908', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3101956', '죽록정사', '죽록정사 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "방문팁", "온마루"]'::jsonb, 35.226528, 127.485989, '2026-05-13T10:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001909', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2569552', '셔블', '해 질 무렵에 셔블 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "사색"]'::jsonb, 35.836816, 129.211543, '2026-07-14T19:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001910', '54500700-0000-4000-8000-000000000203', 'p-tourapi-3541047', '주문진 관광안내센터', '주말에 친구들이랑 주문진 관광안내센터 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 37.889982, 128.828574, '2026-05-10T05:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001911', '54500700-0000-4000-8000-000000000186', 'p-tourapi-1594374', '전주전통한지원', '해 질 무렵에 전주전통한지원 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 35.815995, 127.153533, '2026-05-20T09:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001912', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3532883', '소풍한옥풀빌라', '천천히 골목 걷다가 마주친 소풍한옥풀빌라. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "방문팁", "사진맛집"]'::jsonb, 35.855854, 129.267029, '2026-05-29T05:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001913', '54500700-0000-4000-8000-000000000064', 'p-tourapi-3438368', '해아원', '오랜만에 여유 찾으러 해아원 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "산책로", "혼자여행"]'::jsonb, 37.582897, 126.983320, '2026-06-01T21:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001914', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2939588', '행주커뮤니티센터', '날씨가 너무 맑아서 행주커뮤니티센터 한 바퀴 돌고 왔네요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 37.602622, 126.822865, '2026-04-29T10:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001915', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2663296', '경주 한옥(경주한옥펜션)', '기대 이상으로 너무 좋았던 경주 한옥(경주한옥펜션)! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.801408, 129.196856, '2026-06-26T12:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001916', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3532598', '월하', '예전부터 가보고 싶었던 월하 드디어 방문! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.848067, 129.207415, '2026-06-01T23:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001917', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2737316', '킹콩놀이터', '해 질 무렵에 킹콩놀이터 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 36.008569, 126.773285, '2026-06-13T10:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001918', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3025473', '영광 매간당 고택', '예전부터 가보고 싶었던 영광 매간당 고택 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 35.240848, 126.474309, '2026-04-30T04:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001919', '54500700-0000-4000-8000-000000000092', 'p-tourapi-128788', '설악산 케이블카', '해 질 무렵에 설악산 케이블카 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "혼자여행", "사색"]'::jsonb, 38.173154, 128.489166, '2026-05-05T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001920', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1971917', '청공한옥', 'SNS에서 사진 보고 찾아간 청공한옥, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 35.781946, 129.303306, '2026-04-19T17:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001921', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3438589', '윤은재', '기대 이상으로 너무 좋았던 윤은재! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 35.033470, 126.712265, '2026-05-23T10:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001922', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2638480', '울산안전체험관', '날씨가 너무 맑아서 울산안전체험관 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "사진맛집"]'::jsonb, 35.617736, 129.440348, '2026-06-28T13:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001923', '54500700-0000-4000-8000-000000000141', 'p-tourapi-1610542', '달성 조길방 고택', '비 오는 날 운치 찾아 달성 조길방 고택 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "데이트", "사진맛집", "온마루"]'::jsonb, 35.755808, 128.581749, '2026-05-18T22:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001924', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3438431', '사월 한옥', '주말에 친구들이랑 사월 한옥 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.593910, 127.000024, '2026-05-19T11:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001925', '54500700-0000-4000-8000-000000000064', 'p-tourapi-3072240', '온유헌 바이 버틀러리', '천천히 골목 걷다가 마주친 온유헌 바이 버틀러리. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "사진맛집", "데이트"]'::jsonb, 37.581611, 126.987489, '2026-04-25T01:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001926', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3116447', '웰컴미스테익스', '부모님 모시고 웰컴미스테익스 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "데이트", "사진맛집"]'::jsonb, 37.591722, 126.963228, '2026-07-02T19:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001927', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3438160', '통인 1939', '툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행", "고즈넉"]'::jsonb, 37.579028, 126.970980, '2026-06-29T06:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001928', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2373420', '아띠인력거', '근처 여행 코스로 아띠인력거 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 37.579389, 126.982559, '2026-05-03T05:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001929', '54500700-0000-4000-8000-000000000077', 'p-tourapi-3032740', '대가야기마문화체험장', '근처 여행 코스로 대가야기마문화체험장 넣길 정말 잘했어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 35.711382, 128.267182, '2026-05-29T19:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001930', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1883996', '취옹예술관', '예전부터 가보고 싶었던 취옹예술관 드디어 방문! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 37.752549, 127.359939, '2026-07-06T17:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001931', '54500700-0000-4000-8000-000000000132', 'p-tourapi-1606009', '삼청동오위장김춘영가옥', '삼청동오위장김춘영가옥 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "방문팁", "가족여행", "온마루"]'::jsonb, 37.558800, 126.994800, '2026-07-13T09:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001932', '54500700-0000-4000-8000-000000000083', 'p-tourapi-2775016', '잼토리 JAMTORY', '부모님 모시고 잼토리 JAMTORY 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 36.943564, 127.517309, '2026-05-26T15:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001933', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '해 질 무렵에 미담 한옥 게스트 하우스 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 37.580664, 126.986353, '2026-07-10T13:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001934', '54500700-0000-4000-8000-000000000190', 'p-tourapi-1799268', '회원식당', '해 질 무렵에 회원식당 방문했는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 35.078071, 127.769291, '2026-05-06T10:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001935', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2706485', '오류헌', '오랜만에 여유 찾으러 오류헌 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 36.519515, 128.866840, '2026-05-26T19:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001936', '54500700-0000-4000-8000-000000000191', 'p-tourapi-800528', '춘천 강언덕마을 [농촌전통테마]', '날씨가 너무 맑아서 춘천 강언덕마을 [농촌전통테마] 한 바퀴 돌고 왔네요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행", "주말나들이"]'::jsonb, 37.678664, 127.613691, '2026-06-13T00:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001937', '54500700-0000-4000-8000-000000000185', 'p-tourapi-3438452', '담서제', '부모님 모시고 담서제 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 37.640531, 126.939267, '2026-07-16T09:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001938', '54500700-0000-4000-8000-000000000098', 'p-tourapi-3066280', '전주일몽', '해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "인생샷", "주말나들이", "온마루"]'::jsonb, 35.812079, 127.154722, '2026-07-15T13:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001939', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2707445', '일독일박', '비 오는 날 운치 찾아 일독일박 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 37.578486, 126.968545, '2026-07-16T21:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001940', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2853622', '양수리한옥집', '평일 연차 쓰고 혼자 양수리한옥집 다녀옴. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.547468, 127.321871, '2026-07-06T01:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001941', '54500700-0000-4000-8000-000000000094', 'p-tourapi-3438359', '스테이모일', '비 오는 날 운치 찾아 스테이모일 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["방문팁", "주말나들이", "사진맛집", "온마루"]'::jsonb, 37.576664, 126.991108, '2026-05-08T14:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001942', '54500700-0000-4000-8000-000000000132', 'p-tourapi-1310884', '고성장산리허씨고가', '평일 연차 쓰고 혼자 고성장산리허씨고가 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "힐링", "온마루"]'::jsonb, 35.060351, 128.323950, '2026-07-14T18:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001943', '54500700-0000-4000-8000-000000000187', 'p-tourapi-1624505', '해남 민정기 가옥', '해 질 무렵에 해남 민정기 가옥 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 34.542754, 126.568428, '2026-07-07T10:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001944', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2502595', '술샘', '평일 연차 쓰고 혼자 술샘 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "사색", "산책로"]'::jsonb, 37.233510, 127.298585, '2026-05-05T04:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001945', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2586166', '황토한옥고마', '해 질 무렵에 황토한옥고마 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 36.461445, 127.122366, '2026-05-21T03:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001946', '54500700-0000-4000-8000-000000000203', 'p-tourapi-1972030', '상유재', '해 질 무렵에 상유재 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["데이트", "인생샷", "사진맛집", "온마루"]'::jsonb, 37.379376, 128.660656, '2026-05-08T09:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001947', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2600371', '선비촌', '평일 연차 쓰고 혼자 선비촌 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 36.931363, 128.581189, '2026-05-02T05:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001948', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2598834', '안동 군자마을', '조용히 사색하고 싶어서 찾은 안동 군자마을. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 36.673285, 128.801397, '2026-06-29T23:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001949', '54500700-0000-4000-8000-000000000147', 'p-tourapi-2606387', '예천군체육회활체험센터', '날씨가 너무 맑아서 예천군체육회활체험센터 한 바퀴 돌고 왔네요. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 36.634678, 128.468413, '2026-06-10T11:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001950', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2786838', '산청 남사리 이씨고가', '근처 여행 코스로 산청 남사리 이씨고가 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.274927, 127.935019, '2026-04-28T08:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001951', '54500700-0000-4000-8000-000000000139', 'p-tourapi-3056595', '전주한옥마을역사관', 'SNS에서 사진 보고 찾아간 전주한옥마을역사관, 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "산책로"]'::jsonb, 35.816007, 127.152938, '2026-06-25T07:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001952', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3438561', '스테이용궁', '기대 이상으로 너무 좋았던 스테이용궁! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 37.281413, 127.019773, '2026-07-14T11:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001953', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3469953', '하녹집', '근처 여행 코스로 하녹집 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.564721, 128.736503, '2026-05-31T13:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001954', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2932873', '계와고택', '기대 이상으로 너무 좋았던 계와고택! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 36.506191, 128.852914, '2026-06-07T17:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001955', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3457765', '인천애뜰', '기대 이상으로 너무 좋았던 인천애뜰! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 37.455087, 126.706099, '2026-06-17T13:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001956', '54500700-0000-4000-8000-000000000183', 'p-tourapi-2702475', '고진하 가옥', '날씨가 너무 맑아서 고진하 가옥 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["인생샷", "가족여행", "데이트", "온마루"]'::jsonb, 37.174095, 128.386897, '2026-05-25T20:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001957', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2531675', '진도한옥펜션', '드라이브 겸 나들이로 진도한옥펜션 선택했는데 대만족! 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 34.398482, 126.277327, '2026-07-16T21:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001958', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2603918', '(사)영남선비문화수련원(구암서원)', '조용히 사색하고 싶어서 찾은 (사)영남선비문화수련원(구암서원). 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.901625, 128.596853, '2026-04-28T23:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001959', '54500700-0000-4000-8000-000000000160', 'p-tourapi-2628953', '하늘풍경', '천천히 골목 걷다가 마주친 하늘풍경. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 35.812531, 127.152392, '2026-05-04T12:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001960', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3532770', '월하고택', 'SNS에서 사진 보고 찾아간 월하고택, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.719445, 127.313208, '2026-05-17T04:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001961', '54500700-0000-4000-8000-000000000088', 'p-tourapi-1883085', '늘봄스테이', '비 오는 날 운치 찾아 늘봄스테이 다녀왔어요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.813289, 127.152181, '2026-05-24T14:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001962', '54500700-0000-4000-8000-000000000152', 'p-tourapi-3532465', '동해산타열차', '근처 여행 코스로 동해산타열차 넣길 정말 잘했어요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이", "방문팁", "온마루"]'::jsonb, 37.764062, 128.899666, '2026-06-14T19:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001963', '54500700-0000-4000-8000-000000000100', 'p-tourapi-3438569', '아담', '조용히 사색하고 싶어서 찾은 아담. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "산책로", "온마루"]'::jsonb, 36.450638, 127.122067, '2026-04-29T22:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001964', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2706641', '달빛미소', '평일 연차 쓰고 혼자 달빛미소 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.740520, 126.717927, '2026-06-19T03:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001965', '54500700-0000-4000-8000-000000000129', 'p-tourapi-3438496', '소우주', '예전부터 가보고 싶었던 소우주 드디어 방문! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "사진맛집", "데이트"]'::jsonb, 37.640970, 126.938620, '2026-07-15T02:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001966', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2531683', '옛마실펜션', '부모님 모시고 옛마실펜션 산책 겸 다녀왔습니다. 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 34.851029, 128.724318, '2026-06-12T11:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001967', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2049706', '교동가온', '교동가온 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷", "데이트", "온마루"]'::jsonb, 35.813423, 127.153033, '2026-04-25T21:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001968', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2046299', '한옥이야기', '날씨가 너무 맑아서 한옥이야기 한 바퀴 돌고 왔네요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "방문팁", "사진맛집", "온마루"]'::jsonb, 35.812317, 127.153572, '2026-06-12T13:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001969', '54500700-0000-4000-8000-000000000109', 'p-tourapi-3056595', '전주한옥마을역사관', '오랜만에 여유 찾으러 전주한옥마을역사관 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.816007, 127.152938, '2026-05-14T14:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001970', '54500700-0000-4000-8000-000000000175', 'p-tourapi-2604371', '노을한옥', '기대 이상으로 너무 좋았던 노을한옥! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 34.851191, 127.523245, '2026-06-14T10:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001971', '54500700-0000-4000-8000-000000000128', 'p-tourapi-794941', '안동 진성이씨 종택', '천천히 골목 걷다가 마주친 안동 진성이씨 종택. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집", "온마루"]'::jsonb, 36.639651, 128.741684, '2026-05-22T03:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001972', '54500700-0000-4000-8000-000000000142', 'p-tourapi-4074856', '연림스테이', '예전부터 가보고 싶었던 연림스테이 드디어 방문! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "사진맛집", "데이트", "온마루"]'::jsonb, 35.972113, 128.698835, '2026-05-18T18:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001973', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2000946', '치암고택', '비 오는 날 운치 찾아 치암고택 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "데이트"]'::jsonb, 36.583250, 128.736044, '2026-06-28T09:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001974', '54500700-0000-4000-8000-000000000107', 'p-tourapi-3533160', '와하녹', '조용히 사색하고 싶어서 찾은 와하녹. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링"]'::jsonb, 37.581772, 126.999908, '2026-06-18T12:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001975', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2500218', '광흥당', '부모님 모시고 광흥당 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 37.548636, 126.928676, '2026-06-01T23:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001976', '54500700-0000-4000-8000-000000000184', 'p-tourapi-128645', '춘천최재근가옥', '주말에 친구들이랑 춘천최재근가옥 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 37.843130, 127.727499, '2026-06-24T08:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001977', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2668426', '학림재', '주말에 친구들이랑 학림재 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "사색", "혼자여행", "온마루"]'::jsonb, 36.551056, 127.189936, '2026-04-22T23:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001978', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2598650', '주촌종택(주촌(두루)종택)', '천천히 골목 걷다가 마주친 주촌종택(주촌(두루)종택). 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 36.642635, 128.739253, '2026-05-31T15:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001979', '54500700-0000-4000-8000-000000000092', 'p-tourapi-3438402', '사사로이', '드라이브 겸 나들이로 사사로이 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트", "사진맛집", "온마루"]'::jsonb, 37.578161, 126.981404, '2026-07-16T07:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001980', '54500700-0000-4000-8000-000000000149', 'p-tourapi-231940', '안동 소호헌', '해 질 무렵에 안동 소호헌 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["주말나들이", "방문팁"]'::jsonb, 36.463695, 128.663462, '2026-05-05T09:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001981', '54500700-0000-4000-8000-000000000194', 'p-tourapi-3358056', '닥나무한지체험관 콩닥콩닥', '오랜만에 여유 찾으러 닥나무한지체험관 콩닥콩닥 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.691674, 126.817694, '2026-05-02T11:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001982', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2603996', '매죽헌2(매죽헌한옥민박)', '비 오는 날 운치 찾아 매죽헌2(매죽헌한옥민박) 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["데이트", "가족여행", "방문팁"]'::jsonb, 35.069064, 127.401634, '2026-05-26T15:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001983', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3510980', '유한회사더담희', '드라이브 겸 나들이로 유한회사더담희 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁", "가족여행"]'::jsonb, 35.219197, 126.878187, '2026-05-25T05:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001984', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3065503', '전주 대사습청', '기대 이상으로 너무 좋았던 전주 대사습청! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "사진맛집", "인생샷"]'::jsonb, 35.817686, 127.153545, '2026-07-07T23:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001985', '54500700-0000-4000-8000-000000000182', 'p-tourapi-3012433', '경기도국민안전체험관', '드라이브 겸 나들이로 경기도국민안전체험관 선택했는데 대만족! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집", "가족여행", "온마루"]'::jsonb, 37.178490, 127.062746, '2026-06-28T01:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001986', '54500700-0000-4000-8000-000000000067', 'p-tourapi-3469822', '대동고택', '천천히 골목 걷다가 마주친 대동고택. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "사색"]'::jsonb, 35.821574, 127.136349, '2026-05-22T14:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001987', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3337188', '세종전통문화체험관', '해 질 무렵에 세종전통문화체험관 방문했는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "데이트", "방문팁", "온마루"]'::jsonb, 36.506871, 127.291859, '2026-06-21T12:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001988', '54500700-0000-4000-8000-000000000184', 'p-tourapi-3438616', '한낮', '부모님 모시고 한낮 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "힐링", "혼자여행"]'::jsonb, 36.556245, 128.755548, '2026-07-10T07:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001989', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2701396', '서남산한옥', '오랜만에 여유 찾으러 서남산한옥 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.780864, 129.204559, '2026-06-08T21:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001990', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2393927', '충청남도 안전체험관', '천천히 골목 걷다가 마주친 충청남도 안전체험관. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 36.821636, 127.191839, '2026-05-27T16:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001991', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2614384', '윤동주 유고보존 정병욱 가옥', '근처 여행 코스로 윤동주 유고보존 정병욱 가옥 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "데이트", "주말나들이"]'::jsonb, 34.970753, 127.759167, '2026-06-30T13:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001992', '54500700-0000-4000-8000-000000000152', 'p-tourapi-2609894', '경기전 연가', '날씨가 너무 맑아서 경기전 연가 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "인생샷"]'::jsonb, 35.817436, 127.150187, '2026-05-26T22:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001993', '54500700-0000-4000-8000-000000000091', 'p-tourapi-1089992', '대전교통문화연수원', '근처 여행 코스로 대전교통문화연수원 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 36.377207, 127.386364, '2026-04-20T13:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001994', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2814160', '불국사한옥팜스테이', '조용히 사색하고 싶어서 찾은 불국사한옥팜스테이. 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.782952, 129.328113, '2026-06-17T06:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001995', '54500700-0000-4000-8000-000000000144', 'p-tourapi-3451224', '은계2어울림센터', '은계2어울림센터 다녀왔어요! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.435836, 126.797916, '2026-07-07T03:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001996', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2598834', '안동 군자마을', '기대 이상으로 너무 좋았던 안동 군자마을! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁", "사진맛집"]'::jsonb, 36.673285, 128.801397, '2026-05-13T18:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001997', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3540259', '한옥스테이 파인앤프렌즈', '침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "사진맛집", "온마루"]'::jsonb, 37.776189, 128.933054, '2026-05-11T05:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001998', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2603884', '연당', '근처 여행 코스로 연당 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.582603, 126.987073, '2026-04-26T09:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000001999', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2607481', '향운', '평일 연차 쓰고 혼자 향운 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉"]'::jsonb, 37.583027, 126.985925, '2026-07-04T00:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002000', '54500700-0000-4000-8000-000000000070', 'p-tourapi-1685586', '청풍 황석리 고가', '예전부터 가보고 싶었던 청풍 황석리 고가 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "데이트", "인생샷", "온마루"]'::jsonb, 37.005405, 128.170535, '2026-06-25T10:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002001', '54500700-0000-4000-8000-000000000164', 'p-tourapi-2819158', '매원마을', '매원마을 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 35.994099, 128.430999, '2026-05-05T21:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002002', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2622784', '소양고택 한옥스테이', '해 질 무렵에 소양고택 한옥스테이 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.903680, 127.243089, '2026-07-07T23:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002003', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2668131', '춘화당', '날씨가 너무 맑아서 춘화당 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 34.791348, 126.383094, '2026-04-21T14:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002004', '54500700-0000-4000-8000-000000000130', 'p-tourapi-1972012', '산에는 꽃이피네', '날씨가 너무 맑아서 산에는 꽃이피네 한 바퀴 돌고 왔네요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "인생샷"]'::jsonb, 34.998671, 126.823311, '2026-05-22T08:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002005', '54500700-0000-4000-8000-000000000127', 'p-tourapi-3533160', '와하녹', '기대 이상으로 너무 좋았던 와하녹! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "데이트"]'::jsonb, 37.581772, 126.999908, '2026-06-06T06:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002006', '54500700-0000-4000-8000-000000000096', 'p-tourapi-2046299', '한옥이야기', '드라이브 겸 나들이로 한옥이야기 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트"]'::jsonb, 35.812317, 127.153572, '2026-05-15T08:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002007', '54500700-0000-4000-8000-000000000078', 'p-tourapi-129052', '청송초전댁', '부모님 모시고 청송초전댁 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "산책로"]'::jsonb, 36.437960, 129.026646, '2026-07-10T09:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002008', '54500700-0000-4000-8000-000000000166', 'p-tourapi-3444479', '성주 예산리 배리댁', '기대 이상으로 너무 좋았던 성주 예산리 배리댁! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 35.923369, 128.285109, '2026-06-09T02:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002009', '54500700-0000-4000-8000-000000000181', 'p-tourapi-2604344', '락희원', 'SNS에서 사진 보고 찾아간 락희원, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 35.837371, 129.212015, '2026-06-01T00:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002010', '54500700-0000-4000-8000-000000000061', 'p-tourapi-798830', '영동 김참판댁', '주말에 친구들이랑 영동 김참판댁 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 36.153087, 127.754835, '2026-07-08T02:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002011', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2820893', '평창사랑', '주말에 친구들이랑 평창사랑 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 37.490534, 128.410696, '2026-06-27T02:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002012', '54500700-0000-4000-8000-000000000119', 'p-tourapi-3424446', '영동군 숲에너지육감 활성화센터', '날씨가 너무 맑아서 영동군 숲에너지육감 활성화센터 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 36.155623, 127.785879, '2026-06-05T02:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002013', '54500700-0000-4000-8000-000000000071', 'p-tourapi-1373030', '서상돈 고택', '부모님 모시고 서상돈 고택 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "고즈넉", "힐링"]'::jsonb, 35.867165, 128.587812, '2026-05-03T21:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002014', '54500700-0000-4000-8000-000000000197', 'p-tourapi-1997202', '여수 해상케이블카', '오랜만에 여유 찾으러 여수 해상케이블카 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "풍경맛집"]'::jsonb, 34.730797, 127.739326, '2026-06-10T06:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002015', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2699340', '한옥 게스트하우스 동촌재', '기대 이상으로 너무 좋았던 한옥 게스트하우스 동촌재! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 37.580111, 126.969855, '2026-06-13T06:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002016', '54500700-0000-4000-8000-000000000097', 'p-tourapi-231936', '달성 태고정', '주말에 친구들이랑 달성 태고정 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "힐링"]'::jsonb, 35.911351, 128.416611, '2026-07-02T09:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002017', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3438574', '풍류가옥', '조용히 사색하고 싶어서 찾은 풍류가옥. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["산책로", "사색", "풍경맛집", "온마루"]'::jsonb, 35.824688, 127.155322, '2026-07-16T01:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002018', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3438420', '성북 은은한가', '평일 연차 쓰고 혼자 성북 은은한가 다녀옴. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 37.590744, 127.009037, '2026-05-21T11:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002019', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2595489', '동해한옥 동안재', '고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행", "인생샷"]'::jsonb, 37.528246, 129.108618, '2026-05-12T17:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002020', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2605351', '광주폴리', '조용히 사색하고 싶어서 찾은 광주폴리. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.182620, 126.890259, '2026-06-18T14:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002021', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2600221', '박정우가옥', '예전부터 가보고 싶었던 박정우가옥 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["사진맛집", "인생샷", "주말나들이"]'::jsonb, 36.734650, 128.619780, '2026-07-09T02:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002022', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2380834', '마복산 목재문화체험장', '드라이브 겸 나들이로 마복산 목재문화체험장 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "주말나들이"]'::jsonb, 34.550477, 127.375721, '2026-06-09T06:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002023', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2468936', '옛날에금잔디', '천천히 골목 걷다가 마주친 옛날에금잔디. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.716068, 126.389197, '2026-06-15T09:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002024', '54500700-0000-4000-8000-000000000079', 'p-tourapi-3444338', '완정고택', '비 오는 날 운치 찾아 완정고택 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "고즈넉"]'::jsonb, 36.004157, 128.234459, '2026-07-17T04:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002025', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2651450', '한옥혜윰', '조용히 사색하고 싶어서 찾은 한옥혜윰. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "산책로"]'::jsonb, 35.811471, 127.152078, '2026-05-07T00:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002026', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3438592', '한옥스테이 다가감', 'SNS에서 사진 보고 찾아간 한옥스테이 다가감, 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 35.835069, 129.212923, '2026-06-04T17:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002027', '54500700-0000-4000-8000-000000000147', 'p-tourapi-3454074', '영화의전당 라이브러리 자료실', '날씨가 너무 맑아서 영화의전당 라이브러리 자료실 한 바퀴 돌고 왔네요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "산책로", "온마루"]'::jsonb, 35.171003, 129.127069, '2026-06-25T13:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002028', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2820733', '생생마을여행사', '해 질 무렵에 생생마을여행사 방문했는데 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 37.027128, 127.630291, '2026-04-27T03:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002029', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2713277', '산토끼 노래동산', '조용히 사색하고 싶어서 찾은 산토끼 노래동산. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["사색", "고즈넉"]'::jsonb, 35.577791, 128.383623, '2026-05-10T08:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002030', '54500700-0000-4000-8000-000000000159', 'p-tourapi-1884345', '행복드림한옥', '오랜만에 여유 찾으러 행복드림한옥 다녀왔습니다. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 35.905472, 127.209637, '2026-06-26T08:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002031', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2587214', '제이한옥(JAY Hanok)', '오랜만에 여유 찾으러 제이한옥(JAY Hanok) 다녀왔습니다. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 37.582308, 126.987336, '2026-05-25T01:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002032', '54500700-0000-4000-8000-000000000169', 'p-tourapi-3511602', '주식회사조아지구', '근처 여행 코스로 주식회사조아지구 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["사진맛집", "주말나들이", "가족여행"]'::jsonb, 35.944178, 127.164482, '2026-06-24T11:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002033', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3009051', '도깨비 양조장', '주말에 친구들이랑 도깨비 양조장 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 37.026390, 128.384743, '2026-06-16T02:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002034', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2638488', '거제 관광모노레일', '예전부터 가보고 싶었던 거제 관광모노레일 드디어 방문! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 34.876418, 128.625395, '2026-07-16T16:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002035', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2707438', '하은재', '근처 여행 코스로 하은재 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "방문팁"]'::jsonb, 37.581938, 126.971282, '2026-05-23T09:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002036', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3102211', '자하연', 'SNS에서 사진 보고 찾아간 자하연, 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 35.812215, 127.155011, '2026-05-22T00:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002037', '54500700-0000-4000-8000-000000000093', 'p-tourapi-3101961', '자미재', '기대 이상으로 너무 좋았던 자미재! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "고즈넉", "혼자여행", "온마루"]'::jsonb, 34.911789, 126.648057, '2026-06-21T15:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002038', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3353949', '㈜ 희품씨', '해 질 무렵에 ㈜ 희품씨 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "인생샷"]'::jsonb, 35.567161, 129.112429, '2026-04-24T01:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002039', '54500700-0000-4000-8000-000000000148', 'p-tourapi-1877312', '양소당', '날씨가 너무 맑아서 양소당 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트"]'::jsonb, 36.580236, 128.546811, '2026-05-18T03:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002040', '54500700-0000-4000-8000-000000000143', 'p-tourapi-3532465', '동해산타열차', '천천히 골목 걷다가 마주친 동해산타열차. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "가족여행"]'::jsonb, 37.764062, 128.899666, '2026-07-12T08:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002041', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3438450', '평안채', '천천히 골목 걷다가 마주친 평안채. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "가족여행", "온마루"]'::jsonb, 37.640873, 126.938714, '2026-06-05T07:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002042', '54500700-0000-4000-8000-000000000155', 'p-tourapi-2725010', '휴식 레스토랑', '해 질 무렵에 휴식 레스토랑 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "가족여행", "인생샷", "온마루"]'::jsonb, 36.451188, 126.813247, '2026-06-30T00:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002043', '54500700-0000-4000-8000-000000000201', 'p-tourapi-2620413', '병암고택', '주말에 친구들이랑 병암고택 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행", "사진맛집"]'::jsonb, 36.558046, 129.128132, '2026-07-16T18:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002044', '54500700-0000-4000-8000-000000000114', 'p-tourapi-1594500', '전주목판서화체험관', '드라이브 겸 나들이로 전주목판서화체험관 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "사진맛집", "데이트"]'::jsonb, 35.811515, 127.155650, '2026-06-17T03:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002045', '54500700-0000-4000-8000-000000000060', 'p-tourapi-3105334', '133파티룸 한옥스테이점', '주말에 친구들이랑 133파티룸 한옥스테이점 들렀는데 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 37.279463, 127.016073, '2026-05-15T17:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002046', '54500700-0000-4000-8000-000000000161', 'p-tourapi-2708657', '초정행궁', '부모님 모시고 초정행궁 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["가족여행", "인생샷", "데이트", "온마루"]'::jsonb, 36.721236, 127.601291, '2026-05-30T11:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002047', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3532950', '유류헌', 'SNS에서 사진 보고 찾아간 유류헌, 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 37.881654, 127.742256, '2026-05-26T20:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002048', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2707242', '위연재', '오랜만에 여유 찾으러 위연재 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "풍경맛집", "고즈넉"]'::jsonb, 35.836188, 129.218017, '2026-06-27T23:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002049', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2608140', '하늘누리', '부모님 모시고 하늘누리 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["방문팁", "주말나들이", "데이트", "온마루"]'::jsonb, 34.637934, 127.033879, '2026-06-17T02:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002050', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2638480', '울산안전체험관', '주말에 친구들이랑 울산안전체험관 들렀는데 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "데이트", "인생샷", "온마루"]'::jsonb, 35.617736, 129.440348, '2026-05-27T22:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002051', '54500700-0000-4000-8000-000000000168', 'p-tourapi-3438359', '스테이모일', '날씨가 너무 맑아서 스테이모일 한 바퀴 돌고 왔네요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 37.576664, 126.991108, '2026-06-24T00:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002052', '54500700-0000-4000-8000-000000000177', 'p-tourapi-2049874', '해마루 힐링숲', '해 질 무렵에 해마루 힐링숲 방문했는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.438810, 126.632762, '2026-05-14T03:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002053', '54500700-0000-4000-8000-000000000067', 'p-tourapi-128994', '구례 운조루 고택', '조용히 사색하고 싶어서 찾은 구례 운조루 고택. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "풍경맛집"]'::jsonb, 35.206079, 127.515423, '2026-04-19T18:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002054', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2932921', '한울', '조용히 사색하고 싶어서 찾은 한울. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "사색", "힐링", "온마루"]'::jsonb, 37.237134, 127.265493, '2026-07-01T15:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002055', '54500700-0000-4000-8000-000000000071', 'p-tourapi-3532948', '하녹명당', '해 질 무렵에 하녹명당 방문했는데 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.836630, 129.211832, '2026-05-22T13:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002056', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3007507', '호수양조장', '예전부터 가보고 싶었던 호수양조장 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 37.872331, 127.731141, '2026-05-03T19:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002057', '54500700-0000-4000-8000-000000000186', 'p-tourapi-128547', '이해룡고가', '평일 연차 쓰고 혼자 이해룡고가 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 36.911705, 127.287028, '2026-05-24T15:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002058', '54500700-0000-4000-8000-000000000108', 'p-tourapi-1871270', '맥산댁', '천천히 골목 걷다가 마주친 맥산댁. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.667289, 128.228714, '2026-06-07T18:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002059', '54500700-0000-4000-8000-000000000099', 'p-tourapi-3102212', '한옥마을숙박 가인당', '조용히 사색하고 싶어서 찾은 한옥마을숙박 가인당. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 35.812323, 127.151861, '2026-04-23T06:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002060', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3454325', '꿀잼도시 대전홍보관', '비 오는 날 운치 찾아 꿀잼도시 대전홍보관 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 36.375238, 127.382198, '2026-05-05T18:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002061', '54500700-0000-4000-8000-000000000171', 'p-tourapi-3438485', '다락재', '조용히 사색하고 싶어서 찾은 다락재. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "힐링", "온마루"]'::jsonb, 37.641231, 126.939842, '2026-06-13T18:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002062', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2651484', '생비원', '비 오는 날 운치 찾아 생비원 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷"]'::jsonb, 35.800801, 128.176595, '2026-04-19T16:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002063', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2572792', '매죽헌(매죽헌 한옥 민박)', '부모님 모시고 매죽헌(매죽헌 한옥 민박) 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "데이트", "가족여행"]'::jsonb, 35.066003, 127.404253, '2026-04-22T10:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002064', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2699354', '은혜당', '주말에 친구들이랑 은혜당 들렀는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 36.507605, 129.400748, '2026-07-17T07:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002065', '54500700-0000-4000-8000-000000000067', 'p-tourapi-4041219', '지후헌', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트", "방문팁", "온마루"]'::jsonb, 37.589451, 127.003238, '2026-05-12T17:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002066', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2569237', '운정루', '평일 연차 쓰고 혼자 운정루 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 35.791283, 129.245897, '2026-04-25T04:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002067', '54500700-0000-4000-8000-000000000132', 'p-tourapi-561914', '원주변씨 간재종택 및 간재정', '드라이브 겸 나들이로 원주변씨 간재종택 및 간재정 선택했는데 대만족! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 36.601216, 128.677101, '2026-04-23T19:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002068', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3532618', '산성동그곳', '천천히 골목 걷다가 마주친 산성동그곳. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "고즈넉", "혼자여행"]'::jsonb, 36.458874, 127.126462, '2026-04-21T10:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002069', '54500700-0000-4000-8000-000000000154', 'p-tourapi-1877312', '양소당', '부모님 모시고 양소당 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 36.580236, 128.546811, '2026-07-15T06:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002070', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2725124', '반정', '주말에 친구들이랑 반정 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "사색", "산책로", "온마루"]'::jsonb, 37.492779, 128.457525, '2026-06-05T18:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002071', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3438577', '청연', '해 질 무렵에 청연 방문했는데 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.811242, 127.152217, '2026-06-09T16:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002072', '54500700-0000-4000-8000-000000000092', 'p-tourapi-1627236', '신경섭 전통가옥', '오랜만에 여유 찾으러 신경섭 전통가옥 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "고즈넉", "풍경맛집"]'::jsonb, 36.420803, 126.668294, '2026-06-28T06:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002073', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2939639', '유현문화관광지', '유현문화관광지 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 37.530718, 127.819940, '2026-04-25T00:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002074', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3438468', '생활서가', '비 오는 날 운치 찾아 생활서가 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "가족여행", "주말나들이", "온마루"]'::jsonb, 37.642950, 126.939222, '2026-05-24T05:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002075', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2615342', '비비정예술열차', '천천히 골목 걷다가 마주친 비비정예술열차. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.898992, 127.067778, '2026-06-12T21:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002076', '54500700-0000-4000-8000-000000000093', 'p-tourapi-2811451', '스테이황룡', '부모님 모시고 스테이황룡 산책 겸 다녀왔습니다. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링", "사색", "온마루"]'::jsonb, 35.294972, 126.770106, '2026-05-27T00:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002077', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3105335', '세렌디피아', '비 오는 날 운치 찾아 세렌디피아 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 34.786543, 126.381631, '2026-07-08T09:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002078', '54500700-0000-4000-8000-000000000204', 'p-tourapi-128653', '거창 동계종택', '오랜만에 여유 찾으러 거창 동계종택 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.755466, 127.828767, '2026-06-23T18:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002079', '54500700-0000-4000-8000-000000000155', 'p-tourapi-128655', '거창 황산리 신씨고가', '예전부터 가보고 싶었던 거창 황산리 신씨고가 드디어 방문! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["사진맛집", "데이트", "주말나들이", "온마루"]'::jsonb, 35.762916, 127.837019, '2026-06-03T01:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002080', '54500700-0000-4000-8000-000000000095', 'p-tourapi-3068424', '가리왕산케이블카', '비 오는 날 운치 찾아 가리왕산케이블카 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁", "데이트"]'::jsonb, 37.474254, 128.609754, '2026-05-20T18:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002081', '54500700-0000-4000-8000-000000000151', 'p-tourapi-2606207', '목포 해상케이블카', '목포 해상케이블카 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 34.799416, 126.370053, '2026-06-16T10:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002082', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2677655', '성주 백세각', '날씨가 너무 맑아서 성주 백세각 한 바퀴 돌고 왔네요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.988067, 128.245751, '2026-07-09T04:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002083', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2790490', '비손농장(포항체험잇다)', '천천히 골목 걷다가 마주친 비손농장(포항체험잇다). 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.197610, 129.317423, '2026-06-10T14:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002084', '54500700-0000-4000-8000-000000000200', 'p-tourapi-250460', '남원몽심재', '날씨가 너무 맑아서 남원몽심재 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷", "데이트", "온마루"]'::jsonb, 35.337994, 127.374746, '2026-05-02T18:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002085', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2609878', '흥부가(家)', '드라이브 겸 나들이로 흥부가(家) 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "사진맛집", "온마루"]'::jsonb, 35.815164, 127.151970, '2026-04-25T10:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002086', '54500700-0000-4000-8000-000000000188', 'p-tourapi-2814147', '순천만숲', '비 오는 날 운치 찾아 순천만숲 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 34.897269, 127.506515, '2026-06-13T20:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002087', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2602446', '기헌고택', '근처 여행 코스로 기헌고택 넣길 정말 잘했어요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "힐링"]'::jsonb, 36.911804, 128.873422, '2026-07-06T22:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002088', '54500700-0000-4000-8000-000000000149', 'p-tourapi-2738653', '토토아뜰리에', '토토아뜰리에 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 33.469849, 126.413100, '2026-05-17T09:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002089', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3067572', '점핑고', '오랜만에 여유 찾으러 점핑고 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 36.787725, 127.121480, '2026-07-07T16:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002090', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2574225', '도원', '드라이브 겸 나들이로 도원 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "주말나들이", "온마루"]'::jsonb, 35.807848, 127.150092, '2026-06-03T12:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002091', '54500700-0000-4000-8000-000000000163', 'p-tourapi-264450', '안동 고성이씨 탑동파 종택', '평일 연차 쓰고 혼자 안동 고성이씨 탑동파 종택 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.566330, 128.746713, '2026-05-03T18:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002092', '54500700-0000-4000-8000-000000000074', 'p-tourapi-3102129', '연월한옥', '날씨가 너무 맑아서 연월한옥 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 33.317033, 126.269816, '2026-06-08T05:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002093', '54500700-0000-4000-8000-000000000170', 'p-tourapi-1579811', '거창 반구헌', '거창 반구헌 다녀왔어요! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.755100, 127.829100, '2026-07-01T06:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002094', '54500700-0000-4000-8000-000000000072', 'p-tourapi-3438422', '한옥 스테이 미경', '한옥 스테이 미경 다녀왔어요! 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "풍경맛집"]'::jsonb, 37.586652, 127.007921, '2026-04-28T12:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002095', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2713848', '수상한마법학교', '평일 연차 쓰고 혼자 수상한마법학교 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 37.730501, 128.879166, '2026-06-13T02:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002096', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2576343', '뜰안채', '주말에 친구들이랑 뜰안채 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.817136, 127.149337, '2026-07-06T14:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002097', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3511400', '농업회사법인삼산도가주식회사', '천천히 골목 걷다가 마주친 농업회사법인삼산도가주식회사. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 35.984356, 127.308474, '2026-07-03T02:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002098', '54500700-0000-4000-8000-000000000181', 'p-tourapi-3532770', '월하고택', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행", "온마루"]'::jsonb, 37.719445, 127.313208, '2026-06-08T10:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002099', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2770591', '오봉오감', '비 오는 날 운치 찾아 오봉오감 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 35.892998, 128.581455, '2026-05-28T08:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002100', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3357398', '송해기념관 선비체험관', '비 오는 날 운치 찾아 송해기념관 선비체험관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "사진맛집", "데이트"]'::jsonb, 35.771693, 128.488853, '2026-07-16T09:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002101', '54500700-0000-4000-8000-000000000138', 'p-tourapi-1089992', '대전교통문화연수원', '드라이브 겸 나들이로 대전교통문화연수원 선택했는데 대만족! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.377207, 127.386364, '2026-02-24T09:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002102', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3067572', '점핑고', '천천히 골목 걷다가 마주친 점핑고. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "방문팁", "온마루"]'::jsonb, 36.787725, 127.121480, '2026-01-15T18:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002103', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3457765', '인천애뜰', '예전부터 가보고 싶었던 인천애뜰 드디어 방문! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "가족여행"]'::jsonb, 37.455087, 126.706099, '2026-04-08T11:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002104', '54500700-0000-4000-8000-000000000093', 'p-tourapi-127014', '안동 유일재 종택', '조용히 사색하고 싶어서 찾은 안동 유일재 종택. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "사색", "고즈넉", "온마루"]'::jsonb, 36.616341, 128.774065, '2026-01-06T01:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002105', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2707242', '위연재', '부모님 모시고 위연재 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행"]'::jsonb, 35.836188, 129.218017, '2026-01-22T08:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002106', '54500700-0000-4000-8000-000000000060', 'p-tourapi-2598702', '마골댁', '비 오는 날 운치 찾아 마골댁 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집"]'::jsonb, 36.557751, 129.372652, '2026-03-02T15:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002107', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1882550', '토향고택', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 36.896664, 128.714803, '2026-01-12T11:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002108', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3438160', '통인 1939', '평일 연차 쓰고 혼자 통인 1939 다녀옴. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "사색"]'::jsonb, 37.579028, 126.970980, '2026-01-06T22:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002109', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3532990', '더옐로우', '근처 여행 코스로 더옐로우 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행", "인생샷"]'::jsonb, 35.835021, 129.207685, '2026-03-31T14:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002110', '54500700-0000-4000-8000-000000000074', 'p-tourapi-1992090', '논산 명재고택', '오랜만에 여유 찾으러 논산 명재고택 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "힐링", "혼자여행"]'::jsonb, 36.281869, 127.131209, '2026-04-12T03:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002111', '54500700-0000-4000-8000-000000000069', 'p-tourapi-2600265', '섬계고택', '조용히 사색하고 싶어서 찾은 섬계고택. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 36.734625, 128.618878, '2026-04-01T14:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002112', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2804401', '서울한옥스테이(jnpstay)', '기대 이상으로 너무 좋았던 서울한옥스테이(jnpstay)! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 37.576958, 126.970899, '2026-02-02T10:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002113', '54500700-0000-4000-8000-000000000071', 'p-tourapi-1610542', '달성 조길방 고택', '비 오는 날 운치 찾아 달성 조길방 고택 다녀왔어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷", "주말나들이"]'::jsonb, 35.755808, 128.581749, '2026-02-19T02:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002114', '54500700-0000-4000-8000-000000000175', 'p-tourapi-1600674', '장철성고택', 'SNS에서 사진 보고 찾아간 장철성고택, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 35.770347, 127.002654, '2026-01-16T20:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002115', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2568571', '1928 쉼마루', '근처 여행 코스로 1928 쉼마루 넣길 정말 잘했어요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["사색", "풍경맛집", "산책로"]'::jsonb, 35.811859, 127.152536, '2026-01-27T19:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002116', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2795229', '한지생각이닥', '오랜만에 여유 찾으러 한지생각이닥 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "힐링", "고즈넉", "온마루"]'::jsonb, 37.470628, 126.626196, '2026-04-15T17:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002117', '54500700-0000-4000-8000-000000000086', 'p-tourapi-2679990', '신라불교초전지', '조용히 사색하고 싶어서 찾은 신라불교초전지. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 36.291071, 128.363252, '2026-02-27T01:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002118', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2607661', '남악종택', 'SNS에서 사진 보고 찾아간 남악종택, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "혼자여행", "온마루"]'::jsonb, 36.687687, 128.384478, '2026-03-19T00:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002119', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1883135', '안동고택 이상루', '근처 여행 코스로 안동고택 이상루 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["데이트", "인생샷", "방문팁"]'::jsonb, 36.634748, 128.678495, '2026-02-26T13:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002120', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3033516', '논산한옥마을', 'SNS에서 사진 보고 찾아간 논산한옥마을, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.211445, 127.181241, '2026-01-21T14:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002121', '54500700-0000-4000-8000-000000000168', 'p-tourapi-2707438', '하은재', '평일 연차 쓰고 혼자 하은재 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "사색", "혼자여행"]'::jsonb, 37.581938, 126.971282, '2026-03-02T09:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002122', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2700309', '경주읍성한옥', '평일 연차 쓰고 혼자 경주읍성한옥 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "산책로", "사색", "온마루"]'::jsonb, 35.849567, 129.211526, '2026-03-01T05:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002123', '54500700-0000-4000-8000-000000000149', 'p-tourapi-1600674', '장철성고택', '날씨가 너무 맑아서 장철성고택 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["주말나들이", "사진맛집", "가족여행"]'::jsonb, 35.770347, 127.002654, '2026-04-02T19:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002124', '54500700-0000-4000-8000-000000000076', 'p-tourapi-126973', '이충무공자당기거지', '조용히 사색하고 싶어서 찾은 이충무공자당기거지. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "힐링", "혼자여행", "온마루"]'::jsonb, 34.740084, 127.683973, '2026-04-02T20:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002125', '54500700-0000-4000-8000-000000000105', 'p-tourapi-3021290', '자작자작협동조합', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 36.969041, 127.932752, '2026-03-26T06:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002126', '54500700-0000-4000-8000-000000000178', 'p-tourapi-794941', '안동 진성이씨 종택', '오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "고즈넉", "산책로"]'::jsonb, 36.639651, 128.741684, '2026-03-29T13:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002127', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3009051', '도깨비 양조장', '처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 37.026390, 128.384743, '2026-02-26T04:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002128', '54500700-0000-4000-8000-000000000066', 'p-tourapi-3438504', '한옥 포지티브스', '근처 여행 코스로 한옥 포지티브스 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "주말나들이", "인생샷", "온마루"]'::jsonb, 37.641678, 126.939414, '2026-02-20T22:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002129', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3432261', '인천업사이클에코센터', '예전부터 가보고 싶었던 인천업사이클에코센터 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 37.443213, 126.655334, '2026-03-26T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002130', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', '락고재 컬쳐 라운지 애가헌 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "가족여행", "온마루"]'::jsonb, 37.582243, 126.983944, '2026-03-22T04:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002131', '54500700-0000-4000-8000-000000000074', 'p-tourapi-129448', '두륜산케이블카', '근처 여행 코스로 두륜산케이블카 넣길 정말 잘했어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 34.496818, 126.625341, '2026-03-14T15:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002132', '54500700-0000-4000-8000-000000000088', 'p-tourapi-128594', '창녕 석리 성씨고가', '주말에 친구들이랑 창녕 석리 성씨고가 들렀는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "주말나들이"]'::jsonb, 35.556828, 128.459572, '2026-04-03T14:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002133', '54500700-0000-4000-8000-000000000156', 'p-tourapi-1310884', '고성장산리허씨고가', '비 오는 날 운치 찾아 고성장산리허씨고가 다녀왔어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 35.060351, 128.323950, '2026-02-17T23:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002134', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3544376', '강릉종합사회복지관', '기대 이상으로 너무 좋았던 강릉종합사회복지관! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "고즈넉"]'::jsonb, 37.764743, 128.916148, '2026-02-21T13:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002135', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2598297', '목재고택', 'SNS에서 사진 보고 찾아간 목재고택, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로", "온마루"]'::jsonb, 36.742903, 128.863861, '2026-01-28T21:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002136', '54500700-0000-4000-8000-000000000133', 'p-tourapi-3532720', '메모리스테이 효자', '근처 여행 코스로 메모리스테이 효자 넣길 정말 잘했어요. 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "가족여행", "사진맛집", "온마루"]'::jsonb, 37.582736, 126.971016, '2026-02-14T06:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002137', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2822429', '아산 외암마을 건재고택', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "인생샷", "가족여행"]'::jsonb, 36.730502, 127.016246, '2026-04-18T00:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002138', '54500700-0000-4000-8000-000000000096', 'p-tourapi-128177', '낭추골 현장체험학습원', '낭추골 현장체험학습원 다녀왔어요! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "데이트", "가족여행"]'::jsonb, 36.597880, 127.617904, '2026-01-15T11:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002139', '54500700-0000-4000-8000-000000000202', 'p-tourapi-2679990', '신라불교초전지', '해 질 무렵에 신라불교초전지 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.291071, 128.363252, '2026-02-01T15:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002140', '54500700-0000-4000-8000-000000000202', 'p-tourapi-4065913', '청원루', '대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "주말나들이"]'::jsonb, 36.579469, 128.548711, '2026-02-13T01:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002141', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2613459', '공주 중학동 구 선교사 가옥', '드라이브 겸 나들이로 공주 중학동 구 선교사 가옥 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 36.449491, 127.126458, '2026-02-22T04:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002142', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3354154', '삼포 만화북투어', '비 오는 날 운치 찾아 삼포 만화북투어 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링", "풍경맛집", "온마루"]'::jsonb, 37.481911, 126.621120, '2026-02-06T19:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002143', '54500700-0000-4000-8000-000000000192', 'p-tourapi-2684765', '강화 원도심 스토리워크', '평일 연차 쓰고 혼자 강화 원도심 스토리워크 다녀옴. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "사색", "힐링", "온마루"]'::jsonb, 37.748474, 126.486111, '2026-04-17T16:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002144', '54500700-0000-4000-8000-000000000102', 'p-tourapi-3351556', '서천문화예술창작공간', '천천히 골목 걷다가 마주친 서천문화예술창작공간. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["데이트", "가족여행", "인생샷"]'::jsonb, 36.008334, 126.695905, '2026-01-27T08:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002145', '54500700-0000-4000-8000-000000000157', 'p-tourapi-4093690', '삼호정', '천천히 골목 걷다가 마주친 삼호정. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["인생샷", "방문팁"]'::jsonb, 35.464644, 126.624894, '2026-01-25T20:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002146', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2572898', '고현당', '주말에 친구들이랑 고현당 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 35.815292, 127.153725, '2026-03-23T15:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002147', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2706047', '한옥 게스트하우스 동촌재', 'SNS에서 사진 보고 찾아간 한옥 게스트하우스 동촌재, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "사진맛집", "가족여행"]'::jsonb, 37.580111, 126.969855, '2026-01-20T23:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002148', '54500700-0000-4000-8000-000000000124', 'p-tourapi-129125', '서산 경주김씨 고택', '조용히 사색하고 싶어서 찾은 서산 경주김씨 고택. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "산책로"]'::jsonb, 36.741106, 126.519328, '2026-02-21T09:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002149', '54500700-0000-4000-8000-000000000157', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '주말에 친구들이랑 거창 갈계리 임씨고가 들렀는데 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 35.780200, 127.818700, '2026-04-02T13:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002150', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2638521', '영천 목재문화체험장', '드라이브 겸 나들이로 영천 목재문화체험장 선택했는데 대만족! 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "방문팁", "데이트"]'::jsonb, 36.142432, 128.978252, '2026-02-11T01:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002151', '54500700-0000-4000-8000-000000000139', 'p-tourapi-4104618', '함계정사', 'SNS에서 사진 보고 찾아간 함계정사, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["가족여행", "데이트"]'::jsonb, 36.047544, 128.977956, '2026-04-18T14:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002152', '54500700-0000-4000-8000-000000000154', 'p-tourapi-2854436', '옥천전통문화체험관', '천천히 골목 걷다가 마주친 옥천전통문화체험관. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 36.316731, 127.585462, '2026-02-24T01:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002153', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2751703', '달팽이', '부모님 모시고 달팽이 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.413979, 127.616603, '2026-03-12T13:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002154', '54500700-0000-4000-8000-000000000107', 'p-tourapi-128046', '여주 황포돛배', '기대 이상으로 너무 좋았던 여주 황포돛배! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["가족여행", "데이트"]'::jsonb, 37.293112, 127.666922, '2026-01-15T11:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002155', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1578659', '거창 갈계리 임씨고가', '기대 이상으로 너무 좋았던 거창 갈계리 임씨고가! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["인생샷", "방문팁", "데이트", "온마루"]'::jsonb, 35.780200, 127.818700, '2026-04-12T15:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002156', '54500700-0000-4000-8000-000000000068', 'p-tourapi-1872077', '석정댁', '비 오는 날 운치 찾아 석정댁 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "힐링", "온마루"]'::jsonb, 35.667053, 128.229073, '2026-02-03T13:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002157', '54500700-0000-4000-8000-000000000166', 'p-tourapi-1971911', '채원당', '평일 연차 쓰고 혼자 채원당 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "힐링"]'::jsonb, 35.275784, 127.307017, '2026-03-06T09:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002158', '54500700-0000-4000-8000-000000000124', 'p-tourapi-2820068', '누리마루숲', '부모님 모시고 누리마루숲 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "고즈넉", "사색", "온마루"]'::jsonb, 36.814667, 127.170408, '2026-04-12T23:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002159', '54500700-0000-4000-8000-000000000146', 'p-tourapi-3089931', '모영재', '드라이브 겸 나들이로 모영재 선택했는데 대만족! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 35.934271, 128.719016, '2026-01-10T21:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002160', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2946527', '리얼 이스케이프 챌린지', '기대 이상으로 너무 좋았던 리얼 이스케이프 챌린지! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "힐링", "고즈넉"]'::jsonb, 37.554205, 126.927115, '2026-04-07T02:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002161', '54500700-0000-4000-8000-000000000191', 'p-tourapi-2481866', '백인제가옥', '근처 여행 코스로 백인제가옥 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 37.580469, 126.984142, '2026-03-30T12:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002162', '54500700-0000-4000-8000-000000000080', 'p-tourapi-3508744', '주식회사더정원의뜰', '천천히 골목 걷다가 마주친 주식회사더정원의뜰. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["가족여행", "주말나들이", "방문팁"]'::jsonb, 37.628796, 127.209379, '2026-04-03T16:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002163', '54500700-0000-4000-8000-000000000073', 'p-tourapi-1393351', '연제 안승갑 고가', '기대 이상으로 너무 좋았던 연제 안승갑 고가! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 36.846161, 127.353328, '2026-04-01T18:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002164', '54500700-0000-4000-8000-000000000189', 'p-tourapi-3532770', '월하고택', '조용히 사색하고 싶어서 찾은 월하고택. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "풍경맛집", "산책로", "온마루"]'::jsonb, 37.719445, 127.313208, '2026-02-23T13:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002165', '54500700-0000-4000-8000-000000000148', 'p-tourapi-4012463', '검무한옥 휴복당', '조용히 사색하고 싶어서 찾은 검무한옥 휴복당. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 36.575421, 128.511679, '2026-03-23T10:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002166', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2662467', '만천하 알파인코스터', '만천하 알파인코스터 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 36.977675, 128.337071, '2026-02-10T11:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002167', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2789519', '황병산사냥민속놀이체험관', '근처 여행 코스로 황병산사냥민속놀이체험관 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["사색", "풍경맛집", "산책로"]'::jsonb, 37.707181, 128.687251, '2026-02-06T19:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002168', '54500700-0000-4000-8000-000000000061', 'p-tourapi-1600719', '정종수 고택', '기대 이상으로 너무 좋았던 정종수 고택! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 35.773895, 126.858535, '2026-04-02T23:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002169', '54500700-0000-4000-8000-000000000184', 'p-tourapi-3469943', '안동별장', '안동별장 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 36.566113, 128.716913, '2026-03-14T15:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002170', '54500700-0000-4000-8000-000000000170', 'p-tourapi-2777931', '생산소', '해 질 무렵에 생산소 방문했는데 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "고즈넉"]'::jsonb, 36.243697, 126.887802, '2026-02-21T00:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002171', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2000964', '향단', '날씨가 너무 맑아서 향단 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["데이트", "인생샷"]'::jsonb, 35.999890, 129.252940, '2026-04-10T02:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002172', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2820893', '평창사랑', '초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "산책로", "혼자여행", "온마루"]'::jsonb, 37.490534, 128.410696, '2026-02-07T07:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002173', '54500700-0000-4000-8000-000000000123', 'p-tourapi-231892', '안동 의성김씨 종택', '천천히 골목 걷다가 마주친 안동 의성김씨 종택. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "데이트", "온마루"]'::jsonb, 36.535846, 128.856287, '2026-03-30T06:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002174', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2610294', '문경 가은오픈세트장', '부모님 모시고 문경 가은오픈세트장 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 36.653951, 128.062182, '2026-02-06T20:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002175', '54500700-0000-4000-8000-000000000095', 'p-tourapi-662234', '순천전통야생차체험관', '조용히 사색하고 싶어서 찾은 순천전통야생차체험관. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 34.994895, 127.334076, '2026-02-26T01:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002176', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2604806', '목임당', '부모님 모시고 목임당 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 34.951854, 127.201749, '2026-02-06T18:08:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002177', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2686588', '오성한옥마을', '비 오는 날 운치 찾아 오성한옥마을 다녀왔어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["방문팁", "가족여행", "데이트"]'::jsonb, 35.903070, 127.243284, '2026-03-17T15:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002178', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2046122', '정강원 관광농원', '기대 이상으로 너무 좋았던 정강원 관광농원! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 37.570208, 128.408072, '2026-04-16T22:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002179', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3451224', '은계2어울림센터', '부모님 모시고 은계2어울림센터 산책 겸 다녀왔습니다. 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 37.435836, 126.797916, '2026-04-14T02:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002180', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2961964', '하정사색', '조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "사색", "산책로", "온마루"]'::jsonb, 35.408399, 127.382242, '2026-03-01T21:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002181', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2796968', '진주공예창작지원센터', '부모님 모시고 진주공예창작지원센터 산책 겸 다녀왔습니다. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁", "인생샷"]'::jsonb, 35.246714, 128.042587, '2026-01-26T03:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002182', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2569150', '서울이야기 한옥(서울이야기한옥게스트하우스)', '조용히 사색하고 싶어서 찾은 서울이야기 한옥(서울이야기한옥게스트하우스). 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 37.577006, 126.984604, '2026-02-02T17:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002183', '54500700-0000-4000-8000-000000000171', 'p-tourapi-2588636', '부안청림천문대', '천천히 골목 걷다가 마주친 부안청림천문대. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 35.657756, 126.615433, '2026-03-12T05:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002184', '54500700-0000-4000-8000-000000000177', 'p-tourapi-3454383', '이응노의 집 고암이응노생가기념관', '오랜만에 여유 찾으러 이응노의 집 고암이응노생가기념관 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "혼자여행", "사색"]'::jsonb, 36.623041, 126.632162, '2026-04-10T00:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002185', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2603884', '연당', '드라이브 겸 나들이로 연당 선택했는데 대만족! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "사색"]'::jsonb, 37.582603, 126.987073, '2026-02-14T02:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002186', '54500700-0000-4000-8000-000000000097', 'p-tourapi-1626843', '음성 공산정 고택', '근처 여행 코스로 음성 공산정 고택 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 37.077212, 127.638817, '2026-04-07T03:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002187', '54500700-0000-4000-8000-000000000150', 'p-tourapi-3438573', '자단', '오랜만에 여유 찾으러 자단 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "고즈넉", "온마루"]'::jsonb, 35.823741, 127.153289, '2026-01-14T03:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002188', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3438587', '빌라오', '해 질 무렵에 빌라오 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "혼자여행", "힐링", "온마루"]'::jsonb, 34.953237, 127.479852, '2026-01-07T01:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002189', '54500700-0000-4000-8000-000000000176', 'p-tourapi-1992090', '논산 명재고택', '해 질 무렵에 논산 명재고택 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["산책로", "사색", "고즈넉"]'::jsonb, 36.281869, 127.131209, '2026-02-15T05:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002190', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2996333', '모단아트(모단공예협동조합)', '평일 연차 쓰고 혼자 모단아트(모단공예협동조합) 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.227764, 128.879558, '2026-04-06T01:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002191', '54500700-0000-4000-8000-000000000197', 'p-tourapi-2531357', '경주한옥1번가', '오랜만에 여유 찾으러 경주한옥1번가 다녀왔습니다. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 35.825723, 129.213132, '2026-04-10T15:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002192', '54500700-0000-4000-8000-000000000121', 'p-tourapi-2050197', '어련당', '날씨가 너무 맑아서 어련당 한 바퀴 돌고 왔네요. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 35.574050, 129.350277, '2026-01-16T09:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002193', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3108226', '사단법인 푸른차문화연구원', '비 오는 날 운치 찾아 사단법인 푸른차문화연구원 다녀왔어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.835036, 128.677134, '2026-01-13T13:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002194', '54500700-0000-4000-8000-000000000205', 'p-tourapi-1997202', '여수 해상케이블카', '예전부터 가보고 싶었던 여수 해상케이블카 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "풍경맛집", "고즈넉"]'::jsonb, 34.730797, 127.739326, '2026-03-01T00:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002195', '54500700-0000-4000-8000-000000000167', 'p-tourapi-3438527', '한울타리', '한울타리 다녀왔어요! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 37.641464, 126.939292, '2026-04-14T09:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002196', '54500700-0000-4000-8000-000000000088', 'p-tourapi-2786845', '함양 일두고택', '근처 여행 코스로 함양 일두고택 넣길 정말 잘했어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.566271, 127.768523, '2026-02-22T20:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002197', '54500700-0000-4000-8000-000000000163', 'p-tourapi-2698914', '한옥펜션 나비의 꿈', '창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "사진맛집", "가족여행", "온마루"]'::jsonb, 35.608120, 126.585103, '2026-03-11T05:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002198', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3102033', '풍경의 아침', '해 질 무렵에 풍경의 아침 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "데이트", "가족여행"]'::jsonb, 35.387905, 126.884933, '2026-03-03T00:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002199', '54500700-0000-4000-8000-000000000134', 'p-tourapi-2603733', '중제고택', '근처 여행 코스로 중제고택 넣길 정말 잘했어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트", "방문팁", "온마루"]'::jsonb, 35.384903, 128.321367, '2026-04-09T19:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002200', '54500700-0000-4000-8000-000000000147', 'p-tourapi-1972012', '산에는 꽃이피네', '조용히 사색하고 싶어서 찾은 산에는 꽃이피네. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["풍경맛집", "힐링"]'::jsonb, 34.998671, 126.823311, '2026-02-21T01:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002201', '54500700-0000-4000-8000-000000000123', 'p-tourapi-3013816', '궁집', '오랜만에 여유 찾으러 궁집 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 37.644001, 127.230377, '2026-01-14T14:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002202', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2702472', '김종길 가옥', '오랜만에 여유 찾으러 김종길 가옥 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "산책로"]'::jsonb, 37.270826, 128.264199, '2026-02-09T06:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002203', '54500700-0000-4000-8000-000000000056', 'p-tourapi-3444338', '완정고택', '오랜만에 여유 찾으러 완정고택 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 36.004157, 128.234459, '2026-01-14T14:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002204', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2696312', '소담스테이', 'SNS에서 사진 보고 찾아간 소담스테이, 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.548039, 126.955990, '2026-03-15T15:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002205', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2668037', '월암종택(김호장군고택)', '천천히 골목 걷다가 마주친 월암종택(김호장군고택). 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "사진맛집"]'::jsonb, 35.819635, 129.218670, '2026-03-13T06:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002206', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2850183', '대한옥', '기대 이상으로 너무 좋았던 대한옥! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["주말나들이", "사진맛집", "방문팁", "온마루"]'::jsonb, 37.519414, 126.910895, '2026-01-18T20:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002207', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2782688', '와글아이', '오랜만에 여유 찾으러 와글아이 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.654185, 126.775751, '2026-02-15T20:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002208', '54500700-0000-4000-8000-000000000099', 'p-tourapi-129125', '서산 경주김씨 고택', '부모님 모시고 서산 경주김씨 고택 산책 겸 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 36.741106, 126.519328, '2026-01-29T16:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002209', '54500700-0000-4000-8000-000000000190', 'p-tourapi-3438381', '북촌다락방', '기대 이상으로 너무 좋았던 북촌다락방! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.582780, 126.983926, '2026-02-22T19:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002210', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3102203', '함라한옥체험단지', '비 오는 날 운치 찾아 함라한옥체험단지 다녀왔어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "인생샷", "온마루"]'::jsonb, 36.062774, 126.909874, '2026-04-14T12:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002211', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2604499', '보금자리', '예전부터 가보고 싶었던 보금자리 드디어 방문! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "사진맛집", "가족여행"]'::jsonb, 34.739876, 126.717749, '2026-04-01T08:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002212', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2775017', '주식회사 하늘', '오랜만에 여유 찾으러 주식회사 하늘 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "고즈넉", "산책로", "온마루"]'::jsonb, 35.304934, 126.546587, '2026-03-17T03:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002213', '54500700-0000-4000-8000-000000000200', 'p-tourapi-736751', '화성 정시영 고택', '근처 여행 코스로 화성 정시영 고택 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 37.133126, 126.700850, '2026-04-01T09:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002214', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2753977', '울진과학체험관', '주말에 친구들이랑 울진과학체험관 들렀는데 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.996618, 129.408077, '2026-03-01T09:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002215', '54500700-0000-4000-8000-000000000063', 'p-tourapi-3438579', '스테이 한울', '부모님 모시고 스테이 한울 산책 겸 다녀왔습니다. 창호지 문 사이로 부드럽게 스며드는 아침 햇살 덕분에 기분 좋게 하루를 시작할 수 있었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "풍경맛집"]'::jsonb, 35.812648, 127.152359, '2026-03-16T20:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002216', '54500700-0000-4000-8000-000000000109', 'p-tourapi-2939003', '영월애살으리랏다', '부모님 모시고 영월애살으리랏다 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "인생샷", "주말나들이", "온마루"]'::jsonb, 37.243614, 128.355684, '2026-02-01T05:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002217', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3072218', '오히', '오랜만에 여유 찾으러 오히 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 35.824170, 129.212582, '2026-01-06T04:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002218', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2753977', '울진과학체험관', '기대 이상으로 너무 좋았던 울진과학체험관! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "인생샷", "가족여행", "온마루"]'::jsonb, 36.996618, 129.408077, '2026-04-11T14:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002219', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3544074', '대한노인회 강릉시지회', '비 오는 날 운치 찾아 대한노인회 강릉시지회 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "사색"]'::jsonb, 37.747772, 128.884015, '2026-02-06T17:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002220', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2820629', '부여북포한옥마을', '예전부터 가보고 싶었던 부여북포한옥마을 드디어 방문! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 36.292906, 126.924516, '2026-02-26T02:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002221', '54500700-0000-4000-8000-000000000141', 'p-tourapi-3102073', '오원 스테이', '평일 연차 쓰고 혼자 오원 스테이 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["힐링", "산책로", "고즈넉"]'::jsonb, 35.836305, 129.208901, '2026-02-24T00:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002222', '54500700-0000-4000-8000-000000000082', 'p-tourapi-2569237', '운정루', '해 질 무렵에 운정루 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "가족여행", "데이트"]'::jsonb, 35.791283, 129.245897, '2026-03-15T01:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002223', '54500700-0000-4000-8000-000000000137', 'p-tourapi-2713395', '영월 북쌍리 고택', '비 오는 날 운치 찾아 영월 북쌍리 고택 다녀왔어요. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "인생샷", "주말나들이", "온마루"]'::jsonb, 37.205472, 128.377902, '2026-01-18T01:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002224', '54500700-0000-4000-8000-000000000094', 'p-tourapi-2569150', '서울이야기 한옥(서울이야기한옥게스트하우스)', '부모님 모시고 서울이야기 한옥(서울이야기한옥게스트하우스) 산책 겸 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["인생샷", "주말나들이", "방문팁", "온마루"]'::jsonb, 37.577006, 126.984604, '2026-03-21T16:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002225', '54500700-0000-4000-8000-000000000161', 'p-tourapi-231931', '논산명재고택', '드라이브 겸 나들이로 논산명재고택 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 36.281980, 127.131490, '2026-02-09T09:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002226', '54500700-0000-4000-8000-000000000200', 'p-tourapi-3438452', '담서제', '비 오는 날 운치 찾아 담서제 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉", "온마루"]'::jsonb, 37.640531, 126.939267, '2026-03-20T16:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002227', '54500700-0000-4000-8000-000000000077', 'p-tourapi-126419', '다산초당', '부모님 모시고 다산초당 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 34.580650, 126.745073, '2026-01-05T07:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002228', '54500700-0000-4000-8000-000000000089', 'p-tourapi-3533114', '스테이여유담', '조용히 사색하고 싶어서 찾은 스테이여유담. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.051415, 126.864112, '2026-02-22T22:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002229', '54500700-0000-4000-8000-000000000060', 'p-tourapi-127704', '창원 진해현 관아 및 객사유지', '근처 여행 코스로 창원 진해현 관아 및 객사유지 넣길 정말 잘했어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.114936, 128.488559, '2026-03-13T01:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002230', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2614384', '윤동주 유고보존 정병욱 가옥', '오랜만에 여유 찾으러 윤동주 유고보존 정병욱 가옥 다녀왔습니다. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "풍경맛집"]'::jsonb, 34.970753, 127.759167, '2026-01-12T19:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002231', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2647939', '고스락', '오랜만에 여유 찾으러 고스락 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 36.045904, 126.960681, '2026-01-12T19:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002232', '54500700-0000-4000-8000-000000000132', 'p-tourapi-3066280', '전주일몽', '날씨가 너무 맑아서 전주일몽 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "사진맛집", "온마루"]'::jsonb, 35.812079, 127.154722, '2026-02-24T15:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002233', '54500700-0000-4000-8000-000000000154', 'p-tourapi-3337761', '마마스홈퀴진', '오랜만에 여유 찾으러 마마스홈퀴진 다녀왔습니다. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집"]'::jsonb, 35.561501, 129.116689, '2026-02-07T06:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002234', '54500700-0000-4000-8000-000000000140', 'p-tourapi-3438590', '중정별채', '부모님 모시고 중정별채 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "데이트"]'::jsonb, 35.076940, 126.685755, '2026-03-17T19:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002235', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3072219', '북촌빈관 by 락고재', '주말에 친구들이랑 북촌빈관 by 락고재 들렀는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "인생샷", "데이트"]'::jsonb, 37.582347, 126.984220, '2026-02-23T22:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002236', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3469978', '호연담', '해 질 무렵에 호연담 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 37.910309, 127.741814, '2026-02-13T18:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002237', '54500700-0000-4000-8000-000000000065', 'p-tourapi-561914', '원주변씨 간재종택 및 간재정', '평일 연차 쓰고 혼자 원주변씨 간재종택 및 간재정 다녀옴. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["고즈넉", "사색", "풍경맛집"]'::jsonb, 36.601216, 128.677101, '2026-04-12T04:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002238', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2600221', '박정우가옥', '주말에 친구들이랑 박정우가옥 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["사진맛집", "데이트", "방문팁"]'::jsonb, 36.734650, 128.619780, '2026-04-08T18:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002239', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2587036', '백년한옥', '오랜만에 여유 찾으러 백년한옥 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 35.815953, 127.155314, '2026-04-11T07:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002240', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3438581', '교동94', '기대 이상으로 너무 좋았던 교동94! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 35.812687, 127.152503, '2026-02-08T02:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002241', '54500700-0000-4000-8000-000000000076', 'p-tourapi-264284', '전북 전주 한옥마을 [슬로시티]', '드라이브 겸 나들이로 전북 전주 한옥마을 [슬로시티] 선택했는데 대만족! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.818273, 127.153613, '2026-03-31T15:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002242', '54500700-0000-4000-8000-000000000205', 'p-tourapi-3351567', '충남안전체험관', '오랜만에 여유 찾으러 충남안전체험관 다녀왔습니다. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["혼자여행", "고즈넉", "힐링"]'::jsonb, 36.821766, 127.191892, '2026-02-10T20:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002243', '54500700-0000-4000-8000-000000000078', 'p-tourapi-3533114', '스테이여유담', '오랜만에 여유 찾으러 스테이여유담 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색", "산책로", "온마루"]'::jsonb, 35.051415, 126.864112, '2026-02-14T16:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002244', '54500700-0000-4000-8000-000000000110', 'p-tourapi-1964622', '스카이로드', '바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["인생샷", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.329147, 127.427818, '2026-01-08T12:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002245', '54500700-0000-4000-8000-000000000183', 'p-tourapi-3532598', '월하', '부모님 모시고 월하 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["인생샷", "방문팁", "주말나들이", "온마루"]'::jsonb, 35.848067, 129.207415, '2026-03-13T13:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002246', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2608081', '여락재', '드라이브 겸 나들이로 여락재 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "힐링", "혼자여행", "온마루"]'::jsonb, 34.740728, 126.718438, '2026-02-07T05:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002247', '54500700-0000-4000-8000-000000000144', 'p-tourapi-1883996', '취옹예술관', '예전부터 가보고 싶었던 취옹예술관 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "사색", "고즈넉", "온마루"]'::jsonb, 37.752549, 127.359939, '2026-01-27T02:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002248', '54500700-0000-4000-8000-000000000180', 'p-tourapi-2000946', '치암고택', '평일 연차 쓰고 혼자 치암고택 다녀옴. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "사색"]'::jsonb, 36.583250, 128.736044, '2026-01-31T04:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002249', '54500700-0000-4000-8000-000000000201', 'p-tourapi-1882853', '풍남헌', '비 오는 날 운치 찾아 풍남헌 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["데이트", "방문팁", "가족여행"]'::jsonb, 35.816784, 127.152314, '2026-02-26T07:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002250', '54500700-0000-4000-8000-000000000149', 'p-tourapi-3438452', '담서제', '오랜만에 여유 찾으러 담서제 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 37.640531, 126.939267, '2026-03-31T17:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002251', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3438433', '호우재 한옥', '호우재 한옥 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.595407, 126.999649, '2026-01-25T05:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002252', '54500700-0000-4000-8000-000000000112', 'p-tourapi-792208', '괴산 한지체험박물관', '괴산 한지체험박물관 다녀왔어요! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 36.785439, 128.014900, '2026-02-11T23:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002253', '54500700-0000-4000-8000-000000000082', 'p-tourapi-3533132', '시월재', '시월재 다녀왔어요! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 37.290068, 127.020289, '2026-01-06T10:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002254', '54500700-0000-4000-8000-000000000090', 'p-tourapi-2665817', '부여안방마님', '근처 여행 코스로 부여안방마님 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 36.265577, 126.848410, '2026-01-24T08:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002255', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2706608', '경주오릉한옥', '근처 여행 코스로 경주오릉한옥 넣길 정말 잘했어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "인생샷"]'::jsonb, 35.825828, 129.207499, '2026-03-03T18:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002256', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2775014', '나무키움(전의양묘영농조합법인)', '나무키움(전의양묘영농조합법인) 다녀왔어요! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "주말나들이", "사진맛집", "온마루"]'::jsonb, 36.676447, 127.197876, '2026-01-08T10:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002257', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2992824', '락고재 컬쳐 라운지 애가헌', 'SNS에서 사진 보고 찾아간 락고재 컬쳐 라운지 애가헌, 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "방문팁", "주말나들이"]'::jsonb, 37.582243, 126.983944, '2026-04-18T00:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002258', '54500700-0000-4000-8000-000000000086', 'p-tourapi-3438629', '아늑', 'SNS에서 사진 보고 찾아간 아늑, 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["주말나들이", "인생샷", "사진맛집", "온마루"]'::jsonb, 36.554223, 128.757179, '2026-02-08T13:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002259', '54500700-0000-4000-8000-000000000074', 'p-tourapi-2047715', '소강고택', '소강고택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 36.893692, 128.712359, '2026-01-30T03:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002260', '54500700-0000-4000-8000-000000000088', 'p-tourapi-3438589', '윤은재', '부모님 모시고 윤은재 산책 겸 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["산책로", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 35.033470, 126.712265, '2026-01-28T09:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002261', '54500700-0000-4000-8000-000000000065', 'p-tourapi-2594864', '남호구택', '평일 연차 쓰고 혼자 남호구택 다녀옴. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["힐링", "사색", "혼자여행"]'::jsonb, 36.893831, 128.712401, '2026-02-05T17:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002262', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2820659', '부여 선샤인', '비 오는 날 운치 찾아 부여 선샤인 다녀왔어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 36.274232, 126.887320, '2026-01-23T18:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002263', '54500700-0000-4000-8000-000000000169', 'p-tourapi-2940719', '예린당 바이 버틀러리', '해 질 무렵에 예린당 바이 버틀러리 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["산책로", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.578283, 126.970435, '2026-03-06T20:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002264', '54500700-0000-4000-8000-000000000144', 'p-tourapi-127274', '청주 신전동 고가', 'SNS에서 사진 보고 찾아간 청주 신전동 고가, 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "주말나들이", "사진맛집"]'::jsonb, 36.608893, 127.401963, '2026-01-31T00:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002265', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2000964', '향단', '오랜만에 여유 찾으러 향단 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집"]'::jsonb, 35.999890, 129.252940, '2026-02-28T03:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002266', '54500700-0000-4000-8000-000000000173', 'p-tourapi-2465890', '시은재', '비 오는 날 운치 찾아 시은재 다녀왔어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "온마루"]'::jsonb, 37.573704, 126.987248, '2026-02-21T01:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002267', '54500700-0000-4000-8000-000000000113', 'p-tourapi-2663065', '휴휴당', '기대 이상으로 너무 좋았던 휴휴당! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 35.835513, 129.212276, '2026-04-15T21:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002268', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2820027', '바른스포츠월드', '조용히 사색하고 싶어서 찾은 바른스포츠월드. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "풍경맛집", "산책로"]'::jsonb, 36.599193, 127.423099, '2026-02-14T08:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002269', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2650230', '문래예술공장', '오랜만에 여유 찾으러 문래예술공장 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["사색", "힐링", "온마루"]'::jsonb, 37.513281, 126.900160, '2026-02-12T13:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002270', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2786845', '함양 일두고택', '해 질 무렵에 함양 일두고택 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "인생샷", "데이트"]'::jsonb, 35.566271, 127.768523, '2026-03-07T20:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002271', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3067458', '맘맘스', '오랜만에 여유 찾으러 맘맘스 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링"]'::jsonb, 36.868427, 127.283246, '2026-02-05T02:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002272', '54500700-0000-4000-8000-000000000097', 'p-tourapi-125925', '아산 맹씨 행단(맹사성 고택)', '해 질 무렵에 아산 맹씨 행단(맹사성 고택) 방문했는데 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "방문팁"]'::jsonb, 36.747083, 127.041871, '2026-03-05T16:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002273', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3532711', '안스테이', 'SNS에서 사진 보고 찾아간 안스테이, 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "데이트", "온마루"]'::jsonb, 37.765344, 127.392716, '2026-03-14T13:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002274', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2775336', '와나스타', '기대 이상으로 너무 좋았던 와나스타! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "힐링", "온마루"]'::jsonb, 35.540251, 129.167227, '2026-03-12T08:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002275', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3543415', '주문진문화교육센터', '근처 여행 코스로 주문진문화교육센터 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "힐링", "고즈넉", "온마루"]'::jsonb, 37.881902, 128.822300, '2026-03-18T19:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002276', '54500700-0000-4000-8000-000000000159', 'p-tourapi-2722927', '대전트래블라운지', '날씨가 너무 맑아서 대전트래블라운지 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "사색"]'::jsonb, 36.330510, 127.430001, '2026-03-22T10:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002277', '54500700-0000-4000-8000-000000000115', 'p-tourapi-2569165', '수곡고택', '예전부터 가보고 싶었던 수곡고택 드디어 방문! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["사진맛집", "인생샷", "주말나들이", "온마루"]'::jsonb, 36.574103, 128.526316, '2026-04-05T16:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002278', '54500700-0000-4000-8000-000000000068', 'p-tourapi-1971880', '좋은날', '비 오는 날 운치 찾아 좋은날 다녀왔어요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.817283, 127.149292, '2026-01-31T13:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002279', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3438041', '유선재', '유선재 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "고즈넉", "풍경맛집", "온마루"]'::jsonb, 37.490512, 127.709293, '2026-03-06T01:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002280', '54500700-0000-4000-8000-000000000127', 'p-tourapi-2714276', '말문화체험관', '가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "데이트", "인생샷", "온마루"]'::jsonb, 36.030748, 128.998570, '2026-03-13T02:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002281', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3454469', '아동청소년친화공간 꿈이랑', '비 오는 날 운치 찾아 아동청소년친화공간 꿈이랑 다녀왔어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "산책로", "고즈넉", "온마루"]'::jsonb, 38.199574, 128.580209, '2026-03-01T04:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002282', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2570188', '청풍헌(시랑골한옥스테이)', '비 오는 날 운치 찾아 청풍헌(시랑골한옥스테이) 다녀왔어요. 현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "인생샷", "사진맛집"]'::jsonb, 35.979639, 127.233292, '2026-01-22T23:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002283', '54500700-0000-4000-8000-000000000165', 'p-tourapi-2788137', '화사별서(조씨고가)', '기대 이상으로 너무 좋았던 화사별서(조씨고가)! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["사진맛집", "인생샷", "방문팁"]'::jsonb, 35.171341, 127.700944, '2026-03-28T21:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002284', '54500700-0000-4000-8000-000000000138', 'p-tourapi-895327', '남도한옥민박마을', '아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "산책로", "온마루"]'::jsonb, 34.509319, 126.605754, '2026-04-02T07:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002285', '54500700-0000-4000-8000-000000000085', 'p-tourapi-3438225', '자하', '천천히 골목 걷다가 마주친 자하. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "가족여행", "방문팁", "온마루"]'::jsonb, 37.576689, 126.971160, '2026-03-23T16:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002286', '54500700-0000-4000-8000-000000000087', 'p-tourapi-3072227', '아담한옥', 'SNS에서 사진 보고 찾아간 아담한옥, 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["방문팁", "주말나들이", "가족여행"]'::jsonb, 37.580389, 126.969677, '2026-02-14T12:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002287', '54500700-0000-4000-8000-000000000129', 'p-tourapi-2594218', '정가한옥', '오랜만에 여유 찾으러 정가한옥 다녀왔습니다. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.816289, 127.155113, '2026-03-17T19:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002288', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2768086', '한양 한옥마을점', '근처 여행 코스로 한양 한옥마을점 넣길 정말 잘했어요. 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이", "데이트", "온마루"]'::jsonb, 37.390854, 126.638901, '2026-03-23T09:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002289', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2795956', '양평 창대리 고가', '해 질 무렵에 양평 창대리 고가 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "가족여행", "사진맛집"]'::jsonb, 37.471103, 127.505915, '2026-03-06T07:07:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002290', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2992823', 'K-컬처 스크린(대한민국역사박물관)', '근처 여행 코스로 K-컬처 스크린(대한민국역사박물관) 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "고즈넉", "혼자여행"]'::jsonb, 37.574134, 126.977574, '2026-03-28T15:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002291', '54500700-0000-4000-8000-000000000156', 'p-tourapi-3582821', '한복남 프리미엄점', '예전부터 가보고 싶었던 한복남 프리미엄점 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "데이트", "온마루"]'::jsonb, 37.576404, 126.973230, '2026-03-14T03:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002292', '54500700-0000-4000-8000-000000000112', 'p-tourapi-1923400', '백두대간협곡열차(V-트레인)', '선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "혼자여행", "산책로"]'::jsonb, 37.113109, 129.036710, '2026-03-15T21:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002293', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', '기대 이상으로 너무 좋았던 국가유산 방문 캠페인 인천공항 홍보관! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "가족여행", "사진맛집", "온마루"]'::jsonb, 37.447703, 126.452175, '2026-02-24T17:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002294', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2595862', '온계종택 삼백당', '온계종택 삼백당 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "혼자여행", "풍경맛집"]'::jsonb, 36.749711, 128.830079, '2026-03-30T17:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002295', '54500700-0000-4000-8000-000000000163', 'p-tourapi-1171915', '조선왕가', '천천히 골목 걷다가 마주친 조선왕가. 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 38.063643, 127.101473, '2026-01-29T23:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002296', '54500700-0000-4000-8000-000000000111', 'p-tourapi-1884345', '행복드림한옥', '해 질 무렵에 행복드림한옥 방문했는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "가족여행", "사진맛집", "온마루"]'::jsonb, 35.905472, 127.209637, '2026-01-08T07:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002297', '54500700-0000-4000-8000-000000000182', 'p-tourapi-2576546', '홍시(전주한옥마을 숙박 홍시)', '천천히 골목 걷다가 마주친 홍시(전주한옥마을 숙박 홍시). 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 2, '["방문팁", "주말나들이", "데이트"]'::jsonb, 35.815306, 127.153014, '2026-04-01T02:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002298', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2680818', '산수유사랑채', '주말에 친구들이랑 산수유사랑채 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["사진맛집", "가족여행"]'::jsonb, 37.340776, 127.462296, '2026-01-21T09:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002299', '54500700-0000-4000-8000-000000000118', 'p-tourapi-3483083', '간송옛집', '천천히 골목 걷다가 마주친 간송옛집. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "사진맛집", "데이트"]'::jsonb, 37.664893, 127.028187, '2026-01-09T14:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002300', '54500700-0000-4000-8000-000000000059', 'p-tourapi-3072240', '온유헌 바이 버틀러리', '날씨가 너무 맑아서 온유헌 바이 버틀러리 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "혼자여행", "온마루"]'::jsonb, 37.581611, 126.987489, '2026-04-04T11:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002301', '54500700-0000-4000-8000-000000000094', 'p-tourapi-1201060', '이천보고가', '주말에 친구들이랑 이천보고가 들렀는데 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "가족여행"]'::jsonb, 37.798653, 127.348090, '2026-02-08T07:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002302', '54500700-0000-4000-8000-000000000110', 'p-tourapi-3076943', '벽파정', '천천히 골목 걷다가 마주친 벽파정. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["방문팁", "주말나들이"]'::jsonb, 34.538258, 126.344790, '2026-02-13T14:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002303', '54500700-0000-4000-8000-000000000077', 'p-tourapi-2000725', '안동 수애당', '날씨가 너무 맑아서 안동 수애당 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "사색", "혼자여행"]'::jsonb, 36.553329, 128.923380, '2026-02-01T10:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002304', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2531675', '진도한옥펜션', 'SNS에서 사진 보고 찾아간 진도한옥펜션, 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 34.398482, 126.277327, '2026-01-29T02:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002305', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2572792', '매죽헌(매죽헌 한옥 민박)', '날씨가 너무 맑아서 매죽헌(매죽헌 한옥 민박) 한 바퀴 돌고 왔네요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "데이트", "사진맛집"]'::jsonb, 35.066003, 127.404253, '2026-01-07T21:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002306', '54500700-0000-4000-8000-000000000071', 'p-tourapi-2568571', '1928 쉼마루', '주말에 친구들이랑 1928 쉼마루 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.811859, 127.152536, '2026-04-11T05:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002307', '54500700-0000-4000-8000-000000000125', 'p-tourapi-2604602', '경주 교동한옥집', '평일 연차 쓰고 혼자 경주 교동한옥집 다녀옴. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "힐링", "사색", "온마루"]'::jsonb, 35.828919, 129.211782, '2026-01-26T17:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002308', '54500700-0000-4000-8000-000000000126', 'p-tourapi-800971', '순창 거북장수마을 [농촌전통테마]', '날씨가 너무 맑아서 순창 거북장수마을 [농촌전통테마] 한 바퀴 돌고 왔네요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "사진맛집"]'::jsonb, 35.443771, 127.211540, '2026-04-17T10:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002309', '54500700-0000-4000-8000-000000000159', 'p-tourapi-3455504', '용인특례시 가상현실스포츠체험센터', '드라이브 겸 나들이로 용인특례시 가상현실스포츠체험센터 선택했는데 대만족! 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "가족여행", "사진맛집", "온마루"]'::jsonb, 37.238601, 127.180554, '2026-01-31T12:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002310', '54500700-0000-4000-8000-000000000174', 'p-tourapi-3438166', '뉠스테이', '부모님 모시고 뉠스테이 산책 겸 다녀왔습니다. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집"]'::jsonb, 37.579350, 126.967738, '2026-04-05T02:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002311', '54500700-0000-4000-8000-000000000155', 'p-tourapi-3510160', '주식회사꽃초린두레', '기대 이상으로 너무 좋았던 주식회사꽃초린두레! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "풍경맛집", "사색"]'::jsonb, 35.348560, 128.322537, '2026-01-16T21:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002312', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3089931', '모영재', '기대 이상으로 너무 좋았던 모영재! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["가족여행", "주말나들이", "온마루"]'::jsonb, 35.934271, 128.719016, '2026-03-25T05:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002313', '54500700-0000-4000-8000-000000000194', 'p-tourapi-1578659', '거창 갈계리 임씨고가', 'SNS에서 사진 보고 찾아간 거창 갈계리 임씨고가, 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["산책로", "사색", "온마루"]'::jsonb, 35.780200, 127.818700, '2026-03-19T06:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002314', '54500700-0000-4000-8000-000000000186', 'p-tourapi-2593271', '가은채', '오랜만에 여유 찾으러 가은채 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행"]'::jsonb, 35.817064, 127.153292, '2026-01-18T22:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002315', '54500700-0000-4000-8000-000000000199', 'p-tourapi-3469822', '대동고택', '주말에 친구들이랑 대동고택 들렀는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "주말나들이", "방문팁"]'::jsonb, 35.821574, 127.136349, '2026-03-23T13:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002316', '54500700-0000-4000-8000-000000000107', 'p-tourapi-1998844', '춘우재고택', '춘우재고택 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트", "주말나들이"]'::jsonb, 36.706350, 128.441275, '2026-02-05T17:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002317', '54500700-0000-4000-8000-000000000121', 'p-tourapi-3438435', '사임당 귀한그대', '드라이브 겸 나들이로 사임당 귀한그대 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["힐링", "사색", "온마루"]'::jsonb, 37.641234, 126.940136, '2026-02-11T02:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002318', '54500700-0000-4000-8000-000000000165', 'p-tourapi-3511071', '주식회사피알아이피', '비 오는 날 운치 찾아 주식회사피알아이피 다녀왔어요. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 2, '["주말나들이", "방문팁"]'::jsonb, 35.142914, 129.108355, '2026-04-01T14:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002319', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2782688', '와글아이', '천천히 골목 걷다가 마주친 와글아이. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["데이트", "방문팁"]'::jsonb, 37.654185, 126.775751, '2026-01-13T10:58:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002320', '54500700-0000-4000-8000-000000000184', 'p-tourapi-2593643', '목향재', '근처 여행 코스로 목향재 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "사진맛집", "주말나들이", "온마루"]'::jsonb, 36.501928, 127.239881, '2026-04-08T10:01:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002321', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2627867', '가람나무', '해 질 무렵에 가람나무 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉", "온마루"]'::jsonb, 37.754749, 126.689195, '2026-01-23T22:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002322', '54500700-0000-4000-8000-000000000170', 'p-tourapi-3532757', '곰곰하우스', '부모님 모시고 곰곰하우스 산책 겸 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "산책로", "혼자여행", "온마루"]'::jsonb, 37.581397, 126.986473, '2026-03-02T15:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002323', '54500700-0000-4000-8000-000000000167', 'p-tourapi-2627867', '가람나무', '조용히 사색하고 싶어서 찾은 가람나무. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "산책로", "혼자여행"]'::jsonb, 37.754749, 126.689195, '2026-03-19T07:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002324', '54500700-0000-4000-8000-000000000124', 'p-tourapi-1872349', '순천만 해룡성고택', '순천만 해룡성고택 다녀왔어요! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["인생샷", "데이트", "가족여행", "온마루"]'::jsonb, 34.919947, 127.502479, '2026-02-18T18:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002325', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1882210', '얼음골한옥펜션', '근처 여행 코스로 얼음골한옥펜션 넣길 정말 잘했어요. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["주말나들이", "사진맛집"]'::jsonb, 35.598251, 128.953272, '2026-03-02T15:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002326', '54500700-0000-4000-8000-000000000178', 'p-tourapi-2746709', '파주팜랜드', '비 오는 날 운치 찾아 파주팜랜드 다녀왔어요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "온마루"]'::jsonb, 37.810093, 126.692393, '2026-01-19T11:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002327', '54500700-0000-4000-8000-000000000073', 'p-tourapi-3469889', '석주재', '근처 여행 코스로 석주재 넣길 정말 잘했어요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "주말나들이", "인생샷"]'::jsonb, 35.510612, 128.837726, '2026-02-18T03:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002328', '54500700-0000-4000-8000-000000000172', 'p-tourapi-129517', '예천 예천권씨 초간공파 종택 및 예천권씨 초간종택 별당', '날씨가 너무 맑아서 예천 예천권씨 초간공파 종택 및 예천권씨 초간종택 별당 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "데이트"]'::jsonb, 36.692325, 128.397743, '2026-02-01T08:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002329', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3531662', '최선평 가옥', '조용히 사색하고 싶어서 찾은 최선평 가옥. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "힐링", "풍경맛집"]'::jsonb, 37.878304, 128.795960, '2026-02-28T04:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002330', '54500700-0000-4000-8000-000000000117', 'p-tourapi-2782543', '보성 이진래고택', '근처 여행 코스로 보성 이진래고택 넣길 정말 잘했어요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "인생샷", "데이트"]'::jsonb, 34.762787, 127.186655, '2026-03-30T21:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002331', '54500700-0000-4000-8000-000000000135', 'p-tourapi-2778518', '주포지구한옥전원마을', '조용히 사색하고 싶어서 찾은 주포지구한옥전원마을. 직접 손으로 만져보고 만들어보는 전통 공예 체험이 생각보다 훨씬 뜻깊고 기억에 오래 남습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.091951, 126.461197, '2026-03-12T14:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002332', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2613676', '전주한옥숙박 사랑루', '근처 여행 코스로 전주한옥숙박 사랑루 넣길 정말 잘했어요. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 35.811490, 127.154097, '2026-03-01T13:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002333', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2786859', '읍청정(산청)', '읍청정(산청) 다녀왔어요! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '한적', 1, '["힐링", "혼자여행"]'::jsonb, 35.308869, 127.965517, '2026-02-25T17:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002334', '54500700-0000-4000-8000-000000000070', 'p-tourapi-128559', '농암종택', '날씨가 너무 맑아서 농암종택 한 바퀴 돌고 왔네요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "힐링", "혼자여행"]'::jsonb, 36.763763, 128.885061, '2026-01-11T07:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002335', '54500700-0000-4000-8000-000000000059', 'p-tourapi-250364', '문화역 서울 284', '주말에 친구들이랑 문화역 서울 284 들렀는데 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 37.556011, 126.971625, '2026-04-09T20:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002336', '54500700-0000-4000-8000-000000000189', 'p-tourapi-2774723', '니지모리 스튜디오', '니지모리 스튜디오 다녀왔어요! 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "주말나들이"]'::jsonb, 37.879620, 127.092404, '2026-03-20T03:21:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002337', '54500700-0000-4000-8000-000000000127', 'p-tourapi-1583188', '조해영가옥', '평일 연차 쓰고 혼자 조해영가옥 다녀옴. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 36.061040, 126.910882, '2026-03-15T15:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002338', '54500700-0000-4000-8000-000000000169', 'p-tourapi-802566', '광주 산두른마을', '기대 이상으로 너무 좋았던 광주 산두른마을! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 37.279260, 127.291373, '2026-01-05T11:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002339', '54500700-0000-4000-8000-000000000091', 'p-tourapi-2994636', '다담한옥', '기대 이상으로 너무 좋았던 다담한옥! 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "사색", "풍경맛집"]'::jsonb, 35.588333, 129.059829, '2026-03-04T15:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002340', '54500700-0000-4000-8000-000000000074', 'p-tourapi-3533131', '안동한옥스테이휴', '평일 연차 쓰고 혼자 안동한옥스테이휴 다녀옴. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 36.560241, 128.712044, '2026-01-30T00:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002341', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2775365', '바다공룡 워케이션', '천천히 골목 걷다가 마주친 바다공룡 워케이션. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "풍경맛집"]'::jsonb, 35.016750, 128.297998, '2026-01-13T04:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002342', '54500700-0000-4000-8000-000000000164', 'p-tourapi-3533113', '금천재', '비 오는 날 운치 찾아 금천재 다녀왔어요. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["방문팁", "사진맛집"]'::jsonb, 35.032699, 126.755180, '2026-02-15T00:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002343', '54500700-0000-4000-8000-000000000081', 'p-tourapi-3438622', '스테이 나스러움', '현대식 편의시설과 전통 한옥의 멋이 절묘하게 조화되어 있어서 머무는 내내 너무 편안했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 36.563329, 128.713671, '2026-03-22T00:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002344', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3102104', '도담헌', 'SNS에서 사진 보고 찾아간 도담헌, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "혼자여행"]'::jsonb, 34.945463, 127.483899, '2026-03-26T19:55:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002345', '54500700-0000-4000-8000-000000000103', 'p-tourapi-2932973', '다올재', '기대 이상으로 너무 좋았던 다올재! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 34.955084, 127.480693, '2026-02-27T11:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002346', '54500700-0000-4000-8000-000000000139', 'p-tourapi-2900858', '제천비행장', '예전부터 가보고 싶었던 제천비행장 드디어 방문! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 37.162851, 128.213624, '2026-04-01T03:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002347', '54500700-0000-4000-8000-000000000178', 'p-tourapi-127223', '남성재', '천천히 골목 걷다가 마주친 남성재. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 35.973592, 129.352974, '2026-03-24T20:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002348', '54500700-0000-4000-8000-000000000192', 'p-tourapi-250372', '의성김씨 학봉종택', '의성김씨 학봉종택 다녀왔어요! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집"]'::jsonb, 36.609676, 128.669221, '2026-01-09T01:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002349', '54500700-0000-4000-8000-000000000179', 'p-tourapi-2531357', '경주한옥1번가', '날씨가 너무 맑아서 경주한옥1번가 한 바퀴 돌고 왔네요. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색", "고즈넉"]'::jsonb, 35.825723, 129.213132, '2026-02-21T11:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002350', '54500700-0000-4000-8000-000000000085', 'p-tourapi-2668037', '월암종택(김호장군고택)', '오랜만에 여유 찾으러 월암종택(김호장군고택) 다녀왔습니다. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["고즈넉", "풍경맛집", "힐링", "온마루"]'::jsonb, 35.819635, 129.218670, '2026-01-31T15:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002351', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2373420', '아띠인력거', '천천히 골목 걷다가 마주친 아띠인력거. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "인생샷"]'::jsonb, 37.579389, 126.982559, '2026-01-09T09:28:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002352', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2804370', '화담재', '부모님 모시고 화담재 산책 겸 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "주말나들이", "온마루"]'::jsonb, 34.739037, 126.716758, '2026-01-28T12:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002353', '54500700-0000-4000-8000-000000000126', 'p-tourapi-2817792', '밀알영농조합', '밀알영농조합 다녀왔어요! 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 2, '["인생샷", "방문팁"]'::jsonb, 35.081710, 128.185789, '2026-03-23T10:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002354', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2681174', '고선재', '조용히 사색하고 싶어서 찾은 고선재. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "힐링", "고즈넉"]'::jsonb, 36.566131, 127.517847, '2026-01-05T05:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002355', '54500700-0000-4000-8000-000000000100', 'p-tourapi-2996825', '애플트리 힐링팜', '기대 이상으로 너무 좋았던 애플트리 힐링팜! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 35.557187, 127.099039, '2026-01-13T17:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002356', '54500700-0000-4000-8000-000000000062', 'p-tourapi-2660696', '세연재', '드라이브 겸 나들이로 세연재 선택했는데 대만족! 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "혼자여행", "풍경맛집"]'::jsonb, 37.640328, 126.939534, '2026-01-21T22:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002357', '54500700-0000-4000-8000-000000000068', 'p-tourapi-2932894', '주월재', '조용히 사색하고 싶어서 찾은 주월재. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 34.779345, 127.167378, '2026-03-02T06:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002358', '54500700-0000-4000-8000-000000000140', 'p-tourapi-231933', '경주 양동 무첨당', '평일 연차 쓰고 혼자 경주 양동 무첨당 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "힐링"]'::jsonb, 36.002020, 129.252657, '2026-03-14T21:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002359', '54500700-0000-4000-8000-000000000131', 'p-tourapi-1566740', '양평 맑은숲캠프', '비 오는 날 운치 찾아 양평 맑은숲캠프 다녀왔어요. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "힐링", "혼자여행"]'::jsonb, 37.562041, 127.734400, '2026-03-22T00:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002360', '54500700-0000-4000-8000-000000000132', 'p-tourapi-3425093', '서울 인디스페이스', '드라이브 겸 나들이로 서울 인디스페이스 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "방문팁", "온마루"]'::jsonb, 37.557285, 126.925012, '2026-02-11T18:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002361', '54500700-0000-4000-8000-000000000118', 'p-tourapi-1846830', '남도해양열차 에스트레인(S-train)', '기대 이상으로 너무 좋았던 남도해양열차 에스트레인(S-train)! 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "힐링", "혼자여행"]'::jsonb, 35.115272, 129.042433, '2026-01-20T03:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002362', '54500700-0000-4000-8000-000000000193', 'p-tourapi-2049307', '녹운재', 'SNS에서 사진 보고 찾아간 녹운재, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "고즈넉", "풍경맛집"]'::jsonb, 35.902864, 127.242582, '2026-04-13T18:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002363', '54500700-0000-4000-8000-000000000192', 'p-tourapi-1883590', '옥연정사', '해 질 무렵에 옥연정사 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 2, '["데이트", "인생샷", "온마루"]'::jsonb, 36.543375, 128.518006, '2026-01-10T18:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002364', '54500700-0000-4000-8000-000000000106', 'p-tourapi-2775336', '와나스타', '주말에 친구들이랑 와나스타 들렀는데 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 2, '["인생샷", "주말나들이", "가족여행", "온마루"]'::jsonb, 35.540251, 129.167227, '2026-01-08T02:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002365', '54500700-0000-4000-8000-000000000057', 'p-tourapi-2606219', '영천전투메모리얼파크', '영천전투메모리얼파크 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["사진맛집", "가족여행", "방문팁"]'::jsonb, 35.973412, 128.926969, '2026-01-19T15:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002366', '54500700-0000-4000-8000-000000000057', 'p-tourapi-3438225', '자하', '드라이브 겸 나들이로 자하 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "인생샷"]'::jsonb, 37.576689, 126.971160, '2026-03-31T23:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002367', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2570532', '한옥미담(전주한옥마을 한옥미담)', '비 오는 날 운치 찾아 한옥미담(전주한옥마을 한옥미담) 다녀왔어요. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "고즈넉", "산책로", "온마루"]'::jsonb, 35.819325, 127.150592, '2026-03-18T16:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002368', '54500700-0000-4000-8000-000000000203', 'p-tourapi-1590555', '이웅재고가', '해 질 무렵에 이웅재고가 방문했는데 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "혼자여행", "사색", "온마루"]'::jsonb, 35.504611, 127.316658, '2026-02-21T16:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002369', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1620863', '양금석가옥', 'SNS에서 사진 보고 찾아간 양금석가옥, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "인생샷"]'::jsonb, 33.291311, 126.628597, '2026-01-22T02:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002370', '54500700-0000-4000-8000-000000000130', 'p-tourapi-3072271', '청담', '평일 연차 쓰고 혼자 청담 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "힐링", "온마루"]'::jsonb, 36.455874, 127.120608, '2026-04-07T22:23:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002371', '54500700-0000-4000-8000-000000000133', 'p-tourapi-2576371', '월출산 달빛정원', 'SNS에서 사진 보고 찾아간 월출산 달빛정원, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 34.770838, 126.653762, '2026-02-08T10:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002372', '54500700-0000-4000-8000-000000000172', 'p-tourapi-1623828', '안동권씨유회당종가일원', '날씨가 너무 맑아서 안동권씨유회당종가일원 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 36.277697, 127.404793, '2026-02-17T02:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002373', '54500700-0000-4000-8000-000000000098', 'p-tourapi-2607787', '꿈', '해 질 무렵에 꿈 방문했는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["고즈넉", "산책로", "사색"]'::jsonb, 35.812584, 127.154325, '2026-02-11T17:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002374', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2409490', '만회고택', '예전부터 가보고 싶었던 만회고택 드디어 방문! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "산책로", "온마루"]'::jsonb, 36.897302, 128.715223, '2026-01-31T00:50:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002375', '54500700-0000-4000-8000-000000000061', 'p-tourapi-3532743', '아늑한가 서울한옥 스테이 풀빌라 스파펜션', '비 오는 날 운치 찾아 아늑한가 서울한옥 스테이 풀빌라 스파펜션 다녀왔어요. 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 2, '["방문팁", "데이트", "사진맛집", "온마루"]'::jsonb, 37.693766, 127.043939, '2026-04-13T15:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002376', '54500700-0000-4000-8000-000000000194', 'p-tourapi-2786845', '함양 일두고택', '근처 여행 코스로 함양 일두고택 넣길 정말 잘했어요. 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "힐링", "고즈넉"]'::jsonb, 35.566271, 127.768523, '2026-01-11T07:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002377', '54500700-0000-4000-8000-000000000114', 'p-tourapi-2775365', '바다공룡 워케이션', '주말에 친구들이랑 바다공룡 워케이션 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "사색"]'::jsonb, 35.016750, 128.297998, '2026-04-11T09:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002378', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2680818', '산수유사랑채', '오랜만에 여유 찾으러 산수유사랑채 다녀왔습니다. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.340776, 127.462296, '2026-03-17T09:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002379', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2713848', '수상한마법학교', '천천히 골목 걷다가 마주친 수상한마법학교. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.730501, 128.879166, '2026-04-14T14:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002380', '54500700-0000-4000-8000-000000000122', 'p-tourapi-231909', '안동 예안이씨 충효당', '날씨가 너무 맑아서 안동 예안이씨 충효당 한 바퀴 돌고 왔네요. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "사색", "온마루"]'::jsonb, 36.574451, 128.580208, '2026-01-07T11:09:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002381', '54500700-0000-4000-8000-000000000065', 'p-tourapi-1992717', '의성 소우당', '예전부터 가보고 싶었던 의성 소우당 드디어 방문! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 36.245624, 128.701551, '2026-02-25T09:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002382', '54500700-0000-4000-8000-000000000205', 'p-tourapi-2638521', '영천 목재문화체험장', '부모님 모시고 영천 목재문화체험장 산책 겸 다녀왔습니다. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 36.142432, 128.978252, '2026-02-20T07:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002383', '54500700-0000-4000-8000-000000000097', 'p-tourapi-3354017', '술작가 양조장', '부모님 모시고 술작가 양조장 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["풍경맛집", "고즈넉"]'::jsonb, 37.473367, 126.641335, '2026-02-15T06:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002384', '54500700-0000-4000-8000-000000000095', 'p-tourapi-2606219', '영천전투메모리얼파크', '부모님 모시고 영천전투메모리얼파크 산책 겸 다녀왔습니다. 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "온마루"]'::jsonb, 35.973412, 128.926969, '2026-02-19T00:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002385', '54500700-0000-4000-8000-000000000179', 'p-tourapi-3438724', '소월정', '소월정 다녀왔어요! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.583277, 126.986492, '2026-01-31T14:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002386', '54500700-0000-4000-8000-000000000076', 'p-tourapi-1877312', '양소당', 'SNS에서 사진 보고 찾아간 양소당, 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["사진맛집", "인생샷", "온마루"]'::jsonb, 36.580236, 128.546811, '2026-01-08T17:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002387', '54500700-0000-4000-8000-000000000189', 'p-tourapi-1245865', '심산기념문화센터', '비 오는 날 운치 찾아 심산기념문화센터 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "사색"]'::jsonb, 37.498535, 126.990730, '2026-04-11T08:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002388', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3453420', '황촌마을활력소', '조용히 사색하고 싶어서 찾은 황촌마을활력소. 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "고즈넉", "온마루"]'::jsonb, 35.845001, 129.220908, '2026-01-30T14:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002389', '54500700-0000-4000-8000-000000000108', 'p-tourapi-3529694', '서울아리', '기대 이상으로 너무 좋았던 서울아리! 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "고즈넉", "힐링", "온마루"]'::jsonb, 37.576723, 126.991345, '2026-02-22T20:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002390', '54500700-0000-4000-8000-000000000080', 'p-tourapi-2782667', '김대기가옥', '주말에 친구들이랑 김대기가옥 들렀는데 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "인생샷", "온마루"]'::jsonb, 36.692685, 128.410225, '2026-01-12T03:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002391', '54500700-0000-4000-8000-000000000118', 'p-tourapi-2743315', '의왕도깨비도로', '해 질 무렵에 의왕도깨비도로 방문했는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["힐링", "풍경맛집", "고즈넉", "온마루"]'::jsonb, 37.394053, 127.027516, '2026-02-08T16:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002392', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2657848', '한국트로트가요센터', 'SNS에서 사진 보고 찾아간 한국트로트가요센터, 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 34.791589, 126.685354, '2026-01-22T01:32:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002393', '54500700-0000-4000-8000-000000000087', 'p-tourapi-2996855', '버금상점', '기대 이상으로 너무 좋았던 버금상점! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "데이트"]'::jsonb, 34.972636, 128.323866, '2026-01-14T01:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002394', '54500700-0000-4000-8000-000000000059', 'p-tourapi-2594831', '양참사댁(양동호 가옥 / 한옥152)', '천천히 골목 걷다가 마주친 양참사댁(양동호 가옥 / 한옥152). 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "힐링", "온마루"]'::jsonb, 34.984345, 126.911408, '2026-04-16T02:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002395', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2357469', '훈몽재 유지', '부모님 모시고 훈몽재 유지 산책 겸 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 35.472605, 126.968424, '2026-03-14T20:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002396', '54500700-0000-4000-8000-000000000063', 'p-tourapi-128177', '낭추골 현장체험학습원', '드라이브 겸 나들이로 낭추골 현장체험학습원 선택했는데 대만족! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["사진맛집", "방문팁", "주말나들이"]'::jsonb, 36.597880, 127.617904, '2026-01-05T17:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002397', '54500700-0000-4000-8000-000000000148', 'p-tourapi-2819607', '드로잉라이프', 'SNS에서 사진 보고 찾아간 드로잉라이프, 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["가족여행", "데이트", "사진맛집"]'::jsonb, 34.951259, 127.483463, '2026-02-19T00:34:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002398', '54500700-0000-4000-8000-000000000076', 'p-tourapi-2946242', '내맘대로폰케이스 홍대점', '천천히 골목 걷다가 마주친 내맘대로폰케이스 홍대점. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["힐링", "혼자여행", "풍경맛집"]'::jsonb, 37.551247, 126.921899, '2026-02-26T10:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002399', '54500700-0000-4000-8000-000000000158', 'p-tourapi-3432447', '2025 서울 카페&베이커리페어', '조용히 사색하고 싶어서 찾은 2025 서울 카페&베이커리페어. 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["고즈넉", "사색", "온마루"]'::jsonb, 37.496089, 127.070767, '2026-03-22T23:59:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002400', '54500700-0000-4000-8000-000000000106', 'p-tourapi-4065913', '청원루', '수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["방문팁", "가족여행"]'::jsonb, 36.579469, 128.548711, '2026-04-10T04:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002401', '54500700-0000-4000-8000-000000000156', 'p-tourapi-2638488', '거제 관광모노레일', '예전부터 가보고 싶었던 거제 관광모노레일 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집", "주말나들이"]'::jsonb, 34.876418, 128.625395, '2026-02-24T10:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002402', '54500700-0000-4000-8000-000000000132', 'p-tourapi-2990172', '팔봉제빵점', '부모님 모시고 팔봉제빵점 산책 겸 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "데이트", "인생샷"]'::jsonb, 36.647386, 127.494072, '2026-02-24T05:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002403', '54500700-0000-4000-8000-000000000062', 'p-tourapi-3508744', '주식회사더정원의뜰', '조용히 사색하고 싶어서 찾은 주식회사더정원의뜰. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 37.628796, 127.209379, '2026-03-22T01:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002404', '54500700-0000-4000-8000-000000000199', 'p-tourapi-2677655', '성주 백세각', '성주 백세각 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.988067, 128.245751, '2026-04-08T02:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002405', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2629010', '영남알프스 얼음골케이블카', '근처 여행 코스로 영남알프스 얼음골케이블카 넣길 정말 잘했어요. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["데이트", "사진맛집", "온마루"]'::jsonb, 35.582782, 128.986997, '2026-02-01T06:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002406', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2574164', '금마관', '해 질 무렵에 금마관 방문했는데 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 35.996345, 127.059295, '2026-02-20T08:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002407', '54500700-0000-4000-8000-000000000187', 'p-tourapi-2049307', '녹운재', '해 질 무렵에 녹운재 방문했는데 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["산책로", "고즈넉"]'::jsonb, 35.902864, 127.242582, '2026-02-03T01:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002408', '54500700-0000-4000-8000-000000000069', 'p-tourapi-3038851', '치헌', '드라이브 겸 나들이로 치헌 선택했는데 대만족! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["산책로", "혼자여행", "사색"]'::jsonb, 36.534748, 128.860953, '2026-02-19T18:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002409', '54500700-0000-4000-8000-000000000070', 'p-tourapi-3510944', '주식회사영리캐롤', '예전부터 가보고 싶었던 주식회사영리캐롤 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["가족여행", "주말나들이"]'::jsonb, 36.008325, 128.359602, '2026-01-07T03:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002410', '54500700-0000-4000-8000-000000000147', 'p-tourapi-264402', '화성어차', '부모님 모시고 화성어차 산책 겸 다녀왔습니다. 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "혼자여행", "온마루"]'::jsonb, 37.287915, 127.023703, '2026-03-21T17:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002411', '54500700-0000-4000-8000-000000000136', 'p-tourapi-3114431', '모주체험 여', '기대 이상으로 너무 좋았던 모주체험 여! 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["고즈넉", "힐링"]'::jsonb, 35.815809, 127.152069, '2026-03-03T02:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002412', '54500700-0000-4000-8000-000000000101', 'p-tourapi-1606001', '해풍부원군윤택영댁재실', '기대 이상으로 너무 좋았던 해풍부원군윤택영댁재실! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["데이트", "주말나들이"]'::jsonb, 37.558364, 126.994403, '2026-04-06T19:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002413', '54500700-0000-4000-8000-000000000110', 'p-tourapi-2603652', '경주한옥', '주말에 친구들이랑 경주한옥 들렀는데 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "사진맛집"]'::jsonb, 35.804297, 129.194292, '2026-02-22T22:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002414', '54500700-0000-4000-8000-000000000104', 'p-tourapi-3438433', '호우재 한옥', '예전부터 가보고 싶었던 호우재 한옥 드디어 방문! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.595407, 126.999649, '2026-03-19T11:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002415', '54500700-0000-4000-8000-000000000190', 'p-tourapi-2531675', '진도한옥펜션', '드라이브 겸 나들이로 진도한옥펜션 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["사색", "산책로"]'::jsonb, 34.398482, 126.277327, '2026-03-17T22:22:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002416', '54500700-0000-4000-8000-000000000097', 'p-tourapi-2638566', '주문진읍 BTS 앨범사진 촬영지 (버스정류장)', 'SNS에서 사진 보고 찾아간 주문진읍 BTS 앨범사진 촬영지 (버스정류장), 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "힐링", "사색"]'::jsonb, 37.912546, 128.817052, '2026-03-18T16:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002417', '54500700-0000-4000-8000-000000000196', 'p-tourapi-3438653', '호호재', '근처 여행 코스로 호호재 넣길 정말 잘했어요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행"]'::jsonb, 36.560299, 128.710802, '2026-03-06T10:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002418', '54500700-0000-4000-8000-000000000125', 'p-tourapi-3438358', '정연재', '예전부터 가보고 싶었던 정연재 드디어 방문! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["혼자여행", "풍경맛집", "힐링"]'::jsonb, 37.583480, 126.980701, '2026-04-04T15:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002419', '54500700-0000-4000-8000-000000000104', 'p-tourapi-1622772', '합천 사의정', '주말에 친구들이랑 합천 사의정 들렀는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 35.544184, 128.000424, '2026-03-16T10:13:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002420', '54500700-0000-4000-8000-000000000109', 'p-tourapi-1883085', '늘봄스테이', '해 질 무렵에 늘봄스테이 방문했는데 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "인생샷", "온마루"]'::jsonb, 35.813289, 127.152181, '2026-01-09T22:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002421', '54500700-0000-4000-8000-000000000158', 'p-tourapi-1871270', '맥산댁', '드라이브 겸 나들이로 맥산댁 선택했는데 대만족! 디저트로 나온 쫀득한 찹쌀떡과 약과가 너무 맛있어서 부모님 선물용으로 따로 포장해왔어요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 35.667289, 128.228714, '2026-02-02T20:36:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002422', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3012678', '사기막골 도예촌', '해 질 무렵에 사기막골 도예촌 방문했는데 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "사진맛집"]'::jsonb, 37.293633, 127.411828, '2026-01-27T07:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002423', '54500700-0000-4000-8000-000000000079', 'p-tourapi-126417', '해남윤씨 녹우당 일원', '기대 이상으로 너무 좋았던 해남윤씨 녹우당 일원! 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["힐링", "산책로"]'::jsonb, 34.551054, 126.621937, '2026-02-23T00:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002424', '54500700-0000-4000-8000-000000000178', 'p-tourapi-1624517', '해남윤씨 추원당', '근처 여행 코스로 해남윤씨 추원당 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["방문팁", "인생샷", "온마루"]'::jsonb, 34.588271, 126.679517, '2026-01-25T08:24:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002425', '54500700-0000-4000-8000-000000000099', 'p-tourapi-2481866', '백인제가옥', '해 질 무렵에 백인제가옥 방문했는데 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "데이트"]'::jsonb, 37.580469, 126.984142, '2026-03-18T08:19:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002426', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3438570', '렛스테이', '기대 이상으로 너무 좋았던 렛스테이! 따뜻한 온돌방에 등 지지고 누워있으니 한 주 동안 쌓였던 피로가 싹 풀렸습니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["방문팁", "가족여행", "온마루"]'::jsonb, 36.454377, 127.123439, '2026-03-28T04:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002427', '54500700-0000-4000-8000-000000000197', 'p-tourapi-3532666', '산다', '근처 여행 코스로 산다 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 1, '["인생샷", "가족여행", "사진맛집"]'::jsonb, 35.819131, 127.157480, '2026-03-09T23:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002428', '54500700-0000-4000-8000-000000000145', 'p-tourapi-2610850', '강원숲체험장', '평일 연차 쓰고 혼자 강원숲체험장 다녀옴. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "고즈넉", "사색"]'::jsonb, 37.963056, 127.639721, '2026-03-14T13:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002429', '54500700-0000-4000-8000-000000000203', 'p-tourapi-2607653', '오람정', '부모님 모시고 오람정 산책 겸 다녀왔습니다. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["인생샷", "데이트", "온마루"]'::jsonb, 35.779802, 129.183655, '2026-03-09T17:57:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002430', '54500700-0000-4000-8000-000000000132', 'p-tourapi-231938', '서울 경모궁지', '평일 연차 쓰고 혼자 서울 경모궁지 다녀옴. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["혼자여행", "고즈넉"]'::jsonb, 37.580402, 126.999009, '2026-01-09T12:04:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002431', '54500700-0000-4000-8000-000000000107', 'p-tourapi-1436162', '괴산 이창훈 고가', '조용히 사색하고 싶어서 찾은 괴산 이창훈 고가. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["고즈넉", "힐링", "온마루"]'::jsonb, 36.840840, 127.859224, '2026-02-28T15:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002432', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2820640', '가림상회', '기대 이상으로 너무 좋았던 가림상회! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["힐링", "풍경맛집", "혼자여행", "온마루"]'::jsonb, 36.189900, 126.892869, '2026-03-17T11:12:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002433', '54500700-0000-4000-8000-000000000072', 'p-tourapi-2611669', '양천나눔누리타운', '날씨가 너무 맑아서 양천나눔누리타운 한 바퀴 돌고 왔네요. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "인생샷", "온마루"]'::jsonb, 37.518955, 126.853764, '2026-01-28T09:47:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002434', '54500700-0000-4000-8000-000000000056', 'p-tourapi-2603652', '경주한옥', '기대 이상으로 너무 좋았던 경주한옥! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "방문팁", "가족여행"]'::jsonb, 35.804297, 129.194292, '2026-02-08T18:51:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002435', '54500700-0000-4000-8000-000000000116', 'p-tourapi-2660381', '매월당', '해 질 무렵에 매월당 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 2, '["데이트", "주말나들이", "가족여행"]'::jsonb, 35.348864, 127.272895, '2026-02-13T00:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002436', '54500700-0000-4000-8000-000000000148', 'p-tourapi-3438574', '풍류가옥', '오랜만에 여유 찾으러 풍류가옥 다녀왔습니다. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "산책로"]'::jsonb, 35.824688, 127.155322, '2026-02-07T03:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002437', '54500700-0000-4000-8000-000000000061', 'p-tourapi-2621417', '장락원(장락원전통한옥펜션)', '천천히 골목 걷다가 마주친 장락원(장락원전통한옥펜션). 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["인생샷", "주말나들이", "가족여행"]'::jsonb, 37.727374, 127.553234, '2026-02-15T17:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002438', '54500700-0000-4000-8000-000000000058', 'p-tourapi-2574186', '김포아트빌리지 전통한옥숙박체험관', '비 오는 날 운치 찾아 김포아트빌리지 전통한옥숙박체험관 다녀왔어요. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["가족여행", "인생샷", "방문팁"]'::jsonb, 37.646687, 126.696228, '2026-02-17T01:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002439', '54500700-0000-4000-8000-000000000067', 'p-tourapi-2708658', '최참판댁 한옥숙박시설', '천천히 골목 걷다가 마주친 최참판댁 한옥숙박시설. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["주말나들이", "방문팁", "온마루"]'::jsonb, 35.156044, 127.686440, '2026-03-31T20:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002440', '54500700-0000-4000-8000-000000000172', 'p-tourapi-2811451', '스테이황룡', '날씨가 너무 맑아서 스테이황룡 한 바퀴 돌고 왔네요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 35.294972, 126.770106, '2026-02-01T20:26:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002441', '54500700-0000-4000-8000-000000000204', 'p-tourapi-3358056', '닥나무한지체험관 콩닥콩닥', '해 질 무렵에 닥나무한지체험관 콩닥콩닥 방문했는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["데이트", "주말나들이", "온마루"]'::jsonb, 35.691674, 126.817694, '2026-03-15T18:37:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002442', '54500700-0000-4000-8000-000000000077', 'p-tourapi-662234', '순천전통야생차체험관', '평일 연차 쓰고 혼자 순천전통야생차체험관 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉", "온마루"]'::jsonb, 34.994895, 127.334076, '2026-02-16T02:39:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002443', '54500700-0000-4000-8000-000000000166', 'p-tourapi-2572908', '별바라기집', '드라이브 겸 나들이로 별바라기집 선택했는데 대만족! 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '북적', 1, '["사진맛집", "방문팁", "데이트"]'::jsonb, 34.740867, 126.717738, '2026-03-12T05:29:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002444', '54500700-0000-4000-8000-000000000102', 'p-tourapi-1883758', '창실고택', '날씨가 너무 맑아서 창실고택 한 바퀴 돌고 왔네요. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["주말나들이", "방문팁", "가족여행", "온마루"]'::jsonb, 36.438275, 129.027039, '2026-03-14T03:17:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002445', '54500700-0000-4000-8000-000000000060', 'p-tourapi-1992543', '송정고택', '드라이브 겸 나들이로 송정고택 선택했는데 대만족! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["데이트", "가족여행", "온마루"]'::jsonb, 36.435930, 129.026245, '2026-03-31T15:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002446', '54500700-0000-4000-8000-000000000123', 'p-tourapi-2607653', '오람정', '기대 이상으로 너무 좋았던 오람정! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["데이트", "사진맛집", "가족여행"]'::jsonb, 35.779802, 129.183655, '2026-04-02T04:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002447', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3337799', '레이홉', '드라이브 겸 나들이로 레이홉 선택했는데 대만족! 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["혼자여행", "사색"]'::jsonb, 35.542409, 129.307407, '2026-01-07T11:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002448', '54500700-0000-4000-8000-000000000161', 'p-tourapi-3101964', '고기리 다온스테이', '비 오는 날 운치 찾아 고기리 다온스테이 다녀왔어요. 침구류도 깨끗하고 서까래 인테리어가 너무 아늑해서 꿀잠 잤습니다. 밤 분위기가 진짜 예술! 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 37.352342, 127.067430, '2026-04-11T16:41:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002449', '54500700-0000-4000-8000-000000000106', 'p-tourapi-3438724', '소월정', 'SNS에서 사진 보고 찾아간 소월정, 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["인생샷", "데이트"]'::jsonb, 37.583277, 126.986492, '2026-02-28T18:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002450', '54500700-0000-4000-8000-000000000077', 'p-tourapi-129052', '청송초전댁', '날씨가 너무 맑아서 청송초전댁 한 바퀴 돌고 왔네요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["힐링", "혼자여행", "산책로", "온마루"]'::jsonb, 36.437960, 129.026646, '2026-02-28T23:02:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002451', '54500700-0000-4000-8000-000000000111', 'p-tourapi-1870849', '덕동댁', '드라이브 겸 나들이로 덕동댁 선택했는데 대만족! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "방문팁"]'::jsonb, 35.666836, 128.227948, '2026-03-21T17:27:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002452', '54500700-0000-4000-8000-000000000122', 'p-tourapi-2509920', '울산중구생활문화센터', '조용히 사색하고 싶어서 찾은 울산중구생활문화센터. 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.556530, 129.322163, '2026-01-22T09:53:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002453', '54500700-0000-4000-8000-000000000112', 'p-tourapi-2607765', '다락', '천천히 골목 걷다가 마주친 다락. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 35.816908, 127.150953, '2026-02-20T04:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002454', '54500700-0000-4000-8000-000000000147', 'p-tourapi-3532712', '스테이화요일', '천천히 골목 걷다가 마주친 스테이화요일. 도시 소음 하나 없이 풀벌레 소리 들으면서 잠드는 경험이 너무나 소중하고 특별했어요. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '북적', 1, '["데이트", "인생샷"]'::jsonb, 36.847611, 126.904632, '2026-02-20T20:45:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002455', '54500700-0000-4000-8000-000000000066', 'p-tourapi-2679044', '청향재', '통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["풍경맛집", "사색", "힐링"]'::jsonb, 37.641706, 126.940197, '2026-02-12T15:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002456', '54500700-0000-4000-8000-000000000091', 'p-tourapi-3544376', '강릉종합사회복지관', 'SNS에서 사진 보고 찾아간 강릉종합사회복지관, 은은하게 퍼지는 차향과 전통 목조 건물이 주는 포근한 분위기가 너무 잘 어우러집니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["사진맛집", "인생샷", "데이트", "온마루"]'::jsonb, 37.764743, 128.916148, '2026-02-23T20:35:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002457', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3532720', '메모리스테이 효자', '메모리스테이 효자 다녀왔어요! 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '북적', 2, '["데이트", "방문팁", "가족여행", "온마루"]'::jsonb, 37.582736, 126.971016, '2026-01-31T23:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002458', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2602196', '의양리 권진사댁', '평일 연차 쓰고 혼자 의양리 권진사댁 다녀옴. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 36.944795, 128.912231, '2026-02-02T12:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002459', '54500700-0000-4000-8000-000000000064', 'p-tourapi-2608499', '미담 한옥 게스트 하우스', '주말에 친구들이랑 미담 한옥 게스트 하우스 들렀는데 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["혼자여행", "사색", "온마루"]'::jsonb, 37.580664, 126.986353, '2026-01-15T21:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002460', '54500700-0000-4000-8000-000000000117', 'p-tourapi-3438249', '아보헌', '오랜만에 여유 찾으러 아보헌 다녀왔습니다. 통창 너머로 한옥 정원을 바라보며 차를 음미할 수 있어서 여유로운 오후를 만끽했어요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["풍경맛집", "혼자여행", "사색", "온마루"]'::jsonb, 37.582122, 126.989536, '2026-03-26T07:10:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002461', '54500700-0000-4000-8000-000000000089', 'p-tourapi-2993194', '위라이드 서울전차', '기대 이상으로 너무 좋았던 위라이드 서울전차! 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["고즈넉", "사색"]'::jsonb, 37.570898, 126.979937, '2026-02-03T15:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002462', '54500700-0000-4000-8000-000000000073', 'p-tourapi-2594218', '정가한옥', '비 오는 날 운치 찾아 정가한옥 다녀왔어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["주말나들이", "방문팁"]'::jsonb, 35.816289, 127.155113, '2026-02-01T14:40:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002463', '54500700-0000-4000-8000-000000000136', 'p-tourapi-2574250', '라온한옥꿀잠', '평일 연차 쓰고 혼자 라온한옥꿀잠 다녀옴. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["풍경맛집", "혼자여행"]'::jsonb, 35.815836, 127.154314, '2026-03-14T01:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002464', '54500700-0000-4000-8000-000000000075', 'p-tourapi-2602196', '의양리 권진사댁', '오랜만에 여유 찾으러 의양리 권진사댁 다녀왔습니다. 비가 촉촉하게 내리던 날이라 처마에서 떨어지는 빗방울 구경하며 비멍 제대로 때렸습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 36.944795, 128.912231, '2026-01-23T13:48:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002465', '54500700-0000-4000-8000-000000000174', 'p-tourapi-1624514', '해남윤씨 영모당', '기대 이상으로 너무 좋았던 해남윤씨 영모당! 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["방문팁", "가족여행"]'::jsonb, 34.577567, 126.705621, '2026-03-02T01:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002466', '54500700-0000-4000-8000-000000000151', 'p-tourapi-3433029', '어깨동무스토리움', '평일 연차 쓰고 혼자 어깨동무스토리움 다녀옴. 처마 끝 너머로 병풍처럼 펼쳐진 산세가 감탄을 자아내네요. 풍경 맛집 인정합니다. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '한적', 1, '["풍경맛집", "힐링", "온마루"]'::jsonb, 37.575035, 126.886307, '2026-03-25T19:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002467', '54500700-0000-4000-8000-000000000103', 'p-tourapi-3428156', '국가유산 방문 캠페인 인천공항 홍보관', '기대 이상으로 너무 좋았던 국가유산 방문 캠페인 인천공항 홍보관! 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "인생샷", "데이트", "온마루"]'::jsonb, 37.447703, 126.452175, '2026-03-30T11:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002468', '54500700-0000-4000-8000-000000000070', 'p-tourapi-2610850', '강원숲체험장', 'SNS에서 사진 보고 찾아간 강원숲체험장, 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 1, '["가족여행", "데이트", "온마루"]'::jsonb, 37.963056, 127.639721, '2026-03-18T07:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002469', '54500700-0000-4000-8000-000000000079', 'p-tourapi-264311', '명동', '천천히 골목 걷다가 마주친 명동. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["가족여행", "방문팁", "인생샷", "온마루"]'::jsonb, 37.562152, 126.984915, '2026-03-07T18:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002470', '54500700-0000-4000-8000-000000000128', 'p-tourapi-3351556', '서천문화예술창작공간', '서천문화예술창작공간 다녀왔어요! 해설사 선생님 설명 들으면서 둘러보니까 그냥 지나칠 뻔한 기와 문양이랑 선조들의 지혜가 새롭게 보입니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["산책로", "혼자여행"]'::jsonb, 36.008334, 126.695905, '2026-03-04T11:31:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002471', '54500700-0000-4000-8000-000000000160', 'p-tourapi-1626773', '영동 소석고택', '기대 이상으로 너무 좋았던 영동 소석고택! 툇마루 끝에 걸터앉아 처마 끝으로 이어지는 푸른 하늘을 바라보는데 진정한 힐링이 뭔지 알겠더라구요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["고즈넉", "힐링", "풍경맛집"]'::jsonb, 36.218170, 127.712681, '2026-03-03T11:33:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002472', '54500700-0000-4000-8000-000000000104', 'p-tourapi-2583699', '소소하우스', '근처 여행 코스로 소소하우스 넣길 정말 잘했어요. 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["가족여행", "주말나들이", "사진맛집", "온마루"]'::jsonb, 37.580333, 126.968163, '2026-01-28T21:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002473', '54500700-0000-4000-8000-000000000193', 'p-tourapi-3085314', '북촌전통발효공방 빚담', 'SNS에서 사진 보고 찾아간 북촌전통발효공방 빚담, 전통 체험 프로그램 참여했는데 강사님도 무척 친절하시고 시간 가는 줄 모를 만큼 재밌었어요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '북적', 1, '["가족여행", "주말나들이", "사진맛집"]'::jsonb, 37.582349, 126.985501, '2026-02-11T04:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002474', '54500700-0000-4000-8000-000000000075', 'p-tourapi-3032740', '대가야기마문화체험장', '예전부터 가보고 싶었던 대가야기마문화체험장 드디어 방문! 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "산책로", "고즈넉", "온마루"]'::jsonb, 35.711382, 128.267182, '2026-03-04T18:54:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002475', '54500700-0000-4000-8000-000000000111', 'p-tourapi-3025473', '영광 매간당 고택', '날씨가 너무 맑아서 영광 매간당 고택 한 바퀴 돌고 왔네요. 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["사색", "산책로"]'::jsonb, 35.240848, 126.474309, '2026-02-04T11:30:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002476', '54500700-0000-4000-8000-000000000066', 'p-tourapi-1877477', '노송정종택(퇴계생가)', '주말에 친구들이랑 노송정종택(퇴계생가) 들렀는데 오래된 흙담길 따라서 천천히 걷는데 마음이 절로 차분해지고 경건해지는 기분이 들었어요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["혼자여행", "힐링", "사색", "온마루"]'::jsonb, 36.749721, 128.828350, '2026-01-31T08:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002477', '54500700-0000-4000-8000-000000000096', 'p-tourapi-1870767', '다향소축', 'SNS에서 사진 보고 찾아간 다향소축, 조선시대로 시간 여행 온 것처럼 고즈넉함의 깊이가 남달랐어요. 기둥 하나하나 품격이 느껴짐. 가족들과 소중한 추억 남기기에 이만한 곳이 없는 것 같습니다. 완전 힐링됨.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 34.578900, 126.748914, '2026-02-12T03:56:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002478', '54500700-0000-4000-8000-000000000176', 'p-tourapi-2570229', '결성향교', '날씨가 너무 맑아서 결성향교 한 바퀴 돌고 왔네요. 마당에 심어진 굵은 소나무와 정원의 들꽃들이 한옥 담장과 그림처럼 어우러져 있습니다. 비 오는 날 방문하시면 특유의 운치와 흙냄새를 두 배로 즐기실 수 있습니다.', '북적', 1, '["인생샷", "방문팁", "온마루"]'::jsonb, 36.528794, 126.543250, '2026-01-26T02:42:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002479', '54500700-0000-4000-8000-000000000106', 'p-tourapi-1579811', '거창 반구헌', '평일 연차 쓰고 혼자 거창 반구헌 다녀옴. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '한적', 1, '["사색", "풍경맛집", "온마루"]'::jsonb, 35.755100, 127.829100, '2026-02-20T21:00:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002480', '54500700-0000-4000-8000-000000000081', 'p-tourapi-2607515', '화랑도체험장', '주말에 친구들이랑 화랑도체험장 들렀는데 아이들이랑 같이 방문했는데 책으로만 보던 전통 문화를 직접 오감으로 느낄 수 있어서 유익했어요. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "가족여행", "주말나들이"]'::jsonb, 38.218047, 128.570282, '2026-01-13T15:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002481', '54500700-0000-4000-8000-000000000116', 'p-tourapi-3091065', '홍성 노은리 고택', '오랜만에 여유 찾으러 홍성 노은리 고택 다녀왔습니다. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 오후 4~5시쯤 해 질 무렵에 처마 밑에서 사진 찍으면 무조건 인생샷 나옵니다 ㅎㅎ', '한적', 1, '["산책로", "풍경맛집", "온마루"]'::jsonb, 36.644534, 126.734832, '2026-02-24T18:11:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002482', '54500700-0000-4000-8000-000000000124', 'p-tourapi-3438589', '윤은재', '근처 여행 코스로 윤은재 넣길 정말 잘했어요. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["산책로", "고즈넉", "온마루"]'::jsonb, 35.033470, 126.712265, '2026-04-04T15:18:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002483', '54500700-0000-4000-8000-000000000153', 'p-tourapi-2891338', '동강리버버깅', '조용히 사색하고 싶어서 찾은 동강리버버깅. 산책 한 바퀴 돌고 마루에 앉아 마시는 따뜻한 꽃차 한 잔이 몸과 마음을 녹여주네요. 낮에는 햇살이 좀 강하니 챙 넓은 모자 챙겨가시면 더 좋을 것 같아요!', '한적', 1, '["풍경맛집", "산책로"]'::jsonb, 37.116413, 128.538593, '2026-03-28T16:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002484', '54500700-0000-4000-8000-000000000090', 'p-tourapi-3511071', '주식회사피알아이피', '부모님 모시고 주식회사피알아이피 산책 겸 다녀왔습니다. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "고즈넉"]'::jsonb, 35.142914, 129.108355, '2026-02-14T02:06:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002485', '54500700-0000-4000-8000-000000000158', 'p-tourapi-2820706', '폴링 인 진주', '조용히 사색하고 싶어서 찾은 폴링 인 진주. 고택 특유의 은은한 흙냄새와 마른 소나무 향기가 머리를 맑게 정화해주는 느낌이었습니다. 골목길 산책할 땐 발 편한 운동화 신고 오시는 걸 추천드려요.', '한적', 1, '["산책로", "힐링"]'::jsonb, 35.183188, 128.085518, '2026-02-13T19:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002486', '54500700-0000-4000-8000-000000000078', 'p-tourapi-2613097', '월암재', '월암재 다녀왔어요! 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주말엔 사람이 꽤 몰리니 오전 일찍 방문해서 한적함을 즐겨보세요.', '북적', 1, '["데이트", "인생샷", "주말나들이"]'::jsonb, 35.815671, 129.216207, '2026-02-19T12:20:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002487', '54500700-0000-4000-8000-000000000107', 'p-tourapi-2607675', '학은재', '근처 여행 코스로 학은재 넣길 정말 잘했어요. 가을 단풍이 기와지붕 위로 살포시 내려앉아 있는데 한 폭의 수채화를 보는 듯했습니다. 친구, 연인과 조용조용 도란도란 이야기 나누며 걷기 딱 좋은 코스입니다.', '한적', 1, '["사색", "산책로", "풍경맛집"]'::jsonb, 34.786401, 126.380236, '2026-01-14T09:49:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002488', '54500700-0000-4000-8000-000000000104', 'p-tourapi-231938', '서울 경모궁지', '천천히 골목 걷다가 마주친 서울 경모궁지. 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 복잡한 도시 일상에서 벗어나 조용한 쉼표를 찍고 가기에 최고였어요.', '한적', 1, '["고즈넉", "사색", "산책로", "온마루"]'::jsonb, 37.580402, 126.999009, '2026-01-17T12:44:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002489', '54500700-0000-4000-8000-000000000187', 'p-tourapi-3452786', '시흥시청소년수련관', '시흥시청소년수련관 다녀왔어요! 달지 않고 구수한 전통 다과랑 시원한 오미자 에이드 조합이 정말 끝내줬습니다. 다음에 여유 있을 때 꼭 반나절 이상 머물다 가고 싶은 애정하는 곳입니다.', '한적', 1, '["고즈넉", "혼자여행", "풍경맛집", "온마루"]'::jsonb, 37.446487, 126.797388, '2026-04-15T08:15:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002490', '54500700-0000-4000-8000-000000000102', 'p-tourapi-2702472', '김종길 가옥', '해 질 무렵에 김종길 가옥 방문했는데 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 1, '["가족여행", "데이트", "주말나들이"]'::jsonb, 37.270826, 128.264199, '2026-01-31T04:03:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002491', '54500700-0000-4000-8000-000000000204', 'p-tourapi-2613318', '이가한옥', '해 질 무렵에 이가한옥 방문했는데 선조들의 옛 숨결이 그대로 보존되어 있어서 감탄만 나왔어요. 조상님들 풍류가 이런 거였구나 싶음. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["풍경맛집", "사색", "힐링", "온마루"]'::jsonb, 35.816647, 127.155597, '2026-02-28T03:25:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002492', '54500700-0000-4000-8000-000000000146', 'p-tourapi-2708320', '이랑한옥스테이', '기대 이상으로 너무 좋았던 이랑한옥스테이! 아침에 문 열었을 때 마당에서 들려오는 청량한 새소리와 솔바람 냄새를 잊을 수가 없네요. 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '한적', 1, '["산책로", "풍경맛집", "혼자여행"]'::jsonb, 35.520367, 127.151161, '2026-03-01T02:38:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002493', '54500700-0000-4000-8000-000000000116', 'p-tourapi-1624846', '창원정씨종가', '날씨가 너무 맑아서 창원정씨종가 한 바퀴 돌고 왔네요. 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["힐링", "산책로", "온마루"]'::jsonb, 35.565400, 127.395266, '2026-04-07T10:14:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002494', '54500700-0000-4000-8000-000000000105', 'p-tourapi-2593643', '목향재', '조용히 사색하고 싶어서 찾은 목향재. 바람 불 때마다 처마 밑 풍경 소리가 맑게 딸랑거리는데 듣고만 있어도 잡생각이 다 사라져요. 사계절 풍경이 다 다를 것 같아서 눈 내리는 겨울에 꼭 다시 오고 싶네요.', '한적', 1, '["풍경맛집", "혼자여행", "고즈넉"]'::jsonb, 36.501928, 127.239881, '2026-01-30T13:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002495', '54500700-0000-4000-8000-000000000186', 'p-tourapi-3113740', '고결', '날씨가 너무 맑아서 고결 한 바퀴 돌고 왔네요. 대청마루에 가만히 앉아 앞마당을 내다보고 있으면 바람 소리만 귓가에 사박사박 스칩니다. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '북적', 2, '["방문팁", "인생샷", "주말나들이"]'::jsonb, 36.642765, 128.064640, '2026-02-05T04:46:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002496', '54500700-0000-4000-8000-000000000074', 'p-tourapi-3532720', '메모리스테이 효자', '부모님 모시고 메모리스테이 효자 산책 겸 다녀왔습니다. 초록빛 잔디와 붉은 배롱나무, 그리고 짙은 기와가 만들어내는 색감 조화가 황홀할 정도예요. 주차는 근처 공영주차장 이용하시고 천천히 걸어 들어오시는 게 훨씬 편해요!', '북적', 1, '["인생샷", "가족여행", "데이트", "온마루"]'::jsonb, 37.582736, 126.971016, '2026-03-18T19:43:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002497', '54500700-0000-4000-8000-000000000079', 'p-tourapi-2961964', '하정사색', '기대 이상으로 너무 좋았던 하정사색! 수백 년 세월이 묻어난 대청마루 나무 결이랑 기와지붕 곡선이 정말 압권이네요. 마당 구석 벤치가 숨은 뷰 명당이에요. 다들 그냥 지나치시던데 꼭 앉아보세요!', '한적', 1, '["풍경맛집", "힐링", "산책로"]'::jsonb, 35.408399, 127.382242, '2026-02-26T23:05:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002498', '54500700-0000-4000-8000-000000000198', 'p-tourapi-2638521', '영천 목재문화체험장', '해 질 무렵에 영천 목재문화체험장 방문했는데 다양한 볼거리랑 아기자기한 기념품들이 가득해서 둘러보는 재미가 정말 쏠쏠했습니다. 혼자 와서 책 한 권 읽거나 생각 정리하기에도 더없이 완벽한 장소예요.', '한적', 1, '["사색", "혼자여행", "힐링"]'::jsonb, 36.142432, 128.978252, '2026-03-28T02:16:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002499', '54500700-0000-4000-8000-000000000192', 'p-tourapi-3033516', '논산한옥마을', '예전부터 가보고 싶었던 논산한옥마을 드디어 방문! 마당에서 윷놀이랑 투호 던지기 하면서 놀았는데 어른들이 더 신나서 시간 보냈네요 ㅋㅋㅋ 담장 너머로 보이는 하늘 풍경이 예뻐서 사진만 백 장 넘게 찍고 갑니다 ㅋㅋㅋ', '북적', 2, '["사진맛집", "주말나들이", "온마루"]'::jsonb, 36.211445, 127.181241, '2026-03-18T02:52:06Z'::timestamptz),
('54500700-0000-4000-9000-000000002500', '54500700-0000-4000-8000-000000000066', 'p-tourapi-4039810', '스테이꼬리', '기대 이상으로 너무 좋았던 스테이꼬리! 마당 평상에 둘러앉아 밤하늘 별 보면서 두런두런 이야기 나눴던 순간이 이번 여행 최고 명장면. 부모님 모시고 올 효도 여행지 찾으신다면 망설임 없이 추천합니다.', '북적', 1, '["방문팁", "데이트", "주말나들이"]'::jsonb, 35.813146, 129.212540, '2026-01-26T22:33:06Z'::timestamptz);
INSERT INTO onmaru.community_visit_reviews (
